//! Boxy representation planner.
//!
//! The planner records explicit data consumed by the boxy lowerer: how each
//! checked type is represented internally, which descriptor data dynamic
//! positions require, and which static-dispatch constraints require dictionary
//! arguments. It only consumes checked type data.

const std = @import("std");
const can = @import("can");
const check = @import("check");
const collections = @import("collections");
const Common = @import("../common.zig");
const LiteralRequirements = @import("literal_requirements.zig");
const test_fixtures = @import("test_fixtures.zig");

/// Shared Boxy stage-test fixtures, aliased so every stage builds the same
/// synthetic checked payloads from one definition.
const fixtureTableIndex = test_fixtures.tableIndex;
const builtinNominal = test_fixtures.builtinNominal;

const Allocator = std.mem.Allocator;
const checked = check.CheckedModule;
const checked_names = check.CanonicalNames;
const static_dispatch = check.StaticDispatchRegistry;
const RecordFieldLabelId = @TypeOf(@as(checked.CheckedRecordField, undefined).name);
const TagLabelId = @TypeOf(@as(checked.CheckedTag, undefined).name);
const MethodNameId = @TypeOf(@as(checked.CheckedStaticDispatchConstraint, undefined).fn_name);
const StaticDispatchOrigin = @TypeOf(@as(checked.CheckedStaticDispatchConstraint, undefined).origin);
const NumeralInfo = std.meta.Child(@TypeOf(@as(checked.CheckedStaticDispatchConstraint, undefined).numeralInfo()));

const empty_interface_capabilities = checked.ModuleInterfaceCapabilities{};
const empty_resolved_value_refs = checked.ResolvedValueRefTable{};
const empty_checked_procedure_templates = checked.CheckedProcedureTemplateTable{};
const empty_top_level_procedure_bindings = checked.TopLevelProcedureBindingTable{};
const empty_compile_time_roots = checked.CompileTimeRootTable{};
const empty_nested_proc_sites = checked.NestedProcSiteTable{};
const empty_entry_wrappers = checked.EntryWrapperTable{};
const empty_intrinsic_wrappers = checked.IntrinsicWrapperTable{};
const empty_hosted_procs = checked.HostedProcTable{};
const empty_static_dispatch_plans = static_dispatch.StaticDispatchPlanTable{};
const empty_method_registry = static_dispatch.MethodRegistry{};

/// Stable index of a checked type's planned Boxy representation.
pub const TypeRepId = enum(u32) { _ };
/// Dense identity of a checked type, independent of runtime demand.
pub const TypeBindingId = enum(u32) { _ };
/// Stable index of a requested root in a program plan.
pub const RootPlanId = enum(u32) { _ };
/// Stable index of a lowered worker in a program plan.
pub const WorkerPlanId = enum(u32) { _ };
/// Stable index of an explicit runtime descriptor requirement.
pub const DescriptorRequirementId = enum(u32) { _ };
/// Stable index of an explicit runtime dictionary requirement.
pub const DictionaryRequirementId = enum(u32) { _ };

/// Module-qualified checked type reference used throughout planning.
pub const CheckedTypeIdentity = struct {
    module: checked.ModuleId = .{},
    ty: checked.CheckedTypeId,
};

/// Module-qualified identity of producer-owned monomorphic type evidence in a
/// checked module's `ConstStore`.
pub const StoredTypeIdentity = struct {
    module: checked.ModuleId,
    ty: check.ConstStore.ConstTypeId,
};

/// Module-qualified checked expression reference used throughout planning.
pub const CheckedExprIdentity = struct {
    module: checked.ModuleId = .{},
    expr: checked.CheckedExprId,
};

/// A checked custom conversion whose result depends on its worker's type
/// evidence. The body reads its result; its conversion is an initializer.
pub const LiteralSite = struct {
    source: CheckedExprIdentity,
    worker: WorkerPlanId,
    dispatch: static_dispatch.StaticDispatchPlanId,
};

/// A checked type constructor in the literal planner's term domain, with the
/// checked children its term arguments stand for.
pub const LiteralTypeConstructor = struct {
    source: CheckedTypeIdentity,
    children: []const CheckedTypeIdentity,
    /// An explicitly defaulted leaf has a representation but no separate
    /// checked node: its source still names the original variable.
    leaf_rep: ?TypeRepId = null,
};

/// The literal read in one shared worker's body. Its argument is already an
/// ABI ordinal; lowering never traverses the demand graph.
pub const LiteralSiteKey = struct {
    source: CheckedExprIdentity,
    worker: WorkerPlanId,
};

/// A generated callable worker as captured by one caller worker.
pub const GeneratedCallableKey = struct { caller: WorkerPlanId, worker: WorkerPlanId };

/// Closed incoming evidence for a callable-producing frame during literal CTFE.
/// This is freeze metadata only; it never adds a runtime parameter.
pub const LiteralFreezeContext = struct {
    worker: WorkerPlanId,
    bindings: Span,
    dictionaries: Span,
    callable_types: std.AutoHashMapUnmanaged(TypeRepId, u32) = .empty,
};

/// Everything Boxy planned for compile-time literal values: the literal read
/// at each site, the captures generated callables receive, and the
/// initializers that produce closed literal values.
pub const LiteralEvidencePlan = struct {
    freeze_contexts: std.ArrayList(LiteralFreezeContext) = .empty,
    /// Interned callable type identities in this plan's type-term domain. Only
    /// equality survives planning; no consumer retains the term graph.
    callable_types: std.AutoHashMapUnmanaged(TypeRepId, u32) = .empty,
    sites: std.AutoHashMapUnmanaged(LiteralSiteKey, LiteralRequirements.Argument) = .empty,
    generated_captures: std.AutoHashMapUnmanaged(GeneratedCallableKey, []const LiteralRequirements.Argument) = .empty,
    initializers: std.ArrayList(LiteralInitializer) = .empty,
    bindings: std.ArrayList(SchemeRepSubstitution) = .empty,

    fn deinit(self: *LiteralEvidencePlan, allocator: Allocator) void {
        var captures = self.generated_captures.valueIterator();
        while (captures.next()) |args| allocator.free(args.*);
        self.generated_captures.deinit(allocator);
        for (self.freeze_contexts.items) |*context| context.callable_types.deinit(allocator);
        self.freeze_contexts.deinit(allocator);
        self.callable_types.deinit(allocator);
        self.sites.deinit(allocator);
        self.initializers.deinit(allocator);
        self.bindings.deinit(allocator);
    }
};

/// A Boxy-owned constant producer. Its source is only the literal conversion,
/// never the surrounding generic procedure's body.
pub const LiteralInitializer = struct {
    builtin_numeral: bool = false,
    site: u32,
    rep: TypeRepId,
    callable_rep: TypeRepId,
    bindings: Span,
    dictionary: ?DictionaryRequirementId = null,
    method_evidence: Span = .{},
    direct_call: ?DirectCallPlan = null,
};

/// The planned call through which literal arguments reach a callee worker.
pub const LiteralCallEdge = union(enum) {
    direct: u32,
    root: u32,
    callable: u32,
    nested_callable: u32,
    iterator: u32,
    generated_codec: u32,
    const_eval: u32,
    derived: u32,
    dictionary_method: struct { caller: ?WorkerPlanId, method: u32 },
    literal_initializer: u32,
    generated_callable: GeneratedCallableKey,
};

const CheckedPatternIdentity = struct {
    module: checked.ModuleId = .{},
    pattern: checked.CheckedPatternId,
};

const CheckedStatementIdentity = struct {
    module: checked.ModuleId = .{},
    statement: checked.CheckedStatementId,
};

/// Compact start and length pair into an append-only plan table.
pub const Span = extern struct {
    start: u32 = 0,
    len: u32 = 0,

    pub fn empty() Span {
        return .{};
    }
};

/// Whether a dynamic type variable is flexible or rigid.
pub const DynamicKind = enum {
    flex,
    rigid,
};

/// Representation policy for a nominal checked type.
pub const NominalKind = enum {
    transparent,
    opaque_nominal,
    builtin_other,
};

/// Complete planned representation category for one checked type.
pub const RepresentationKind = union(enum) {
    in_progress,
    dynamic: DynamicKind,
    primitive: checked.CheckedPrimitive,
    bool_tag_union,
    /// Every function value, pure or effectful, has the one erased-callable
    /// representation.
    erased_callable,
    alias,
    record,
    tuple,
    nominal: NominalKind,
    list,
    box,
    generated_field,
    generated_field_names,
    generated_tag_union_spec,
    empty_record,
    tag_union,
    empty_tag_union,
};

/// Structural relationship between a representation and one child.
pub const ChildRole = union(enum) {
    alias_backing,
    alias_arg: u32,
    nominal_backing,
    nominal_arg: u32,
    nominal_padding_field: u32,
    record_field: RecordFieldLabelId,
    record_ext,
    tuple_elem: u32,
    function_arg: u32,
    function_ret,
    tag_payload: struct {
        tag: TagLabelId,
        index: u32,
    },
    tag_ext,
    list_elem,
    box_payload,
};

/// Whether a child is part of the runtime value represented by its parent.
/// Function signatures and alias/nominal type arguments are type-level
/// relations; erased callables and their result descriptors own those
/// boundaries independently.
pub fn childCarriesRuntimeDescriptor(role: ChildRole) bool {
    return switch (role) {
        .alias_backing,
        .nominal_backing,
        .record_field,
        .record_ext,
        .tuple_elem,
        .tag_payload,
        .tag_ext,
        .list_elem,
        .box_payload,
        => true,
        .alias_arg,
        .nominal_arg,
        .nominal_padding_field,
        .function_arg,
        .function_ret,
        => false,
    };
}

/// A nominal's backing and padding are written in terms of its declaration
/// formals; its type arguments belong to the enclosing scope.
fn childIsInNominalDeclarationScope(role: ChildRole) bool {
    return switch (role) {
        .nominal_backing, .nominal_padding_field => true,
        .alias_backing,
        .alias_arg,
        .nominal_arg,
        .record_field,
        .record_ext,
        .tuple_elem,
        .tag_payload,
        .tag_ext,
        .list_elem,
        .box_payload,
        .function_arg,
        .function_ret,
        => false,
    };
}

/// One explicitly analyzed child of a type representation.
pub const RepChild = struct {
    role: ChildRole,
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    record_field_kind: checked.CheckedFieldKind = .required,
};

/// One tag name and its planned payload representation span.
pub const TagVariant = struct {
    name: TagLabelId,
    name_module: checked.ModuleId = .{},
    payloads: Span = .{},
};

/// Source and representation metadata for one declared aggregate field.
pub const DeclaredField = struct {
    index: u32,
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    is_padding: bool = false,
};

/// Interned checked identity. A nominal formal can be registered before any
/// runtime or evidence dependency demands its representation.
pub const TypeRepBinding = struct {
    source_type: CheckedTypeIdentity,
    rep: ?TypeRepId = null,
};

/// Mapping from exact stored monomorphic type evidence to its Boxy
/// representation. Stored representations are separate from checked-type
/// bindings because one generalized checked type may have several concrete
/// `ConstStore` instantiations.
pub const StoredTypeRepBinding = struct {
    source_type: StoredTypeIdentity,
    rep: TypeRepId,
};

/// A complete nominal use in `nominal_backing_uses`: `start` addresses its
/// shared-formals offset, followed by `len` exact actual representation ids.
/// The two-word handle keeps non-nominal representation rows unchanged in size.
pub const NominalBackingSubstitutions = Span;

/// Transient view of one substitution. A null formal representation means the
/// binding has no runtime demand; the actual is always present.
pub const NominalBackingArgSubstitution = struct {
    arg_index: u32,
    formal_rep: ?TypeRepId,
    actual_rep: TypeRepId,
};

/// Reads shared bindings by id on each step, without retaining growable-table slices.
pub const NominalBackingSubstitutionIterator = struct {
    plan: *const ProgramPlan,
    span: NominalBackingSubstitutions,
    index: u32 = 0,

    /// Return the next exact actual and its formal's current runtime binding.
    pub fn next(self: *NominalBackingSubstitutionIterator) ?NominalBackingArgSubstitution {
        if (self.index == self.span.len) return null;
        const index = self.index;
        self.index += 1;
        const formals_start = self.plan.nominal_backing_uses.items[self.span.start];
        const binding = self.plan.nominal_backing_formals.items[formals_start + index];
        return .{
            .arg_index = index,
            .formal_rep = self.plan.type_reps.items[@intFromEnum(binding)].rep,
            .actual_rep = @enumFromInt(self.plan.nominal_backing_uses.items[self.span.start + 1 + index]),
        };
    }
};

/// Runtime field-order policy selected from checked nominal metadata.
pub const RecordFieldOrder = enum(u8) {
    structural,
    declared,
};

/// Planner output describing one checked type's complete representation.
pub const TypeRepresentation = struct {
    source_type: CheckedTypeIdentity,
    kind: RepresentationKind,
    children: Span = .{},
    tag_variants: Span = .{},
    /// Produced from a checked tag row whose extension remains open, including
    /// rows with no named variants. Distinguishes these dynamic values from
    /// bare type parameters and open records during call substitution.
    is_open_tag_row: bool = false,
    /// Explicit nominal field metadata used by aggregate descriptor lowering.
    /// `record_field_order` independently controls its runtime layout.
    declared_fields: Span = .{},
    record_field_order: RecordFieldOrder = .structural,
    nominal_backing_arg_substitutions: NominalBackingSubstitutions = .{},
    dictionaries: Span = .{},
    descriptor: ?DescriptorRequirementId = null,
    /// For a bare `.dynamic = .flex` representation, the representation its
    /// checked variable seals to (numeric default, row default, or the empty
    /// tag union) when no enclosing worker quantifies it. A static descriptor
    /// for an unbound flex describes this representation's payload.
    sealed_default: ?TypeRepId = null,
    /// Set when this planned representation transitively stores at least one
    /// dynamic child whose ownership is descriptor-defined. Lowering consumes
    /// `contains_dynamic` directly; committed layouts are not an input.
    contains_dynamic: bool = false,
    /// This representation is the checker-defined `[#Missing, #Present(a)]`
    /// storage convention used for an optional or still-parametric field kind.
    /// The discriminant is explicit so later stages never infer the field's
    /// presence kind from tag names or representation shape.
    presence_slot_present_discriminant: ?u32 = null,
    /// The source nominal type declared itself opaque: inspect must not
    /// reveal the backing structure.
    inspect_opaque: bool = false,
    /// Public source opacity boxes record backings that contain callables.
    /// Selected while resolving checked ABI shapes, before layout commitment.
    abi_boxed_backing: bool = false,
    /// Inspection is demanded at this representation, including when its
    /// concrete value is supplied through a generic worker boundary.
    inspect_demanded: bool = false,
};

/// Reason a representation must carry an explicit runtime descriptor.
pub const DescriptorReason = enum {
    dynamic_payload,
    aggregate_contains_dynamic,
    list_element_dynamic,
    box_payload_dynamic,
};

/// Explicit runtime descriptor demanded by one planned representation.
pub const DescriptorRequirement = struct {
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    reason: DescriptorReason,
};

/// Hidden worker parameter that supplies a runtime type descriptor.
pub const HiddenDescriptorParam = struct {
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    desc: DescriptorRequirementId,
};

/// A non-dictionary checked evidence slot backed by one worker descriptor
/// parameter. `hidden_desc_index` is relative to `WorkerPlan.hidden_descs`.
pub const WorkerEvidenceDescriptorParam = struct {
    evidence_index: u32,
    hidden_desc_index: u32,
};

/// Checked module and absolute evidence-pool index of a scheme requirement.
pub const SchemeDictionaryKey = struct {
    module: checked.ModuleId,
    param: u32,
    callable_contract: ?u32 = null,
};

/// Hidden worker parameter that supplies one or more method dictionaries.
pub const HiddenDictionaryParam = struct {
    /// Compiler-owned literal result accessor, after ordinary dictionaries.
    literal_parameter: ?u32 = null,
    scheme_param: ?SchemeDictionaryKey = null,
    /// Exact method in a shared dictionary group, when selected by a checked owner.
    dispatch_requirement: ?DictionaryRequirementId = null,
    /// Explicit scheme requirements have their own checked evidence slot.
    evidence_index: ?u32 = null,
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    dictionaries: Span,
};

/// Descriptor argument mapping for one direct worker call.
pub const DirectCallHiddenDescriptorArg = struct {
    worker_desc: DescriptorRequirementId,
    worker_rep: TypeRepId,
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    source_arg_index: ?u32 = null,
    source_value_rep: ?TypeRepId = null,
    /// The hidden representation is the entire call argument at
    /// `source_arg_index`, so the operand's own descriptor supplies it.
    whole_operand: bool = false,
    /// The operand's representation at the hidden parameter's position in
    /// the worker argument, when the operand's own descriptor reaches it.
    source_operand_rep: ?TypeRepId = null,
    /// Row tails retain the descriptor of the original argument storage.
    argument_source: enum { adapted, original } = .adapted,
    /// Index in this call's hidden descriptor arguments of an earlier operand
    /// descriptor supplying the same callable parameter. Lowering reuses that
    /// local, including its exact read from the adapted operand.
    source_descriptor_index: ?u32 = null,
};

/// Exact runtime source for one dictionary method worker descriptor.
pub const DictionaryMethodHiddenDescriptorSource = union(enum) {
    slot: u32,
    call: u32,
    argument: u32,
};

/// Exact runtime source for one descriptor in a checked dictionary method
/// requirement, in requirement traversal order.
pub const DictionaryMethodDescriptorSource = struct {
    rep: TypeRepId,
    source: Source,

    pub const Source = union(enum) {
        static_rep,
        argument: u32,
        call: u32,
    };
};

/// Dictionary argument mapping for one direct worker call.
pub const DirectCallHiddenDictionaryArg = struct {
    worker_dictionaries: Span,
    source_type: CheckedTypeIdentity,
    rep: TypeRepId,
    method_evidence: Span = .{},
    source: Source,
    /// The scheme pairs of the call that planned this argument, when that
    /// call derived its evidence from its callable and so named variables no
    /// checked substitution supplied (`DictionaryCallArgs.derived_receivers`).
    /// Empty for every other call.
    derived_substitution: Span = .{},
    /// The derived-method formal bindings a `static_rep` inside a generic
    /// nominal's backing is instantiated at (`ProgramPlan.derivedEnvBindings`).
    env: u32 = 0,

    pub const Source = union(enum) {
        bound_dictionaries: Span,
        static_rep: TypeRepId,
        literal: LiteralRequirements.Argument,
    };
};

/// Exact checked implementation and callable type for one static dictionary slot.
pub const DictionaryMethodEvidence = struct {
    requirement_type: CheckedTypeIdentity,
    callable_type: CheckedTypeIdentity,
    resolution: Resolution,
    nested_dict_args: Span = .{},
    worker_desc_args: Span = .{},
    requirement_desc_sources: Span = .{},
    requirement_desc_args: Span = .{},
    /// One representation per open record inside the requirement's
    /// signature, in `requirementOpenRecords` order: the value this method's
    /// evidence callable has at that position. A frame holding this
    /// dictionary reads each one as a requirement descriptor after the
    /// requirement's own.
    requirement_leaf_sources: Span = .{},
    hidden_desc_sources: Span = .{},
    /// The checked evidence edge that selected this method's target. Its
    /// recorded substitution names the type each variable of the target's
    /// scheme took at this edge, including variables its signature never
    /// mentions (those reached only through its own where-clauses).
    evidence_edge: ?EvidenceEdge = null,

    /// The scheme variables of the worker this dictionary is passed to, as
    /// the checked call supplying it instantiated them. The requirement type
    /// is written in those variables, so a static dictionary's adapter
    /// describes them with these representations.
    requirement_substitution: Span = .{},

    /// A target selected from the dictionary's own type, with no checked
    /// evidence edge, is called at an explicit instantiation of its declared
    /// callable (`dictionary_method_call_types`): the dispatcher's positions
    /// hold the dictionary's type and the calling edge's types fill the
    /// requirement variables it instantiates. `callable_type` stays the
    /// target's declared callable.
    instantiation_arg_types: Span = .{},
    instantiation_ret_type: ?CheckedTypeIdentity = null,
    instantiation_rep: ?TypeRepId = null,

    /// Present when the method's worker needs values of the frame building
    /// the dictionary: a local procedure with runtime captures, or a worker
    /// specialized by such context. No runtime dictionary can call that
    /// worker, so the dictionary's slot is absent and each worker receiving
    /// the dictionary is specialized to receive the method as a context
    /// input, which the building frame constructs.
    context: ?MethodContext = null,

    pub const MethodContext = struct {
        /// `ContextArg`s supplying the method worker's own context inputs,
        /// from the frame building the dictionary.
        context_args: Span = .{},
    };

    pub const EvidenceEdge = struct {
        module: checked.ModuleId,
        node: static_dispatch.EvidenceNodeId,
    };

    pub const Resolution = union(enum) {
        builtin_numeral,
        worker: WorkerPlanId,
        structural: static_dispatch.StructuralKind,
        constraint,
        checked_error,
        unreachable_value,
    };
};

/// One variable of a called worker's scheme together with the caller-side
/// representation the call's checked substitution gave it.
pub const SchemeRepSubstitution = struct {
    scheme_rep: TypeRepId,
    site_rep: TypeRepId,
};

/// One checked call-site instantiation of a worker type position.
///
/// `operand_type` is the argument expression's checked type. `call_type` is
/// the contextual type from the checker's instantiated function type for the
/// call. The corresponding reps make both checked relations explicit before
/// the final boundary into `worker_rep`.
pub const CallTypeSubstitution = struct {
    operand_type: CheckedTypeIdentity,
    operand_rep: TypeRepId,
    call_type: CheckedTypeIdentity,
    call_rep: TypeRepId,
    worker_rep: TypeRepId,
};

