    slot: u32,
    fn_name: MethodNameId,
    fn_ty: CheckedTypeIdentity,
    origin: StaticDispatchOrigin,
    binop_negated: bool,
    num_literal: ?NumeralInfo,
};

/// One program-wide dictionary slot identity. Method ids are module-local, so
