    worker: WorkerPlanId,
    arg_types: [2]CheckedTypeIdentity,
    ret_type: CheckedTypeIdentity,
    hidden_desc_args: Span = .{},
    hidden_dict_args: Span = .{},
    /// `ContextArg`s for a context-specialized `worker`, from `frame`.
    context_args: Span = .{},
};

