/// The actual `bindings` binds `rep` to, when `rep` is one of its formals.
pub fn derivedEnvActual(bindings: []const DerivedBinding, rep: TypeRepId) ?TypeRepId {
    for (bindings) |binding| {
        if (binding.formal == rep) return binding.actual;
    }
    return null;
}

/// The ordered form of a stack of formal bindings, outermost first: each
/// formal's innermost binding, ordered by formal. A recursive nominal
/// reached again under the same actuals has the same environment.
pub fn orderedDerivedEnv(allocator: Allocator, stack: []const DerivedBinding) Allocator.Error![]DerivedBinding {
    var bindings = std.ArrayList(DerivedBinding).empty;
    errdefer bindings.deinit(allocator);
    for (stack) |binding| {
        for (bindings.items) |*existing| {
            if (existing.formal == binding.formal) {
                existing.actual = binding.actual;
                break;
            }
        } else try bindings.append(allocator, binding);
    }
    std.mem.sort(DerivedBinding, bindings.items, {}, struct {
        fn lessThan(_: void, a: DerivedBinding, b: DerivedBinding) bool {
            return @intFromEnum(a.formal) < @intFromEnum(b.formal);
        }
    }.lessThan);
    return try bindings.toOwnedSlice(allocator);
}

/// Target-independent Boxy representation and call plan for a checked program.
pub const ProgramPlan = struct {
    allocator: Allocator,
    literal_sites: std.ArrayList(LiteralSite) = .empty,
    literal_evidence: ?LiteralEvidencePlan = null,
    /// Literals whose direct conversion reaches a local procedure with
    /// runtime captures: they convert in place at runtime, in the frame
    /// holding those captures, and have no compile-time conversion.
    in_place_conversions: std.ArrayList(CheckedExprIdentity) = .empty,
    roots: std.ArrayList(RootPlan),
    workers: std.ArrayList(WorkerPlan),
    direct_calls: std.ArrayList(DirectCallPlan),
    /// Calls whose checked direct target is an exact procedure alias. Boxy
    /// lowers these through the alias's materialized callable value, as a
    /// call of that value.
    alias_calls: std.ArrayList(CheckedExprIdentity),
    call_operands: std.ArrayList(CallOperand),
    dictionary_dispatches: std.ArrayList(DictionaryDispatchPlan),
    nested_callable_uses: std.ArrayList(NestedCallableUsePlan),
    context_inputs: std.ArrayList(ContextInput),
    context_args: std.ArrayList(ContextArg),
    context_constructs: std.ArrayList(ContextConstruct),
    /// For each structural comparison or hash of a closed representation
    /// that reaches local procedures with runtime captures, those
    /// procedures' workers (a span of `frame_context_proc_ids`).
    frame_context_procs: std.AutoHashMapUnmanaged(FrameContextKey, Span) = .{},
    frame_context_proc_ids: std.ArrayList(WorkerPlanId) = .empty,
    callable_uses: std.ArrayList(CallableUsePlan),
    runtime_callable_eval_uses: std.ArrayList(RuntimeCallableEvalUsePlan),
    stored_callable_capture_sources: std.ArrayList(StoredCallableCaptureSource),
    inspect_methods: std.ArrayList(InspectMethodPlan),
    const_eval_calls: std.ArrayList(ConstEvalCallPlan),
    iterator_calls: std.ArrayList(IteratorCallPlan),
    generated_codec_calls: std.ArrayList(GeneratedCodecCallPlan),
    derived_component_calls: std.ArrayList(DerivedComponentCallPlan),
    dictionary_method_call_types: std.ArrayList(CheckedTypeIdentity),
    derived_component_decisions: std.AutoHashMap(DerivedComponentKey, DerivedComponentDecision),
    /// The closed representation of a variable nothing binds where it is read
    /// (or of an open row whose extension is one), at its checked default.
    shared_closed_reps: std.AutoHashMapUnmanaged(TypeRepId, TypeRepId) = .empty,
    /// Ordered derived-method formal environments: env `n` is
    /// `derived_envs.items[n - 1]`, a span of `derived_env_bindings`; env 0 is
    /// empty.
    derived_env_bindings: std.ArrayList(DerivedBinding),
    derived_envs: std.ArrayList(Span),
    generated_codec_call_types: std.ArrayList(CheckedTypeIdentity),
    generated_codec_runtime_links: std.ArrayList(GeneratedCodecRuntimeLink),
    generated_parser_runtime_plans: std.ArrayList(GeneratedParserRuntimePlan),
    generated_encoder_runtime_plans: std.ArrayList(GeneratedEncoderRuntimePlan),
    generated_parser_tag_call_links: std.ArrayList(GeneratedParserTagCallLink),
    generated_parser_tag_union_plans: std.ArrayList(GeneratedParserTagUnionPlan),
    generated_parser_tag_union_record_types: std.ArrayList(CheckedTypeIdentity),
    generated_field_iterator_links: std.ArrayList(GeneratedFieldIteratorLink),
    generated_interpolations: std.ArrayList(GeneratedInterpolationPlan),
    generated_parser_field_captures: std.ArrayList(GeneratedParserFieldCapture),
    generated_parser_missing_required_fields: std.ArrayList(GeneratedParserMissingRequiredField),
    generated_parser_try_plans: std.ArrayList(GeneratedParserTryPlan),
    generated_parser_dictionary_field_selections: std.ArrayList(GeneratedParserDictionaryFieldSelection),
    generated_encoder_try_plans: std.ArrayList(GeneratedEncoderTryPlan),
    root_reps: std.ArrayList(TypeRepId),
    type_reps: std.ArrayList(TypeRepBinding),
    stored_type_reps: std.ArrayList(StoredTypeRepBinding),
    representations: std.ArrayList(TypeRepresentation),
    /// Checked-source ABI shapes, requested only at public boundaries.
    host_reps: collections.DenseMap(TypeRepId, TypeRepId),
    /// The ABI representation the sort low-level calls each comparator
    /// representation through, keyed by the comparator's representation.
    sort_comparator_abis: collections.DenseMap(TypeRepId, TypeRepId),
    children: std.ArrayList(RepChild),
    tag_variants: std.ArrayList(TagVariant),
    declared_fields: std.ArrayList(DeclaredField),
    nominal_backing_formals: std.ArrayList(TypeBindingId),
    /// Packed use records: formal-vector offset, then actual TypeRepId ordinals.
    /// Only generic nominals pay for a header; no per-argument index is stored.
    nominal_backing_uses: std.ArrayList(u32),
    descriptors: std.ArrayList(DescriptorRequirement),
    hidden_descriptor_params: std.ArrayList(HiddenDescriptorParam),
    worker_evidence_descriptor_params: std.ArrayList(WorkerEvidenceDescriptorParam),
    hidden_dictionary_params: std.ArrayList(HiddenDictionaryParam),
    direct_call_hidden_desc_args: std.ArrayList(DirectCallHiddenDescriptorArg),
    direct_call_hidden_dict_args: std.ArrayList(DirectCallHiddenDictionaryArg),
    dictionary_method_evidence: std.ArrayList(DictionaryMethodEvidence),
    dictionary_method_desc_sources: std.ArrayList(DictionaryMethodDescriptorSource),
    requirement_leaf_reps: std.ArrayList(TypeRepId),
    worker_dictionary_descs: std.ArrayList(WorkerDictionaryDescriptor),
    dictionary_method_hidden_desc_sources: std.ArrayList(DictionaryMethodHiddenDescriptorSource),
    scheme_rep_substitutions: std.ArrayList(SchemeRepSubstitution),
    call_type_substitutions: std.ArrayList(CallTypeSubstitution),
    erased_captures: std.ArrayList(ErasedCapture),
    dictionaries: std.ArrayList(DictionaryRequirement),
    dictionary_method_slots: std.ArrayList(DictionaryMethodSlotIdentity),
    static_fns: std.ArrayList(StaticFnPlan),

    pub fn init(allocator: Allocator) ProgramPlan {
        return .{
            .allocator = allocator,
            .roots = .empty,
            .workers = .empty,
            .direct_calls = .empty,
            .alias_calls = .empty,
            .call_operands = .empty,
            .dictionary_dispatches = .empty,
            .nested_callable_uses = .empty,
            .context_inputs = .empty,
            .context_args = .empty,
            .context_constructs = .empty,
            .callable_uses = .empty,
            .runtime_callable_eval_uses = .empty,
            .stored_callable_capture_sources = .empty,
            .inspect_methods = .empty,
            .const_eval_calls = .empty,
            .iterator_calls = .empty,
            .generated_codec_calls = .empty,
            .derived_component_calls = .empty,
            .dictionary_method_call_types = .empty,
            .derived_component_decisions = std.AutoHashMap(DerivedComponentKey, DerivedComponentDecision).init(allocator),
            .derived_env_bindings = .empty,
            .derived_envs = .empty,
            .generated_codec_call_types = .empty,
            .generated_codec_runtime_links = .empty,
            .generated_parser_runtime_plans = .empty,
            .generated_encoder_runtime_plans = .empty,
            .generated_parser_tag_call_links = .empty,
            .generated_parser_tag_union_plans = .empty,
            .generated_parser_tag_union_record_types = .empty,
            .generated_field_iterator_links = .empty,
            .generated_interpolations = .empty,
            .generated_parser_field_captures = .empty,
            .generated_parser_missing_required_fields = .empty,
            .generated_parser_try_plans = .empty,
            .generated_parser_dictionary_field_selections = .empty,
            .generated_encoder_try_plans = .empty,
            .root_reps = .empty,
            .type_reps = .empty,
            .stored_type_reps = .empty,
            .representations = .empty,
            .host_reps = collections.DenseMap(TypeRepId, TypeRepId).init(allocator),
            .sort_comparator_abis = collections.DenseMap(TypeRepId, TypeRepId).init(allocator),
            .children = .empty,
            .tag_variants = .empty,
            .declared_fields = .empty,
            .nominal_backing_formals = .empty,
            .nominal_backing_uses = .empty,
            .descriptors = .empty,
            .hidden_descriptor_params = .empty,
            .worker_evidence_descriptor_params = .empty,
            .hidden_dictionary_params = .empty,
            .direct_call_hidden_desc_args = .empty,
            .direct_call_hidden_dict_args = .empty,
            .dictionary_method_evidence = .empty,
            .dictionary_method_desc_sources = .empty,
            .requirement_leaf_reps = .empty,
            .worker_dictionary_descs = .empty,
            .dictionary_method_hidden_desc_sources = .empty,
            .scheme_rep_substitutions = .empty,
            .call_type_substitutions = .empty,
            .erased_captures = .empty,
            .dictionaries = .empty,
            .dictionary_method_slots = .empty,
            .static_fns = .empty,
        };
    }

    /// Exact ABI shape for an explicitly requested worker/source representation.
    pub fn hostRepFor(self: *const ProgramPlan, rep: TypeRepId) TypeRepId {
        return self.host_reps.get(rep) orelse boxyPlanInvariant("missing checked host ABI request");
    }

    pub fn convertsInPlace(self: *const ProgramPlan, expr: CheckedExprIdentity) bool {
        for (self.in_place_conversions.items) |candidate| {
            if (exprRefEql(candidate, expr)) return true;
        }
        return false;
    }

    pub fn sortComparatorAbiRep(self: *const ProgramPlan, comparator_rep: TypeRepId) TypeRepId {
        return self.sort_comparator_abis.get(comparator_rep) orelse boxyPlanInvariant("missing planned sort comparator ABI");
    }

    pub fn deinit(self: *ProgramPlan) void {
        self.literal_sites.deinit(self.allocator);
        self.in_place_conversions.deinit(self.allocator);
        if (self.literal_evidence) |*evidence| evidence.deinit(self.allocator);
        self.static_fns.deinit(self.allocator);
        self.dictionary_method_slots.deinit(self.allocator);
        self.dictionaries.deinit(self.allocator);
        self.erased_captures.deinit(self.allocator);
        self.call_type_substitutions.deinit(self.allocator);
        self.dictionary_method_hidden_desc_sources.deinit(self.allocator);
