    pub fn childSlice(self: *const ProgramPlan, span: Span) []const RepChild {
        return self.children.items[span.start .. span.start + span.len];
    }

    pub fn dictionaryMethodCallTypeSlice(self: *const ProgramPlan, span: Span) []const CheckedTypeIdentity {
        return self.dictionary_method_call_types.items[span.start .. span.start + span.len];
    }

    /// The closed representation planned for a variable nothing binds where
    /// it is read, when one was planned.
    pub fn sharedClosedRep(self: *const ProgramPlan, rep: TypeRepId) ?TypeRepId {
        return self.shared_closed_reps.get(rep);
    }

    /// The decision a derived method recorded for one component.
    pub fn derivedComponentDecision(self: *const ProgramPlan, key: DerivedComponentKey) ?DerivedComponentDecision {
        return self.derived_component_decisions.get(key);
    }

    /// The frame a derived method over `rep_id` reads when lowered in
    /// `worker`: none when the derived type names no type variable, because
    /// every component it reaches is then described and dispatched statically.
    pub fn derivedFrame(
        self: *const ProgramPlan,
        allocator: Allocator,
        worker: ?WorkerPlanId,
        rep_id: TypeRepId,
        env: u32,
    ) Allocator.Error!?WorkerPlanId {
        var visited = collections.DenseMap(TypeRepId, void).init(allocator);
        defer visited.deinit();
        // A derivation reaching local procedures that need a frame's values
        // belongs to the frame performing it.
        if (env == 0 and self.repNeedsFrameContext(rep_id)) {
            if (worker) |frame| return frame;
        }
        if (!try self.repNamesTypeVariable(rep_id, self.derivedEnvBindings(env), &visited)) return null;
        return worker orelse boxyPlanInvariant("derived method over a type variable had no enclosing worker");
    }

    /// Whether `rep_id` names a type variable outside nominal backing templates.
    pub fn namesTypeVariable(self: *const ProgramPlan, allocator: Allocator, rep_id: TypeRepId) Allocator.Error!bool {
        var visited = collections.DenseMap(TypeRepId, void).init(allocator);
        defer visited.deinit();
        return try self.repNamesTypeVariable(rep_id, &.{}, &visited);
    }

    /// A formal names what `bindings` binds it to. Which reps the walk
    /// reaches depends only on each rep, so the answer does not depend on
    /// visiting order.
    fn repNamesTypeVariable(
        self: *const ProgramPlan,
        root: TypeRepId,
        bindings: []const DerivedBinding,
        visited: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!bool {
        var pending: std.ArrayList(TypeRepId) = .empty;
        defer pending.deinit(visited.allocator);
        try pending.append(visited.allocator, root);
        while (pending.pop()) |rep_id| {
            if ((try visited.getOrPut(rep_id)).found_existing) continue;
            const rep = self.representations.items[@intFromEnum(rep_id)];
            if (rep.kind == .dynamic) {
                if (derivedEnvActual(bindings, rep_id)) |actual| {
                    try pending.append(visited.allocator, actual);
                } else if (rep.sealed_default) |sealed| {
                    try pending.append(visited.allocator, sealed);
                } else return true;
                continue;
            }
            // A nominal use's shared backing names its declaration's formals, not
            // this use's types; the use's actuals are what it stores.
            if (rep.nominal_backing_arg_substitutions.len != 0) {
                var substitutions = self.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                while (substitutions.next()) |substitution| try pending.append(visited.allocator, substitution.actual_rep);
                continue;
            }
            for (self.childSlice(rep.children)) |child| try pending.append(visited.allocator, child.rep);
            for (self.tagVariantSlice(rep.tag_variants)) |variant| {
                for (self.childSlice(variant.payloads)) |payload| try pending.append(visited.allocator, payload.rep);
            }
        }
        return false;
    }

    /// The bindings of derived-method formal environment `env`.
    pub fn derivedEnvBindings(self: *const ProgramPlan, env: u32) []const DerivedBinding {
        if (env == 0) return &.{};
        const span = self.derived_envs.items[env - 1];
        return self.derived_env_bindings.items[span.start .. span.start + span.len];
    }

    /// The environment whose ordered bindings are `bindings`, if planning
    /// recorded one.
    pub fn findDerivedEnv(self: *const ProgramPlan, bindings: []const DerivedBinding) ?u32 {
        if (bindings.len == 0) return 0;
        for (self.derived_envs.items, 0..) |span, index| {
            const candidate = self.derived_env_bindings.items[span.start .. span.start + span.len];
            if (candidate.len != bindings.len) continue;
            for (candidate, bindings) |a, b| {
                if (a.formal != b.formal or a.actual != b.actual) break;
            } else return @intCast(index + 1);
        }
        return null;
    }

    /// Whether describing `rep_id` reads a formal `bindings` binds. A nested
    /// nominal use rebinds its own formals, so only its actuals are read.
    pub fn repReadsDerivedFormal(
        self: *const ProgramPlan,
        allocator: Allocator,
        rep_id: TypeRepId,
        bindings: []const DerivedBinding,
    ) Allocator.Error!bool {
        if (bindings.len == 0) return false;
        var visited = collections.DenseMap(TypeRepId, void).init(allocator);
        defer visited.deinit();
        var pending: std.ArrayList(TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, rep_id);
        while (pending.pop()) |current| {
            if ((try visited.getOrPut(current)).found_existing) continue;
            if (derivedEnvActual(bindings, current) != null) return true;
            const rep = self.representations.items[@intFromEnum(current)];
            if (rep.kind == .nominal and rep.nominal_backing_arg_substitutions.len != 0) {
                var substitutions = self.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                while (substitutions.next()) |substitution| try pending.append(allocator, substitution.actual_rep);
                continue;
            }
            for (self.childSlice(rep.children)) |child| {
                if (!childCarriesRuntimeDescriptor(child.role)) continue;
                try pending.append(allocator, child.rep);
            }
            for (self.tagVariantSlice(rep.tag_variants)) |variant| {
                for (self.childSlice(variant.payloads)) |payload| try pending.append(allocator, payload.rep);
            }
        }
        return false;
    }

    /// A nominal use with type arguments stores its declaration's shared
    /// backing template. The template's formals stand for a different actual
    /// at every use, including uses nested inside another use of the same
    /// declaration, so no rep inside the template names one runtime type.
    /// Hidden descriptors and dictionaries for such a value therefore come
    /// from the nominal itself and its arguments, never from the template.
    pub fn childIsSharedBackingTemplate(self: *const ProgramPlan, parent_rep_id: TypeRepId, child: RepChild) bool {
        const parent = self.representations.items[@intFromEnum(parent_rep_id)];
        if (parent.kind != .nominal or parent.nominal_backing_arg_substitutions.len == 0) return false;
        return switch (child.role) {
            .nominal_backing, .nominal_padding_field => true,
            .nominal_arg => false,
            .alias_arg, .alias_backing, .record_field, .record_ext, .tuple_elem, .tag_payload, .tag_ext, .list_elem, .box_payload, .function_arg, .function_ret => boxyPlanInvariant("boxy nominal representation had a non-nominal child"),
        };
    }

    /// Whether hidden descriptor parameters and call-site descriptor arguments
    /// continue through `child` of a runtime value. A nominal's shared backing
    /// template is described by the nominal's type arguments, so those
    /// arguments stand in for the template's runtime contents.
    pub fn childCarriesHiddenDescriptor(self: *const ProgramPlan, parent_rep_id: TypeRepId, child: RepChild) bool {
        if (self.childIsSharedBackingTemplate(parent_rep_id, child)) return false;
        if (child.role == .nominal_arg) {
            return self.representations.items[@intFromEnum(parent_rep_id)].nominal_backing_arg_substitutions.len != 0;
        }
        return childCarriesRuntimeDescriptor(child.role);
    }

    /// Dictionary parameters and checked evidence share the scheme order
    /// defined by `dispatch_evidence`: alias/nominal arguments precede their
    /// backing type. Runtime representation children keep backing-first order
    /// where layout lowering needs it, so dictionary traversals use this
    /// explicit view instead of inheriting layout order.
    fn dictionaryChildAt(self: *const ProgramPlan, rep_id: TypeRepId, visit_index: usize) ?RepChild {
        const rep = self.representations.items[@intFromEnum(rep_id)];
        const children = self.childSlice(rep.children);
        const class_count: usize = if (rep.kind == .alias)
            2
        else if (rep.kind == .nominal)
            3
        else
            return if (visit_index < children.len) children[visit_index] else null;

        var seen: usize = 0;
        var class: usize = 0;
        while (class < class_count) : (class += 1) {
            for (children) |child| {
                const child_class: usize = if (rep.kind == .alias)
                    if (child.role == .alias_arg)
                        0
                    else if (child.role == .alias_backing)
                        1
                    else
                        boxyPlanInvariant("boxy alias representation had a non-alias child")
                else if (rep.kind == .nominal)
                    if (child.role == .nominal_arg)
                        0
                    else if (child.role == .nominal_backing)
                        1
                    else if (child.role == .nominal_padding_field)
                        2
                    else
                        boxyPlanInvariant("boxy nominal representation had a non-nominal child")
                else
                    unreachable;
                if (child_class != class) continue;
                if (seen == visit_index) return child;
                seen += 1;
            }
        }
        return null;
    }

    pub fn tagVariantSlice(self: *const ProgramPlan, span: Span) []const TagVariant {
        return self.tag_variants.items[span.start .. span.start + span.len];
    }

    /// Whether two representations are the same representation under
    /// different ids: equal kinds and storage metadata, with children and tag
    /// payloads pairwise identical in turn. A value of one needs no conversion
    /// to be a value of the other. Inspection demand is descriptor metadata,
    /// not storage, so it does not distinguish them.
    pub fn repsStructurallyIdentical(
        self: *const ProgramPlan,
        allocator: Allocator,
        a: TypeRepId,
        b: TypeRepId,
    ) Allocator.Error!bool {
        // Every pair reachable from `(a, b)` must agree locally. A pair
        // already seen is identical unless some other position proves
        // otherwise, which is how recursive types terminate.
        var assumed = std.AutoHashMap(u64, void).init(allocator);
        defer assumed.deinit();
        var pending: std.ArrayList([2]TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, .{ a, b });
        while (pending.pop()) |pair| {
            if (pair[0] == pair[1]) continue;
            const pair_key = (@as(u64, @intFromEnum(pair[0])) << 32) | @as(u64, @intFromEnum(pair[1]));
            if ((try assumed.getOrPut(pair_key)).found_existing) continue;

            const rep_a = self.representations.items[@intFromEnum(pair[0])];
            const rep_b = self.representations.items[@intFromEnum(pair[1])];
            if (!std.meta.eql(rep_a.kind, rep_b.kind)) return false;
            if (rep_a.record_field_order != rep_b.record_field_order or
                rep_a.contains_dynamic != rep_b.contains_dynamic or
                rep_a.presence_slot_present_discriminant != rep_b.presence_slot_present_discriminant or
                rep_a.inspect_opaque != rep_b.inspect_opaque or
                rep_a.abi_boxed_backing != rep_b.abi_boxed_backing)
            {
                return false;
            }
            if (rep_a.declared_fields.len != 0 or rep_b.declared_fields.len != 0 or
                rep_a.nominal_backing_arg_substitutions.len != 0 or rep_b.nominal_backing_arg_substitutions.len != 0 or
                rep_a.dictionaries.len != 0 or rep_b.dictionaries.len != 0)
            {
                return false;
            }
            if (!try self.pushIdenticalChildren(allocator, &pending, rep_a.children, rep_b.children)) return false;

            const variants_a = self.tagVariantSlice(rep_a.tag_variants);
            const variants_b = self.tagVariantSlice(rep_b.tag_variants);
            if (variants_a.len != variants_b.len) return false;
            for (variants_a, variants_b) |variant_a, variant_b| {
                if (variant_a.name != variant_b.name or !moduleKeyEqual(variant_a.name_module, variant_b.name_module)) return false;
                if (!try self.pushIdenticalChildren(allocator, &pending, variant_a.payloads, variant_b.payloads)) return false;
            }
        }
        return true;
    }

    /// Queue the child pairs of two child spans, or report that the spans
    /// disagree locally.
    fn pushIdenticalChildren(
        self: *const ProgramPlan,
        allocator: Allocator,
        pending: *std.ArrayList([2]TypeRepId),
        a: Span,
        b: Span,
    ) Allocator.Error!bool {
        const children_a = self.childSlice(a);
        const children_b = self.childSlice(b);
        if (children_a.len != children_b.len) return false;
        for (children_a, children_b) |child_a, child_b| {
            if (!std.meta.eql(child_a.role, child_b.role) or !std.meta.eql(child_a.record_field_kind, child_b.record_field_kind)) return false;
            try pending.append(allocator, .{ child_a.rep, child_b.rep });
        }
        return true;
    }

    pub fn declaredFieldSlice(self: *const ProgramPlan, span: Span) []const DeclaredField {
        return self.declared_fields.items[span.start .. span.start + span.len];
    }

    /// Iterate a nominal use with its shared declaration bindings.
    pub fn nominalBackingSubstitutions(
        self: *const ProgramPlan,
        span: NominalBackingSubstitutions,
    ) NominalBackingSubstitutionIterator {
        return .{ .plan = self, .span = span };
    }

    /// The declaration a nominal use binds, identified by its shared formal
    /// vector. Two uses of one declaration share their backing template.
    pub fn nominalBackingDeclaration(self: *const ProgramPlan, span: NominalBackingSubstitutions) ?u32 {
        if (span.len == 0) return null;
        return self.nominal_backing_uses.items[span.start];
    }

    /// Actuals are total and ordered, including when the formal has no runtime
    /// representation. No child search or formal analysis is needed here.
    pub fn nominalBackingActual(
        self: *const ProgramPlan,
        span: NominalBackingSubstitutions,
        arg_index: u32,
    ) ?TypeRepId {
        if (arg_index >= span.len) return null;
        return @enumFromInt(self.nominal_backing_uses.items[span.start + 1 + arg_index]);
    }

