        request: CodecCallRequest,
        contract_view: ModuleView,
        callable_ty: checked.CheckedTypeId,
        method: MethodNameId,
        checked_evidence: Span,
        evidence_edge: ?DictionaryMethodEvidence.EvidenceEdge,
