    const ConstFnCapture = struct {
        store_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        worker: WorkerPlanId,
        visited: *StaticConstVisited,
        index: usize = 0,
    };

    fn ensureWorker(
        self: *Builder,
        source: WorkerSource,
        checked_type: CheckedTypeIdentity,
        root_request: ?checked.RootRequest,
    ) Allocator.Error!WorkerPlanId {
        try self.runPlanActions(.{ .ensure_worker = .{ .source = source, .checked_type = checked_type, .root_request = root_request } });
        return self.plan_worker_result;
    }

    fn analyzeWorkerBodyTypes(self: *Builder, body: WorkerBody) Allocator.Error!void {
        try self.runPlanActions(.{ .worker_body = body });
    }

    fn materializeInspectMethodsForRep(self: *Builder, rep_id: TypeRepId) Allocator.Error!void {
        try self.runPlanActions(.{ .inspect_methods = rep_id });
    }

    fn analyzeDispatchPlanTypes(self: *Builder, view: ModuleView, maybe_plan: ?static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        try self.runPlanActions(.{ .dispatch_plan_types = .{ .view = view, .plan = maybe_plan } });
    }

    fn recordNestedCallableExprUseForCaller(
        self: *Builder,
        view: ModuleView,
        expr_id: checked.CheckedExprId,
        callable_ty: CheckedTypeIdentity,
        caller: WorkerPlanId,
    ) Allocator.Error!void {
        try self.runPlanActions(.{ .nested_callable_use_for_caller = .{ .view = view, .expr = expr_id, .callable_ty = callable_ty, .caller = caller } });
    }

    fn analyzeStaticConstNode(
        self: *Builder,
        store_view: ModuleView,
        node: checked.ConstNodeId,
        rep_id: TypeRepId,
        const_type: ?check.ConstStore.ConstTypeId,
        visited: *StaticConstVisited,
    ) Allocator.Error!void {
        try self.runPlanActions(.{ .static_const_node = .{ .store_view = store_view, .node = node, .rep_id = rep_id, .const_type = const_type, .visited = visited } });
    }

    fn runPlanActions(self: *Builder, first: PlanAction) Allocator.Error!void {
        var actions: std.ArrayList(PlanAction) = .empty;
        defer actions.deinit(self.allocator);
        errdefer while (actions.pop()) |action| self.abandonPlanAction(action);
        try actions.append(self.allocator, first);
        while (actions.pop()) |action| try self.stepPlanAction(&actions, action);
    }

    /// Undo what a pending action holds when planning fails: restore the
    /// state it would have restored, and free what it owns.
    fn abandonPlanAction(self: *Builder, action: PlanAction) void {
        switch (action) {
            .restore_active_worker => |worker| self.active_worker = worker,
            .restore_nested_callable_args => |value| self.analyzing_nested_callable_args = value,
            .free_visited => |visited| self.freeStaticConstVisited(visited),
            .parser_record_fields => |state| self.allocator.free(state.fields),
            .encoder_tag_union_body, .encoder_tag_union_payloads, .encoder_tag_union_payload => |state| self.allocator.free(state.row_reps),
            .encoder_record_body, .encoder_record_fields_worker, .encoder_record_rename, .encoder_record_field => |state| self.allocator.free(state.fields),
            .ensure_worker, .worker_result, .ensure_worker_runtime_link, .ensure_worker_parser_runtime, .ensure_worker_encoder_runtime, .codec_call, .codec_call_checked_subject, .codec_call_finish, .parser_shape, .parser_alias_links, .parser_tag_link, .parser_try_plan, .parser_dict_key_method, .parser_dict_unit_key, .parser_dict_selection, .parser_record, .encoder_shape, .encoder_set, .encoder_sequence, .encoder_sequence_body, .encoder_sequence_elements, .encoder_sequence_item, .encoder_list, .encoder_list_body, .encoder_list_elements, .encoder_thunk, .encoder_dict, .encoder_dict_encode, .encoder_dict_body, .encoder_dict_fields, .encoder_dict_key_thunk, .encoder_dict_value_thunk, .encoder_tag_union, .encoder_record, .inspect_methods, .inspect_override, .worker_body, .worker_root_expr, .field_iterator, .field_iterator_link, .expr, .call_after_args, .block_statement, .lambda_args, .interpolation_after_parts, .derived_root_after_operands, .low_level_after_args, .inspect_expr, .inspect_expr_methods, .quote_conversion, .numeral_conversion, .callable_lookup, .callable_lookup_after_const, .callable_lookup_runtime, .callable_lookup_worker, .callable_lookup_use, .stored_fn_captures, .const_definition, .const_eval_call, .nested_callable_expr_use, .nested_callable_use_for_caller, .nested_callable_use_record, .nested_callable_use, .nested_callable_direct_record, .dispatch_plan_types, .generated_interpolation, .generated_interpolation_done, .generated_interpolation_record, .dispatch_call_target, .dispatch_call_after_types, .dispatch_call_after_worker, .iterator_for, .iterator_call, .iterator_call_after_operands, .iterator_call_after_worker, .analyze_type, .statement, .pattern, .direct_call_target, .direct_call_after_worker, .omitted_defaults, .static_const_node, .static_fn_value, .static_fn_record, .static_fn_captures, .const_fn_capture => {},
        }
    }

    fn newStaticConstVisited(self: *Builder) Allocator.Error!*StaticConstVisited {
        const visited = try self.allocator.create(StaticConstVisited);
        visited.* = StaticConstVisited.init(self.allocator);
        return visited;
    }

    fn freeStaticConstVisited(self: *Builder, visited: *StaticConstVisited) void {
        visited.deinit();
        self.allocator.destroy(visited);
    }

    /// Push `sequence` so its first action runs next.
    fn pushPlanActions(self: *Builder, actions: *std.ArrayList(PlanAction), sequence: []const PlanAction) Allocator.Error!void {
        try actions.ensureUnusedCapacity(self.allocator, sequence.len);
        var index = sequence.len;
        while (index > 0) {
            index -= 1;
            actions.appendAssumeCapacity(sequence[index]);
        }
    }

    /// Mark where a sequence of pushed actions begins; `finishPlanSequence`
    /// reverses what was pushed since then so it runs in push order.
    fn beginPlanSequence(actions: *const std.ArrayList(PlanAction)) usize {
        return actions.items.len;
    }

    fn finishPlanSequence(actions: *std.ArrayList(PlanAction), start: usize) void {
        std.mem.reverse(PlanAction, actions.items[start..]);
    }

    fn codecCallAction(caller: WorkerPlanId, dispatch_type: CheckedTypeIdentity, method_text: []const u8, subject_type: ?CheckedTypeIdentity) PlanAction {
        return .{ .codec_call = .{ .caller = caller, .dispatch_type = dispatch_type, .method_text = method_text, .subject_type = subject_type } };
    }

    fn exprAction(view: ModuleView, expr: checked.CheckedExprId) PlanAction {
        return .{ .expr = .{ .view = view, .expr = expr } };
    }

    fn patternAction(view: ModuleView, pattern: checked.CheckedPatternId) PlanAction {
        return .{ .pattern = .{ .view = view, .pattern = pattern } };
    }

    fn stepPlanAction(self: *Builder, actions: *std.ArrayList(PlanAction), action: PlanAction) Allocator.Error!void {
        switch (action) {
            .ensure_worker => |request| try self.stepEnsureWorker(actions, request.source, request.checked_type, request.root_request),
            .worker_result => |worker| self.plan_worker_result = worker,
            .ensure_worker_runtime_link => |state| {
                try self.plan.generated_codec_runtime_links.append(self.allocator, .{
                    .constructor = state.worker,
                    .runtime = self.plan_worker_result,
                });
                try self.planWorkerBody(actions, state.worker, state.body);
            },
            .ensure_worker_parser_runtime => |state| {
                try self.plan.generated_parser_runtime_plans.append(self.allocator, .{
                    .worker = state.worker,
                    .schema_type = try self.generatedParserRuntimeSchema(state.body_shape),
                });
                try self.planWorkerBody(actions, state.worker, state.body);
            },
            .ensure_worker_encoder_runtime => |state| {
                try self.plan.generated_encoder_runtime_plans.append(self.allocator, .{
                    .worker = state.worker,
                    .body_type = state.body_shape,
                });
                try self.planWorkerBody(actions, state.worker, state.body);
            },
            .codec_call => |request| try self.stepCodecCall(actions, request),
            .codec_call_checked_subject => |request| try self.stepCodecCallCheckedSubject(actions, request.caller, request.dispatch_type, request.method_text),
            .codec_call_finish => |finish| try self.finishCodecCall(finish),
            .parser_shape => |shape| try self.stepParserShape(actions, shape),
            .parser_alias_links => |links| {
                try self.propagateGeneratedParserTagCallLink(links.worker, links.shape, links.backing);
                try self.propagateGeneratedParserTryPlan(links.worker, links.shape, links.backing);
            },
            .parser_tag_link => |link| try self.appendGeneratedParserTagCallLink(link.worker, link.shape, link.shape),
            .parser_try_plan => |plan| try self.appendGeneratedParserTryPlan(plan.worker, plan.shape, plan.ok_type, plan.err_type, plan.kinds),
            .parser_dict_key_method => |key| try self.appendGeneratedParserDictionaryFieldSelection(key.worker, key.key_type, .{ .method = .{
                .module = self.plan_codec_result.method_module,
                .name = self.plan_codec_result.method,
            } }),
            .parser_dict_unit_key => |key| {
                const subject = self.plan_codec_result.subject_type orelse
                    boxyPlanInvariant("generated unit-tag Dict key string call had no checked subject");
                try self.pushPlanActions(actions, &.{
                    codecCallAction(key.worker, key.encoding_type, "invalid_value", null),
                    .{ .parser_dict_selection = .{ .worker = key.worker, .key_type = key.key_type, .strategy = .{ .unit_tags = subject } } },
                });
            },
            .parser_dict_selection => |selection| try self.appendGeneratedParserDictionaryFieldSelection(selection.worker, selection.key_type, selection.strategy),
            .parser_record => |shape| try self.stepParserRecord(actions, shape),
            .parser_record_fields => |state| try self.stepParserRecordFields(actions, state),
            .encoder_shape => |shape| try self.stepEncoderShape(actions, shape),
            .encoder_set => |set| try actions.append(self.allocator, .{ .encoder_list = .{
                .worker = set.shape.worker,
                .contract_worker = set.shape.contract_worker,
                .list_shape = self.plan_codec_result.ret_type,
                .list_type = self.plan_codec_result.ret_type,
                .encode_subject_type = set.shape.subject_type,
                .elem_type = set.elem_type,
                .encoding_type = set.shape.encoding_type,
            } }),
            .encoder_sequence => |sequence| try self.pushPlanActions(actions, &.{
                codecCallAction(sequence.worker, sequence.encoding_type, sequence.method_text, sequence.sequence_type),
                .{ .encoder_sequence_body = sequence },
            }),
            .encoder_sequence_body => |sequence| try self.stepEncoderSequenceBody(actions, sequence),
            .encoder_sequence_elements => |state| {
                var items = state;
                items.elements_worker = self.plan_worker_result;
                try self.recordGeneratedCallable(items.sequence.worker, items.elements_worker);
                try actions.append(self.allocator, .{ .encoder_sequence_item = items });
            },
            .encoder_sequence_item => |state| {
                if (state.index == state.sequence.item_types.len) return;
                var next = state;
                next.index += 1;
                const item_type = typeRef(state.sequence.item_view, state.sequence.item_types[state.index]);
                const contract_worker = state.sequence.contract_worker;
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                        .kind = .encoder_value_thunk,
                        .shape = item_type,
                        .capture_type = state.sequence.encoding_type,
                        .contract_worker = contract_worker,
                        .contract_expr = self.generatedCodecSourceForWorker(contract_worker).contract_expr,
                    } }, .checked_type = state.thunk_type, .root_request = null } },
                    .{ .encoder_thunk = .{ .owner = state.elements_worker, .contract_worker = contract_worker, .shape = item_type, .encoding_type = state.sequence.encoding_type, .null_call = false } },
                    .{ .encoder_sequence_item = next },
                });
            },
            .encoder_list => |list| try self.pushPlanActions(actions, &.{
                codecCallAction(list.worker, list.encoding_type, "encode_list", list.encode_subject_type),
                .{ .encoder_list_body = list },
            }),
            .encoder_list_body => |list| try self.stepEncoderListBody(actions, list),
            .encoder_list_elements => |state| {
                const elements_worker = self.plan_worker_result;
                try self.recordGeneratedCallable(state.list.worker, elements_worker);
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                        .kind = .encoder_value_thunk,
                        .shape = state.list.elem_type,
                        .capture_type = state.list.encoding_type,
                        .contract_worker = state.list.contract_worker,
                        .contract_expr = state.contract_expr,
                    } }, .checked_type = state.thunk_type, .root_request = null } },
                    .{ .encoder_thunk = .{ .owner = elements_worker, .contract_worker = state.list.contract_worker, .shape = state.list.elem_type, .encoding_type = state.list.encoding_type, .null_call = false } },
                });
            },
            .encoder_thunk => |thunk| {
                const thunk_worker = self.plan_worker_result;
                try self.recordGeneratedCallable(thunk.owner, thunk_worker);
                const start = beginPlanSequence(actions);
                if (thunk.null_call) try actions.append(self.allocator, codecCallAction(thunk_worker, thunk.encoding_type, "encode_null", null));
                try actions.append(self.allocator, .{ .encoder_shape = .{
                    .worker = thunk_worker,
                    .contract_worker = thunk.contract_worker,
                    .shape = thunk.shape,
                    .subject_type = thunk.shape,
                    .encoding_type = thunk.encoding_type,
                } });
                finishPlanSequence(actions, start);
            },
            .encoder_dict => |dict| try self.pushPlanActions(actions, &.{
                codecCallAction(dict.worker, dict.dict_shape, "to_list", dict.dict_shape),
                .{ .encoder_dict_encode = .{ .dict = dict, .to_list_ret = undefined } },
            }),
            .encoder_dict_encode => |state| try self.pushPlanActions(actions, &.{
                codecCallAction(state.dict.worker, state.dict.encoding_type, "encode_dict", state.dict.dict_type),
                .{ .encoder_dict_body = .{ .dict = state.dict, .to_list_ret = self.plan_codec_result.ret_type } },
            }),
            .encoder_dict_body => |state| try self.stepEncoderDictBody(actions, state.dict, state.to_list_ret),
            .encoder_dict_fields => |state| {
                const fields_worker = self.plan_worker_result;
                try self.recordGeneratedCallable(state.dict.worker, fields_worker);
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                        .kind = .encoder_dict_key_thunk,
                        .shape = state.dict.key_type,
                        .capture_type = state.dict.encoding_type,
                        .contract_worker = state.dict.contract_worker,
                        .contract_expr = state.contract_expr,
                    } }, .checked_type = state.key_thunk_type, .root_request = null } },
                    .{ .encoder_dict_key_thunk = .{ .dict = state.dict, .fields_worker = fields_worker, .value_thunk_type = state.value_thunk_type, .contract_expr = state.contract_expr } },
                });
            },
            .encoder_dict_key_thunk => |state| try self.stepEncoderDictKeyThunk(actions, state.dict, state.fields_worker, state.value_thunk_type, state.contract_expr),
            .encoder_dict_value_thunk => |state| try self.pushPlanActions(actions, &.{
                .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                    .kind = .encoder_value_thunk,
                    .shape = state.dict.value_type,
                    .capture_type = state.dict.encoding_type,
                    .contract_worker = state.dict.contract_worker,
                    .contract_expr = state.contract_expr,
                } }, .checked_type = state.value_thunk_type, .root_request = null } },
                .{ .encoder_thunk = .{ .owner = state.fields_worker, .contract_worker = state.dict.contract_worker, .shape = state.dict.value_type, .encoding_type = state.dict.encoding_type, .null_call = false } },
            }),
            .encoder_tag_union => |shape| try self.stepEncoderTagUnion(actions, shape),
            .encoder_tag_union_body => |state| try self.stepEncoderTagUnionBody(actions, state),
            .encoder_tag_union_payloads => |state| {
                var payloads = state;
                payloads.payload_worker = self.plan_worker_result;
                errdefer self.allocator.free(payloads.row_reps);
                try self.recordGeneratedCallable(payloads.shape.worker, payloads.payload_worker);
                try actions.append(self.allocator, .{ .encoder_tag_union_payload = payloads });
            },
            .encoder_tag_union_payload => |state| try self.stepEncoderTagUnionPayload(actions, state),
            .encoder_record => |shape| try self.stepEncoderRecord(actions, shape),
            .encoder_record_body => |state| try self.stepEncoderRecordBody(actions, state),
            .encoder_record_fields_worker => |state| {
                var record = state;
                errdefer self.allocator.free(record.fields);
                record.fields_worker = self.plan_worker_result;
                try self.recordGeneratedCallable(record.shape.worker, record.fields_worker);
                if (record.fields.len != 0) {
                    try self.pushPlanActions(actions, &.{
                        codecCallAction(record.shape.contract_worker, record.shape.encoding_type, "rename_field", null),
                        .{ .encoder_record_rename = record },
                    });
                } else {
                    try actions.append(self.allocator, .{ .encoder_record_field = record });
                }
            },
            .encoder_record_rename => |state| {
                var record = state;
                record.rename_ret = self.plan_codec_result.ret_type;
                try actions.append(self.allocator, .{ .encoder_record_field = record });
            },
            .encoder_record_field => |state| try self.stepEncoderRecordField(actions, state),
            .inspect_methods => |rep_id| try self.stepInspectMethods(actions, rep_id),
            .inspect_override => |state| try self.finishInspectOverride(state.rep_id, state.lookup, state.source_fn_type),
            .worker_body => |body| switch (body) {
                .checked_expr => |checked_body| {
                    if (checked_body.stored_fn) |stored_fn| try self.analyzeStoredFnCaptureTypes(stored_fn);
                    try actions.append(self.allocator, .{ .worker_root_expr = .{ .view = checked_body.view, .expr = checked_body.root_expr } });
                },
                .intrinsic_wrapper => |intrinsic| try self.stepIntrinsicWrapper(actions, intrinsic.view, intrinsic.wrapper),
                .hosted_proc => |hosted| try self.analyzeHostedProcTypes(hosted.view, hosted.proc),
                // A crash body references no types beyond the declared signature,
                // which the worker's own representation already covers.
                .unimplemented => {},
            },
            .worker_root_expr => |root| {
                const expr = root.view.checked_bodies.expr(root.expr);
                if (expr.data != .lambda) return try actions.append(self.allocator, exprAction(root.view, root.expr));
                const start = beginPlanSequence(actions);
                for (expr.data.lambda.args) |arg| try actions.append(self.allocator, patternAction(root.view, arg));
                try actions.append(self.allocator, exprAction(root.view, expr.data.lambda.body));
                finishPlanSequence(actions, start);
            },
            .field_iterator => |mode| try self.stepFieldIterator(actions, mode),
            .field_iterator_link => |intrinsic_worker| try self.plan.generated_field_iterator_links.append(self.allocator, .{
                .intrinsic = intrinsic_worker,
                .first_step = self.plan_worker_result,
            }),
            .expr => |site| try self.stepExprTypes(actions, site.view, site.expr),
            .call_after_args => |site| {
                const call = site.view.checked_bodies.expr(site.expr).data.call;
                _ = try self.analyzeType(site.view, call.source_fn_ty_payload);
                // A call through an exact procedure alias calls the alias's
                // callable value; it has no direct target to plan.
                const direct_target = call.direct_target orelse return;
                if (self.directTargetIsThroughAlias(site.view, direct_target)) return;
                const local_proc_direct_target = self.directTargetIsLocalProc(site.view, direct_target);
                const local_proc_worker_call = local_proc_direct_target and self.directTargetHasNoCaptures(site.view, direct_target);
                if (local_proc_worker_call or !local_proc_direct_target) {
                    try actions.append(self.allocator, .{ .direct_call_target = site });
                } else {
                    try actions.append(self.allocator, .{ .nested_callable_use = .{ .view = site.view, .target = direct_target, .func = call.func } });
                }
            },
            .block_statement => |state| {
                const bodies = state.view.checked_bodies;
                const block = bodies.expr(state.block).data.block;
                if (state.index != 0 and bodies.statementDiverges(block.statements[state.index - 1], .run)) return;
                if (state.index == block.statements.len) return try actions.append(self.allocator, exprAction(state.view, block.final_expr));
                try self.pushPlanActions(actions, &.{
                    .{ .statement = .{ .view = state.view, .statement = block.statements[state.index] } },
                    .{ .block_statement = .{ .view = state.view, .block = state.block, .index = state.index + 1 } },
                });
            },
            .lambda_args => |site| {
                const lambda = site.view.checked_bodies.expr(site.expr).data.lambda;
                const start = beginPlanSequence(actions);
                for (lambda.args) |arg| try actions.append(self.allocator, patternAction(site.view, arg));
                try actions.append(self.allocator, .{ .restore_nested_callable_args = self.analyzing_nested_callable_args });
                finishPlanSequence(actions, start);
                self.analyzing_nested_callable_args = true;
            },
            .interpolation_after_parts => |site| {
                const interpolation = site.view.checked_bodies.expr(site.expr).data.interpolation;
                _ = try self.analyzeType(site.view, interpolation.step_fn_ty);
                try actions.append(self.allocator, .{ .dispatch_call_target = .{ .view = site.view, .call_expr = site.expr, .plan = interpolation.plan } });
            },
            .derived_root_after_operands => |site| {
                const bodies = site.view.checked_bodies;
                const expr = bodies.expr(site.expr);
                switch (expr.data) {
                    .structural_eq => |eq| {
                        const operand_ty = bodies.expr(eq.lhs).ty;
                        try self.registerDerivedRoot(
                            site.worker,
                            .equality,
                            try self.analyzeType(site.view, operand_ty),
                            0,
                            typeRef(site.view, operand_ty),
                            typeRef(site.view, expr.ty),
                        );
                    },
                    .structural_hash => |hash| try self.registerDerivedRoot(
                        site.worker,
                        .hash,
                        try self.analyzeType(site.view, bodies.expr(hash.value).ty),
                        0,
                        typeRef(site.view, bodies.expr(hash.hasher).ty),
                        typeRef(site.view, expr.ty),
                    ),
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => unreachable,
                }
            },
            .low_level_after_args => |site| {
                const expr = site.view.checked_bodies.expr(site.expr);
                if (builtinTryArgs(site.view.checked_types, expr.ty) != null or expr.data.run_low_level.op == .compare) {
                    _ = try self.requestHostRep(try self.analyzeType(site.view, expr.ty));
                }
                const run = expr.data.run_low_level;
                if (run.op == .list_sort_with) {
                    if (run.args.len != 2) boxyPlanInvariant("list_sort_with did not take a list and a comparator");
                    try self.planSortComparatorAbi(try self.analyzeType(site.view, site.view.checked_bodies.expr(run.args[1]).ty));
                }
            },
            .inspect_expr => |site| try self.pushPlanActions(actions, &.{
                exprAction(site.view, site.expr),
                .{ .inspect_expr_methods = site },
            }),
            .inspect_expr_methods => |site| {
                const rep = try self.analyzeType(site.view, site.view.checked_bodies.expr(site.expr).ty);
                try actions.append(self.allocator, .{ .inspect_methods = rep });
            },
            .quote_conversion => |site| try self.stepQuoteConversion(actions, site),
            .numeral_conversion => |site| try self.stepNumeralConversion(actions, site),
            .callable_lookup => |site| {
                const expr = site.view.checked_bodies.expr(site.expr);
                const maybe_ref: ?checked.ResolvedValueRefId = if (expr.data == .lookup_local)
                    expr.data.lookup_local.resolved
                else if (expr.data == .lookup_external)
                    expr.data.lookup_external
                else if (expr.data == .lookup_required)
                    expr.data.lookup_required
                else
                    boxyPlanInvariant("non-lookup expression reached callable lookup worker planning");
                const ref_id = maybe_ref orelse return;
                try self.pushPlanActions(actions, &.{
                    .{ .const_definition = .{ .view = site.view, .ref_id = ref_id } },
                    .{ .callable_lookup_after_const = site },
                });
            },
            .callable_lookup_after_const => |site| try self.stepCallableLookupAfterConst(actions, site),
            .callable_lookup_runtime => |state| {
                const use = CheckedExprIdentity{ .module = state.view.key, .expr = state.expr };
                const caller = self.active_worker orelse
                    boxyPlanInvariant("boxy runtime callable evaluation was analyzed outside a worker body");
                if (self.plan.runtimeCallableEvalUsePlan(use, caller) == null) {
                    try self.plan.runtime_callable_eval_uses.append(self.allocator, .{
                        .use = use,
                        .caller = caller,
                        .source = state.runtime_source,
                        .callable_ty = typeRef(state.view, state.view.checked_bodies.expr(state.expr).ty),
                    });
                }
            },
            .callable_lookup_worker => |state| {
                const worker = self.plan_worker_result;
                const use_action: PlanAction = .{ .callable_lookup_use = .{ .view = state.view, .expr = state.expr, .stored_fn = state.stored_fn, .worker = worker } };
                if (state.stored_fn) |stored| {
                    try self.pushPlanActions(actions, &.{ .{ .stored_fn_captures = .{ .stored_fn = stored, .worker = worker } }, use_action });
                } else {
                    try actions.append(self.allocator, use_action);
                }
            },
            .callable_lookup_use => |state| {
                const use = CheckedExprIdentity{ .module = state.view.key, .expr = state.expr };
                const caller = self.active_worker orelse
                    boxyPlanInvariant("boxy callable lookup was analyzed outside a worker body");
                try self.analyzeUseSchemeSubstitution(state.worker, use);
                if (self.plan.callableUsePlan(use, caller) == null) {
                    try self.plan.callable_uses.append(self.allocator, .{
                        .use = use,
                        .caller = caller,
                        .worker = state.worker,
                        .callable_ty = typeRef(state.view, state.view.checked_bodies.expr(state.expr).ty),
                        .stored_fn = state.stored_fn,
                    });
                }
            },
            .stored_fn_captures => |state| {
                const store_view = self.moduleForId(state.stored_fn.module);
                const store = store_view.const_store orelse
                    boxyPlanInvariant("stored callable capture planning had no ConstStore");
                if (@intFromEnum(state.stored_fn.fn_id) >= store.fns.items.len) {
                    boxyPlanInvariant("stored callable capture planning referenced a missing function");
                }
                const visited = try self.newStaticConstVisited();
                errdefer self.freeStaticConstVisited(visited);
                try self.pushPlanActions(actions, &.{
                    .{ .const_fn_capture = .{ .store_view = store_view, .fn_value = store.getFn(state.stored_fn.fn_id), .worker = state.worker, .visited = visited } },
                    .{ .free_visited = visited },
                });
            },
            .const_definition => |state| try self.stepConstDefinition(actions, state.view, state.ref_id),
            .const_eval_call => |state| {
                const worker = self.plan_worker_result;
                const ret_type = typeRef(state.view, state.requested_ty);
                if (self.plan.constEvalCallFor(worker, ret_type) == null) {
                    const worker_plan = self.plan.workers.items[@intFromEnum(worker)];
                    const worker_function = (self.repQuery().functionChildren(worker_plan.rep)) orelse
                        boxyPlanInvariant("boxy const-eval worker was not a function");
                    if (worker_function.arg_count != 0) {
                        boxyPlanInvariant("boxy const-eval worker had explicit arguments");
                    }
                    const call_rep = try self.analyzeType(state.view, state.requested_ty);
                    try self.plan.const_eval_calls.append(self.allocator, .{
                        .worker = worker,
                        .ret_type = ret_type,
                        .ret_substitution = .{
                            .operand_type = self.plan.representations.items[@intFromEnum(worker_function.ret)].source_type,
                            .operand_rep = worker_function.ret,
                            .call_type = ret_type,
                            .call_rep = call_rep,
                            .worker_rep = worker_function.ret,
                        },
                    });
                }
            },
            .nested_callable_expr_use => |site| {
                const caller = self.active_worker orelse
                    boxyPlanInvariant("boxy nested callable value was analyzed outside a worker body");
                // A generalized function stored in a containing value is used as the
                // instance checking stored there, not as its own generalized type.
                const use_ty = site.view.static_dispatch_plans.siteInstanceType(site.expr) orelse site.view.checked_bodies.expr(site.expr).ty;
                _ = try self.analyzeType(site.view, use_ty);
                try actions.append(self.allocator, .{ .nested_callable_use_for_caller = .{
                    .view = site.view,
                    .expr = site.expr,
                    .callable_ty = typeRef(site.view, use_ty),
                    .caller = caller,
                } });
            },
            .nested_callable_use_for_caller => |state| {
                const use = CheckedExprIdentity{ .module = state.view.key, .expr = state.expr };
                for (self.plan.nested_callable_uses.items) |planned| {
                    if (planned.caller == state.caller and
                        exprRefEql(planned.use, use) and
                        typeRefEql(planned.callable_ty, state.callable_ty))
                    {
                        return;
                    }
                }
                const source = WorkerSource{ .nested_expr = .{ .module = state.view.key, .expr = state.expr } };
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{
                        .source = source,
                        .checked_type = self.workerCheckedTypeForSource(source, typeRef(state.view, state.view.checked_bodies.expr(state.expr).ty)),
                        .root_request = null,
                    } },
                    .{ .nested_callable_use_record = state },
                });
            },
            .nested_callable_use_record => |state| {
                const worker = self.plan_worker_result;
                const use = CheckedExprIdentity{ .module = state.view.key, .expr = state.expr };
                try self.analyzeUseSchemeSubstitution(worker, use);
                try self.plan.nested_callable_uses.append(self.allocator, .{
                    .use = use,
                    .caller = state.caller,
                    .worker = worker,
                    .callable_ty = state.callable_ty,
                });
            },
            .nested_callable_use => |state| {
                const source = self.workerSourceForDirectTarget(state.view, state.target);
                if (source != .nested_expr) return;
                const callable_ty = typeRef(state.view, state.view.checked_bodies.expr(state.func).ty);
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{ .source = source, .checked_type = self.workerCheckedTypeForSource(source, callable_ty), .root_request = null } },
                    .{ .nested_callable_direct_record = .{ .view = state.view, .func = state.func, .callable_ty = callable_ty } },
                });
            },
            .nested_callable_direct_record => |state| {
                const caller = self.active_worker orelse
                    boxyPlanInvariant("boxy nested callable use was analyzed outside a worker body");
                try self.plan.nested_callable_uses.append(self.allocator, .{
                    .use = .{ .module = state.view.key, .expr = state.func },
                    .caller = caller,
                    .worker = self.plan_worker_result,
                    .callable_ty = state.callable_ty,
                });
            },
            .dispatch_plan_types => |state| try self.stepDispatchPlanTypes(actions, state.view, state.plan),
            .generated_interpolation => |state| try self.stepGeneratedInterpolation(actions, state.view, state.expr, state.iter_ty),
            .generated_interpolation_done => |state| {
                var steps = state;
                steps.one_step = self.plan_worker_result;
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{ .source = .{ .generated_interpolation_step = .{
                        .step_type = steps.source_step_type,
                    } }, .checked_type = steps.source_step_type, .root_request = null } },
                    .{ .generated_interpolation_record = steps },
                });
            },
            .generated_interpolation_record => |state| try self.plan.generated_interpolations.append(self.allocator, .{
                .interpolation = state.identity,
                .caller = state.caller,
                .iter_rep = state.iter_rep,
                .one_step = state.one_step,
                .done_step = self.plan_worker_result,
            }),
            .dispatch_call_target => |site| try self.pushPlanActions(actions, &.{
                .{ .dispatch_plan_types = .{ .view = site.view, .plan = site.plan } },
                .{ .dispatch_call_after_types = site },
            }),
            .dispatch_call_after_types => |site| try self.stepDispatchCallAfterTypes(actions, site),
            .dispatch_call_after_worker => |site| try self.finishDispatchCall(site),
            .iterator_for => |state| try self.stepIteratorFor(actions, state.view, state.plan),
            .iterator_call => |site| try self.stepIteratorCall(actions, site),
            .iterator_call_after_operands => |site| try self.stepIteratorCallAfterOperands(actions, site),
            .iterator_call_after_worker => |site| try self.finishIteratorCall(site),
            .analyze_type => |state| _ = try self.analyzeType(state.view, state.ty),
            .statement => |state| try self.stepStatementTypes(actions, state.view, state.statement),
            .pattern => |state| try self.stepPatternTypes(actions, state.view, state.pattern),
            .direct_call_target => |site| {
                const call = site.view.checked_bodies.expr(site.expr).data.call;
                const target = call.direct_target orelse return;
                const source = self.workerSourceForDirectTarget(site.view, target);
                const checked_type = self.workerCheckedTypeForSource(source, typeRef(site.view, call.source_fn_ty_payload));
                const source_fn_type = self.directCallInstantiationSourceFnType(site.view, target, call.source_fn_ty_payload);
                _ = try self.analyzeType(self.moduleForId(source_fn_type.module), source_fn_type.ty);
                try self.pushPlanActions(actions, &.{
                    .{ .ensure_worker = .{ .source = source, .checked_type = checked_type, .root_request = null } },
                    .{ .direct_call_after_worker = .{ .view = site.view, .call_expr = site.expr, .source_fn_type = source_fn_type } },
                });
            },
            .direct_call_after_worker => |state| {
                const worker = self.plan_worker_result;
                const call_ref = CheckedExprIdentity{ .module = state.view.key, .expr = state.call_expr };
                const caller = self.active_worker orelse
                    boxyPlanInvariant("boxy direct call was analyzed outside a worker body");
                if (self.plan.directWorkerForCall(call_ref, caller)) |existing| {
                    if (existing != worker) {
                        boxyPlanInvariant("boxy direct call plan tried to bind a checked call to two workers");
                    }
                    return;
                }
                const call = state.view.checked_bodies.expr(state.call_expr).data.call;
                try self.plan.direct_calls.append(self.allocator, .{
                    .call = call_ref,
                    .caller = caller,
                    .worker = worker,
                    .source_fn_type = state.source_fn_type,
                    .operands = try self.appendCheckedCallOperands(call.args),
                });
                try self.analyzeDirectCallSchemeSubstitution(self.plan.direct_calls.items[self.plan.direct_calls.items.len - 1]);
            },
            .omitted_defaults => |site| {
                const start = beginPlanSequence(actions);
                for (site.view.checked_bodies.record_omitted_defaults) |entry| {
                    if (entry.expr != site.expr) continue;
                    const declaring_view = self.moduleForFieldDefaultOrigin(site.view, entry.default);
                    const default_expr = declaring_view.checked_bodies.defaultExpr(entry.default.expr_node) orelse
                        boxyPlanInvariant("defaulted record field's expression was not archived");
                    try actions.append(self.allocator, exprAction(declaring_view, default_expr));
                }
                finishPlanSequence(actions, start);
            },
            .static_const_node => |state| try self.stepStaticConstNode(actions, state),
            .static_fn_value => |state| try self.stepStaticFnValue(actions, state.store_view, state.fn_id, state.requested_rep, state.const_type),
            .static_fn_record => |state| try self.plan.static_fns.append(self.allocator, .{
                .store_module = state.store_view.key,
                .fn_id = state.fn_id,
                .rep = state.requested_rep,
                .worker = self.plan_worker_result,
            }),
            .static_fn_captures => |state| {
                const store = state.store_view.const_store.?;
                try actions.append(self.allocator, .{ .const_fn_capture = .{
                    .store_view = state.store_view,
                    .fn_value = store.getFn(state.fn_id),
                    .worker = self.plan_worker_result,
                    .visited = state.visited,
                } });
            },
            .const_fn_capture => |state| try self.stepConstFnCapture(actions, state),
            .restore_active_worker => |worker| self.active_worker = worker,
            .restore_nested_callable_args => |value| self.analyzing_nested_callable_args = value,
            .free_visited => |visited| self.freeStaticConstVisited(visited),
        }
    }

    fn stepEnsureWorker(
        self: *Builder,
        actions: *std.ArrayList(PlanAction),
        source: WorkerSource,
        checked_type: CheckedTypeIdentity,
        root_request: ?checked.RootRequest,
    ) Allocator.Error!void {
        const selected_source = self.workerSourceForCallableEvalSource(source);
        if (!workerSourceEql(selected_source, source)) {
            return try actions.append(self.allocator, .{ .ensure_worker = .{ .source = selected_source, .checked_type = checked_type, .root_request = root_request } });
        }
        const worker_type = if (source == .nested_expr)
            self.workerCheckedTypeForSource(source, checked_type)
        else
            checked_type;
        const rep = try self.analyzeType(self.moduleForId(worker_type.module), worker_type.ty);
        const definition_type = self.workerCheckedTypeForSource(source, worker_type);
        if (!typeRefEql(definition_type, worker_type)) {
            _ = try self.analyzeType(self.moduleForId(definition_type.module), definition_type.ty);
        }
        for (self.plan.workers.items) |worker| {
            if (worker.context_base == null and workerSourceEql(worker.source, source) and (source == .nested_expr or typeRefEql(worker.checked_type, worker_type))) {
                if (root_request) |request| {
                    if (worker.root_request == null) {
                        self.plan.workers.items[@intFromEnum(worker.id)].root_request = request;
                    }
                }
                self.plan_worker_result = worker.id;
                return;
            }
        }

        const worker_id: WorkerPlanId = @enumFromInt(@as(u32, @intCast(self.plan.workers.items.len)));
        const body = if (self.root_module != null and
            source != .generated_codec and
            source != .generated_field_iterator and
            source != .generated_interpolation_step)
            self.rootWorkerBody(source)
        else
            null;
        try self.plan.workers.append(self.allocator, .{
            .id = worker_id,
            .root_request = root_request,
            .source = source,
            .checked_type = worker_type,
            .rep = rep,
            .stored_fn = if (body) |resolved_body| switch (resolved_body) {
                .checked_expr => |checked_body| checked_body.stored_fn,
                .intrinsic_wrapper, .hosted_proc, .unimplemented => null,
            } else null,
        });

        switch (source) {
            .generated_codec => |codec| switch (codec.kind) {
                .parser_constructor,
                .encoder_constructor,
                => {
                    const function = (self.repQuery().functionChildren(rep)) orelse
                        boxyPlanInvariant("generated codec constructor did not have a function representation");
                    if (function.arg_count != 1) {
                        boxyPlanInvariant("generated codec constructor did not have one encoding argument");
                    }
                    const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
                    const encoding_type = children[function.args_start].source_type;
                    const checked_runtime_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
                    const contract = self.generatedCodecContractForConstructor(
                        codec,
                        worker_type,
                        encoding_type,
                        checked_runtime_type,
                    );
                    const runtime_type = typeRef(contract.view, contract.derivation.runtime_ty);
                    return try self.pushPlanActions(actions, &.{
                        .{ .ensure_worker = .{
                            .source = .{ .generated_codec = .{
                                .kind = switch (codec.kind) {
                                    .parser_constructor => .parser_runtime,
                                    .encoder_constructor => .encoder_runtime,
                                    .parser_runtime,
                                    .encoder_runtime,
                                    .encoder_record_fields,
                                    .encoder_dict_fields,
                                    .encoder_sequence_elements,
                                    .encoder_tag_payload_elements,
                                    .encoder_value_thunk,
                                    .encoder_dict_key_thunk,
                                    => unreachable,
                                },
                                .shape = typeRef(contract.view, contract.derivation.shape_ty),
                                .runtime_type = runtime_type,
                                .capture_type = typeRef(contract.view, contract.derivation.encoding_ty),
                                .contract_derivation = codec.contract_derivation,
                                .contract_expr = codec.contract_expr,
                            } },
                            .checked_type = runtime_type,
                            .root_request = null,
                        } },
                        .{ .ensure_worker_runtime_link = .{ .worker = worker_id, .body = body } },
                    });
                },
                .parser_runtime,
                => {
                    const encoding_type = codec.capture_type orelse
                        boxyPlanInvariant("generated parser runtime had no encoding capture type");
                    _ = try self.analyzeType(self.moduleForId(codec.shape.module), codec.shape.ty);
                    // The checker validated the generated body against the
                    // contract's body shape, which for a declaration-backed
                    // nominal is its own snapshot of the backing; every call
                    // subject in the contract names that snapshot.
                    const contract = self.generatedCodecContractForWorker(worker_id);
                    const body_shape = typeRef(contract.view, contract.derivation.body_shape_ty);
                    _ = try self.analyzeType(contract.view, body_shape.ty);
                    return try self.pushPlanActions(actions, &.{
                        .{ .parser_shape = .{ .worker = worker_id, .shape = body_shape, .encoding_type = encoding_type } },
                        .{ .ensure_worker_parser_runtime = .{ .worker = worker_id, .body_shape = body_shape, .body = body } },
                    });
                },
                .encoder_runtime => {
                    const encoding_type = codec.capture_type orelse
                        boxyPlanInvariant("generated encoder runtime had no encoding capture type");
                    _ = try self.analyzeType(self.moduleForId(codec.shape.module), codec.shape.ty);
                    const function = (self.repQuery().functionChildren(rep)) orelse
                        boxyPlanInvariant("generated encoder runtime did not have a function representation");
                    if (function.arg_count != 2) {
                        boxyPlanInvariant("generated encoder runtime did not have value and state arguments");
                    }
                    // As for parsers, the checker validated the generated body
                    // against the contract's body shape, and every call
                    // subject in the contract names that snapshot.
                    const contract = self.generatedCodecContractForWorker(worker_id);
                    const body_shape = typeRef(contract.view, contract.derivation.body_shape_ty);
                    _ = try self.analyzeType(contract.view, body_shape.ty);
                    return try self.pushPlanActions(actions, &.{
                        .{ .encoder_shape = .{ .worker = worker_id, .contract_worker = worker_id, .shape = body_shape, .subject_type = body_shape, .encoding_type = encoding_type } },
                        .{ .ensure_worker_encoder_runtime = .{ .worker = worker_id, .body_shape = body_shape, .body = body } },
                    });
                },
                .encoder_record_fields,
                .encoder_dict_fields,
                .encoder_sequence_elements,
                .encoder_tag_payload_elements,
                .encoder_value_thunk,
                .encoder_dict_key_thunk,
                => {},
            },
            .generated_field_iterator => {},
            .generated_interpolation_step => {},
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            => {},
        }
        try self.planWorkerBody(actions, worker_id, body);
    }

    /// Plan a new worker's body under that worker, then leave `worker` in
    /// the result register.
    fn planWorkerBody(self: *Builder, actions: *std.ArrayList(PlanAction), worker: WorkerPlanId, body: ?WorkerBody) Allocator.Error!void {
        const resolved_body = body orelse {
            self.plan_worker_result = worker;
            return;
        };
        const previous_worker = self.active_worker;
        try self.pushPlanActions(actions, &.{
            .{ .worker_body = resolved_body },
            .{ .restore_active_worker = previous_worker },
            .{ .worker_result = worker },
        });
        self.active_worker = worker;
    }

    fn stepCodecCall(self: *Builder, actions: *std.ArrayList(PlanAction), request: CodecCallRequest) Allocator.Error!void {
        const caller = request.caller;
        const dispatch_type = request.dispatch_type;
        const method_text = request.method_text;
        const subject_type = request.subject_type;
        const contract = self.generatedCodecContractForWorker(caller);
        const contract_names = contract.view.canonical_names orelse
            boxyPlanInvariant("generated codec contract module had no checked names");
        var checked_call: ?static_dispatch.GeneratedCodecCall = null;
        for (contract.derivation.callsSlice(contract.view.static_dispatch_plans)) |candidate| {
            if (!std.mem.eql(u8, contract_names.methodNameText(candidate.method), method_text)) continue;
            if (!moduleKeyEqual(dispatch_type.module, contract.view.key) or candidate.dispatcher_ty != dispatch_type.ty) continue;
            const candidate_subject = if (candidate.subject_ty) |ty| typeRef(contract.view, ty) else null;
            if (!optionalTypeRefEql(candidate_subject, subject_type)) continue;
            if (checked_call) |existing| {
                if (!std.meta.eql(
                    contract.view.checked_types.rootKey(existing.callable_ty),
                    contract.view.checked_types.rootKey(candidate.callable_ty),
                ) or !std.meta.eql(
                    contract.view.checked_types.rootKey(existing.dispatcher_ty),
                    contract.view.checked_types.rootKey(candidate.dispatcher_ty),
                )) {
                    boxyPlanInvariant("generated codec contract had ambiguous method call metadata");
                }
                continue;
            }
            checked_call = candidate;
        }
        const exact_call = checked_call orelse
            boxyPlanInvariant("generated codec contract was missing a required method call");
        const exact_dispatch_type = typeRef(contract.view, exact_call.dispatcher_ty);
        if (!typeRefEql(exact_dispatch_type, dispatch_type)) {
            boxyPlanInvariant("generated codec contract dispatcher disagreed with the planned call");
        }

        for (self.plan.generated_codec_calls.items) |planned| {
            if (planned.caller != caller or !typeRefEql(planned.dispatch_type, dispatch_type)) continue;
            if (!optionalTypeRefEql(planned.subject_type, subject_type)) continue;
            const planned_view = self.moduleForId(planned.method_module);
            const planned_names = planned_view.canonical_names orelse
                boxyPlanInvariant("planned generated codec method module had no checked names");
            if (std.mem.eql(u8, planned_names.methodNameText(planned.method), method_text)) {
                self.plan_codec_result = planned;
                return;
            }
        }

        var source: WorkerSource = undefined;
        var source_fn_type: CheckedTypeIdentity = undefined;
        var checked_evidence: Span = .{};
        var evidence_edge: ?DictionaryMethodEvidence.EvidenceEdge = null;
        switch (exact_call.resolution) {
            .callable => |node_id| blk: {
                const node = contract.view.static_dispatch_plans.evidenceNode(node_id);
                const target_view = switch (node.target.kind) {
                    .procedure => |procedure| self.moduleForCheckedModuleId(procedure.template.artifact),
                    .local_proc => contract.view,
                    .structural => boxyPlanInvariant("callable generated codec resolution named a structural target"),
                };
                const lookup = MethodTargetLookup{
                    .view = target_view,
                    .method = exact_call.method,
                    .target = node.target,
                };
                const nested = switch (node.nested) {
                    .resolved => |span| span,
                    .from_callable => boxyPlanInvariant("generated codec call retained callable-derived evidence"),
                };
                source = self.workerSourceForMethodTarget(lookup, dispatch_type, null);
                source_fn_type = .{ .module = target_view.key, .ty = node.target.callable_ty };
                checked_evidence = .{ .start = nested.start, .len = nested.len };
                const edge: DictionaryMethodEvidence.EvidenceEdge = .{ .module = contract.view.key, .node = node_id };
                try self.analyzeEvidenceEdgeSchemeSubstitution(edge);
                evidence_edge = edge;
                break :blk;
            },
            .structural => |derivation_id| blk: {
                if (@intFromEnum(derivation_id) >= contract.view.static_dispatch_plans.generated_codec_derivations.len) {
                    boxyPlanInvariant("generated codec call referenced a missing nested derivation");
                }
                const nested = contract.view.static_dispatch_plans.generated_codec_derivations[@intFromEnum(derivation_id)];
                source = .{ .generated_codec = .{
                    .kind = if (nested.kind == .parser) .parser_constructor else .encoder_constructor,
                    .shape = dispatch_type,
                    .contract_derivation = derivation_id,
                } };
                source_fn_type = .{ .module = contract.view.key, .ty = nested.constructor_ty };
                break :blk;
            },
            .pending => boxyPlanInvariant("unlinked generated codec call reached Boxy planning"),
            .checked_error => boxyPlanInvariant("rejected generated codec call reached Boxy planning"),
        }
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = source, .checked_type = source_fn_type, .root_request = null } },
            .{ .codec_call_finish = .{
                .request = request,
                .contract_view = contract.view,
                .callable_ty = exact_call.callable_ty,
                .method = exact_call.method,
                .checked_evidence = checked_evidence,
                .evidence_edge = evidence_edge,
            } },
        });
    }

    fn finishCodecCall(self: *Builder, finish: CodecCallFinish) Allocator.Error!void {
        const worker = self.plan_worker_result;
        const exact_fn_rep = try self.analyzeType(finish.contract_view, finish.callable_ty);
        const function = (self.repQuery().functionChildren(exact_fn_rep)) orelse
            boxyPlanInvariant("generated codec call contract was not a function");
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);

        const arg_start: u32 = @intCast(self.plan.generated_codec_call_types.items.len);
        for (children[function.args_start..][0..function.arg_count]) |child| {
            try self.plan.generated_codec_call_types.append(self.allocator, child.source_type);
        }
        const planned = GeneratedCodecCallPlan{
            .caller = finish.request.caller,
            .dispatch_type = finish.request.dispatch_type,
            .subject_type = finish.request.subject_type,
            .method_module = finish.contract_view.key,
            .method = finish.method,
            .worker = worker,
            .arg_types = .{ .start = arg_start, .len = function.arg_count },
            .ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type,
            .checked_evidence = finish.checked_evidence,
            .evidence_edge = finish.evidence_edge,
        };
        try self.plan.generated_codec_calls.append(self.allocator, planned);
        self.plan_codec_result = planned;
    }

    fn stepCodecCallCheckedSubject(
        self: *Builder,
        actions: *std.ArrayList(PlanAction),
        caller: WorkerPlanId,
        dispatch_type: CheckedTypeIdentity,
        method_text: []const u8,
    ) Allocator.Error!void {
        const contract = self.generatedCodecContractForWorker(caller);
        const names = contract.view.canonical_names orelse
            boxyPlanInvariant("generated codec contract module had no checked names");
        var subject_type: ?CheckedTypeIdentity = null;
        for (contract.derivation.callsSlice(contract.view.static_dispatch_plans)) |candidate| {
            if (!std.mem.eql(u8, names.methodNameText(candidate.method), method_text)) continue;
            if (!moduleKeyEqual(dispatch_type.module, contract.view.key) or candidate.dispatcher_ty != dispatch_type.ty) continue;
            const candidate_ty = candidate.subject_ty orelse
                boxyPlanInvariant("generated codec method required a checked subject but the producer recorded none");
            const candidate_type = typeRef(contract.view, candidate_ty);
            if (subject_type) |existing| {
                if (!std.meta.eql(
                    contract.view.checked_types.rootKey(existing.ty),
                    contract.view.checked_types.rootKey(candidate_type.ty),
                )) {
                    boxyPlanInvariant("generated codec method had ambiguous checked subjects");
                }
                continue;
            }
            subject_type = candidate_type;
        }
        try actions.append(self.allocator, codecCallAction(
            caller,
            dispatch_type,
            method_text,
            subject_type orelse boxyPlanInvariant("generated codec contract was missing a subject-bearing method call"),
        ));
    }

    fn stepParserShape(self: *Builder, actions: *std.ArrayList(PlanAction), request: GeneratedShape) Allocator.Error!void {
        const worker = request.worker;
        const shape = request.shape;
        const encoding_type = request.encoding_type;
        const visit = try self.generated_codec_shapes_seen.getOrPut(.{ .worker = worker, .shape = shape });
        if (visit.found_existing) return;

        const view = self.moduleForId(shape.module);
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        switch (view.checked_types.payload(shape.ty)) {
            .pending => boxyPlanInvariant("pending checked type reached generated parser planning"),
            .err => boxyPlanInvariant("checked error type reached generated parser planning"),
            .flex, .rigid => boxyPlanInvariant("open checked type reached generated parser planning"),
            .function, .empty_tag_union => boxyPlanInvariant("unsupported checked type reached generated parser planning"),
            .alias => |alias| {
                const backing = typeRef(view, alias.backing);
                try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = backing, .encoding_type = encoding_type } });
                try actions.append(self.allocator, .{ .parser_alias_links = .{ .worker = worker, .shape = shape, .backing = backing } });
            },
            .record => try actions.append(self.allocator, .{ .parser_record = request }),
            .empty_record => try self.appendParserRecordProtocol(actions, worker, shape, encoding_type),
            .tuple => |elems| {
                try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_tuple_start", shape));
                try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_tuple_next", shape));
                try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_tuple_end", shape));
                for (elems) |elem| {
                    try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = typeRef(view, elem), .encoding_type = encoding_type } });
                }
            },
            .tag_union => {
                try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_tag_union", shape));
                try actions.append(self.allocator, .{ .parser_tag_link = .{ .worker = worker, .shape = shape } });
                try self.appendParserTagRow(actions, worker, shape, encoding_type);
            },
            .nominal => |nominal| {
                if (nominal.builtin) |builtin| {
                    if (generatedParserScalarMethod(builtin)) |method_text| {
                        try actions.append(self.allocator, codecCallAction(worker, encoding_type, method_text, shape));
                        return;
                    }
                    switch (builtin) {
                        .box => {
                            if (nominal.args.len != 1) boxyPlanInvariant("Box generated parser type had unexpected arity");
                            try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = typeRef(view, nominal.args[0]), .encoding_type = encoding_type } });
                        },
                        .list => {
                            if (nominal.args.len != 1) boxyPlanInvariant("List generated parser type had unexpected arity");
                            try self.appendParserListProtocol(actions, worker, shape, encoding_type);
                            try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = typeRef(view, nominal.args[0]), .encoding_type = encoding_type } });
                        },
                        .dict => {
                            if (nominal.args.len != 2) boxyPlanInvariant("Dict generated parser type had unexpected arity");
                            const key_type = typeRef(view, nominal.args[0]);
                            try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_dict_start", shape));
                            try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_dict_next", shape));
                            try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_dict_after_key", shape));
                            try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_dict_after_entry", shape));
                            if (generatedParserKeyMethod(view, nominal.args[0])) |method_text| {
                                try actions.append(self.allocator, codecCallAction(worker, encoding_type, method_text, key_type));
                                try actions.append(self.allocator, .{ .parser_dict_key_method = .{ .worker = worker, .key_type = key_type } });
                            } else if (checkedParserUnitTagKey(view, nominal.args[0])) {
                                // The checker reads a unit-tag key as a key string at a
                                // `Str` subject of its own, then matches the tag names.
                                try actions.append(self.allocator, .{ .codec_call_checked_subject = .{ .caller = worker, .dispatch_type = encoding_type, .method_text = "parse_key_str" } });
                                try actions.append(self.allocator, .{ .parser_dict_unit_key = .{ .worker = worker, .key_type = key_type, .encoding_type = encoding_type } });
                            } else {
                                // A key with no key-string rendering is read by its own
                                // parser once the format opens the key position.
                                try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_key_start", key_type));
                                try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = key_type, .encoding_type = encoding_type } });
                                try actions.append(self.allocator, .{ .parser_dict_selection = .{ .worker = worker, .key_type = key_type, .strategy = .key_start } });
                            }
                            try actions.append(self.allocator, codecCallAction(worker, shape, "with_capacity", shape));
                            try actions.append(self.allocator, codecCallAction(worker, shape, "insert", shape));
                            try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = typeRef(view, nominal.args[1]), .encoding_type = encoding_type } });
                        },
                        .set => {
                            if (nominal.args.len != 1) boxyPlanInvariant("Set generated parser type had unexpected arity");
                            try self.appendParserListProtocol(actions, worker, shape, encoding_type);
                            try actions.append(self.allocator, codecCallAction(worker, shape, "from_list", shape));
                            try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = typeRef(view, nominal.args[0]), .encoding_type = encoding_type } });
                        },
                        .try_ => {
                            // Outside a record field, the only parseable `Try`
                            // is the nullable `Try(ok, [Null])` value shape.
                            const payloads = checkedTryPayloads(view, shape.ty) orelse
                                boxyPlanInvariant("generated Try parser had no Ok and Err payloads");
                            const kinds = checkedTryErrorKinds(view, payloads.err) orelse
                                boxyPlanInvariant("generated Try parser had unsupported error tags");
                            if (!kinds.null or kinds.missing or kinds.other) {
                                boxyPlanInvariant("generated Try parser was not the nullable [Null] shape");
                            }
                            const ok_type = typeRef(view, payloads.ok);
                            try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_null", null));
                            try actions.append(self.allocator, .{ .parser_try_plan = .{ .worker = worker, .shape = shape, .ok_type = ok_type, .err_type = typeRef(view, payloads.err), .kinds = kinds } });
                            try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = ok_type, .encoding_type = encoding_type } });
                        },
                        .bool,
                        .str,
                        .u8,
                        .i8,
                        .u16,
                        .i16,
                        .u32,
                        .i32,
                        .u64,
                        .i64,
                        .u128,
                        .i128,
                        .f32,
                        .f64,
                        .dec,
                        .u8x16,
                        .i8x16,
                        .u16x8,
                        .i16x8,
                        .u32x4,
                        .i32x4,
                        .u64x2,
                        .i64x2,
                        .iter,
                        .stream,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => boxyPlanInvariant("unsupported builtin reached generated parser planning"),
                    }
                    return;
                }

                // Every other nominal parses through its own `parser_for`:
                // a declared one, or the compiler-generated structural parser,
                // whose body the checker validated as a nested derivation of
                // its own (reached through the contract's `parser_for` edge).
                try actions.append(self.allocator, codecCallAction(worker, shape, "parser_for", shape));
            },
        }
    }

    fn appendParserListProtocol(self: *Builder, actions: *std.ArrayList(PlanAction), worker: WorkerPlanId, subject_type: CheckedTypeIdentity, encoding_type: CheckedTypeIdentity) Allocator.Error!void {
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_list_start", subject_type));
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_list_next", subject_type));
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_list_after_item", subject_type));
    }

    fn appendParserRecordProtocol(self: *Builder, actions: *std.ArrayList(PlanAction), worker: WorkerPlanId, record_type: CheckedTypeIdentity, encoding_type: CheckedTypeIdentity) Allocator.Error!void {
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_record_start", record_type));
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_record_field", record_type));
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "parse_record_after_field", record_type));
        try actions.append(self.allocator, codecCallAction(worker, encoding_type, "skip_record_field", null));
    }

    /// Append, in row order, the payload parsers of every variant along a
    /// tag row. Payload boundaries are the format's `ParseTagUnionSpec`
    /// callbacks, so a variant plans only its payload parsers.
    fn appendParserTagRow(self: *Builder, actions: *std.ArrayList(PlanAction), worker: WorkerPlanId, row_type: CheckedTypeIdentity, encoding_type: CheckedTypeIdentity) Allocator.Error!void {
        var seen = std.AutoHashMap(CheckedTypeIdentity, void).init(self.allocator);
        defer seen.deinit();
        var current = row_type;
        while (true) {
            if ((try seen.getOrPut(current)).found_existing) boxyPlanInvariant("generated parser tag row was cyclic");
            const view = self.moduleForId(current.module);
            switch (view.checked_types.payload(current.ty)) {
                .tag_union => |row| {
                    for (row.tags) |tag| {
                        for (tag.argsSlice(view.checked_types)) |arg| {
                            try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = typeRef(view, arg), .encoding_type = encoding_type } });
                        }
                    }
                    current = typeRef(view, row.ext);
                },
                .alias => |alias| current = typeRef(view, alias.backing),
                .nominal => |nominal| {
                    const backing = try self.nominalBackingSource(view, nominal);
                    current = typeRef(backing.view, backing.ty);
                },
                .empty_tag_union => return,
                .flex, .rigid => |variable| {
                    if (variable.row_default != .empty_tag_union) {
                        boxyPlanInvariant("generated parser tag row had a nonempty open extension");
                    }
                    return;
                },
                .pending => boxyPlanInvariant("pending tag row reached generated parser planning"),
                .err, .record, .tuple, .function, .empty_record => boxyPlanInvariant("generated parser tag row extension was not a tag row"),
            }
        }
    }

    fn stepParserRecord(self: *Builder, actions: *std.ArrayList(PlanAction), shape: GeneratedShape) Allocator.Error!void {
        const fields = try self.generatedRecordCheckedFields(shape.shape);
        errdefer self.allocator.free(fields);
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        try self.appendParserRecordProtocol(actions, shape.worker, shape.shape, shape.encoding_type);
        if (fields.len != 0) try actions.append(self.allocator, codecCallAction(shape.worker, shape.encoding_type, "rename_field", null));
        try actions.append(self.allocator, .{ .parser_record_fields = .{ .shape = shape, .fields = fields, .rename_ret = if (fields.len != 0) undefined else null } });
    }

    fn stepParserRecordFields(self: *Builder, actions: *std.ArrayList(PlanAction), state: ParserRecordFields) Allocator.Error!void {
        var fields_state = state;
        errdefer self.allocator.free(fields_state.fields);
        if (fields_state.index == 0 and fields_state.fields.len != 0) fields_state.rename_ret = self.plan_codec_result.ret_type;
        if (fields_state.index == fields_state.fields.len) {
            self.allocator.free(fields_state.fields);
            if (fields_state.needs_required) try self.planGeneratedParserMissingRequiredField(fields_state.shape.worker);
            return;
        }
        const worker = fields_state.shape.worker;
        const planned_field = fields_state.fields[fields_state.index];
        const field_view = self.moduleForId(planned_field.module);
        const field = planned_field.field;
        const field_type = typeRef(field_view, field.ty);
        const parser_kind: GeneratedParserFieldKind = switch (field.kind.tag) {
            .optional => .optional_slot,
            .undetermined => .undetermined_slot,
            .defaulted => .{ .defaulted = .{ .module = field_view.key, .default = field.kind.default } },
            .err => boxyPlanInvariant("checked-error record field reached generated parser planning"),
            // Only a builtin `Try(ok, [Missing])` field of the required
            // kind may otherwise be absent; every other field parses at
            // its own type, including a nullable `Try(ok, [Null])`.
            .required => if (checkedTryPayloads(field_view, field.ty)) |payloads|
                if (checkedTryErrorKinds(field_view, payloads.err)) |kinds|
                    if (kinds.missing and !kinds.null and !kinds.other)
                        .{ .missing_try = typeRef(field_view, payloads.err) }
                    else
                        .required
                else
                    .required
            else
                .required,
        };
        const parse_type = switch (parser_kind) {
            .missing_try => typeRef(field_view, checkedTryPayloads(field_view, field.ty).?.ok),
            .required, .optional_slot, .undetermined_slot, .defaulted => field_type,
        };
        try self.plan.generated_parser_field_captures.append(self.allocator, .{
            .worker = worker,
            .record_type = fields_state.shape.shape,
            .field_module = field_view.key,
            .field_name = field.name,
            .source_type = fields_state.rename_ret.?,
            .parse_type = parse_type,
            .parser_kind = parser_kind,
        });
        var next = fields_state;
        next.index += 1;
        var default_worker: ?WorkerPlanId = null;
        const start = beginPlanSequence(actions);
        switch (parser_kind) {
            .required, .undetermined_slot => next.needs_required = true,
            .missing_try, .optional_slot => {},
            .defaulted => |defaulted| {
                const declaring_view = self.moduleForFieldDefaultOrigin(field_view, defaulted.default);
                const default_expr = declaring_view.checked_bodies.defaultExpr(defaulted.default.expr_node) orelse
                    boxyPlanInvariant("defaulted record field's expression was not archived");
                try actions.append(self.allocator, exprAction(declaring_view, default_expr));
                try actions.append(self.allocator, .{ .restore_active_worker = self.active_worker });
                default_worker = worker;
            },
        }
        try actions.append(self.allocator, .{ .parser_shape = .{ .worker = worker, .shape = parse_type, .encoding_type = fields_state.shape.encoding_type } });
        try actions.append(self.allocator, .{ .parser_record_fields = next });
        finishPlanSequence(actions, start);
        if (default_worker) |default_expr_worker| self.active_worker = default_expr_worker;
    }

    fn stepEncoderShape(self: *Builder, actions: *std.ArrayList(PlanAction), request: EncoderShape) Allocator.Error!void {
        const worker = request.worker;
        const contract_worker = request.contract_worker;
        const shape = request.shape;
        const subject_type = request.subject_type;
        const encoding_type = request.encoding_type;
        const visit = try self.generated_codec_shapes_seen.getOrPut(.{ .worker = worker, .shape = shape });
        if (visit.found_existing) return;

        const view = self.moduleForId(shape.module);
        switch (view.checked_types.payload(shape.ty)) {
            .pending => boxyPlanInvariant("pending checked type reached generated encoder planning"),
            .err => boxyPlanInvariant("checked error type reached generated encoder planning"),
            .flex, .rigid => boxyPlanInvariant("open checked type reached generated encoder planning"),
            .function, .empty_tag_union => boxyPlanInvariant("unsupported checked type reached generated encoder planning"),
            .alias => {
                const shape_rep = try self.analyzeType(view, shape.ty);
                const backing = requiredSingleChildOf(&self.plan, shape_rep, .alias_backing);
                try actions.append(self.allocator, .{ .encoder_shape = .{ .worker = worker, .contract_worker = contract_worker, .shape = backing.source_type, .subject_type = subject_type, .encoding_type = encoding_type } });
            },
            .record, .empty_record => try actions.append(self.allocator, .{ .encoder_record = request }),
            .tuple => |elems| try actions.append(self.allocator, .{ .encoder_sequence = .{
                .worker = worker,
                .contract_worker = contract_worker,
                .sequence_shape = shape,
                .sequence_type = subject_type,
                .item_view = view,
                .item_types = elems,
                .encoding_type = encoding_type,
                .method_text = "encode_tuple",
            } }),
            .tag_union => try actions.append(self.allocator, .{ .encoder_tag_union = request }),
            .nominal => |nominal| {
                if (nominal.builtin) |builtin| {
                    if (generatedEncoderScalarMethod(builtin)) |method_text| {
                        try actions.append(self.allocator, codecCallAction(worker, encoding_type, method_text, subject_type));
                        return;
                    }
                    switch (builtin) {
                        .box => {
                            if (nominal.args.len != 1) boxyPlanInvariant("Box generated encoder type had unexpected arity");
                            const payload = typeRef(view, nominal.args[0]);
                            try actions.append(self.allocator, .{ .encoder_shape = .{ .worker = worker, .contract_worker = contract_worker, .shape = payload, .subject_type = payload, .encoding_type = encoding_type } });
                        },
                        .list => {
                            if (nominal.args.len != 1) boxyPlanInvariant("List generated encoder type had unexpected arity");
                            try actions.append(self.allocator, .{ .encoder_list = .{
                                .worker = worker,
                                .contract_worker = contract_worker,
                                .list_shape = shape,
                                .list_type = subject_type,
                                .encode_subject_type = subject_type,
                                .elem_type = typeRef(view, nominal.args[0]),
                                .encoding_type = encoding_type,
                            } });
                        },
                        .set => {
                            if (nominal.args.len != 1) boxyPlanInvariant("Set generated encoder type had unexpected arity");
                            try self.pushPlanActions(actions, &.{
                                codecCallAction(worker, shape, "to_list", shape),
                                .{ .encoder_set = .{ .shape = request, .elem_type = typeRef(view, nominal.args[0]) } },
                            });
                        },
                        .dict => {
                            if (nominal.args.len != 2) boxyPlanInvariant("Dict generated encoder type had unexpected arity");
                            try actions.append(self.allocator, .{ .encoder_dict = .{
                                .worker = worker,
                                .contract_worker = contract_worker,
                                .dict_shape = shape,
                                .dict_type = subject_type,
                                .key_type = typeRef(view, nominal.args[0]),
                                .value_type = typeRef(view, nominal.args[1]),
                                .encoding_type = encoding_type,
                            } });
                        },
                        .try_ => {
                            const try_payloads = checkedTryPayloads(view, shape.ty) orelse
                                boxyPlanInvariant("Builtin.Try generated encoder type had no payloads");
                            const kinds = checkedTryErrorKinds(view, try_payloads.err) orelse
                                boxyPlanInvariant("generated Try encoder had unsupported error tags");
                            if (kinds.other) {
                                boxyPlanInvariant("generated Try encoder had unsupported error tags");
                            }
                            if (kinds.missing) {
                                boxyPlanInvariant("generated root Try encoder included Missing");
                            }
                            var found = false;
                            for (self.plan.generated_encoder_try_plans.items) |planned| {
                                if (planned.worker == worker and typeRefEql(planned.try_type, shape)) {
                                    if (!typeRefEql(planned.ok_type, typeRef(view, try_payloads.ok)) or
                                        planned.missing != kinds.missing or planned.null != kinds.null)
                                    {
                                        boxyPlanInvariant("generated Try encoder shape had conflicting plans");
                                    }
                                    found = true;
                                    break;
                                }
                            }
                            if (!found) try self.plan.generated_encoder_try_plans.append(self.allocator, .{
                                .worker = worker,
                                .try_type = shape,
                                .ok_type = typeRef(view, try_payloads.ok),
                                .missing = kinds.missing,
                                .null = kinds.null,
                            });
                            const ok_type = typeRef(view, try_payloads.ok);
                            const start = beginPlanSequence(actions);
                            defer finishPlanSequence(actions, start);
                            if (kinds.null) try actions.append(self.allocator, codecCallAction(worker, encoding_type, "encode_null", null));
                            try actions.append(self.allocator, .{ .encoder_shape = .{ .worker = worker, .contract_worker = contract_worker, .shape = ok_type, .subject_type = ok_type, .encoding_type = encoding_type } });
                        },
                        .bool,
                        .str,
                        .u8,
                        .i8,
                        .u16,
                        .i16,
                        .u32,
                        .i32,
                        .u64,
                        .i64,
                        .u128,
                        .i128,
                        .f32,
                        .f64,
                        .dec,
                        .u8x16,
                        .i8x16,
                        .u16x8,
                        .i16x8,
                        .u32x4,
                        .i32x4,
                        .u64x2,
                        .i64x2,
                        .iter,
                        .stream,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => boxyPlanInvariant("unsupported builtin reached generated encoder planning"),
                    }
                    return;
                }

                if (methodOwnerForModuleType(view, shape.ty)) |owner| {
                    if (view.canonical_names.?.lookupMethodName("encoder_for")) |encoder_for| {
                        if (self.lookupMethodTarget(view, owner, view, encoder_for)) |lookup| {
                            switch (lookup.target.kind) {
                                // A declared encoder, or the compiler-generated
                                // structural encoder, whose body the checker
                                // validated as a nested derivation of its own
                                // (reached through the contract's `encoder_for`
                                // edge).
                                .procedure, .local_proc => {
                                    try actions.append(self.allocator, codecCallAction(worker, shape, "encoder_for", shape));
                                    return;
                                },
                                .structural => |kind| switch (kind) {
                                    .encoder => {
                                        try actions.append(self.allocator, codecCallAction(worker, shape, "encoder_for", shape));
                                        return;
                                    },
                                    .parser => boxyPlanInvariant("encoder planning resolved to generated parser target"),
                                    .equality, .hash, .map, .map_effectful => boxyPlanInvariant("encoder planning resolved to a non-encoder structural target"),
                                },
                            }
                        }
                    }
                }

                const shape_rep = try self.analyzeType(view, shape.ty);
                const backing = requiredSingleChildOf(&self.plan, shape_rep, .nominal_backing);
                try actions.append(self.allocator, .{ .encoder_shape = .{ .worker = worker, .contract_worker = contract_worker, .shape = backing.source_type, .subject_type = subject_type, .encoding_type = encoding_type } });
            },
        }
    }

    /// The source type of an encoder call's element writer's thunk argument:
    /// the call's `body_index` argument is a callable whose second argument
    /// writes one element, and that writer's `thunk_index` argument is the
    /// element thunk.
    fn generatedEncoderThunkType(self: *Builder, call: GeneratedCodecCallPlan, arg_count: usize, body_index: usize, writer_arity: u32, thunk_index: usize, comptime what: []const u8) Allocator.Error!CheckedTypeIdentity {
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != arg_count) boxyPlanInvariant(what);
        const body_rep = try self.analyzeType(self.moduleForId(arg_types[body_index].module), arg_types[body_index].ty);
        const body_fn = (self.repQuery().functionChildren(body_rep)) orelse
            boxyPlanInvariant("generated encoder body argument was not callable");
        if (body_fn.arg_count != 2) boxyPlanInvariant("generated encoder body had an unexpected arity");
        const body_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(body_fn.rep)].children);
        const body_args = body_children[body_fn.args_start..][0..body_fn.arg_count];
        const writer_fn = (self.repQuery().functionChildren(body_args[1].rep)) orelse
            boxyPlanInvariant("generated encoder element writer was not callable");
        if (writer_fn.arg_count != writer_arity) boxyPlanInvariant("generated encoder element writer had an unexpected arity");
        const writer_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(writer_fn.rep)].children);
        const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
        return writer_args[thunk_index].source_type;
    }

    fn stepEncoderSequenceBody(self: *Builder, actions: *std.ArrayList(PlanAction), sequence: EncoderSequence) Allocator.Error!void {
        const encode_call = self.plan_codec_result;
        const thunk_type = try self.generatedEncoderThunkType(encode_call, 3, 2, 2, 1, "generated sequence encoder call did not have three arguments");
        const arg_types = self.plan.generatedCodecCallTypeSlice(encode_call.arg_types);
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                .kind = .encoder_sequence_elements,
                .shape = sequence.sequence_shape,
                .value_type = sequence.sequence_type,
                .capture_type = sequence.encoding_type,
                .contract_worker = sequence.contract_worker,
                .contract_expr = self.generatedCodecSourceForWorker(sequence.contract_worker).contract_expr,
            } }, .checked_type = arg_types[2], .root_request = null } },
            .{ .encoder_sequence_elements = .{ .sequence = sequence, .thunk_type = thunk_type } },
        });
    }

    fn stepEncoderListBody(self: *Builder, actions: *std.ArrayList(PlanAction), list: EncoderList) Allocator.Error!void {
        const encode_call = self.plan_codec_result;
        const thunk_type = try self.generatedEncoderThunkType(encode_call, 3, 2, 2, 1, "generated list encoder call did not have three arguments");
        const arg_types = self.plan.generatedCodecCallTypeSlice(encode_call.arg_types);
        const contract_expr = self.generatedCodecSourceForWorker(list.contract_worker).contract_expr;
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                .kind = .encoder_sequence_elements,
                .shape = list.list_shape,
                .value_type = list.list_type,
                .capture_type = list.encoding_type,
                .contract_worker = list.contract_worker,
                .contract_expr = contract_expr,
            } }, .checked_type = arg_types[2], .root_request = null } },
            .{ .encoder_list_elements = .{ .list = list, .thunk_type = thunk_type, .contract_expr = contract_expr } },
        });
    }

    fn stepEncoderDictBody(self: *Builder, actions: *std.ArrayList(PlanAction), dict: EncoderDict, to_list_ret: CheckedTypeIdentity) Allocator.Error!void {
        const encode_dict = self.plan_codec_result;
        const key_thunk_type = try self.generatedEncoderThunkType(encode_dict, 3, 2, 3, 1, "generated Dict encode_dict call did not have three arguments");
        const value_thunk_type = try self.generatedEncoderThunkType(encode_dict, 3, 2, 3, 2, "generated Dict encode_dict call did not have three arguments");
        const arg_types = self.plan.generatedCodecCallTypeSlice(encode_dict.arg_types);
        const contract_expr = self.generatedCodecSourceForWorker(dict.contract_worker).contract_expr;
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                .kind = .encoder_dict_fields,
                .shape = to_list_ret,
                .value_type = to_list_ret,
                .capture_type = dict.encoding_type,
                .contract_worker = dict.contract_worker,
                .contract_expr = contract_expr,
            } }, .checked_type = arg_types[2], .root_request = null } },
            .{ .encoder_dict_fields = .{ .dict = dict, .key_thunk_type = key_thunk_type, .value_thunk_type = value_thunk_type, .contract_expr = contract_expr } },
        });
    }

    fn stepEncoderDictKeyThunk(
        self: *Builder,
        actions: *std.ArrayList(PlanAction),
        dict: EncoderDict,
        fields_worker: WorkerPlanId,
        value_thunk_type: CheckedTypeIdentity,
        contract_expr: ?CheckedExprIdentity,
    ) Allocator.Error!void {
        const key_thunk_worker = self.plan_worker_result;
        try self.recordGeneratedCallable(fields_worker, key_thunk_worker);
        const key_type = dict.key_type;
        const encoding_type = dict.encoding_type;
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        if (generatedEncoderKeyMethod(self.moduleForId(key_type.module), key_type.ty)) |method_text| {
            try actions.append(self.allocator, codecCallAction(key_thunk_worker, encoding_type, method_text, key_type));
        } else if (self.generatedCodecContractRecordsCall(key_thunk_worker, encoding_type, "encode_key_start", key_type)) {
            try actions.append(self.allocator, codecCallAction(key_thunk_worker, encoding_type, "encode_key_start", key_type));
            try actions.append(self.allocator, .{ .encoder_shape = .{ .worker = key_thunk_worker, .contract_worker = dict.contract_worker, .shape = key_type, .subject_type = key_type, .encoding_type = encoding_type } });
        } else {
            try actions.append(self.allocator, .{ .codec_call_checked_subject = .{ .caller = key_thunk_worker, .dispatch_type = encoding_type, .method_text = "encode_key_str" } });
        }
        try actions.append(self.allocator, .{ .encoder_dict_value_thunk = .{ .dict = dict, .fields_worker = fields_worker, .value_thunk_type = value_thunk_type, .contract_expr = contract_expr } });
    }

    fn stepEncoderTagUnion(self: *Builder, actions: *std.ArrayList(PlanAction), shape: EncoderShape) Allocator.Error!void {
        const tag_rep = try self.analyzeType(self.moduleForId(shape.shape.module), shape.shape.ty);
        const row_reps = try self.generatedEncoderTagRowReps(tag_rep);
        errdefer self.allocator.free(row_reps);

        var has_variant = false;
        for (row_reps) |row_rep| {
            const row = self.plan.representations.items[@intFromEnum(row_rep)];
            if (row.tag_variants.len != 0) has_variant = true;
        }
        if (!has_variant) boxyPlanInvariant("generated encoder tag union had no variants");
        try self.pushPlanActions(actions, &.{
            codecCallAction(shape.worker, shape.encoding_type, "encode_tag", shape.subject_type),
            .{ .encoder_tag_union_body = .{ .shape = shape, .row_reps = row_reps } },
        });
    }

    fn stepEncoderTagUnionBody(self: *Builder, actions: *std.ArrayList(PlanAction), state: EncoderTagUnion) Allocator.Error!void {
        var tag_union = state;
        errdefer self.allocator.free(tag_union.row_reps);
        const encode_tag = self.plan_codec_result;
        tag_union.thunk_type = try self.generatedEncoderThunkType(encode_tag, 4, 3, 2, 1, "generated tag encoder encode_tag call did not have four arguments");
        const arg_types = self.plan.generatedCodecCallTypeSlice(encode_tag.arg_types);
        tag_union.contract_expr = self.generatedCodecSourceForWorker(tag_union.shape.contract_worker).contract_expr;
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                .kind = .encoder_tag_payload_elements,
                .shape = tag_union.shape.shape,
                .value_type = tag_union.shape.subject_type,
                .capture_type = tag_union.shape.encoding_type,
                .contract_worker = tag_union.shape.contract_worker,
                .contract_expr = tag_union.contract_expr,
            } }, .checked_type = arg_types[3], .root_request = null } },
            .{ .encoder_tag_union_payloads = tag_union },
        });
    }

    fn stepEncoderTagUnionPayload(self: *Builder, actions: *std.ArrayList(PlanAction), state: EncoderTagUnion) Allocator.Error!void {
        var cursor = state;
        errdefer self.allocator.free(cursor.row_reps);
        while (cursor.row < cursor.row_reps.len) {
            const row = self.plan.representations.items[@intFromEnum(cursor.row_reps[cursor.row])];
            const variants = self.plan.tagVariantSlice(row.tag_variants);
            if (cursor.variant == variants.len) {
                cursor.row += 1;
                cursor.variant = 0;
                cursor.payload = 0;
                continue;
            }
            const payloads = self.plan.childSlice(variants[cursor.variant].payloads);
            if (cursor.payload == payloads.len) {
                cursor.variant += 1;
                cursor.payload = 0;
                continue;
            }
            const payload = payloads[cursor.payload];
            cursor.payload += 1;
            return try self.pushPlanActions(actions, &.{
                .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                    .kind = .encoder_value_thunk,
                    .shape = payload.source_type,
                    .capture_type = cursor.shape.encoding_type,
                    .contract_worker = cursor.shape.contract_worker,
                    .contract_expr = cursor.contract_expr,
                } }, .checked_type = cursor.thunk_type, .root_request = null } },
                .{ .encoder_thunk = .{ .owner = cursor.payload_worker, .contract_worker = cursor.shape.contract_worker, .shape = payload.source_type, .encoding_type = cursor.shape.encoding_type, .null_call = false } },
                .{ .encoder_tag_union_payload = cursor },
            });
        }
        self.allocator.free(cursor.row_reps);
    }

    fn stepEncoderRecord(self: *Builder, actions: *std.ArrayList(PlanAction), shape: EncoderShape) Allocator.Error!void {
        const fields = try self.generatedRecordCheckedFields(shape.shape);
        errdefer self.allocator.free(fields);
        try self.pushPlanActions(actions, &.{
            codecCallAction(shape.worker, shape.encoding_type, "encode_record", shape.subject_type),
            .{ .encoder_record_body = .{ .shape = shape, .fields = fields } },
        });
    }

    fn stepEncoderRecordBody(self: *Builder, actions: *std.ArrayList(PlanAction), state: EncoderRecord) Allocator.Error!void {
        var record = state;
        errdefer self.allocator.free(record.fields);
        const encode_call = self.plan_codec_result;
        record.thunk_type = try self.generatedEncoderThunkType(encode_call, 3, 2, 3, 2, "generated encode_record call did not have three arguments");
        const arg_types = self.plan.generatedCodecCallTypeSlice(encode_call.arg_types);
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                .kind = .encoder_record_fields,
                .shape = record.shape.shape,
                .value_type = record.shape.subject_type,
                .capture_type = record.shape.encoding_type,
                .contract_worker = record.shape.contract_worker,
                .contract_expr = self.generatedCodecSourceForWorker(record.shape.contract_worker).contract_expr,
            } }, .checked_type = arg_types[2], .root_request = null } },
            .{ .encoder_record_fields_worker = record },
        });
    }

    fn stepEncoderRecordField(self: *Builder, actions: *std.ArrayList(PlanAction), state: EncoderRecord) Allocator.Error!void {
        var record = state;
        errdefer self.allocator.free(record.fields);
        if (record.index == record.fields.len) {
            self.allocator.free(record.fields);
            return;
        }
        const contract_worker = record.shape.contract_worker;
        const encoding_type = record.shape.encoding_type;
        const record_shape = record.shape.shape;
        const planned_field = record.fields[record.index];
        record.index += 1;
        const field_view = self.moduleForId(planned_field.module);
        const field = planned_field.field;
        const field_type = typeRef(field_view, field.ty);
        const try_payloads = checkedTryPayloads(field_view, field.ty);
        const encode_type = if (try_payloads) |payloads| typeRef(field_view, payloads.ok) else field_type;
        const optional_kinds = if (try_payloads) |payloads|
            checkedTryErrorKinds(field_view, payloads.err) orelse
                boxyPlanInvariant("generated record encoder Try field had unsupported error tags")
        else
            null;
        if (optional_kinds) |kinds| {
            if (kinds.other) {
                boxyPlanInvariant("generated record encoder Try field had unsupported error tags");
            }
        }
        var found_capture = false;
        for (self.plan.generated_parser_field_captures.items) |capture| {
            if (capture.worker == contract_worker and
                typeRefEql(capture.record_type, record_shape) and
                moduleKeyEqual(capture.field_module, field_view.key) and
                capture.field_name == field.name)
            {
                found_capture = true;
                break;
            }
        }
        if (!found_capture) {
            try self.plan.generated_parser_field_captures.append(self.allocator, .{
                .worker = contract_worker,
                .record_type = record_shape,
                .field_module = field_view.key,
                .field_name = field.name,
                .source_type = record.rename_ret.?,
                .parse_type = encode_type,
                .optional_error_type = if (try_payloads) |payloads| typeRef(field_view, payloads.err) else null,
                .optional_missing = if (optional_kinds) |kinds| kinds.missing else false,
                .optional_null = if (optional_kinds) |kinds| kinds.null else false,
            });
        }
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_codec = .{
                .kind = .encoder_value_thunk,
                .shape = encode_type,
                .value_type = if (try_payloads != null) field_type else null,
                .optional_missing = if (optional_kinds) |kinds| kinds.missing else false,
                .optional_null = if (optional_kinds) |kinds| kinds.null else false,
                .capture_type = encoding_type,
                .contract_worker = contract_worker,
                .contract_expr = self.generatedCodecSourceForWorker(contract_worker).contract_expr,
            } }, .checked_type = record.thunk_type, .root_request = null } },
            .{ .encoder_thunk = .{
                .owner = record.fields_worker,
                .contract_worker = contract_worker,
                .shape = encode_type,
                .encoding_type = encoding_type,
                .null_call = if (optional_kinds) |kinds| kinds.null else false,
            } },
            .{ .encoder_record_field = record },
        });
    }

    fn stepInspectMethods(self: *Builder, actions: *std.ArrayList(PlanAction), rep_id: TypeRepId) Allocator.Error!void {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.inspect_demanded) return;
        self.plan.representations.items[@intFromEnum(rep_id)].inspect_demanded = true;
        self.inspect_demand_count += 1;
        if (rep.kind == .erased_callable) return;
        const view = self.moduleForId(rep.source_type.module);
        if (rep.kind == .primitive) {
            switch (Common.primitiveInspectLowering(rep.kind.primitive)) {
                .low_level, .bool_tag_union => return,
                .builtin_method => {},
            }
        }
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        // Only the nominal's own representation owns its inspect method. A
        // wrapper that shares the nominal's checked type (an alias, or a
        // field-presence slot around it) reaches the method through its child.
        const owns_methods = rep.kind == .nominal or rep.kind == .primitive;
        if (if (owns_methods) methodOwnerForModuleType(view, rep.source_type.ty) else null) |owner| {
            if (self.lookupInspectOverride(view, owner)) |lookup| {
                if (self.plan.inspectMethodForRep(rep_id) == null) {
                    const source = self.workerSourceForMethodTarget(lookup, rep.source_type, null);
                    const source_fn_type = CheckedTypeIdentity{ .module = lookup.view.key, .ty = lookup.target.callable_ty };
                    _ = try self.analyzeType(lookup.view, lookup.target.callable_ty);
                    try actions.append(self.allocator, .{ .ensure_worker = .{ .source = source, .checked_type = source_fn_type, .root_request = null } });
                    try actions.append(self.allocator, .{ .inspect_override = .{ .rep_id = rep_id, .lookup = lookup, .source_fn_type = source_fn_type } });
                }
            }
        }
        for (0..rep.children.len) |child_index| {
            const child = self.plan.children.items[@as(usize, rep.children.start) + child_index];
            try actions.append(self.allocator, .{ .inspect_methods = child.rep });
        }
    }

    fn finishInspectOverride(self: *Builder, rep_id: TypeRepId, lookup: MethodTargetLookup, source_fn_type: CheckedTypeIdentity) Allocator.Error!void {
        const worker = self.plan_worker_result;
        // An eligible inspect override has type `T -> Str` where `T`
        // is the owning nominal (design.md "Inspect Overrides"), so
        // the worker's receiver is its only argument, analyzed in
        // the override's declaring view.
        const source_fn_rep = self.plan.repForSourceType(source_fn_type) orelse
            boxyPlanInvariant("planned boxy inspect override callable type was not analyzed");
        const source_function = self.repQuery().functionChildren(source_fn_rep) orelse
            boxyPlanInvariant("planned boxy inspect override callable type was not callable");
        if (source_function.arg_count != 1) {
            boxyPlanInvariant("planned boxy inspect override callable had unexpected receiver arity");
        }
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const source = self.workerSourceForMethodTarget(lookup, rep.source_type, null);
        const evidence: DictionaryMethodEvidence.EvidenceEdge = .{
            .module = lookup.view.key,
            .node = lookup.inspect_evidence orelse
                boxyPlanInvariant("planned boxy inspect target had no checked use evidence"),
        };
        try self.analyzeEvidenceEdgeSchemeSubstitution(evidence);
        const nested = inspectUseNestedEvidence(lookup.view, evidence.node);
        try self.observeNumeralEvidence(lookup.view, nested, self.workerEvidenceParams(source));
        for (nested) |entry| _ = try self.analyzeType(lookup.view, entry.dispatcher_ty);
        try self.plan.inspect_methods.append(self.allocator, .{
            .source_rep = rep_id,
            .worker = worker,
            .method_module = lookup.view.key,
            .method = lookup.method orelse
                boxyPlanInvariant("planned boxy inspect target had no checked method identity"),
            .evidence = evidence,
        });
    }

    fn stepIntrinsicWrapper(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, wrapper: checked.IntrinsicWrapper) Allocator.Error!void {
        const function = checkedFunctionPayload(view, wrapper.checked_fn_root);
        switch (wrapper.intrinsic) {
            .str_inspect => {
                if (function.args.len != 1) {
                    boxyPlanInvariant("Str.inspect intrinsic wrapper had an unexpected arity");
                }
                _ = try self.analyzeType(view, function.args[0]);
                _ = try self.analyzeType(view, function.ret);
            },
            .structural_eq => boxyPlanInvariant("structural equality intrinsic wrapper must lower through checked dispatch plans"),
            .field_names_iter => {
                for (function.args) |arg| _ = try self.analyzeType(view, arg);
                _ = try self.analyzeType(view, function.ret);
                try actions.append(self.allocator, .{ .field_iterator = .all });
            },
            .field_names_for_size => {
                for (function.args) |arg| _ = try self.analyzeType(view, arg);
                _ = try self.analyzeType(view, function.ret);
                try actions.append(self.allocator, .{ .field_iterator = .for_size });
            },
            .parse_tag_union,
            .field_names_rename_fields,
            .field_names_shortest_name,
            .field_names_longest_name,
            .field_name,
            => {
                for (function.args) |arg| _ = try self.analyzeType(view, arg);
                _ = try self.analyzeType(view, function.ret);
            },
        }
    }

    fn stepFieldIterator(self: *Builder, actions: *std.ArrayList(PlanAction), mode: GeneratedFieldIteratorMode) Allocator.Error!void {
        const intrinsic_worker = self.active_worker orelse
            boxyPlanInvariant("FieldNames iterator intrinsic was analyzed outside a worker");
        const intrinsic = self.plan.workers.items[@intFromEnum(intrinsic_worker)];
        const function = (self.repQuery().functionChildren(intrinsic.rep)) orelse
            boxyPlanInvariant("FieldNames iterator intrinsic was not callable");
        const expected_arity: u32 = switch (mode) {
            .all => 1,
            .for_size => 2,
        };
        if (function.arg_count != expected_arity) {
            boxyPlanInvariant("FieldNames iterator intrinsic had an unexpected arity");
        }

        const function_children = self.plan.childSlice(
            self.plan.representations.items[@intFromEnum(function.rep)].children,
        );
        const field_names_type = function_children[function.args_start].source_type;
        const iter_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
        const size_type: ?CheckedTypeIdentity = switch (mode) {
            .all => null,
            .for_size => function_children[function.args_start + 1].source_type,
        };
        const len_if_known = try self.generatedRecordFieldForRep(function.ret, "len_if_known");
        const index_type = (try self.generatedTagPayloadForRep(len_if_known.rep, "Known")).source_type;
        const step = try self.generatedRecordFieldForRep(function.ret, "step");
        const step_function = (self.repQuery().functionChildren(step.rep)) orelse
            boxyPlanInvariant("FieldNames iterator step field was not callable");
        if (step_function.arg_count != 0) {
            boxyPlanInvariant("FieldNames iterator step worker was not zero-argument");
        }
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_field_iterator = .{
                .mode = mode,
                .field_names_type = field_names_type,
                .iter_type = iter_type,
                .index_type = index_type,
                .size_type = size_type,
            } }, .checked_type = step.source_type, .root_request = null } },
            .{ .field_iterator_link = intrinsic_worker },
        });
    }

    fn stepExprTypes(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, expr_id: checked.CheckedExprId) Allocator.Error!void {
        const worker = self.active_worker orelse
            boxyPlanInvariant("checked expression was analyzed outside a worker body");
        const entry = try self.body_exprs_seen.getOrPut(.{
            .expr = .{ .module = view.key, .expr = expr_id },
            .worker = worker,
        });
        if (entry.found_existing) return;

        const bodies = view.checked_bodies;
        const expr = bodies.expr(expr_id);
        // A runtime error has no value, so its own type is never analyzed;
        // the operands it evaluates before it crashes are ordinary
        // expressions.
        if (expr.data == .runtime_error) {
            const start = beginPlanSequence(actions);
            defer finishPlanSequence(actions, start);
            for (expr.data.runtime_error.evaluated) |operand| try actions.append(self.allocator, exprAction(view, operand));
            return;
        }
        const expr_rep = try self.analyzeType(view, expr.ty);
        // A nested callable's own type belongs to that callable's worker.
        if (expr.data != .lambda and expr.data != .closure) try self.recordWorkerBodyType(worker, expr_rep);

        const site: ViewExpr = .{ .view = view, .expr = expr_id };
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        switch (expr.data) {
            .pending => boxyPlanInvariant("pending checked expression reached boxy body type planning"),
            .numeral => |numeral| try actions.append(self.allocator, .{ .numeral_conversion = .{ .view = view, .expr = expr_id, .plan = numeral.plan } }),
            .str_segment,
            .bytes_literal,
            .empty_list,
            .zero_argument_tag,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            .break_,
            => {},
            .empty_record => try actions.append(self.allocator, .{ .omitted_defaults = site }),
            .str_from_quote => |quote| try actions.append(self.allocator, .{ .quote_conversion = .{ .view = view, .expr = expr_id, .plan = quote.plan } }),
            .lookup_local,
            .lookup_external,
            .lookup_required,
            => try actions.append(self.allocator, .{ .callable_lookup = site }),
            .str,
            .list,
            .tuple,
            => |items| for (items) |item| try actions.append(self.allocator, exprAction(view, item)),
            .match_ => |match| {
                try actions.append(self.allocator, exprAction(view, match.cond));
                for (match.branches) |branch| {
                    for (branch.patternsSlice(bodies)) |branch_pattern| {
                        try actions.append(self.allocator, patternAction(view, branch_pattern.pattern));
                    }
                    if (branch.guard) |guard| try actions.append(self.allocator, exprAction(view, guard));
                    try actions.append(self.allocator, exprAction(view, branch.value));
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch| {
                    try actions.append(self.allocator, exprAction(view, branch.cond));
                    try actions.append(self.allocator, exprAction(view, branch.body));
                }
                try actions.append(self.allocator, exprAction(view, if_.final_else));
            },
            .call => |call| {
                const direct_target: ?checked.ResolvedValueId = if (call.direct_target) |target|
                    if (self.directTargetIsThroughAlias(view, target)) null else target
                else
                    null;
                if (call.direct_target != null and direct_target == null) {
                    try self.plan.alias_calls.append(self.allocator, .{ .module = view.key, .expr = expr_id });
                }
                const local_proc_direct_target = if (direct_target) |target|
                    self.directTargetIsLocalProc(view, target)
                else
                    false;
                const local_proc_worker_call = local_proc_direct_target and self.directTargetHasNoCaptures(view, direct_target.?);
                if (direct_target == null or (local_proc_direct_target and !local_proc_worker_call)) {
                    try actions.append(self.allocator, exprAction(view, call.func));
                } else {
                    const func = view.checked_bodies.expr(call.func);
                    _ = try self.analyzeType(view, func.ty);
                }
                for (call.args) |arg| try actions.append(self.allocator, exprAction(view, arg));
                try actions.append(self.allocator, .{ .call_after_args = site });
            },
            .record => |record| {
                if (record.ext) |ext| try actions.append(self.allocator, exprAction(view, ext));
                for (record.fields) |field| try actions.append(self.allocator, exprAction(view, field.value));
                try actions.append(self.allocator, .{ .omitted_defaults = site });
            },
            .block => try actions.append(self.allocator, .{ .block_statement = .{ .view = view, .block = expr_id, .index = 0 } }),
            .tag => |tag| for (tag.args) |arg| try actions.append(self.allocator, exprAction(view, arg)),
            .nominal => |nominal| try actions.append(self.allocator, exprAction(view, nominal.backing_expr)),
            .closure => {
                try actions.append(self.allocator, .{ .nested_callable_expr_use = site });
                for (nestedCallableRuntimeCaptures(view, expr_id)) |capture| try actions.append(self.allocator, patternAction(view, capture.pattern));
            },
            .lambda => {
                try actions.append(self.allocator, .{ .nested_callable_expr_use = site });
                for (nestedCallableRuntimeCaptures(view, expr_id)) |capture| try actions.append(self.allocator, patternAction(view, capture.pattern));
                try actions.append(self.allocator, .{ .lambda_args = site });
            },
            .binop => |binop| {
                try actions.append(self.allocator, exprAction(view, binop.lhs));
                try actions.append(self.allocator, exprAction(view, binop.rhs));
            },
            .unary_minus,
            .unary_not,
            .expect,
            => |child| try actions.append(self.allocator, exprAction(view, child)),
            .dbg => |child| try actions.append(self.allocator, .{ .inspect_expr = .{ .view = view, .expr = child } }),
            .field_access => |access| try actions.append(self.allocator, exprAction(view, access.receiver)),
            .interpolation => |interpolation| {
                try actions.append(self.allocator, exprAction(view, interpolation.first));
                for (interpolation.parts) |part| {
                    try actions.append(self.allocator, exprAction(view, part.value));
                    try actions.append(self.allocator, exprAction(view, part.following_segment));
                }
                try actions.append(self.allocator, .{ .interpolation_after_parts = site });
            },
            .structural_eq => |eq| {
                if (eq.discriminant) |discriminant| {
                    try actions.append(self.allocator, exprAction(view, discriminant.value));
                    return;
                }
                try actions.append(self.allocator, exprAction(view, eq.lhs));
                try actions.append(self.allocator, exprAction(view, eq.rhs));
                try actions.append(self.allocator, .{ .derived_root_after_operands = .{ .view = view, .expr = expr_id, .worker = worker } });
            },
            .structural_hash => |hash| {
                try actions.append(self.allocator, exprAction(view, hash.value));
                try actions.append(self.allocator, exprAction(view, hash.hasher));
                try actions.append(self.allocator, .{ .derived_root_after_operands = .{ .view = view, .expr = expr_id, .worker = worker } });
            },
            .dispatch_call, .type_dispatch_call, .method_eq => |plan| try actions.append(self.allocator, .{ .dispatch_call_target = .{ .view = view, .call_expr = expr_id, .plan = plan } }),
            .tuple_access => |access| try actions.append(self.allocator, exprAction(view, access.tuple)),
            .expect_err => |expect_err| try actions.append(self.allocator, .{ .inspect_expr = .{ .view = view, .expr = expect_err.expr } }),
            .return_ => |ret| try actions.append(self.allocator, exprAction(view, ret.expr)),
            .for_ => |for_| {
                try actions.append(self.allocator, .{ .iterator_for = .{ .view = view, .plan = for_.plan } });
                try actions.append(self.allocator, patternAction(view, for_.pattern));
                try actions.append(self.allocator, exprAction(view, for_.expr));
                try actions.append(self.allocator, exprAction(view, for_.body));
            },
            .hosted_lambda => |hosted| for (hosted.args) |arg| try actions.append(self.allocator, patternAction(view, arg)),
            .run_low_level => |run| {
                for (run.args) |arg| try actions.append(self.allocator, exprAction(view, arg));
                try actions.append(self.allocator, .{ .low_level_after_args = site });
            },
        }
    }

    fn stepQuoteConversion(self: *Builder, actions: *std.ArrayList(PlanAction), site: ConversionSite) Allocator.Error!void {
        const view = site.view;
        const expr_id = site.expr;
        const plan_id = site.plan orelse return;
        const dispatch_action: PlanAction = .{ .dispatch_call_target = .{ .view = view, .call_expr = expr_id, .plan = site.plan } };
        switch (view.static_dispatch_plans.plans[@intFromEnum(plan_id)].resolution) {
            .evidence_dependent => {
                try self.recordLiteralSite(view, expr_id, plan_id);
                return try actions.append(self.allocator, dispatch_action);
            },
            .checked_error, .@"unreachable" => return try actions.append(self.allocator, dispatch_action),
            .direct_closed, .direct_parametric => {},
            .direct_pending, .structural => boxyPlanInvariant("quote conversion had an invalid checked dispatch resolution"),
        }
        // A conversion reaching a local procedure that needs its declaration
        // context runs where that context exists: in place, at runtime.
        if (self.conversionNeedsFrameContext(view, plan_id)) {
            try self.recordInPlaceConversion(view, expr_id);
            return try actions.append(self.allocator, dispatch_action);
        }
        const root_id = view.checked_bodies.literalConversionRoot(expr_id) orelse {
            try self.recordLiteralSite(view, expr_id, plan_id);
            return try actions.append(self.allocator, dispatch_action);
        };
        const root = view.compile_time_roots.root(root_id);
        switch (root.payload) {
            .const_node => |node| {
                const store = view.const_store orelse
                    boxyPlanInvariant("finalized from_quote conversion module had no ConstStore");
                switch (store.get(node)) {
                    .crash, .checked_error => return,
                    .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .tag, .nominal, .fn_value => {},
                }
                try self.pushStaticConstRoot(actions, view, node, try self.analyzeType(view, view.checked_bodies.expr(expr_id).ty), null);
            },
            .pending => {
                try self.recordLiteralSite(view, expr_id, plan_id);
                try actions.append(self.allocator, dispatch_action);
            },
            .fn_value,
            .discarded,
            .expect,
            .runtime,
            => boxyPlanInvariant("from_quote conversion root had a non-data payload"),
        }
    }

    /// Whether a literal's direct conversion selects a local procedure with
    /// runtime captures, as its target or in that target's nested evidence.
    fn conversionNeedsFrameContext(self: *Builder, view: ModuleView, plan_id: static_dispatch.StaticDispatchPlanId) bool {
        if (!self.has_capturing_local_methods) return false;
        const plans = view.static_dispatch_plans;
        const node_id = switch (plans.plans[@intFromEnum(plan_id)].resolution) {
            .direct_closed, .direct_parametric => |direct| direct.evidence,
            .direct_pending, .evidence_dependent, .structural, .checked_error, .@"unreachable" => return false,
        };
        return self.evidenceNodeNeedsFrameContext(view, node_id);
    }

    /// A literal whose worker received its conversion method as a context
    /// input converts through that input where it runs, in place, rather
    /// than through compile-time literal evaluation, which has no frame to
    /// construct the input from.
    fn separateContextLiteralSites(self: *Builder) Allocator.Error!void {
        if (!self.has_capturing_local_methods) return;
        var kept: usize = 0;
        for (self.plan.literal_sites.items) |site| {
            if (self.literalSiteUsesContext(site)) {
                const expr = site.source;
                if (!self.plan.convertsInPlace(expr)) try self.plan.in_place_conversions.append(self.allocator, expr);
                continue;
            }
            self.plan.literal_sites.items[kept] = site;
            kept += 1;
        }
        self.plan.literal_sites.shrinkRetainingCapacity(kept);
    }

    fn literalSiteUsesContext(self: *Builder, site: LiteralSite) bool {
        const worker = self.plan.workers.items[@intFromEnum(site.worker)];
        if (worker.context.len == 0) return false;
        const dispatch = self.plan.dictionaryDispatchPlanForCall(site.source, site.worker) orelse return false;
        const requirement = dispatch.scheme_requirement orelse blk: {
            const view = self.moduleForId(site.source.module);
            const dictionaries = self.plan.representations.items[@intFromEnum(dispatch.dispatcher_rep)].dictionaries;
            const name = view.canonical_names.?.methodNameText(dispatch.method);
            for (self.plan.dictionarySlice(dictionaries), 0..) |candidate, offset| {
                const candidate_view = self.moduleForId(candidate.source_type.module);
                if (std.mem.eql(u8, name, candidate_view.canonical_names.?.methodNameText(candidate.fn_name)))
                    break :blk @as(DictionaryRequirementId, @enumFromInt(dictionaries.start + offset));
            }
            return false;
        };
        return self.plan.workerContextInput(site.worker, .{ .requirement = requirement }) != null;
    }

    fn recordInPlaceConversion(self: *Builder, view: ModuleView, expr_id: checked.CheckedExprId) Allocator.Error!void {
        const expr = CheckedExprIdentity{ .module = view.key, .expr = expr_id };
        if (self.plan.convertsInPlace(expr)) return;
        try self.plan.in_place_conversions.append(self.allocator, expr);
    }

    fn evidenceNodeNeedsFrameContext(self: *Builder, view: ModuleView, node_id: static_dispatch.EvidenceNodeId) bool {
        const plans = view.static_dispatch_plans;
        const node = plans.evidenceNode(node_id);
        switch (node.target.kind) {
            .local_proc => |local| if (!self.nestedCallableHasNoCaptures(.{ .module = view.key, .expr = local.expr })) return true,
            .procedure, .structural => {},
        }
        const nested = switch (node.nested) {
            .resolved => plans.nestedEvidence(node),
            .from_callable => return false,
        };
        for (nested) |evidence| switch (evidence.resolution) {
            .direct => |child| if (self.evidenceNodeNeedsFrameContext(view, child)) return true,
            .constraint, .structural, .from_callable, .from_scheme, .checked_error, .unreachable_value => {},
        };
        return false;
    }

    fn stepNumeralConversion(self: *Builder, actions: *std.ArrayList(PlanAction), site: ConversionSite) Allocator.Error!void {
        const view = site.view;
        const expr_id = site.expr;
        const maybe_plan = site.plan;
        const root_id = view.checked_bodies.literalConversionRoot(expr_id) orelse {
            const plan_id = maybe_plan orelse return;
            const dispatch = view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
            // A parametric nominal's conversion is selected explicitly by
            // checking even though its value cannot be a checked constant yet.
            // Builtin numeral representation operations retain their existing
            // descriptor-guided lowering.
            switch (dispatch.resolution) {
                .direct_closed, .direct_parametric => {
                    const owner = methodOwnerForModuleType(view, dispatch.dispatcher_ty) orelse
                        boxyPlanInvariant("direct numeral conversion omitted its checked owner");
                    if (owner == .builtin) return;
                    if (self.conversionNeedsFrameContext(view, plan_id))
                        try self.recordInPlaceConversion(view, expr_id)
                    else
                        try self.recordLiteralSite(view, expr_id, plan_id);
                    return try actions.append(self.allocator, .{ .dispatch_call_target = .{ .view = view, .call_expr = expr_id, .plan = plan_id } });
                },
                .evidence_dependent => {
                    try self.generic_numeral_sites.append(self.allocator, .{
                        .source = .{ .module = view.key, .expr = expr_id },
                        .worker = self.active_worker orelse boxyPlanInvariant("generic numeral had no worker"),
                        .dispatch = plan_id,
                    });
                    return;
                },
                .checked_error, .@"unreachable" => return,
                .direct_pending, .structural => boxyPlanInvariant("numeral conversion had an invalid checked dispatch resolution"),
            }
        };
        const root = view.compile_time_roots.root(root_id);
        switch (root.payload) {
            .const_node => |node| {
                const store = view.const_store orelse
                    boxyPlanInvariant("finalized from_numeral conversion module had no ConstStore");
                switch (store.get(node)) {
                    .crash, .checked_error => return,
                    .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .tag, .nominal, .fn_value => {},
                }
                try self.pushStaticConstRoot(actions, view, node, try self.analyzeType(view, view.checked_bodies.expr(expr_id).ty), null);
            },
            .pending => {
                try self.recordLiteralSite(view, expr_id, maybe_plan orelse
                    boxyPlanInvariant("pending custom numeral omitted its conversion plan"));
                try actions.append(self.allocator, .{ .dispatch_call_target = .{ .view = view, .call_expr = expr_id, .plan = maybe_plan } });
            },
            .fn_value,
            .discarded,
            .expect,
            .runtime,
            => boxyPlanInvariant("from_numeral conversion root had a non-data payload"),
        }
    }

    /// Analyze a stored constant's nodes under a visited set of their own.
    fn pushStaticConstRoot(
        self: *Builder,
        actions: *std.ArrayList(PlanAction),
        store_view: ModuleView,
        node: checked.ConstNodeId,
        rep_id: TypeRepId,
        const_type: ?check.ConstStore.ConstTypeId,
    ) Allocator.Error!void {
        const visited = try self.newStaticConstVisited();
        errdefer self.freeStaticConstVisited(visited);
        try self.pushPlanActions(actions, &.{
            .{ .static_const_node = .{ .store_view = store_view, .node = node, .rep_id = rep_id, .const_type = const_type, .visited = visited } },
            .{ .free_visited = visited },
        });
    }

    fn stepCallableLookupAfterConst(self: *Builder, actions: *std.ArrayList(PlanAction), site: ViewExpr) Allocator.Error!void {
        const view = site.view;
        const expr = view.checked_bodies.expr(site.expr);
        const ref_id = switch (expr.data) {
            .lookup_local => |lookup| lookup.resolved.?,
            .lookup_external, .lookup_required => |resolved| resolved.?,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => unreachable,
        };
        const stored_fn = self.storedFnSourceForProcedureValueRef(view, ref_id);
        const source = if (stored_fn) |stored|
            try self.workerSourceForStoredFnAtType(stored, typeRef(view, expr.ty))
        else
            self.workerSourceForProcedureValueRef(view, ref_id) orelse return;
        if (self.pendingCallableEvalExprForSource(source)) |runtime_source| {
            const source_view = self.moduleForId(runtime_source.module);
            return try self.pushPlanActions(actions, &.{
                exprAction(source_view, runtime_source.expr),
                .{ .callable_lookup_runtime = .{ .view = view, .expr = site.expr, .runtime_source = runtime_source } },
            });
        }
        // A lookup instantiates the callable boundary, not its worker body.
        // The body retains its declaration's variables and dictionary ABI.
        const checked_type = self.workerCheckedTypeForSource(source, typeRef(view, expr.ty));
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = source, .checked_type = checked_type, .root_request = null } },
            .{ .callable_lookup_worker = .{ .view = view, .expr = site.expr, .stored_fn = stored_fn } },
        });
    }

    fn stepConstDefinition(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, ref_id: checked.ResolvedValueRefId) Allocator.Error!void {
        const record = self.resolvedValueRecord(view, ref_id);
        const const_use = if (record.ref == .selected_hoisted_const)
            record.ref.selected_hoisted_const.const_use
        else if (record.ref == .top_level_const)
            record.ref.top_level_const
        else if (record.ref == .imported_const)
            record.ref.imported_const
        else if (record.ref == .platform_required_const)
            record.ref.platform_required_const.const_use
        else
            return;
        // The lowerer restores the const through its use-site requested type
        // (`beginRestoreConstUse`), so that type's representation must be
        // planned. The enclosing expression's type is not always the same
        // node as the requested payload type in module graphs whose root is
        // not the app itself.
        if (const_use.requested_source_ty_payload) |requested_ty| {
            _ = try self.analyzeType(view, requested_ty);
        }
        const store_view = self.moduleForId(checked.constModuleId(const_use.const_ref));
        // A constant whose value is computed by evaluating a body (rather than
        // a compile-time-stored value) is produced at runtime by calling the
        // constant's entry-wrapper thunk. Plan that thunk as a worker so the
        // lowerer can emit the call.
        const const_templates = store_view.const_templates orelse return;
        switch (const_templates.get(const_use.const_ref).state) {
            .eval_template => |eval| {
                const start = beginPlanSequence(actions);
                defer finishPlanSequence(actions, start);
                try actions.append(self.allocator, .{ .ensure_worker = .{
                    .source = .{ .procedure_template = eval.entry_template },
                    .checked_type = self.checkedTypeForTemplate(eval.entry_template),
                    .root_request = null,
                } });
                if (const_use.requested_source_ty_payload) |requested_ty| {
                    try actions.append(self.allocator, .{ .const_eval_call = .{ .view = view, .requested_ty = requested_ty } });
                }
            },
            .stored_const => |stored| {
                const producer_ty = self.constProducerCheckedType(store_view, const_use.const_ref);
                const producer_rep = try self.analyzeStoredType(
                    store_view,
                    stored.root_type,
                    typeRef(store_view, producer_ty),
                );
                try self.pushStaticConstRoot(actions, store_view, stored.node, producer_rep, stored.root_type);
            },
            // Neither a reserved template nor a declaration without an
            // implementation contributes a value to plan for.
            .reserved, .unimplemented => {},
        }
    }

    /// A dispatch that cannot run (`checked_error` or `unreachable`) calls no
    /// method: it evaluates its operands and then crashes. Its plan is the
    /// source operands it evaluates, exactly the expressions its lowering
    /// evaluates; it selects no worker and binds no dictionary.
    fn pushCrashingDispatchOperands(
        self: *Builder,
        actions: *std.ArrayList(PlanAction),
        view: ModuleView,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!void {
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        for (plan.argsSlice(view.static_dispatch_plans)) |operand| switch (operand) {
            .checked_expr => |expr| try actions.append(self.allocator, exprAction(view, expr)),
            .generated_interpolation_iter => |expr| {
                const interpolation = switch (view.checked_bodies.expr(expr).data) {
                    .interpolation => |value| value,
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyPlanInvariant("crashing interpolation iterator referenced a non-interpolation expression"),
                };
                try actions.append(self.allocator, exprAction(view, interpolation.first));
                for (interpolation.parts) |part| {
                    try actions.append(self.allocator, exprAction(view, part.value));
                    try actions.append(self.allocator, exprAction(view, part.following_segment));
                }
            },
            .generated_numeral, .generated_quote => {},
        };
    }

    fn stepDispatchPlanTypes(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, maybe_plan: ?static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        const plan_id = maybe_plan orelse
            boxyPlanInvariant("checked dispatch expression reached boxy planning without a dispatch plan");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.plans.len) {
            boxyPlanInvariant("checked dispatch expression referenced a missing dispatch plan");
        }
        const plan = view.static_dispatch_plans.plans[raw];
        if (dispatchCannotRun(plan.resolution)) return try self.pushCrashingDispatchOperands(actions, view, plan);
        _ = try self.analyzeType(view, plan.dispatcher_ty);
        _ = try self.analyzeType(view, plan.callable_ty);
        const operands = plan.argsSlice(view.static_dispatch_plans);
        const callable = checkedFunctionPayload(view, plan.callable_ty);
        if (operands.len != callable.args.len) {
            boxyPlanInvariant("checked dispatch operand arity disagreed with its callable type");
        }
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        for (operands, callable.args) |operand, formal_ty| {
            switch (operand) {
                .checked_expr => |operand_expr| try actions.append(self.allocator, exprAction(view, operand_expr)),
                .generated_interpolation_iter => |operand_expr| {
                    try actions.append(self.allocator, exprAction(view, operand_expr));
                    try actions.append(self.allocator, .{ .generated_interpolation = .{ .view = view, .expr = operand_expr, .iter_ty = formal_ty } });
                },
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
    }

    fn stepGeneratedInterpolation(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, expr_id: checked.CheckedExprId, iter_ty: checked.CheckedTypeId) Allocator.Error!void {
        const caller = self.active_worker orelse
            boxyPlanInvariant("generated interpolation was planned outside a worker body");
        const identity = CheckedExprIdentity{ .module = view.key, .expr = expr_id };
        if (self.plan.generatedInterpolationPlan(identity, caller) != null) return;

        const expr = view.checked_bodies.expr(expr_id);
        if (expr.data != .interpolation) {
            boxyPlanInvariant("generated interpolation operand pointed at a non-interpolation expression");
        }
        const interpolation = expr.data.interpolation;
        const iter_rep = try self.analyzeType(view, iter_ty);
        const step = try self.generatedRecordFieldForRep(iter_rep, "step");
        const step_function = (self.repQuery().functionChildren(step.rep)) orelse
            boxyPlanInvariant("generated interpolation iterator step field was not callable");
        if (step_function.arg_count != 0) {
            boxyPlanInvariant("generated interpolation iterator step worker was not zero-argument");
        }
        const source_step_type = typeRef(view, interpolation.step_fn_ty);
        const source_step_rep = try self.analyzeType(view, interpolation.step_fn_ty);
        const source_step_function = (self.repQuery().functionChildren(source_step_rep)) orelse
            boxyPlanInvariant("checked generated interpolation step type was not callable");
        if (source_step_function.arg_count != 0) {
            boxyPlanInvariant("checked generated interpolation step worker was not zero-argument");
        }
        const one_payload = try self.generatedTagPayloadForRep(source_step_function.ret, "One");
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = .{ .generated_interpolation_step = .{
                .step_type = source_step_type,
                .one_payload_type = one_payload.source_type,
            } }, .checked_type = source_step_type, .root_request = null } },
            .{ .generated_interpolation_done = .{ .identity = identity, .caller = caller, .iter_rep = iter_rep, .source_step_type = source_step_type } },
        });
    }

    fn stepDispatchCallAfterTypes(self: *Builder, actions: *std.ArrayList(PlanAction), site: DispatchCallSite) Allocator.Error!void {
        const view = site.view;
        const plan_id = site.plan orelse
            boxyPlanInvariant("checked dispatch expression reached boxy planning without a dispatch plan");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.plans.len) {
            boxyPlanInvariant("checked dispatch expression referenced a missing dispatch plan");
        }
        const dispatch = view.static_dispatch_plans.plans[raw];
        // A dispatch that cannot run has no method target or dictionary; its
        // operands were planned by `pushCrashingDispatchOperands`.
        if (dispatchCannotRun(dispatch.resolution)) return;
        const dispatcher_rep = try self.analyzeType(view, dispatch.dispatcher_ty);
        // A transparent alias dispatches through its backing, so the
        // dispatcher's dictionaries are those of its alias-unwrapped
        // representation.
        const dictionary_rep = self.repQuery().dictionaryArgumentIdentityRep(dispatcher_rep);
        if (structuralCodecDispatchWorker(view, dispatch)) |codec| {
            // The checked plan selected the compiler-generated codec for this
            // structural dispatcher; the call runs that codec's constructor.
            try self.pushPlanActions(actions, &.{
                .{ .ensure_worker = .{ .source = codec.source, .checked_type = codec.worker_type, .root_request = null } },
                .{ .dispatch_call_after_worker = site },
            });
            return;
        }
        const evidence = directDispatchEvidence(view.static_dispatch_plans, dispatch.resolution);
        if (evidence == null) {
            const caller = self.active_worker orelse
                boxyPlanInvariant("boxy dictionary dispatch was analyzed outside a worker body");
            const scheme_requirement: ?DictionaryRequirementId = if (dispatch.resolution == .evidence_dependent and dispatch.resolution.evidence_dependent.scheme_param != null) blk: {
                const dictionary = try self.requireWorkerSchemeDictionary(caller, .{
                    .module = view.key,
                    .param = dispatch.resolution.evidence_dependent.scheme_param.?,
                    .callable_contract = dispatch.resolution.evidence_dependent.callable_contract,
                });
                break :blk dictionary.dispatch_requirement orelse
                    boxyPlanInvariant("checked dictionary owner had no method requirement");
            } else blk: {
                try self.recordActiveWorkerDictionaryUse(dictionary_rep);
                break :blk null;
            };
            if (scheme_requirement == null and self.plan.representations.items[@intFromEnum(dictionary_rep)].dictionaries.len == 0) {
                try self.registerStructuralDispatchDerivation(view, caller, dispatch, dispatcher_rep);
            }
            if (scheme_requirement != null or self.plan.representations.items[@intFromEnum(dictionary_rep)].dictionaries.len != 0) {
                const call_ref = CheckedExprIdentity{ .module = view.key, .expr = site.call_expr };
                if (self.plan.dictionaryDispatchPlanForCall(call_ref, caller) == null) {
                    try self.plan.dictionary_dispatches.append(self.allocator, .{
                        .call = call_ref,
                        .caller = caller,
                        .dispatcher_rep = dictionary_rep,
                        .scheme_requirement = scheme_requirement,
                        .method = dispatch.method,
                        .source_fn_type = typeRef(view, dispatch.callable_ty),
                        .operands = try self.appendDispatchCallOperands(dispatch, view.static_dispatch_plans),
                    });
                }
            }
        }
        const selected = evidence orelse return;
        const lookup = self.dispatchMethodTargetLookup(
            view,
            selected.target,
            typeRef(view, dispatch.dispatcher_ty),
        );
        if (lookup.source == .nested_expr and !self.nestedCallableHasNoCaptures(lookup.source.nested_expr)) {
            // A local procedure that needs values of its declaration context
            // is constructed from this frame, as a lookup of its binding
            // would construct it, and the dispatch calls that callable. The
            // use is the dispatch itself, so its evidence edge supplies the
            // procedure's instantiation and nested evidence.
            const caller = self.active_worker orelse
                boxyPlanInvariant("boxy local procedure dispatch was analyzed outside a worker body");
            const callable_ty = selectedDispatchCallableType(view, lookup.view, selected);
            _ = try self.analyzeType(self.moduleForId(callable_ty.module), callable_ty.ty);
            try self.pushPlanActions(actions, &.{
                .{ .ensure_worker = .{
                    .source = lookup.source,
                    .checked_type = self.workerCheckedTypeForSource(lookup.source, callable_ty),
                    .root_request = null,
                } },
                .{ .nested_callable_use_record = .{
                    .view = view,
                    .expr = site.call_expr,
                    .callable_ty = callable_ty,
                    .caller = caller,
                } },
            });
            return;
        }
        // The worker is the target's generalized declaration; the call
        // boundary is this edge's instantiation of it. They are separate
        // checked identities and neither substitutes for the other.
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{
                .source = lookup.source,
                .checked_type = self.workerCheckedTypeForSource(lookup.source, typeRef(view, dispatch.callable_ty)),
                .root_request = null,
            } },
            .{ .dispatch_call_after_worker = site },
        });
    }

    fn finishDispatchCall(self: *Builder, site: DispatchCallSite) Allocator.Error!void {
        const worker = self.plan_worker_result;
        const view = site.view;
        const dispatch = view.static_dispatch_plans.plans[@intFromEnum(site.plan.?)];
        const source_fn_type = if (structuralCodecDispatchWorker(view, dispatch) != null)
            typeRef(view, dispatch.callable_ty)
        else blk: {
            const selected = directDispatchEvidence(view.static_dispatch_plans, dispatch.resolution).?;
            const lookup = self.dispatchMethodTargetLookup(
                view,
                selected.target,
                typeRef(view, dispatch.dispatcher_ty),
            );
            break :blk selectedDispatchCallableType(view, lookup.view, selected);
        };
        _ = try self.analyzeType(self.moduleForId(source_fn_type.module), source_fn_type.ty);
        const call_ref = CheckedExprIdentity{ .module = view.key, .expr = site.call_expr };
        const caller = self.active_worker orelse
            boxyPlanInvariant("boxy dispatch call was analyzed outside a worker body");
        if (self.plan.directWorkerForCall(call_ref, caller)) |existing| {
            if (existing != worker) {
                boxyPlanInvariant("boxy dispatch call plan tried to bind a checked call to two workers");
            }
            return;
        }
        try self.plan.direct_calls.append(self.allocator, .{
            .call = call_ref,
            .caller = caller,
            .worker = worker,
            .source_fn_type = source_fn_type,
            .operands = try self.appendDispatchCallOperands(dispatch, view.static_dispatch_plans),
        });
        try self.analyzeDirectCallSchemeSubstitution(self.plan.direct_calls.items[self.plan.direct_calls.items.len - 1]);
    }

    const StructuralCodecDispatchWorker = struct {
        source: WorkerSource,
        worker_type: CheckedTypeIdentity,
    };

    /// The generated codec constructor a checked structural `parser_for` or
    /// `encoder_for` call runs, declared at its checked derivation's source
    /// roles, or null for any other resolution.
    fn structuralCodecDispatchWorker(
        view: ModuleView,
        dispatch: static_dispatch.StaticDispatchCallPlan,
    ) ?StructuralCodecDispatchWorker {
        const derivation = switch (dispatch.resolution) {
            .structural => |derivation| derivation,
            .direct_pending, .direct_closed, .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => return null,
        };
        const kind: GeneratedCodecKind = switch (derivation.kind()) {
            .parser => .parser_constructor,
            .encoder => .encoder_constructor,
            .equality, .hash, .map, .map_effectful => return null,
        };
        const derivation_id = dispatch.generated_codec_derivation orelse
            boxyPlanInvariant("structural codec dispatch had no checked derivation reference");
        if (@intFromEnum(derivation_id) >= view.static_dispatch_plans.generated_codec_derivations.len) {
            boxyPlanInvariant("structural codec dispatch referenced a missing checked derivation");
        }
        const contract = view.static_dispatch_plans.generated_codec_derivations[@intFromEnum(derivation_id)];
        return .{
            .source = .{ .generated_codec = .{
                .kind = kind,
                .shape = typeRef(view, contract.source_shape_ty),
                .contract_derivation = derivation_id,
            } },
            .worker_type = typeRef(view, contract.source_constructor_ty),
        };
    }

    fn stepIteratorFor(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, maybe_plan: ?static_dispatch.IteratorForPlanId) Allocator.Error!void {
        const plan_id = maybe_plan orelse
            boxyPlanInvariant("checked iterator for reached boxy planning without an iterator dispatch plan");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.iterator_for_plans.len) {
            boxyPlanInvariant("checked iterator for referenced a missing iterator dispatch plan");
        }
        const plan = view.static_dispatch_plans.iterator_for_plans[raw];

        if (iteratorPlanDoesNotExecute(plan)) return;

        _ = try self.analyzeType(view, plan.item_ty);
        _ = try self.analyzeType(view, plan.iterator_ty);
        _ = try self.analyzeType(view, plan.step_ty);
        try self.pushPlanActions(actions, &.{
            .{ .iterator_call = .{ .view = view, .plan_id = plan_id, .plan = plan, .kind = .iter, .call = plan.iter, .ret_type = typeRef(view, plan.iterator_ty) } },
            .{ .iterator_call = .{ .view = view, .plan_id = plan_id, .plan = plan, .kind = .next, .call = plan.next, .ret_type = typeRef(view, plan.step_ty) } },
        });
    }

    fn stepIteratorCall(self: *Builder, actions: *std.ArrayList(PlanAction), site: IteratorCallSite) Allocator.Error!void {
        const view = site.view;
        _ = try self.analyzeType(view, site.call.dispatcher_ty);
        _ = try self.analyzeType(view, site.call.callable_ty);
        _ = try self.analyzeType(self.moduleForId(site.ret_type.module), site.ret_type.ty);
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        for (site.call.argsSlice(view.static_dispatch_plans)) |operand| {
            switch (operand) {
                .checked_expr => |expr| try actions.append(self.allocator, exprAction(view, expr)),
                .loop_iterator_state => try actions.append(self.allocator, .{ .analyze_type = .{ .view = view, .ty = site.plan.iterator_ty } }),
            }
        }
        try actions.append(self.allocator, .{ .iterator_call_after_operands = site });
    }

    fn stepIteratorCallAfterOperands(self: *Builder, actions: *std.ArrayList(PlanAction), site: IteratorCallSite) Allocator.Error!void {
        const view = site.view;
        const dispatcher_rep = try self.analyzeType(view, site.call.dispatcher_ty);
        const evidence = directDispatchEvidence(view.static_dispatch_plans, site.call.resolution);
        if (evidence == null) {
            try self.recordActiveWorkerDictionaryUse(self.repQuery().dictionaryArgumentIdentityRep(dispatcher_rep));
        }
        const selected = evidence orelse return;
        const lookup = self.dispatchMethodTargetLookup(
            view,
            selected.target,
            typeRef(view, site.call.dispatcher_ty),
        );
        // As in ordinary dispatch planning, the worker is the protocol
        // method's generalized declaration while the call boundary is this
        // edge's instantiation of it. A local procedure that needs values of
        // its declaration context is reached through its specialization
        // receiving its runtime captures from the calling frame.
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{
                .source = lookup.source,
                .checked_type = self.workerCheckedTypeForSource(lookup.source, typeRef(view, site.call.callable_ty)),
                .root_request = null,
            } },
            .{ .iterator_call_after_worker = site },
        });
    }

    fn finishIteratorCall(self: *Builder, site: IteratorCallSite) Allocator.Error!void {
        const worker = self.plan_worker_result;
        const view = site.view;
        const call = site.call;
        const plan = site.plan;
        const selected = directDispatchEvidence(view.static_dispatch_plans, call.resolution).?;
        const lookup = self.dispatchMethodTargetLookup(
            view,
            selected.target,
            typeRef(view, call.dispatcher_ty),
        );
        const source_fn_type = selectedDispatchCallableType(view, lookup.view, selected);
        const source_view = self.moduleForId(source_fn_type.module);
        _ = try self.analyzeType(source_view, source_fn_type.ty);

        const caller = self.active_worker orelse
            boxyPlanInvariant("boxy iterator call was analyzed outside a worker body");
        if (self.plan.iteratorCallPlanFor(view.key, site.plan_id, site.kind, caller)) |existing| {
            const existing_base = self.plan.workers.items[@intFromEnum(existing.worker)].context_base orelse existing.worker;
            if (existing_base != worker or !typeRefEql(existing.source_fn_type, source_fn_type)) {
                boxyPlanInvariant("boxy iterator dispatch plan tried to bind a checked iterator call to two workers");
            }
            return;
        }

        const source_fn = checkedFunctionPayload(source_view, source_fn_type.ty);
        const operands = call.argsSlice(view.static_dispatch_plans);
        if (source_fn.args.len != operands.len) {
            boxyPlanInvariant("boxy iterator dispatch source function type arity disagreed with operands");
        }
        const worker_plan = self.plan.workers.items[@intFromEnum(worker)];
        const worker_function = (self.repQuery().functionChildren(worker_plan.rep)) orelse
            boxyPlanInvariant("boxy iterator dispatch worker was not a function");
        if (worker_function.arg_count != operands.len) {
            boxyPlanInvariant("boxy iterator dispatch worker arity disagreed with operands");
        }
        const worker_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(worker_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];

        const arg_start: u32 = @intCast(self.plan.call_type_substitutions.items.len);
        for (operands, source_fn.args, worker_args) |operand, source_arg_ty, worker_arg| {
            const operand_type = switch (operand) {
                .checked_expr => |expr_id| typeRef(view, view.checked_bodies.expr(expr_id).ty),
                .loop_iterator_state => typeRef(view, plan.iterator_ty),
            };
            const call_type = typeRef(source_view, source_arg_ty);
            try self.plan.call_type_substitutions.append(self.allocator, .{
                .operand_type = operand_type,
                .operand_rep = try self.analyzeType(self.moduleForId(operand_type.module), operand_type.ty),
                .call_type = call_type,
                .call_rep = try self.analyzeType(source_view, source_arg_ty),
                .worker_rep = worker_arg.rep,
            });
        }
        const call_ret_rep = self.plan.repForSourceType(site.ret_type) orelse
            boxyPlanInvariant("boxy iterator dispatch return type was not analyzed");
        try self.plan.iterator_calls.append(self.allocator, .{
            .module = view.key,
            .for_plan = site.plan_id,
            .kind = site.kind,
            .caller = caller,
            .worker = worker,
            .source_fn_type = source_fn_type,
            .arg_substitutions = .{
                .start = arg_start,
                .len = @intCast(call.argsSlice(view.static_dispatch_plans).len),
            },
            .ret_type = site.ret_type,
            .ret_substitution = .{
                .operand_type = self.plan.representations.items[@intFromEnum(worker_function.ret)].source_type,
                .operand_rep = worker_function.ret,
                .call_type = site.ret_type,
                .call_rep = call_ret_rep,
                .worker_rep = worker_function.ret,
            },
        });
    }

    fn stepStatementTypes(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, statement_id: checked.CheckedStatementId) Allocator.Error!void {
        const worker = self.active_worker orelse
            boxyPlanInvariant("checked statement was analyzed outside a worker body");
        const entry = try self.body_statements_seen.getOrPut(.{
            .statement = .{ .module = view.key, .statement = statement_id },
            .worker = worker,
        });
        if (entry.found_existing) return;

        const statement = view.checked_bodies.statement(statement_id);
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        switch (statement.data) {
            .pending => boxyPlanInvariant("pending checked statement reached boxy body type planning"),
            // A promoted procedure is planned as its own template.
            .promoted_proc => {},
            .decl => |decl| {
                if (view.checked_bodies.expr(decl.expr).data == .runtime_error) return try actions.append(self.allocator, exprAction(view, decl.expr));
                // A declaration that binds no runtime value is never lowered:
                // each typed use instantiates its target instead.
                if (try declarationOmitsRuntimeBinding(self.allocator, view, decl.pattern, decl.expr)) return;
                try actions.append(self.allocator, patternAction(view, decl.pattern));
                try actions.append(self.allocator, exprAction(view, decl.expr));
            },
            .var_ => |decl| {
                if (view.checked_bodies.expr(decl.expr).data == .runtime_error) return try actions.append(self.allocator, exprAction(view, decl.expr));
                try actions.append(self.allocator, patternAction(view, decl.pattern));
                try actions.append(self.allocator, exprAction(view, decl.expr));
            },
            .var_uninitialized => |decl| try actions.append(self.allocator, patternAction(view, decl.pattern)),
            .reassign => |reassign| {
                if (view.checked_bodies.expr(reassign.expr).data == .runtime_error) return try actions.append(self.allocator, exprAction(view, reassign.expr));
                try actions.append(self.allocator, patternAction(view, reassign.pattern));
                try actions.append(self.allocator, exprAction(view, reassign.expr));
            },
            .crash,
            .break_,
            .import_,
            .alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .where_alias_decl,
            .runtime_error,
            => {},
            .expr,
            .expect,
            => |expr| try actions.append(self.allocator, exprAction(view, expr)),
            .dbg => |expr| try actions.append(self.allocator, .{ .inspect_expr = .{ .view = view, .expr = expr } }),
            .for_ => |for_| {
                try actions.append(self.allocator, .{ .iterator_for = .{ .view = view, .plan = for_.plan } });
                try actions.append(self.allocator, patternAction(view, for_.pattern));
                try actions.append(self.allocator, exprAction(view, for_.expr));
                try actions.append(self.allocator, exprAction(view, for_.body));
            },
            .while_, .infinite_loop, .breakable_loop => |loop| {
                try actions.append(self.allocator, exprAction(view, loop.cond));
                try actions.append(self.allocator, exprAction(view, loop.body));
            },
            .return_ => |ret| try actions.append(self.allocator, exprAction(view, ret.expr)),
        }
    }

    fn stepPatternTypes(self: *Builder, actions: *std.ArrayList(PlanAction), view: ModuleView, pattern_id: checked.CheckedPatternId) Allocator.Error!void {
        const worker = self.active_worker orelse
            boxyPlanInvariant("checked pattern was analyzed outside a worker body");
        const entry = try self.body_patterns_seen.getOrPut(.{
            .pattern = .{ .module = view.key, .pattern = pattern_id },
            .worker = worker,
        });
        if (entry.found_existing) return;

        const pattern = view.checked_bodies.pattern(pattern_id);
        const pattern_rep = try self.analyzeType(view, pattern.ty);
        if (!self.analyzing_nested_callable_args) try self.recordWorkerBodyType(worker, pattern_rep);
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        switch (pattern.data) {
            .pending => boxyPlanInvariant("pending checked pattern reached boxy body type planning"),
            .assign,
            .underscore,
            .runtime_error,
            => {},
            .as => |as| try actions.append(self.allocator, patternAction(view, as.pattern)),
            .applied_tag => |tag| for (tag.args) |arg| try actions.append(self.allocator, patternAction(view, arg)),
            .nominal => |nominal| try actions.append(self.allocator, patternAction(view, nominal.backing_pattern)),
            .record_destructure => |fields| for (fields) |field| {
                switch (field.kind) {
                    .required,
                    .sub_pattern,
                    .rest,
                    => |child| try actions.append(self.allocator, patternAction(view, child)),
                }
            },
            .list => |list| {
                for (list.patterns) |child| try actions.append(self.allocator, patternAction(view, child));
                if (list.rest) |rest| if (rest.pattern) |child| try actions.append(self.allocator, patternAction(view, child));
            },
            .tuple => |items| for (items) |child| try actions.append(self.allocator, patternAction(view, child)),
            .numeral_literal => |literal| if (literal.guard) |guard| try actions.append(self.allocator, exprAction(view, guard)),
            .str_literal => |literal| if (literal.guard) |guard| try actions.append(self.allocator, exprAction(view, guard)),
            .str_interpolation => |interpolation| {
                for (interpolation.steps) |step| {
                    if (step.capture) |capture| try actions.append(self.allocator, patternAction(view, capture));
                }
            },
        }
    }

    fn stepStaticConstNode(self: *Builder, actions: *std.ArrayList(PlanAction), state: StaticConstNode) Allocator.Error!void {
        const store_view = state.store_view;
        const node = state.node;
        const rep_id = state.rep_id;
        const const_type = state.const_type;
        const visited = state.visited;
        const entry = try visited.getOrPut(.{ .node = node, .rep = rep_id });
        if (entry.found_existing) return;
        const store = store_view.const_store orelse
            boxyPlanInvariant("static data request module had no ConstStore");
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const child = struct {
            fn at(from: StaticConstNode, child_node: checked.ConstNodeId, child_rep: TypeRepId, child_type: ?check.ConstStore.ConstTypeId) PlanAction {
                return .{ .static_const_node = .{ .store_view = from.store_view, .node = child_node, .rep_id = child_rep, .const_type = child_type, .visited = from.visited } };
            }
        };
        switch (rep.kind) {
            .alias => {
                const backing_type = if (const_type) |stored_type| switch (store.type_store.get(stored_type)) {
                    .named => |named| (named.backing orelse
                        boxyPlanInvariant("stored alias type had no backing")).ty,
                    .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => boxyPlanInvariant("stored alias representation had a non-named stored type"),
                } else null;
                return try actions.append(self.allocator, child.at(state, node, requiredSingleChildOf(&self.plan, rep_id, .alias_backing).rep, backing_type));
            },
            .nominal => |kind| {
                if (kind != .opaque_nominal) {
                    const backing = requiredSingleChildOf(&self.plan, rep_id, .nominal_backing).rep;
                    const backing_node = switch (store.get(node)) {
                        .nominal => |nominal| nominal.backing,
                        .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .crash, .checked_error, .tag, .fn_value => node,
                    };
                    const backing_type = if (const_type) |stored_type| switch (store.type_store.get(stored_type)) {
                        .named => |named| (named.backing orelse
                            boxyPlanInvariant("stored nominal type had no backing")).ty,
                        .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => boxyPlanInvariant("stored nominal representation had a non-named stored type"),
                    } else null;
                    return try actions.append(self.allocator, child.at(state, backing_node, backing, backing_type));
                }
            },
            .in_progress,
            .dynamic,
            .primitive,
            .bool_tag_union,
            .erased_callable,
            .record,
            .tuple,
            .list,
            .box,
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => {},
        }
        const start = beginPlanSequence(actions);
        defer finishPlanSequence(actions, start);
        switch (store.get(node)) {
            .pending => boxyPlanInvariant("pending ConstStore node reached static data planning"),
            .zst, .scalar, .str, .crash, .checked_error => {},
            .box => |payload| try actions.append(self.allocator, child.at(
                state,
                payload,
                requiredSingleChildOf(&self.plan, rep_id, .box_payload).rep,
                if (const_type) |stored_type| switch (store.type_store.get(stored_type)) {
                    .box => |payload_type| payload_type,
                    .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => boxyPlanInvariant("stored box node had a non-box stored type"),
                } else null,
            )),
            .nominal => |nominal| {
                if (rep.kind == .nominal) {
                    if (rep.kind.nominal != .opaque_nominal) {
                        boxyPlanInvariant("transparent static nominal node was not unwrapped before traversal");
                    }
                } else {
                    const nominal_view = self.moduleForId(.{ .bytes = nominal.named_type.module.bytes });
                    const nominal_rep = try self.analyzeType(nominal_view, nominal.named_type.ty);
                    try actions.append(self.allocator, child.at(state, node, nominal_rep, null));
                }
            },
            .list => |list_value| {
                const elem_rep = requiredSingleChildOf(&self.plan, rep_id, .list_elem).rep;
                const elem_type = if (const_type) |stored_type| switch (store.type_store.get(stored_type)) {
                    .list => |element| element,
                    .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => boxyPlanInvariant("stored list node had a non-list stored type"),
                } else null;
                switch (list_value) {
                    // Packed products carry no nested ConstStore nodes, so
                    // there is nothing further to analyze for representation.
                    .packed_bytes, .empty => {},
                    .nodes => |children| for (children) |item| try actions.append(self.allocator, child.at(state, item, elem_rep, elem_type)),
                }
            },
            .tuple, .record => |children| {
                var child_index: usize = 0;
                for (self.plan.childSlice(rep.children)) |rep_child| {
                    const is_value_child = rep_child.role == .tuple_elem or rep_child.role == .record_field;
                    if (!is_value_child) continue;
                    if (child_index >= children.len) boxyPlanInvariant("static aggregate ConstStore node had too few children");
                    try actions.append(self.allocator, child.at(
                        state,
                        children[child_index],
                        rep_child.rep,
                        if (const_type) |stored_type| switch (store.type_store.get(stored_type)) {
                            .tuple => |items| store.type_store.typeSpan(items)[child_index],
                            .record => |fields| store.type_store.fieldSpan(fields)[child_index].ty,
                            .primitive, .named, .tag_union, .list, .box, .func, .erased, .zst => boxyPlanInvariant("stored aggregate node had a non-aggregate stored type"),
                        } else null,
                    ));
                    child_index += 1;
                }
                if (child_index != children.len) boxyPlanInvariant("static aggregate ConstStore node had too many children");
            },
            .tag => |tag| {
                var selected: ?TagVariant = null;
                for (self.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                    const name_view = self.moduleForId(variant.name_module);
                    const canonical_names = name_view.canonical_names orelse
                        boxyPlanInvariant("static tag representation module had no checked name store");
                    if (std.mem.eql(u8, tag.tag_name, canonical_names.tagLabelText(variant.name))) {
                        selected = variant;
                        break;
                    }
                }
                const variant = selected orelse {
                    var extension: ?RepChild = null;
                    for (self.plan.childSlice(rep.children)) |rep_child| {
                        if (rep_child.role != .tag_ext) continue;
                        if (extension != null) boxyPlanInvariant("static tag representation had duplicate row extensions");
                        extension = rep_child;
                    }
                    const ext = extension orelse {
                        if (@import("builtin").mode == .Debug) {
                            std.debug.panic(
                                "boxy plan invariant violated: static tag {s} was absent from {s} representation {d} for checked type {d}",
                                .{ tag.tag_name, @tagName(rep.kind), @intFromEnum(rep_id), @intFromEnum(rep.source_type.ty) },
                            );
                        }
                        unreachable;
                    };
                    return try actions.append(self.allocator, child.at(state, node, ext.rep, const_type));
                };
                const payload_reps = self.plan.childSlice(variant.payloads);
                if (payload_reps.len != tag.payloads.len) boxyPlanInvariant("static tag payload count disagreed with its representation");
                var stored_payload_types: ?[]const check.ConstStore.ConstTypeId = null;
                if (const_type) |stored_type| {
                    const stored_tags = switch (store.type_store.get(stored_type)) {
                        .tag_union => |tags| store.type_store.tagSpan(tags),
                        .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => boxyPlanInvariant("stored tag node had a non-tag-union stored type"),
                    };
                    const names = store_view.canonical_names orelse
                        boxyPlanInvariant("stored tag type had no resolved tag labels");
                    for (stored_tags) |stored_tag| {
                        if (std.mem.eql(u8, tag.tag_name, names.tagLabelText(stored_tag.checked_name))) {
                            stored_payload_types = store.type_store.typeSpan(stored_tag.payloads);
                            break;
                        }
                    }
                    if (stored_payload_types == null) {
                        boxyPlanInvariant("stored tag node was absent from its stored type");
                    }
                }
                for (tag.payloads, payload_reps, 0..) |payload, payload_rep, index| {
                    try actions.append(self.allocator, child.at(
                        state,
                        payload,
                        payload_rep.rep,
                        if (stored_payload_types) |types| types[index] else null,
                    ));
                }
            },
            .fn_value => |fn_id| {
                const function = (self.repQuery().functionChildren(rep_id)) orelse
                    boxyPlanInvariant("static function ConstStore node had a non-callable representation");
                try actions.append(self.allocator, .{ .static_fn_value = .{ .store_view = store_view, .fn_id = fn_id, .requested_rep = function.rep, .const_type = const_type } });
                try actions.append(self.allocator, .{ .static_fn_captures = .{ .store_view = store_view, .fn_id = fn_id, .visited = visited } });
            },
        }
    }

    fn stepStaticFnValue(
        self: *Builder,
        actions: *std.ArrayList(PlanAction),
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        requested_rep: TypeRepId,
        const_type: ?check.ConstStore.ConstTypeId,
    ) Allocator.Error!void {
        for (self.plan.static_fns.items) |planned| {
            if (moduleKeyEqual(planned.store_module, store_view.key) and planned.fn_id == fn_id and planned.rep == requested_rep) {
                self.plan_worker_result = planned.worker;
                return;
            }
        }
        const store = store_view.const_store orelse
            boxyPlanInvariant("static function value had no ConstStore");
        const fn_value = store.getFn(fn_id);
        const requested_type = self.plan.representations.items[@intFromEnum(requested_rep)].source_type;
        const source = if (const_type) |stored_type|
            try self.workerSourceForConstFnValueAtStoredType(store_view, fn_value, stored_type)
        else
            self.workerSourceForConstFnValue(fn_value, requested_type);
        const checked_type = switch (source) {
            .procedure_template => |template| self.checkedTypeForTemplate(template),
            .nested_expr => self.workerCheckedTypeForSource(source, typeRef(store_view, fn_value.source_fn_ty)),
            .generated_codec => |codec| codec.runtime_type orelse typeRef(store_view, fn_value.source_fn_ty),
            .procedure_binding,
            .procedure_use,
            .generated_field_iterator,
            .generated_interpolation_step,
            => unreachable,
        };
        try self.pushPlanActions(actions, &.{
            .{ .ensure_worker = .{ .source = source, .checked_type = checked_type, .root_request = null } },
            .{ .static_fn_record = .{ .store_view = store_view, .fn_id = fn_id, .requested_rep = requested_rep } },
        });
    }

    fn stepConstFnCapture(self: *Builder, actions: *std.ArrayList(PlanAction), state: ConstFnCapture) Allocator.Error!void {
        if (state.index == state.fn_value.captures.len) return;
        const store_view = state.store_view;
        const fn_view = switch (state.fn_value.fn_def) {
            .nested => |nested| self.moduleForStoredNestedFn(nested),
            .local_template,
            .imported_template,
            .local_hosted,
            .imported_hosted,
            .checked_generated,
            .parser_runtime,
            .encoder_for_runtime,
            => store_view,
        };
        const capture = state.fn_value.captures[state.index];
        const source_type = if (capture.id.isCanonical())
            typeRef(fn_view, self.checkedBinderType(fn_view, capture.id.binder()))
        else
            self.generatedWorkerCaptureType(state.worker, capture.id);
        const capture_rep = try self.analyzeStoredType(store_view, capture.ty, source_type);
        var next = state;
        next.index += 1;
        try self.pushPlanActions(actions, &.{
            .{ .static_const_node = .{ .store_view = store_view, .node = capture.value, .rep_id = capture_rep, .const_type = capture.ty, .visited = state.visited } },
            .{ .const_fn_capture = next },
        });
    }

    /// The declaring module's view for a field default's origin identity.
    fn moduleForFieldDefaultOrigin(
        self: *Builder,
        view: ModuleView,
        default: checked.CheckedFieldDefault,
    ) ModuleView {
        const origin = default.origin() orelse
            boxyPlanInvariant("defaulted record field carried no declaring module identity");
        const names = view.canonical_names orelse
            boxyPlanInvariant("defaulted record field's consuming module had no checked name store");
        const origin_hash = names.moduleIdentityBytes(origin);
        if (self.root_module) |root_module| {
            if (std.mem.eql(u8, &root_module.module.module_identity.stable_hash, origin_hash)) {
                return self.root_view;
            }
        }
        for (self.imports) |imported| {
            if (std.mem.eql(u8, &imported.module_identity.stable_hash, origin_hash)) {
                return moduleViewFromImported(imported);
            }
        }
        for (self.relation_modules) |relation| {
            if (std.mem.eql(u8, &relation.module_identity.stable_hash, origin_hash)) {
                return moduleViewFromImported(relation);
            }
        }
        boxyPlanInvariant("defaulted record field's declaring module was absent from boxy planning");
    }

    /// The module view owning a stored nested function's checked site: the
    /// declaring module (resolved by content identity, like every defaults
    /// lookup) for a default-root-qualified reference, the owner template's
    /// module otherwise (design.md "Defaulted Fields").
    fn moduleForStoredNestedFn(self: *Builder, nested: anytype) ModuleView {
        const identity = nested.default_root orelse
            return self.moduleForId(.{ .bytes = checked_names.procTemplateModuleDigest(nested.owner).bytes });
        if (self.root_module) |root_module| {
            if (std.mem.eql(u8, &root_module.module.module_identity.stable_hash, &identity.bytes)) {
                return self.root_view;
            }
        }
        for (self.imports) |imported| {
            if (std.mem.eql(u8, &imported.module_identity.stable_hash, &identity.bytes)) {
                return moduleViewFromImported(imported);
            }
        }
        for (self.relation_modules) |relation| {
            if (std.mem.eql(u8, &relation.module_identity.stable_hash, &identity.bytes)) {
                return moduleViewFromImported(relation);
            }
        }
        boxyPlanInvariant("stored default-root function's declaring module was absent from boxy planning");
    }

    fn analyzeRoot(self: *Builder, root: checked.RootRequest, view: ModuleView) Allocator.Error!void {
        const host_type = typeRef(view, root.checked_type);
        const host_rep = try self.analyzeType(view, root.checked_type);
        const source = workerSourceForRoot(root, view.key) orelse
            boxyPlanInvariant("boxy root request had no checked procedure worker source");
        const worker_id = try self.ensureWorker(source, host_type, root);
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const source_type = self.workerCheckedTypeForSource(source, worker.checked_type);
        const source_rep = self.plan.repForSourceType(source_type) orelse
            boxyPlanInvariant("boxy root source type was not analyzed");

        const id: RootPlanId = @enumFromInt(@as(u32, @intCast(self.plan.roots.items.len)));
        try self.plan.roots.append(self.allocator, .{
            .id = id,
            .request = root,
            .worker = worker_id,
            .wrapper_kind = if (rootRequiresHostWrapper(root)) .host_shaped_wrapper else .private_worker_only,
            .host_type = host_type,
            .host_rep = host_rep,
            .source_type = source_type,
            .source_rep = source_rep,
            .worker_rep = worker.rep,
        });
        try self.plan.root_reps.append(self.allocator, host_rep);

        if (host_rep != worker.rep) {
            boxyPlanInvariant("boxy root worker representation disagreed with root representation");
        }
    }

    fn analyzeStaticDataRequest(self: *Builder, request: Common.StaticDataRequest) Allocator.Error!void {
        const store_view = self.moduleForId(checked.constModuleId(request.const_locator));
        const templates = store_view.const_templates orelse
            boxyPlanInvariant("static data request module had no const templates");
        const stored = switch (templates.get(request.const_locator).state) {
            .stored_const => |stored| stored,
            .reserved, .eval_template => boxyPlanInvariant("static data request const was not stored before boxy planning"),
            .unimplemented => boxyPlanInvariant("static data request reached a declaration with no implementation"),
        };
        try self.plan.root_reps.append(
            self.allocator,
            try self.analyzeStoredType(store_view, stored.root_type, typeRef(self.root_view, request.checked_type)),
        );
        const node = request.node orelse stored.node;
        const root_rep = self.plan.root_reps.items[self.plan.root_reps.items.len - 1];
        // ConstStore already supplies an exact monomorphic source shape. Keep
        // its callable identities and concrete arguments at the data boundary.
        try self.plan.host_reps.put(root_rep, root_rep);
        var visited = std.AutoHashMap(StaticConstVisit, void).init(self.allocator);
        defer visited.deinit();
        try self.analyzeStaticConstNode(store_view, node, root_rep, stored.root_type, &visited);
    }

    fn generatedWorkerCaptureType(
        self: *Builder,
        worker_id: WorkerPlanId,
        capture_id: checked.CaptureId,
    ) CheckedTypeIdentity {
        if (capture_id.isCanonical()) {
            boxyPlanInvariant("source capture reached generated worker capture type lookup");
        }
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const codec = switch (worker.source) {
            .generated_codec => |codec| switch (codec.kind) {
                .parser_runtime, .encoder_runtime => codec,
                .parser_constructor,
                .encoder_constructor,
                .encoder_record_fields,
                .encoder_dict_fields,
                .encoder_sequence_elements,
                .encoder_tag_payload_elements,
                .encoder_value_thunk,
                .encoder_dict_key_thunk,
                => boxyPlanInvariant("generated stored capture referenced a non-runtime codec worker"),
            },
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            .generated_field_iterator,
            .generated_interpolation_step,
            => boxyPlanInvariant("generated stored capture referenced a non-codec worker"),
        };
        if (capture_id == checked.CaptureId.generatedCheck(0)) {
            return codec.capture_type orelse
                boxyPlanInvariant("generated runtime codec had no encoding capture type");
        }
        var next_capture: u32 = 1;
        for (self.plan.generated_parser_field_captures.items) |field_capture| {
            if (field_capture.worker != worker_id) continue;
            if (capture_id == checked.CaptureId.generatedCheck(next_capture)) return field_capture.source_type;
            next_capture += 1;
        }
        boxyPlanInvariant("generated stored capture id was absent from its worker capture plan");
    }

    fn workerSourceForConstFnValue(
        self: *Builder,
        fn_value: check.ConstStore.ConstFn,
        requested_type: CheckedTypeIdentity,
    ) WorkerSource {
        return switch (fn_value.fn_def) {
            .local_template,
            .imported_template,
            .checked_generated,
            .local_hosted,
            .imported_hosted,
            => |template| .{ .procedure_template = template },
            .nested => |nested| blk: {
                // A default-root-qualified stored function resolves its site
                // in the declaring module against the `.default_root` owner
                // (const-store restore is the second sanctioned resolver of
                // default-root sites, design.md "Defaulted Fields").
                const view = self.moduleForStoredNestedFn(nested);
                var site_expr: ?checked.CheckedExprId = null;
                for (view.nested_proc_sites.sites) |site| {
                    if (site.site != nested.site) continue;
                    switch (site.owner) {
                        .template => |site_owner| {
                            if (nested.default_root != null) continue;
                            if (!checked_names.procedureTemplateRefEql(site_owner, nested.owner)) continue;
                        },
                        .default_root => if (nested.default_root == null) continue,
                    }
                    site_expr = site.checked_expr orelse
                        boxyPlanInvariant("stored nested function had no checked expression site");
                    break;
                }
                break :blk .{ .nested_expr = .{
                    .module = view.key,
                    .expr = site_expr orelse boxyPlanInvariant("stored nested function referenced a missing checked nested site"),
                } };
            },
            .parser_runtime => |runtime| blk: {
                const view = self.moduleForId(.{ .bytes = checked_names.procTemplateModuleDigest(runtime.owner).bytes });
                break :blk .{ .generated_codec = self.storedGeneratedCodecSource(
                    view,
                    runtime.expr,
                    requested_type.ty,
                    .parser_runtime,
                    .parser,
                    fn_value,
                ) };
            },
            .encoder_for_runtime => |runtime| blk: {
                const view = self.moduleForId(.{ .bytes = checked_names.procTemplateModuleDigest(runtime.owner).bytes });
                break :blk .{ .generated_codec = self.storedGeneratedCodecSource(
                    view,
                    runtime.expr,
                    requested_type.ty,
                    .encoder_runtime,
                    .encoder,
                    fn_value,
                ) };
            },
        };
    }

    fn workerSourceForConstFnValueAtStoredType(
        self: *Builder,
        store_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        stored_type: check.ConstStore.ConstTypeId,
    ) Allocator.Error!WorkerSource {
        const selection: ?struct {
            owner: checked_names.ProcedureTemplateRef,
            expr: checked.CheckedExprId,
            kind: GeneratedCodecKind,
            derivation_kind: static_dispatch.GeneratedCodecDerivationKind,
        } = switch (fn_value.fn_def) {
            .parser_runtime => |runtime| .{
                .owner = runtime.owner,
                .expr = runtime.expr,
                .kind = .parser_runtime,
                .derivation_kind = .parser,
            },
            .encoder_for_runtime => |runtime| .{
                .owner = runtime.owner,
                .expr = runtime.expr,
                .kind = .encoder_runtime,
                .derivation_kind = .encoder,
            },
            .local_template,
            .imported_template,
            .nested,
            .local_hosted,
            .imported_hosted,
            .checked_generated,
            => null,
        };
        const selected = selection orelse return self.workerSourceForConstFnValue(
            fn_value,
            typeRef(store_view, fn_value.source_fn_ty),
        );
        const view = self.moduleForId(.{ .bytes = checked_names.procTemplateModuleDigest(selected.owner).bytes });
        const selected_contract = self.generatedCodecContractForRuntimeExpr(
            view,
            selected.expr,
            selected.derivation_kind,
            fn_value,
        );
        const derivation = selected_contract.derivation;
        if (!try self.storedTypeInstantiatesCheckedType(store_view, stored_type, view, selected_contract.runtime_ty)) {
            boxyPlanInvariant("stored generated codec runtime type disagreed with its checked contract");
        }
        return .{ .generated_codec = .{
            .kind = selected.kind,
            .shape = typeRef(view, derivation.shape_ty),
            .runtime_type = typeRef(view, derivation.runtime_ty),
            .capture_type = typeRef(view, derivation.encoding_ty),
            .contract_derivation = selected_contract.id,
            .contract_expr = .{ .module = view.key, .expr = selected.expr },
        } };
    }

    const StoredCheckedTypePair = struct {
        stored: check.ConstStore.ConstTypeId,
        checked_module: checked.ModuleId,
        checked_ty: checked.CheckedTypeId,
    };

    const CheckedNamedTypeIdentity = struct {
        kind: check.ConstStore.TypeNamedKind,
        name: checked_names.TypeNameId,
        origin_module: checked_names.ModuleIdentityId,
        source_decl: ?u32,
        args: []const checked.CheckedTypeId,
        backing: TypeSource,
    };

    fn storedTypeMatchesCheckedType(
        self: *Builder,
        store_view: ModuleView,
        stored_type: check.ConstStore.ConstTypeId,
        checked_view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        // Every pair reachable from the root must match locally. A pair
        // already seen matches unless some other position proves otherwise,
        // which is how recursive types terminate.
        var visited = std.AutoHashMap(StoredCheckedTypePair, void).init(self.allocator);
        defer visited.deinit();
        var pending: std.ArrayList(StoredTypeMatch) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ .stored = stored_type, .checked_view = checked_view, .checked_ty = checked_ty });
        while (pending.pop()) |pair| {
            const visit = try visited.getOrPut(.{
                .stored = pair.stored,
                .checked_module = pair.checked_view.key,
                .checked_ty = pair.checked_ty,
            });
            if (visit.found_existing) continue;
            if (!try self.storedTypeMatchesLocally(store_view, pair.stored, pair.checked_view, pair.checked_ty, &pending)) return false;
        }
        return true;
    }

    /// Whether a stored type is an instance of a checked type: equal except
    /// that each of the checked type's variables stands for one stored type,
    /// and an open tag row's extension for the stored row's other variants.
    fn storedTypeInstantiatesCheckedType(
        self: *Builder,
        store_view: ModuleView,
        stored_type: check.ConstStore.ConstTypeId,
        checked_view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        var bindings = StoredInstanceBindings{};
        defer bindings.deinit(self.allocator);
        const outer = self.stored_instance_bindings;
        self.stored_instance_bindings = &bindings;
        defer self.stored_instance_bindings = outer;
        return try self.storedTypeMatchesCheckedType(store_view, stored_type, checked_view, checked_ty);
    }

    const StoredInstanceBinding = union(enum) {
        type: check.ConstStore.ConstTypeId,
        row: []const check.ConstStore.TypeTag,
    };

    const StoredInstanceBindings = struct {
        entries: std.AutoHashMapUnmanaged(CheckedTypeIdentity, StoredInstanceBinding) = .empty,

        fn deinit(self: *StoredInstanceBindings, allocator: Allocator) void {
            var it = self.entries.valueIterator();
            while (it.next()) |binding| switch (binding.*) {
                .row => |tags| allocator.free(tags),
                .type => {},
            };
            self.entries.deinit(allocator);
        }
    };

    fn bindStoredInstanceVariable(
        self: *Builder,
        bindings: *StoredInstanceBindings,
        store_view: ModuleView,
        variable: CheckedTypeIdentity,
        binding: StoredInstanceBinding,
    ) Allocator.Error!bool {
        const store = store_view.const_store orelse boxyPlanInvariant("stored instance binding had no ConstStore");
        if (bindings.entries.get(variable)) |existing| {
            const same = switch (existing) {
                .type => |existing_type| switch (binding) {
                    .type => |new_type| storedTypesEqual(store, existing_type, new_type, 0),
                    .row => false,
                },
                .row => |existing_tags| switch (binding) {
                    .row => |new_tags| storedTagRowsEqual(store, existing_tags, new_tags, 0),
                    .type => false,
                },
            };
            switch (binding) {
                .row => |tags| self.allocator.free(tags),
                .type => {},
            }
            return same;
        }
        try bindings.entries.put(self.allocator, variable, binding);
        return true;
    }

    fn storedTypesEqual(
        store: anytype,
        left: check.ConstStore.ConstTypeId,
        right: check.ConstStore.ConstTypeId,
        depth: u32,
    ) bool {
        if (left == right) return true;
        if (depth > 1024) boxyPlanInvariant("stored type comparison exceeded its depth limit");
        const a = store.type_store.get(left);
        const b = store.type_store.get(right);
        if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
        return switch (a) {
            .primitive => |primitive| primitive == b.primitive,
            .erased => |digest| std.meta.eql(digest, b.erased),
            .zst => true,
            .list => |item| storedTypesEqual(store, item, b.list, depth + 1),
            .box => |payload| storedTypesEqual(store, payload, b.box, depth + 1),
            .func => |function| storedTypeSpansEqual(store, store.type_store.typeSpan(function.args), store.type_store.typeSpan(b.func.args), depth) and
                storedTypesEqual(store, function.ret, b.func.ret, depth + 1),
            .tuple => |range| storedTypeSpansEqual(store, store.type_store.typeSpan(range), store.type_store.typeSpan(b.tuple), depth),
            .record => |range| blk: {
                const left_fields = store.type_store.fieldSpan(range);
                const right_fields = store.type_store.fieldSpan(b.record);
                if (left_fields.len != right_fields.len) break :blk false;
                for (left_fields, right_fields) |left_field, right_field| {
                    if (left_field.name != right_field.name or
                        !std.meta.eql(left_field.default, right_field.default) or
                        !storedTypesEqual(store, left_field.ty, right_field.ty, depth + 1)) break :blk false;
                    if ((left_field.value_ty == null) != (right_field.value_ty == null)) break :blk false;
                    if (left_field.value_ty) |left_value| {
                        if (!storedTypesEqual(store, left_value, right_field.value_ty.?, depth + 1)) break :blk false;
                    }
                }
                break :blk true;
            },
            .tag_union => |range| storedTagRowsEqual(store, store.type_store.tagSpan(range), store.type_store.tagSpan(b.tag_union), depth),
            .named => |named| blk: {
                const other = b.named;
                if (!std.meta.eql(named.named_type, other.named_type) or
                    !std.meta.eql(named.def, other.def) or
                    named.kind != other.kind or
                    named.builtin_owner != other.builtin_owner) break :blk false;
                if (!storedTypeSpansEqual(store, store.type_store.typeSpan(named.args), store.type_store.typeSpan(other.args), depth)) break :blk false;
                if ((named.backing == null) != (other.backing == null)) break :blk false;
                if (named.backing) |backing| {
                    if (!storedTypesEqual(store, backing.ty, other.backing.?.ty, depth + 1)) break :blk false;
                }
                break :blk true;
            },
        };
    }

    fn storedTypeSpansEqual(
        store: anytype,
        left: []const check.ConstStore.ConstTypeId,
        right: []const check.ConstStore.ConstTypeId,
        depth: u32,
    ) bool {
        if (left.len != right.len) return false;
        for (left, right) |left_type, right_type| {
            if (!storedTypesEqual(store, left_type, right_type, depth + 1)) return false;
        }
        return true;
    }

    fn storedTagRowsEqual(
        store: anytype,
        left: []const check.ConstStore.TypeTag,
        right: []const check.ConstStore.TypeTag,
        depth: u32,
    ) bool {
        if (left.len != right.len) return false;
        for (left) |left_tag| {
            const right_tag = for (right) |candidate| {
                if (candidate.name == left_tag.name) break candidate;
            } else return false;
            if (!storedTypeSpansEqual(store, store.type_store.typeSpan(left_tag.payloads), store.type_store.typeSpan(right_tag.payloads), depth)) return false;
        }
        return true;
    }

    /// A stored type and checked type still to be compared.
    const StoredTypeMatch = struct {
        stored: check.ConstStore.ConstTypeId,
        checked_view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    };

    fn pushStoredTypeMatch(
        self: *Builder,
        pending: *std.ArrayList(StoredTypeMatch),
        stored: check.ConstStore.ConstTypeId,
        checked_view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        try pending.append(self.allocator, .{ .stored = stored, .checked_view = checked_view, .checked_ty = checked_ty });
        return true;
    }

    /// Whether a stored type agrees with a checked type at its outermost
    /// constructor, queueing the pairs of their components.
    fn storedTypeMatchesLocally(
        self: *Builder,
        store_view: ModuleView,
        stored_type: check.ConstStore.ConstTypeId,
        checked_view: ModuleView,
        checked_ty: checked.CheckedTypeId,
        pending: *std.ArrayList(StoredTypeMatch),
    ) Allocator.Error!bool {
        const store = store_view.const_store orelse
            boxyPlanInvariant("stored type comparison had no ConstStore");
        const stored = store.type_store.get(stored_type);
        const payload = checked_view.checked_types.payload(checked_ty);
        if (payload == .alias and stored != .named) {
            return try self.pushStoredTypeMatch(pending, stored_type, checked_view, payload.alias.backing);
        }

        if (self.stored_instance_bindings) |bindings| switch (payload) {
            // An instance binds each of its type's variables to one stored type.
            .flex, .rigid => return try self.bindStoredInstanceVariable(bindings, store_view, typeRef(checked_view, checked_ty), .{ .type = stored_type }),
            .pending, .err, .alias, .record, .tuple, .nominal, .function, .tag_union, .empty_record, .empty_tag_union => {},
        };

        return switch (stored) {
            .func => |function| switch (payload) {
                .function => |checked_fn| blk: {
                    const stored_args = store.type_store.typeSpan(function.args);
                    if (stored_args.len != checked_fn.args.len) break :blk false;
                    for (stored_args, checked_fn.args) |stored_arg, checked_arg| {
                        if (!try self.pushStoredTypeMatch(pending, stored_arg, checked_view, checked_arg)) {
                            break :blk false;
                        }
                    }
                    break :blk try self.pushStoredTypeMatch(pending, function.ret, checked_view, checked_fn.ret);
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .nominal,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => false,
            },
            .primitive => |primitive| switch (payload) {
                .nominal => |nominal| if (nominal.builtin) |builtin|
                    storedPrimitiveMatchesBuiltin(primitive, builtin)
                else
                    false,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => false,
            },
            .named => |named| try self.storedNamedTypeMatchesChecked(
                store_view,
                named,
                checked_view,
                payload,
                pending,
            ),
            .record => |range| switch (payload) {
                .record => |record| try self.storedRecordTypeMatchesChecked(
                    store_view,
                    store.type_store.fieldSpan(range),
                    checked_view,
                    record,
                    pending,
                ),
                .empty_record => range.len == 0,
                .pending, .err, .flex, .rigid, .alias, .tuple, .nominal, .function, .tag_union, .empty_tag_union => false,
            },
            .tuple => |range| switch (payload) {
                .tuple => |items| blk: {
                    const stored_items = store.type_store.typeSpan(range);
                    if (stored_items.len != items.len) break :blk false;
                    for (stored_items, items) |stored_item, item| {
                        if (!try self.pushStoredTypeMatch(pending, stored_item, checked_view, item)) {
                            break :blk false;
                        }
                    }
                    break :blk true;
                },
                .pending, .err, .flex, .rigid, .alias, .record, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => false,
            },
            .tag_union => |range| switch (payload) {
                .tag_union => |tag_union| try self.storedTagTypeMatchesChecked(
                    store_view,
                    store.type_store.tagSpan(range),
                    checked_view,
                    tag_union,
                    pending,
                ),
                .empty_tag_union => range.len == 0,
                .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record => false,
            },
            .list => |element| switch (payload) {
                .nominal => |nominal| if (nominal.builtin == .list and nominal.args.len == 1)
                    try self.pushStoredTypeMatch(pending, element, checked_view, nominal.args[0])
                else
                    false,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => false,
            },
            .box => |element| switch (payload) {
                .nominal => |nominal| if (nominal.builtin == .box and nominal.args.len == 1)
                    try self.pushStoredTypeMatch(pending, element, checked_view, nominal.args[0])
                else
                    false,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => false,
            },
            .erased => |digest| std.meta.eql(digest, checked_view.checked_types.rootKey(checked_ty)),
            .zst => payload == .empty_record or payload == .empty_tag_union,
        };
    }

    fn storedNamedTypeMatchesChecked(
        self: *Builder,
        store_view: ModuleView,
        stored: anytype,
        checked_view: ModuleView,
        payload: checked.CheckedTypePayload,
        pending: *std.ArrayList(StoredTypeMatch),
    ) Allocator.Error!bool {
        const checked_def: CheckedNamedTypeIdentity = switch (payload) {
            .alias => |alias| .{
                .kind = check.ConstStore.TypeNamedKind.alias,
                .name = alias.name,
                .origin_module = alias.origin_module,
                .source_decl = alias.source_decl,
                .args = alias.args,
                .backing = .{ .view = checked_view, .ty = alias.backing },
            },
            .nominal => |nominal| .{
                .kind = if (nominal.is_opaque)
                    check.ConstStore.TypeNamedKind.@"opaque"
                else
                    check.ConstStore.TypeNamedKind.nominal,
                .name = nominal.name,
                .origin_module = nominal.origin_module,
                .source_decl = nominal.source_decl,
                .args = nominal.args,
                .backing = try self.nominalBackingSource(checked_view, nominal),
            },
            .pending,
            .err,
            .flex,
            .rigid,
            .record,
            .tuple,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return false,
        };
        if (stored.kind != checked_def.kind or stored.def.source_decl != checked_def.source_decl) return false;
        const store_names = store_view.canonical_names orelse
            boxyPlanInvariant("stored named type comparison had no ConstStore names");
        const checked_names_store = checked_view.canonical_names orelse
            boxyPlanInvariant("stored named type comparison had no checked names");
        if (!std.mem.eql(
            u8,
            store_names.moduleIdentityBytes(stored.def.module),
            checked_names_store.moduleIdentityBytes(checked_def.origin_module),
        )) return false;
        if (!std.mem.eql(
            u8,
            store_names.typeNameText(stored.def.type_name),
            checked_names_store.typeNameText(checked_def.name),
        )) return false;

        const store = store_view.const_store orelse
            boxyPlanInvariant("stored named type comparison had no ConstStore");
        const stored_args = store.type_store.typeSpan(stored.args);
        if (stored_args.len != checked_def.args.len) return false;
        for (stored_args, checked_def.args) |stored_arg, checked_arg| {
            if (!try self.pushStoredTypeMatch(pending, stored_arg, checked_view, checked_arg)) {
                return false;
            }
        }
        if (stored.backing) |backing| {
            return try self.pushStoredTypeMatch(pending, backing.ty, checked_def.backing.view, checked_def.backing.ty);
        }
        return true;
    }

    fn storedRecordTypeMatchesChecked(
        self: *Builder,
        store_view: ModuleView,
        stored_fields: []const check.ConstStore.TypeField,
        checked_view: ModuleView,
        root: checked.CheckedRecordType,
        pending: *std.ArrayList(StoredTypeMatch),
    ) Allocator.Error!bool {
        var checked_fields = std.ArrayList(checked.CheckedRecordField).empty;
        defer checked_fields.deinit(self.allocator);
        try checked_fields.appendSlice(self.allocator, root.fields);
        var extension = root.ext;
        while (true) {
            switch (checked_view.checked_types.payload(extension)) {
                .alias => |alias| extension = alias.backing,
                .record => |record| {
                    try checked_fields.appendSlice(self.allocator, record.fields);
                    extension = record.ext;
                },
                .empty_record => break,
                .flex, .rigid => |variable| {
                    if (variable.row_default != .empty_record) return false;
                    break;
                },
                .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => return false,
            }
        }
        if (stored_fields.len != checked_fields.items.len) return false;
        const store_names = store_view.canonical_names orelse
            boxyPlanInvariant("stored record type comparison had no ConstStore names");
        const checked_names_store = checked_view.canonical_names orelse
            boxyPlanInvariant("stored record type comparison had no checked names");
        for (stored_fields) |stored_field| {
            const stored_name = store_names.recordFieldLabelText(stored_field.name);
            var matched: ?checked.CheckedRecordField = null;
            for (checked_fields.items) |checked_field| {
                if (std.mem.eql(u8, stored_name, checked_names_store.recordFieldLabelText(checked_field.name))) {
                    if (matched != null) boxyPlanInvariant("checked record type had duplicate field labels");
                    matched = checked_field;
                }
            }
            const checked_field = matched orelse return false;
            if (!try self.pushStoredTypeMatch(pending, stored_field.ty, checked_view, checked_field.ty)) return false;
        }
        return true;
    }

    fn storedTagTypeMatchesChecked(
        self: *Builder,
        store_view: ModuleView,
        stored_tags: []const check.ConstStore.TypeTag,
        checked_view: ModuleView,
        root: checked.CheckedTagUnionType,
        pending: *std.ArrayList(StoredTypeMatch),
    ) Allocator.Error!bool {
        var checked_tags = std.ArrayList(checked.CheckedTag).empty;
        defer checked_tags.deinit(self.allocator);
        try checked_tags.appendSlice(self.allocator, root.tags);
        var extension = root.ext;
        var extension_variable: ?checked.CheckedTypeId = null;
        while (true) {
            switch (checked_view.checked_types.payload(extension)) {
                .alias => |alias| extension = alias.backing,
                .tag_union => |tag_union| {
                    try checked_tags.appendSlice(self.allocator, tag_union.tags);
                    extension = tag_union.ext;
                },
                .empty_tag_union => break,
                .flex, .rigid => |variable| {
                    // An instance fills the extension with its other variants.
                    if (self.stored_instance_bindings != null) {
                        extension_variable = extension;
                        break;
                    }
                    if (variable.row_default != .empty_tag_union) return false;
                    break;
                },
                .pending, .err, .record, .tuple, .nominal, .function, .empty_record => return false,
            }
        }
        if (extension_variable == null and stored_tags.len != checked_tags.items.len) return false;
        const store = store_view.const_store orelse
            boxyPlanInvariant("stored tag type comparison had no ConstStore");
        const store_names = store_view.canonical_names orelse
            boxyPlanInvariant("stored tag type comparison had no ConstStore names");
        const checked_names_store = checked_view.canonical_names orelse
            boxyPlanInvariant("stored tag type comparison had no checked names");
        var extension_tags = std.ArrayList(check.ConstStore.TypeTag).empty;
        defer extension_tags.deinit(self.allocator);
        for (stored_tags) |stored_tag| {
            const stored_name = store_names.tagLabelText(stored_tag.name);
            var matched: ?checked.CheckedTag = null;
            for (checked_tags.items) |checked_tag| {
                if (std.mem.eql(u8, stored_name, checked_names_store.tagLabelText(checked_tag.name))) {
                    if (matched != null) boxyPlanInvariant("checked tag type had duplicate tag labels");
                    matched = checked_tag;
                }
            }
            const checked_tag = matched orelse {
                if (extension_variable != null) {
                    try extension_tags.append(self.allocator, stored_tag);
                    continue;
                }
                return false;
            };
            const stored_payloads = store.type_store.typeSpan(stored_tag.payloads);
            const checked_payloads = checked_tag.argsSlice(checked_view.checked_types);
            if (stored_payloads.len != checked_payloads.len) return false;
            for (stored_payloads, checked_payloads) |stored_payload, checked_payload| {
                if (!try self.pushStoredTypeMatch(pending, stored_payload, checked_view, checked_payload)) return false;
            }
        }
        if (extension_variable) |variable| {
            if (stored_tags.len - extension_tags.items.len != checked_tags.items.len) return false;
            return try self.bindStoredInstanceVariable(
                self.stored_instance_bindings.?,
                store_view,
                typeRef(checked_view, variable),
                .{ .row = try extension_tags.toOwnedSlice(self.allocator) },
            );
        }
        return true;
    }

    fn storedGeneratedCodecSource(
        self: *Builder,
        view: ModuleView,
        expr_id: checked.CheckedExprId,
        stored_runtime_ty: checked.CheckedTypeId,
        kind: GeneratedCodecKind,
        derivation_kind: static_dispatch.GeneratedCodecDerivationKind,
        stored: check.ConstStore.ConstFn,
    ) GeneratedCodecSource {
        const selected = self.generatedCodecContractForRuntimeExpr(view, expr_id, derivation_kind, stored);
        const derivation = selected.derivation;
        if (selected.runtime_ty != stored_runtime_ty or
            checkedFunctionPayload(view, derivation.source_constructor_ty).args.len != 1)
        {
            boxyPlanInvariant("stored generated codec runtime disagreed with its checked contract");
        }
        return .{
            .kind = kind,
            .shape = typeRef(view, derivation.shape_ty),
            .runtime_type = typeRef(view, derivation.runtime_ty),
            .capture_type = typeRef(view, derivation.encoding_ty),
            .contract_derivation = selected.id,
            .contract_expr = .{ .module = view.key, .expr = expr_id },
        };
    }

    const GeneratedCodecContract = struct {
        id: static_dispatch.GeneratedCodecDerivationId,
        derivation: static_dispatch.GeneratedCodecDerivation,
        /// The runtime function type the stored value instantiates: the
        /// contract's own source runtime for a structural source plan, or the
        /// runtime result of the callable its retained evidence names.
        runtime_ty: checked.CheckedTypeId,
    };

    /// The checked codec contract a stored generated runtime was produced
    /// from. A structural source plan names it directly. An evidence-dependent
    /// source plan (a `parser_for` dispatched through a `where` requirement)
    /// names it through the structural evidence the stored function retained
    /// from the use that produced it.
    fn generatedCodecContractForRuntimeExpr(
        self: *Builder,
        view: ModuleView,
        expr_id: checked.CheckedExprId,
        expected_kind: static_dispatch.GeneratedCodecDerivationKind,
        stored: check.ConstStore.ConstFn,
    ) GeneratedCodecContract {
        const dispatch = self.dispatchPlanForGeneratedRuntime(view, expr_id);
        const selected: struct {
            kind: static_dispatch.StructuralKind,
            derivation: ?static_dispatch.GeneratedCodecDerivationId,
            callable_ty: checked.CheckedTypeId,
            dispatcher_ty: checked.CheckedTypeId,
            from_evidence: bool,
        } = switch (dispatch.resolution) {
            .structural => |derivation| .{
                .kind = derivation.kind(),
                .derivation = dispatch.generated_codec_derivation,
                .callable_ty = dispatch.callable_ty,
                .dispatcher_ty = dispatch.dispatcher_ty,
                .from_evidence = false,
            },
            .evidence_dependent => |dependent| blk: {
                const evidence = storedStructuralEvidence(stored, dependent.index, dependent.callable_contract);
                const checked_evidence = evidence.checked orelse
                    boxyPlanInvariant("stored generated codec evidence had no checked structural identity");
                if (!std.meta.eql(checked_evidence.view.bytes, view.key.bytes)) {
                    boxyPlanInvariant("stored generated codec evidence named a contract outside its runtime's module");
                }
                break :blk .{
                    .kind = evidence.derivation.kind(),
                    .derivation = checked_evidence.generated_codec_derivation,
                    .callable_ty = checked_evidence.callable_ty,
                    .dispatcher_ty = checked_evidence.dispatcher_ty,
                    .from_evidence = true,
                };
            },
            .direct_pending, .direct_closed, .direct_parametric, .checked_error, .@"unreachable" => boxyPlanInvariant("stored generated codec source plan did not select a structural codec"),
        };
        const expected_structural: static_dispatch.StructuralKind = switch (expected_kind) {
            .parser => .parser,
            .encoder => .encoder,
        };
        if (selected.kind != expected_structural) {
            boxyPlanInvariant("stored generated codec source plan had the wrong structural kind");
        }
        const derivation_id = selected.derivation orelse
            boxyPlanInvariant("stored generated codec source plan had no checked contract identity");
        if (@intFromEnum(derivation_id) >= view.static_dispatch_plans.generated_codec_derivations.len) {
            boxyPlanInvariant("stored generated codec source plan referenced a missing checked contract");
        }
        const derivation = view.static_dispatch_plans.generated_codec_derivations[@intFromEnum(derivation_id)];
        if (derivation.kind != expected_kind or
            !std.meta.eql(view.checked_types.rootKey(derivation.source_constructor_ty), view.checked_types.rootKey(selected.callable_ty)) or
            !std.meta.eql(view.checked_types.structuralRootKey(derivation.source_shape_ty), view.checked_types.structuralRootKey(selected.dispatcher_ty)))
        {
            boxyPlanInvariant("stored generated codec source plan disagreed with its checked contract");
        }
        return .{
            .id = derivation_id,
            .derivation = derivation,
            .runtime_ty = if (selected.from_evidence)
                checkedFunctionPayload(view, selected.callable_ty).ret
            else
                derivation.source_runtime_ty,
        };
    }

    /// The structural evidence entry a stored function retained at a checked
    /// evidence coordinate: `depth` frames out from its innermost frame, the
    /// `index`th root there, or that root's selected callable contract.
    fn storedStructuralEvidence(
        stored: check.ConstStore.ConstFn,
        coordinate: static_dispatch.EvidenceChainIndex,
        callable_contract: ?u32,
    ) check.ConstStore.ConstFnStructuralEvidence {
        var frame_index = stored.evidence_frame_head orelse
            boxyPlanInvariant("stored generated codec had no retained evidence for its evidence-dependent source");
        if (frame_index >= stored.evidence_frames.len) boxyPlanInvariant("stored function evidence head was outside its frames");
        var depth = coordinate.depth;
        while (depth > 0) : (depth -= 1) {
            frame_index = stored.evidence_frames[frame_index].parent orelse
                boxyPlanInvariant("stored function evidence coordinate escaped its outermost frame");
        }
        const frame = stored.evidence_frames[frame_index];
        if (coordinate.index >= frame.roots_len) boxyPlanInvariant("stored function evidence index exceeded its frame");
        var cursor: usize = frame.roots_start;
        skipStoredEvidenceEntries(stored.evidence, &cursor, coordinate.index);
        if (cursor >= stored.evidence.len) boxyPlanInvariant("stored function evidence ended before its selected entry");
        var entry = stored.evidence[cursor];
        if (callable_contract) |contract_index| {
            const contracts_len = storedEvidenceCallableContractCount(entry);
            if (contracts_len != 0) {
                if (contract_index >= contracts_len) boxyPlanInvariant("stored function callable contract index exceeded its entry");
                var contract_cursor = cursor + 1;
                if (entry == .target) switch (entry.target.nested) {
                    .resolved => |resolved| contract_cursor += resolved.subtree_len,
                    .from_callable => {},
                };
                skipStoredEvidenceEntries(stored.evidence, &contract_cursor, contract_index);
                if (contract_cursor >= stored.evidence.len) boxyPlanInvariant("stored function evidence ended before its selected contract");
                entry = stored.evidence[contract_cursor];
            }
        }
        return switch (entry) {
            .structural => |structural| structural,
            .target, .from_callable, .from_scheme, .unreachable_value, .checked_error => boxyPlanInvariant("stored generated codec evidence did not select a structural codec"),
        };
    }

    fn storedEvidenceCallableContractCount(entry: check.ConstStore.ConstFnEvidence) u32 {
        return switch (entry) {
            .target => |target| target.callable_contracts,
            .structural => |structural| structural.callable_contracts,
            .from_callable => |use| use.callable_contracts,
            .from_scheme, .unreachable_value, .checked_error => 0,
        };
    }

    /// Advance past `count` stored evidence entries, each with its nested
    /// evidence and callable contracts.
    fn skipStoredEvidenceEntries(nodes: []const check.ConstStore.ConstFnEvidence, cursor: *usize, count: u32) void {
        var remaining = count;
        while (remaining > 0) : (remaining -= 1) {
            if (cursor.* >= nodes.len) boxyPlanInvariant("stored function evidence ended inside a skipped entry");
            const entry = nodes[cursor.*];
            cursor.* += 1;
            if (entry == .target) switch (entry.target.nested) {
                .resolved => |resolved| cursor.* += resolved.subtree_len,
                .from_callable => {},
            };
            skipStoredEvidenceEntries(nodes, cursor, storedEvidenceCallableContractCount(entry));
        }
    }

    fn dispatchPlanForGeneratedRuntime(
        _: *Builder,
        view: ModuleView,
        expr_id: checked.CheckedExprId,
    ) static_dispatch.StaticDispatchCallPlan {
        const expr = view.checked_bodies.expr(expr_id);
        const plan_id = if (expr.data == .dispatch_call)
            expr.data.dispatch_call orelse
                boxyPlanInvariant("stored serialization dispatch expression had no dispatch plan")
        else if (expr.data == .type_dispatch_call)
            expr.data.type_dispatch_call orelse
                boxyPlanInvariant("stored serialization type dispatch expression had no dispatch plan")
        else
            boxyPlanInvariant("stored serialization runtime function did not reference a dispatch expression");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.plans.len) {
            boxyPlanInvariant("stored serialization dispatch plan was outside its checked table");
        }
        return view.static_dispatch_plans.plans[raw];
    }

    const GeneratedCodecContractLookup = struct {
        view: ModuleView,
        derivation: static_dispatch.GeneratedCodecDerivation,
    };

    fn generatedCodecContractForConstructor(
        self: *Builder,
        codec: GeneratedCodecSource,
        constructor_type: CheckedTypeIdentity,
        encoding_type: CheckedTypeIdentity,
        runtime_type: CheckedTypeIdentity,
    ) GeneratedCodecContractLookup {
        const expected_kind: static_dispatch.GeneratedCodecDerivationKind = switch (codec.kind) {
            .parser_constructor => .parser,
            .encoder_constructor => .encoder,
            .parser_runtime,
            .encoder_runtime,
            .encoder_record_fields,
            .encoder_dict_fields,
            .encoder_sequence_elements,
            .encoder_tag_payload_elements,
            .encoder_value_thunk,
            .encoder_dict_key_thunk,
            => boxyPlanInvariant("generated codec constructor contract requested for a runtime worker"),
        };
        const view = self.moduleForId(runtime_type.module);
        if (!moduleKeyEqual(codec.shape.module, view.key) or
            !moduleKeyEqual(constructor_type.module, view.key) or
            !moduleKeyEqual(encoding_type.module, view.key))
        {
            boxyPlanInvariant("generated codec constructor components belonged to different checked modules");
        }
        const runtime_fn = checkedFunctionPayload(view, runtime_type.ty);
        const state_ty = switch (expected_kind) {
            .parser => if (runtime_fn.args.len == 1)
                runtime_fn.args[0]
            else
                boxyPlanInvariant("generated parser constructor runtime had unexpected arity"),
            .encoder => if (runtime_fn.args.len == 2)
                runtime_fn.args[1]
            else
                boxyPlanInvariant("generated encoder constructor runtime had unexpected arity"),
        };
        const constructor_key = view.checked_types.rootKey(constructor_type.ty);
        const shape_key = view.checked_types.rootKey(codec.shape.ty);
        const encoding_key = view.checked_types.rootKey(encoding_type.ty);
        const state_key = view.checked_types.rootKey(state_ty);
        const derivation_id = codec.contract_derivation orelse
            boxyPlanInvariant("generated codec constructor had no checked contract identity");
        if (@intFromEnum(derivation_id) >= view.static_dispatch_plans.generated_codec_derivations.len) {
            boxyPlanInvariant("generated codec constructor referenced a missing checked derivation");
        }
        const derivation = view.static_dispatch_plans.generated_codec_derivations[@intFromEnum(derivation_id)];
        // Every generated constructor worker is requested at a source use of
        // the contract, so it is checked against the contract's source roles.
        if (derivation.kind != expected_kind or
            !std.meta.eql(constructor_key, view.checked_types.rootKey(derivation.source_constructor_ty)) or
            !std.meta.eql(shape_key, view.checked_types.rootKey(derivation.source_shape_ty)) or
            !std.meta.eql(encoding_key, view.checked_types.rootKey(derivation.source_encoding_ty)) or
            !std.meta.eql(state_key, view.checked_types.rootKey(derivation.source_state_ty)) or
            !std.meta.eql(view.checked_types.rootKey(runtime_type.ty), view.checked_types.rootKey(derivation.source_runtime_ty)))
        {
            boxyPlanInvariant("generated codec constructor disagreed with its checked derivation reference");
        }
        return .{ .view = view, .derivation = derivation };
    }

    fn generatedCodecContractForWorker(self: *Builder, worker_id: WorkerPlanId) GeneratedCodecContractLookup {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const codec = switch (worker.source) {
            .generated_codec => |codec| codec,
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            .generated_field_iterator,
            .generated_interpolation_step,
            => boxyPlanInvariant("generated codec call was planned outside a generated worker"),
        };
        const contract_worker = if (codec.contract_worker) |root|
            self.plan.workers.items[@intFromEnum(root)]
        else
            worker;
        const contract_codec = switch (contract_worker.source) {
            .generated_codec => |source| source,
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            .generated_field_iterator,
            .generated_interpolation_step,
            => boxyPlanInvariant("generated codec callback contract did not reference a generated worker"),
        };
        const expected_kind: static_dispatch.GeneratedCodecDerivationKind = switch (codec.kind) {
            .parser_runtime => .parser,
            .encoder_runtime,
            .encoder_record_fields,
            .encoder_dict_fields,
            .encoder_sequence_elements,
            .encoder_tag_payload_elements,
            .encoder_value_thunk,
            .encoder_dict_key_thunk,
            => .encoder,
            .parser_constructor, .encoder_constructor => boxyPlanInvariant("generated codec call was planned from a constructor worker"),
        };
        const view = if (contract_codec.contract_expr) |expr|
            self.moduleForId(expr.module)
        else
            self.moduleForId(contract_worker.checked_type.module);
        if (!moduleKeyEqual(contract_codec.shape.module, view.key)) {
            boxyPlanInvariant("generated codec shape and runtime contract belonged to different checked modules");
        }
        const capture_type = contract_codec.capture_type orelse
            boxyPlanInvariant("generated codec runtime had no capture type");
        if (!moduleKeyEqual(capture_type.module, view.key)) {
            boxyPlanInvariant("generated codec capture and runtime contract belonged to different checked modules");
        }
        const runtime_type = contract_codec.runtime_type orelse contract_worker.checked_type;
        const derivation_id = contract_codec.contract_derivation orelse
            boxyPlanInvariant("generated codec worker had no checked contract identity");
        if (@intFromEnum(derivation_id) >= view.static_dispatch_plans.generated_codec_derivations.len) {
            boxyPlanInvariant("generated codec worker referenced a missing checked derivation");
        }
        const derivation = view.static_dispatch_plans.generated_codec_derivations[@intFromEnum(derivation_id)];
        if (derivation.kind != expected_kind or
            !moduleKeyEqual(runtime_type.module, view.key) or
            !std.meta.eql(view.checked_types.rootKey(runtime_type.ty), view.checked_types.rootKey(derivation.runtime_ty)) or
            !std.meta.eql(view.checked_types.rootKey(contract_codec.shape.ty), view.checked_types.rootKey(derivation.shape_ty)) or
            !std.meta.eql(view.checked_types.rootKey(capture_type.ty), view.checked_types.rootKey(derivation.encoding_ty)))
        {
            boxyPlanInvariant("generated codec worker disagreed with its checked derivation reference");
        }
        return .{ .view = view, .derivation = derivation };
    }

    fn propagateGeneratedParserTryPlan(
        self: *Builder,
        worker: WorkerPlanId,
        shape_type: CheckedTypeIdentity,
        backing_type: CheckedTypeIdentity,
    ) Allocator.Error!void {
        const backing = self.plan.generatedParserTryPlan(worker, backing_type) orelse return;
        try self.appendGeneratedParserTryPlan(
            worker,
            shape_type,
            backing.ok_type,
            backing.error_type,
            .{ .missing = backing.missing, .null = backing.null },
        );
    }

    fn appendGeneratedParserTryPlan(
        self: *Builder,
        worker: WorkerPlanId,
        try_type: CheckedTypeIdentity,
        ok_type: CheckedTypeIdentity,
        error_type: CheckedTypeIdentity,
        kinds: CheckedTryErrorKinds,
    ) Allocator.Error!void {
        for (self.plan.generated_parser_try_plans.items) |existing| {
            if (existing.worker != worker or !typeRefEql(existing.try_type, try_type)) continue;
            if (!typeRefEql(existing.ok_type, ok_type) or
                !typeRefEql(existing.error_type, error_type) or
                existing.missing != kinds.missing or
                existing.null != kinds.null)
            {
                boxyPlanInvariant("generated Try parser plan had conflicting checked identities");
            }
            return;
        }
        try self.plan.generated_parser_try_plans.append(self.allocator, .{
            .worker = worker,
            .try_type = try_type,
            .ok_type = ok_type,
            .error_type = error_type,
            .missing = kinds.missing,
            .null = kinds.null,
        });
    }

    fn appendGeneratedParserDictionaryFieldSelection(
        self: *Builder,
        worker: WorkerPlanId,
        key_type: CheckedTypeIdentity,
        strategy: GeneratedParserDictionaryFieldStrategy,
    ) Allocator.Error!void {
        for (self.plan.generated_parser_dictionary_field_selections.items) |existing| {
            if (existing.worker != worker or !typeRefEql(existing.key_type, key_type)) continue;
            if (!std.meta.eql(existing.strategy, strategy)) {
                boxyPlanInvariant("generated Dict key parser plan had conflicting checked strategies");
            }
            return;
        }
        try self.plan.generated_parser_dictionary_field_selections.append(self.allocator, .{
            .worker = worker,
            .key_type = key_type,
            .strategy = strategy,
        });
    }

    fn propagateGeneratedParserTagCallLink(
        self: *Builder,
        worker: WorkerPlanId,
        shape_type: CheckedTypeIdentity,
        backing_type: CheckedTypeIdentity,
    ) Allocator.Error!void {
        const call_shape = self.plan.generatedParserTagCallShape(worker, backing_type) orelse return;
        try self.appendGeneratedParserTagCallLink(worker, shape_type, call_shape);
    }

    fn appendGeneratedParserTagCallLink(
        self: *Builder,
        worker: WorkerPlanId,
        shape_type: CheckedTypeIdentity,
        call_shape_type: CheckedTypeIdentity,
    ) Allocator.Error!void {
        for (self.plan.generated_parser_tag_call_links.items) |existing| {
            if (existing.contract_worker != worker or !typeRefEql(existing.shape_type, shape_type)) continue;
            if (!typeRefEql(existing.call_shape_type, call_shape_type)) {
                boxyPlanInvariant("generated parser shape selected conflicting checked tag call subjects");
            }
            return;
        }
        try self.plan.generated_parser_tag_call_links.append(self.allocator, .{
            .contract_worker = worker,
            .shape_type = shape_type,
            .call_shape_type = call_shape_type,
        });
    }

    fn generatedParserRuntimeSchema(
        self: *Builder,
        root_shape: CheckedTypeIdentity,
    ) Allocator.Error!CheckedTypeIdentity {
        var shape = root_shape;
        while (true) {
            const view = self.moduleForId(shape.module);
            switch (view.checked_types.payload(shape.ty)) {
                .alias => |alias| shape = typeRef(view, alias.backing),
                .nominal => |nominal| {
                    if (nominal.builtin != null) return shape;
                    if (methodOwnerForModuleType(view, shape.ty)) |owner| {
                        if (view.canonical_names.?.lookupMethodName("parser_for")) |parser_for| {
                            if (self.lookupMethodTarget(view, owner, view, parser_for)) |lookup| {
                                switch (lookup.target.kind) {
                                    .procedure, .local_proc => return shape,
                                    .structural => |kind| switch (kind) {
                                        .parser => {},
                                        .encoder => boxyPlanInvariant("parser schema resolved to generated encoder target"),
                                        .equality, .hash, .map, .map_effectful => boxyPlanInvariant("parser schema resolved to a non-parser structural target"),
                                    },
                                }
                            }
                        }
                    }
                    const backing = try self.nominalBackingSource(view, nominal);
                    if (checkedTryPayloads(backing.view, backing.ty) != null) return shape;
                    shape = typeRef(backing.view, backing.ty);
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .record,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return shape,
            }
        }
    }

    /// Record the checked error row `worker`'s generated record parser reports
    /// an absent required field in. The checker adds `MissingRequiredField(Str)`
    /// to the error row of every derived parser that owns a required field.
    fn planGeneratedParserMissingRequiredField(
        self: *Builder,
        worker: WorkerPlanId,
    ) Allocator.Error!void {
        for (self.plan.generated_parser_missing_required_fields.items) |planned| {
            if (planned.worker == worker) return;
        }
        const contract = self.generatedCodecContractForWorker(worker);
        if (!checkedErrorRowHasTag(contract.view, contract.derivation.error_ty, "MissingRequiredField")) {
            boxyPlanInvariant("derived parser with a required field had no MissingRequiredField in its checked error row");
        }
        _ = try self.analyzeType(contract.view, contract.derivation.error_ty);
        try self.plan.generated_parser_missing_required_fields.append(self.allocator, .{
            .worker = worker,
            .error_type = typeRef(contract.view, contract.derivation.error_ty),
        });
    }

    const GeneratedRecordCheckedField = struct {
        module: checked.ModuleId,
        field: checked.CheckedRecordField,
    };

    fn generatedRecordCheckedFields(
        self: *Builder,
        record_type: CheckedTypeIdentity,
    ) Allocator.Error![]GeneratedRecordCheckedField {
        var fields = std.ArrayList(GeneratedRecordCheckedField).empty;
        defer fields.deinit(self.allocator);
        var seen = std.AutoHashMap(CheckedTypeIdentity, void).init(self.allocator);
        defer seen.deinit();

        var current: ?CheckedTypeIdentity = record_type;
        while (current) |row_type| {
            const visit = try seen.getOrPut(row_type);
            if (visit.found_existing) break;

            const view = self.moduleForId(row_type.module);
            switch (view.checked_types.payload(row_type.ty)) {
                .record => |record| {
                    for (record.fields) |field| {
                        try fields.append(self.allocator, .{ .module = view.key, .field = field });
                    }
                    current = typeRef(view, record.ext);
                },
                .alias => |alias| current = typeRef(view, alias.backing),
                .empty_record => current = null,
                .flex, .rigid => |variable| {
                    if (variable.row_default != .empty_record) {
                        boxyPlanInvariant("generated record codec reached an open checked row");
                    }
                    current = null;
                },
                .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => boxyPlanInvariant("generated record codec row extension was not a record row"),
            }
        }
        return try self.allocator.dupe(GeneratedRecordCheckedField, fields.items);
    }

    fn recordGeneratedCallable(self: *Builder, caller: WorkerPlanId, worker: WorkerPlanId) Allocator.Error!void {
        try self.generated_callable_uses.put(self.allocator, .{ .caller = caller, .worker = worker }, {});
    }

    /// Whether the checked contract of `caller` recorded a call to
    /// `method_text` on `dispatch_type` with exactly this subject.
    fn generatedCodecContractRecordsCall(
        self: *Builder,
        caller: WorkerPlanId,
        dispatch_type: CheckedTypeIdentity,
        method_text: []const u8,
        subject_type: CheckedTypeIdentity,
    ) bool {
        const contract = self.generatedCodecContractForWorker(caller);
        const names = contract.view.canonical_names orelse
            boxyPlanInvariant("generated codec contract module had no checked names");
        for (contract.derivation.callsSlice(contract.view.static_dispatch_plans)) |candidate| {
            if (!std.mem.eql(u8, names.methodNameText(candidate.method), method_text)) continue;
            if (!moduleKeyEqual(dispatch_type.module, contract.view.key) or candidate.dispatcher_ty != dispatch_type.ty) continue;
            const candidate_subject = candidate.subject_ty orelse continue;
            if (typeRefEql(typeRef(contract.view, candidate_subject), subject_type)) return true;
        }
        return false;
    }

    fn generatedEncoderTagRowReps(
        self: *Builder,
        source_rep: TypeRepId,
    ) Allocator.Error![]TypeRepId {
        var rows = std.ArrayList(TypeRepId).empty;
        defer rows.deinit(self.allocator);
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();

        var current = source_rep;
        rows_loop: while (true) {
            const rep = self.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => {
                    current = requiredSingleChildOf(&self.plan, current, .alias_backing).rep;
                    continue;
                },
                .nominal => {
                    current = requiredSingleChildOf(&self.plan, current, .nominal_backing).rep;
                    continue;
                },
                .tag_union => {},
                .empty_tag_union => break :rows_loop,
                .dynamic => boxyPlanInvariant("generated tag encoder shape had a dynamic row representation"),
                .bool_tag_union => boxyPlanInvariant("generated tag encoder shape unexpectedly used the Bool representation"),
                .in_progress,
                .primitive,
                .erased_callable,
                .record,
                .tuple,
                .list,
                .box,
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                .empty_record,
                => boxyPlanInvariant("generated tag encoder shape was not a closed tag union"),
            }
            const visit = try seen.getOrPut(current);
            if (visit.found_existing) boxyPlanInvariant("generated tag encoder row representation was cyclic");
            try rows.append(self.allocator, current);

            var extension: ?TypeRepId = null;
            for (self.plan.childSlice(rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                if (extension != null) boxyPlanInvariant("generated tag encoder row had duplicate extensions");
                extension = child.rep;
            }
            current = extension orelse break;
        }
        return try self.allocator.dupe(TypeRepId, rows.items);
    }

    fn generatedCodecSourceForWorker(self: *const Builder, worker: WorkerPlanId) GeneratedCodecSource {
        return switch (self.plan.workers.items[@intFromEnum(worker)].source) {
            .generated_codec => |source| source,
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            .generated_field_iterator,
            .generated_interpolation_step,
            => boxyPlanInvariant("generated codec contract worker was not generated"),
        };
    }

    fn materializeHostAbiRequests(self: *Builder) Allocator.Error!void {
        // All worker discovery is complete. This traversal is confined to public
        // boundaries and reads checked types, never erased representation children.
        for (self.plan.roots.items) |root| {
            if (root.wrapper_kind == .host_shaped_wrapper) _ = try self.requestHostRep(root.host_rep);
        }
        const request_start = self.plan.roots.items.len;
        for (self.plan.root_reps.items[request_start..]) |rep| _ = try self.requestHostRep(rep);
        for (self.hosted_host_requests.items) |request| try self.materializeHostedHostRep(request);
        try self.finalizeHostNominalStorage();
    }

    fn freshHostContext(self: *Builder) u32 {
        const context = self.host_context_count;
        self.host_context_count += 1;
        return context;
    }

    /// A hosted declaration written with type variables is a scheme, and each
    /// use instantiates it: the host's single C signature covers every
    /// instantiation because the host never looks inside a variable slot, so
    /// a slot crosses the boundary exactly as the worker represents it.
    /// Analyze the declared signature in a context of its own where each
    /// variable slot is bound to the worker's representation at the same
    /// position, so no adapter converts a value the host cannot see.
    fn materializeHostedHostRep(self: *Builder, request: HostedHostRequest) Allocator.Error!void {
        const context = self.freshHostContext();
        const worker_rep = self.plan.workers.items[@intFromEnum(request.worker)].rep;
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        try self.bindHostedVariableSlots(request.declared_rep, worker_rep, context, &seen);

        const saved_mode = self.host_mode;
        const saved_context = self.host_context;
        self.host_mode = true;
        self.host_context = null;
        defer {
            self.host_mode = saved_mode;
            self.host_context = saved_context;
        }
        const host_rep = try self.analyzeHostType(.{ .source = request.declared, .context = context });
        self.plan.workers.items[@intFromEnum(request.worker)].host_fn_rep = host_rep;
    }

    /// Bind each hosted type variable slot the declared signature reaches to
    /// its worker representation, in pre-order.
    fn bindHostedVariableSlots(
        self: *Builder,
        root_declared: TypeRepId,
        root_worker: TypeRepId,
        context: u32,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList([2]TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ root_declared, root_worker });
        while (pending.pop()) |pair| try self.bindHostedVariableSlot(pair[0], pair[1], context, seen, &pending);
    }

    fn bindHostedVariableSlot(
        self: *Builder,
        declared_rep_id: TypeRepId,
        worker_rep_id: TypeRepId,
        context: u32,
        seen: *std.AutoHashMap(u64, void),
        pending: *std.ArrayList([2]TypeRepId),
    ) Allocator.Error!void {
        const pair_key = (@as(u64, @intFromEnum(declared_rep_id)) << 32) | @as(u64, @intFromEnum(worker_rep_id));
        if ((try seen.getOrPut(pair_key)).found_existing) return;

        const declared_rep = self.plan.representations.items[@intFromEnum(declared_rep_id)];
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        if (declared_rep.kind == .dynamic) {
            const view = self.moduleForId(declared_rep.source_type.module);
            switch (view.checked_types.payload(declared_rep.source_type.ty)) {
                .flex, .rigid => |variable| {
                    // A defaulted variable lowers to the same type for every
                    // use, so it is part of the declared signature itself.
                    if (variable.numeric_default_phase != null or variable.row_default != null) return;
                },
                .pending, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => return,
            }
            const slot: HostTypeKey = .{ .source = declared_rep.source_type, .context = context };
            const entry = try self.host_slot_reps.getOrPut(self.allocator, slot);
            if (entry.found_existing) {
                if (entry.value_ptr.* != worker_rep_id) boxyPlanInvariant("one hosted type variable had two worker representations");
            } else {
                entry.value_ptr.* = worker_rep_id;
            }
            return;
        }

        const worker_children = self.plan.childSlice(worker_rep.children);
        const declared_children = self.plan.childSlice(declared_rep.children);
        var index = declared_children.len;
        while (index > 0) {
            index -= 1;
            const worker_child = self.namedQuery().findMatchingChildByRole(worker_children, declared_children[index]) orelse continue;
            try pending.append(self.allocator, .{ declared_children[index].rep, worker_child.rep });
        }
    }

    /// The sort low-level calls its boxed comparator through a fixed ABI: the
    /// comparator's arguments keep their worker representation, and its
    /// ordering result is the closed `[Before, Same, After]` that the ABI
    /// context gives the open callback result.
    fn planSortComparatorAbi(self: *Builder, boxed_comparator_rep: TypeRepId) Allocator.Error!void {
        const comparator_rep = self.repQuery().requiredSingleChild(boxed_comparator_rep, .box_payload).rep;
        if (self.plan.sort_comparator_abis.get(comparator_rep) != null) return;
        const function = self.repQuery().functionChildren(comparator_rep) orelse
            boxyPlanInvariant("sort comparator was not a function");
        const abi_ret = try self.requestHostRep(function.ret);
        var children = std.ArrayList(RepChild).empty;
        defer children.deinit(self.allocator);
        for (self.plan.childSlice(self.plan.representations.items[@intFromEnum(comparator_rep)].children)) |child| {
            var abi_child = child;
            switch (child.role) {
                .function_ret => {
                    abi_child.rep = abi_ret;
                    abi_child.source_type = self.plan.representations.items[@intFromEnum(abi_ret)].source_type;
                },
                .function_arg => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyPlanInvariant("sort comparator representation had a non-function child"),
            }
            try children.append(self.allocator, abi_child);
        }
        const abi_rep: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        try self.plan.representations.append(self.allocator, .{
            .source_type = self.plan.representations.items[@intFromEnum(comparator_rep)].source_type,
            .kind = .erased_callable,
            .children = try self.commitPendingChildren(children.items),
        });
        try self.plan.sort_comparator_abis.put(comparator_rep, abi_rep);
    }

    fn requestHostRep(self: *Builder, worker_rep: TypeRepId) Allocator.Error!TypeRepId {
        if (self.plan.host_reps.get(worker_rep)) |rep| return rep;
        const source = self.plan.representations.items[@intFromEnum(worker_rep)].source_type;
        const saved_mode = self.host_mode;
        const saved_context = self.host_context;
        self.host_mode = true;
        self.host_context = null;
        defer {
            self.host_mode = saved_mode;
            self.host_context = saved_context;
        }
        const rep = try self.analyzeHostType(.{ .source = source, .context = null });
        try self.plan.host_reps.put(worker_rep, rep);
        return rep;
    }

    fn resolveHostBinding(self: *Builder, source: HostTypeKey) HostTypeKey {
        // Bindings point to already-resolved arguments in an outer context.
        // They cannot form a cycle or refer to the context being constructed.
        return self.host_bindings.get(source) orelse source;
    }

    // Representation analysis //
    //
    // A type's representation is built from its components' representations,
    // and components follow type nesting. Each representation still waiting
    // on a component is a frame on one heap-backed stack, so type nesting
    // never becomes native call depth. Frames allocate representation ids,
    // children, variants, dictionaries, declared fields, and bindings in the
    // same order a direct recursive analysis would.

    /// One component analysis a representation waits on.
    const RepRequest = union(enum) {
        /// A checked type; in host mode, under the host binding `context`.
        checked: struct { view: ModuleView, ty: checked.CheckedTypeId, context: ?u32 },
        /// A host-ABI type under its own binding context.
        host: HostTypeKey,
        /// The presence slot of an optional record field whose value has
        /// type `ty`.
        optional_slot: struct { view: ModuleView, ty: checked.CheckedTypeId, context: ?u32 },
    };

    const RepFrame = struct {
        /// The host binding context current when this frame began, restored
        /// when it finishes.
        saved_context: ?u32,
        state: union(enum) {
            /// A row with no declared tags, bound to its extension's plan.
            row_redirect: struct { binding: TypeBindingId, request: ?RepRequest },
            build: RepBuild,
            optional_slot: struct {
                rep_id: TypeRepId,
                source_type: CheckedTypeIdentity,
                view: ModuleView,
                present: TagLabelId,
                missing: TagLabelId,
                request: ?RepRequest,
            },
            host_nominal: HostNominalBuild,
        },

        fn deinit(frame: *RepFrame, allocator: Allocator) void {
            switch (frame.state) {
                .row_redirect, .optional_slot => {},
                .build => |*build| build.deinit(allocator),
                .host_nominal => |*build| build.deinit(allocator),
            }
        }
    };

    /// A representation built once its component analyses, requested in
    /// order, have finished.
    const RepBuild = struct {
        rep_id: TypeRepId,
        requests: []RepRequest,
        results: []TypeRepId,
        next: usize = 0,
        finish: RepFinish,

        fn deinit(build: *RepBuild, allocator: Allocator) void {
            allocator.free(build.requests);
            allocator.free(build.results);
            build.finish.deinit(allocator);
        }
    };

    /// How a built representation combines its components.
    const RepFinish = union(enum) {
        dynamic: struct {
            source_type: CheckedTypeIdentity,
            kind: DynamicKind,
            dictionaries: Span,
            /// The variable a flex seals to when nothing quantifies it.
            sealed_default: ?checked.CheckedTypeVariable,
        },
        /// Each request is one child, committed in request order.
        children: struct {
            source_type: CheckedTypeIdentity,
            kind: RepresentationKind,
            roles: []ChildRole,
            sources: []CheckedTypeIdentity,
            inspect_opaque: bool = false,
        },
        record: struct {
            source_type: CheckedTypeIdentity,
            closed: bool,
            view: ModuleView,
            roles: []ChildRole,
            sources: []CheckedTypeIdentity,
            kinds: []checked.CheckedFieldKind,
        },
        tag_union: struct {
            source_type: CheckedTypeIdentity,
            closed: bool,
            view: ModuleView,
            roles: []ChildRole,
            sources: []CheckedTypeIdentity,
            /// Layout-ordered tags; owned when `owned_tags`.
            tags: []const checked.CheckedTag,
            owned_tags: bool,
        },
        host_tag_union: struct {
            source_type: CheckedTypeIdentity,
            open: bool,
            roles: []ChildRole,
            sources: []CheckedTypeIdentity,
            /// Variants whose payload starts are relative to the children.
            variants: []TagVariant,
        },
        bool_nominal: CheckedTypeIdentity,
        nominal: NominalFinish,

        fn deinit(finish: *RepFinish, allocator: Allocator) void {
            switch (finish.*) {
                .dynamic, .bool_nominal => {},
                .children => |*value| {
                    allocator.free(value.roles);
                    allocator.free(value.sources);
                },
                .record => |*value| {
                    allocator.free(value.roles);
                    allocator.free(value.sources);
                    allocator.free(value.kinds);
                },
                .tag_union => |*value| {
                    allocator.free(value.roles);
                    allocator.free(value.sources);
                    if (value.owned_tags) allocator.free(value.tags);
                },
                .host_tag_union => |*value| {
                    allocator.free(value.roles);
                    allocator.free(value.sources);
                    allocator.free(value.variants);
                },
                .nominal => |*value| value.deinit(allocator),
            }
        }
    };

    /// A nominal's children are its first `roles.len` results; its declared
    /// fields are the rest.
    const NominalFinish = struct {
        source_type: CheckedTypeIdentity,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        backing: ?TypeSource,
        roles: []ChildRole,
        sources: []CheckedTypeIdentity,
        declared: []DeclaredField,
        kind: RepresentationKind,
        record_field_order: RecordFieldOrder,

        fn deinit(finish: *NominalFinish, allocator: Allocator) void {
            allocator.free(finish.roles);
            allocator.free(finish.sources);
            allocator.free(finish.declared);
        }
    };

    /// A host-ABI nominal: its arguments first, then, when no plan exists for
    /// those arguments, its backing and declared fields in a fresh context.
    const HostNominalBuild = struct {
        key: HostTypeKey,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        lookup: NominalDeclarationLookup,
        sources: []HostTypeKey,
        args: []TypeRepId,
        args_owned: bool = true,
        next: usize = 0,
        stage: enum { args, backing } = .args,
        rep: TypeRepId = undefined,
        backing: TypeSource = undefined,
        /// The backing and declared-field analyses of the fresh context.
        requests: []RepRequest = &.{},
        results: []TypeRepId = &.{},
        declared: []DeclaredField = &.{},

        fn deinit(build: *HostNominalBuild, allocator: Allocator) void {
            allocator.free(build.sources);
            if (build.args_owned) allocator.free(build.args);
            allocator.free(build.requests);
            allocator.free(build.results);
            allocator.free(build.declared);
        }
    };

    const RepStep = union(enum) {
        request: RepRequest,
        done: TypeRepId,
    };

    fn analyzeType(self: *Builder, view: ModuleView, ty: checked.CheckedTypeId) Allocator.Error!TypeRepId {
        return try self.runRepresentation(.{ .checked = .{ .view = view, .ty = ty, .context = self.host_context } });
    }

    fn analyzeHostType(self: *Builder, input: HostTypeKey) Allocator.Error!TypeRepId {
        return try self.runRepresentation(.{ .host = input });
    }

    fn optionalSlotRepresentation(self: *Builder, view: ModuleView, payload_ty: checked.CheckedTypeId) Allocator.Error!TypeRepId {
        return try self.runRepresentation(.{ .optional_slot = .{ .view = view, .ty = payload_ty, .context = self.host_context } });
    }

    fn runRepresentation(self: *Builder, root: RepRequest) Allocator.Error!TypeRepId {
        var frames: std.ArrayList(RepFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.deinit(self.allocator);
            frames.deinit(self.allocator);
        }
        errdefer if (frames.items.len != 0) {
            self.host_context = frames.items[0].saved_context;
        };
        var input: ?TypeRepId = try self.beginRepRequest(&frames, root);
        if (frames.items.len == 0) return input.?;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            switch (try self.stepRepFrame(frame, input)) {
                .request => |request| input = try self.beginRepRequest(&frames, request),
                .done => |rep| {
                    var finished = frames.pop().?;
                    self.host_context = finished.saved_context;
                    finished.deinit(self.allocator);
                    if (frames.items.len == 0) return rep;
                    input = rep;
                },
            }
        }
    }

    /// Start a request: its representation when already known, or null
    /// after pushing the frame that builds it.
    fn beginRepRequest(self: *Builder, frames: *std.ArrayList(RepFrame), request: RepRequest) Allocator.Error!?TypeRepId {
        switch (request) {
            .checked => |checked_request| {
                self.host_context = checked_request.context;
                if (self.host_mode) return try self.beginHostType(frames, .{ .source = typeRef(checked_request.view, checked_request.ty), .context = self.host_context });
                return try self.beginCheckedType(frames, checked_request.view, checked_request.ty);
            },
            .host => |key| return try self.beginHostType(frames, key),
            .optional_slot => |slot| {
                self.host_context = slot.context;
                return try self.beginOptionalSlot(frames, slot.view, slot.ty);
            },
        }
    }

    fn beginCheckedType(self: *Builder, frames: *std.ArrayList(RepFrame), view: ModuleView, ty: checked.CheckedTypeId) Allocator.Error!?TypeRepId {
        const source_type = typeRef(view, ty);
        const binding = try self.internTypeBinding(source_type);
        if (self.plan.type_reps.items[@intFromEnum(binding)].rep) |rep| return rep;

        // A row with no declared tags has exactly its extension's storage
        // and descriptor. Keep both checked types bound to that same plan.
        var row_ty = ty;
        var remaining = view.checked_types.payloadCount();
        while (view.checked_types.payload(row_ty) == .tag_union) {
            const row = view.checked_types.payload(row_ty).tag_union;
            if (row.tags.len != 0) break;
            if (remaining == 0) boxyPlanInvariant("cyclic checked empty tag row extension");
            remaining -= 1;
            row_ty = row.ext;
        }
        if (row_ty != ty) {
            try frames.append(self.allocator, .{ .saved_context = self.host_context, .state = .{ .row_redirect = .{
                .binding = binding,
                .request = .{ .checked = .{ .view = view, .ty = row_ty, .context = self.host_context } },
            } } });
            return null;
        }

        const rep_id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        self.plan.type_reps.items[@intFromEnum(binding)].rep = rep_id;
        try self.plan.representations.append(self.allocator, .{
            .source_type = source_type,
            .kind = .in_progress,
        });
        return try self.beginBuild(frames, rep_id, view, ty, self.host_context);
    }

    fn beginHostType(self: *Builder, frames: *std.ArrayList(RepFrame), input: HostTypeKey) Allocator.Error!?TypeRepId {
        const key = self.resolveHostBinding(input);
        if (self.host_slot_reps.get(key)) |rep| return rep;
        if (self.host_types.get(key)) |rep| return rep;
        const saved_context = self.host_context;
        self.host_context = key.context;
        errdefer self.host_context = saved_context;
        const view = self.moduleForId(key.source.module);
        const payload = view.checked_types.payload(key.source.ty);
        // These checked leaves have no substitution-dependent children. Reuse
        // their already committed representation identity when it is present.
        const leaf = switch (payload) {
            .empty_record, .empty_tag_union => true,
            .nominal => |nominal| if (nominal.builtin) |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                .primitive, .bool_tag_union => true,
                .try_nominal, .list, .box, .dict, .set, .iterator, .parse_tag_union_spec, .fields, .field, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => false,
            } else false,
            .pending, .err, .flex, .rigid, .alias, .record, .tuple, .function, .tag_union => false,
        };
        if (leaf) {
            if (self.by_type.get(key.source)) |binding| {
                if (self.plan.type_reps.items[@intFromEnum(binding)].rep) |existing| {
                    try self.host_types.put(self.allocator, key, existing);
                    self.host_context = saved_context;
                    return existing;
                }
            }
        }
        if (payload == .nominal) {
            const nominal = payload.nominal;
            const opens_backing = if (nominal.builtin) |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                .primitive, .bool_tag_union, .list, .box, .field, .fields, .parse_tag_union_spec => false,
                .try_nominal, .dict, .set, .iterator, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => true,
            } else nominal.representation != .opaque_without_backing;
            if (opens_backing) {
                try self.beginHostNominal(frames, saved_context, key, view, nominal);
                return null;
            }
        }
        const rep: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        try self.host_types.put(self.allocator, key, rep);
        try self.plan.representations.append(self.allocator, .{ .source_type = key.source, .kind = .in_progress });
        switch (payload) {
            .flex, .rigid => |variable| {
                self.plan.representations.items[@intFromEnum(rep)] = .{ .source_type = key.source, .kind = variableDefaultKind(variable) };
                self.host_context = saved_context;
                return rep;
            },
            .pending, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => {
                const done = try self.beginBuild(frames, rep, view, key.source.ty, saved_context);
                if (done != null) self.host_context = saved_context;
                return done;
            },
        }
    }

    fn beginOptionalSlot(self: *Builder, frames: *std.ArrayList(RepFrame), view: ModuleView, payload_ty: checked.CheckedTypeId) Allocator.Error!?TypeRepId {
        const source_type = typeRef(view, payload_ty);
        const entry: struct { found_existing: bool, value_ptr: *TypeRepId } = if (self.host_mode) blk: {
            const slot = try self.host_optional_slots.getOrPut(self.allocator, .{ .source = source_type, .context = self.host_context });
            break :blk .{ .found_existing = slot.found_existing, .value_ptr = slot.value_ptr };
        } else blk: {
            const slot = try self.optional_slots.getOrPut(source_type);
            break :blk .{ .found_existing = slot.found_existing, .value_ptr = slot.value_ptr };
        };
        if (entry.found_existing) return entry.value_ptr.*;

        const rep_id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        entry.value_ptr.* = rep_id;
        try self.plan.representations.append(self.allocator, .{
            .source_type = source_type,
            .kind = .in_progress,
        });

        const names = view.canonical_names orelse
            boxyPlanInvariant("optional field slot representation ModuleView had no name store");
        const missing = names.lookupTagLabel("#Missing") orelse
            boxyPlanInvariant("optional field slot representation was missing the reserved Missing label");
        const present = names.lookupTagLabel("#Present") orelse
            boxyPlanInvariant("optional field slot representation was missing the reserved Present label");
        try frames.append(self.allocator, .{ .saved_context = self.host_context, .state = .{ .optional_slot = .{
            .rep_id = rep_id,
            .source_type = source_type,
            .view = view,
            .present = present,
            .missing = missing,
            .request = .{ .checked = .{ .view = view, .ty = payload_ty, .context = self.host_context } },
        } } });
        return null;
    }

    fn stepRepFrame(self: *Builder, frame: *RepFrame, input: ?TypeRepId) Allocator.Error!RepStep {
        switch (frame.state) {
            .row_redirect => |*redirect| {
                if (redirect.request) |request| {
                    redirect.request = null;
                    return .{ .request = request };
                }
                self.plan.type_reps.items[@intFromEnum(redirect.binding)].rep = input.?;
                return .{ .done = input.? };
            },
            .optional_slot => |*slot| {
                if (slot.request) |request| {
                    slot.request = null;
                    return .{ .request = request };
                }
                const child_start: u32 = @intCast(self.plan.children.items.len);
                try self.plan.children.append(self.allocator, .{
                    .role = .{ .tag_payload = .{ .tag = slot.present, .index = 0 } },
                    .source_type = slot.source_type,
                    .rep = input.?,
                });
                const variant_start: u32 = @intCast(self.plan.tag_variants.items.len);
                try self.plan.tag_variants.appendSlice(self.allocator, &.{
                    .{ .name = slot.missing, .name_module = slot.view.key },
                    .{ .name = slot.present, .name_module = slot.view.key, .payloads = .{ .start = child_start, .len = 1 } },
                });
                self.plan.representations.items[@intFromEnum(slot.rep_id)] = .{
                    .source_type = slot.source_type,
                    .kind = .tag_union,
                    .children = .{ .start = child_start, .len = 1 },
                    .tag_variants = .{ .start = variant_start, .len = 2 },
                    // Slot tags carry their payload descriptor through enclosing
                    // records even when this particular payload is concrete.
                    .contains_dynamic = true,
                    .presence_slot_present_discriminant = 1,
                };
                return .{ .done = slot.rep_id };
            },
            .build => |*build| {
                if (input) |rep| {
                    build.results[build.next] = rep;
                    build.next += 1;
                }
                if (build.next < build.requests.len) return .{ .request = build.requests[build.next] };
                // Finishing can append representations; write the result
                // only after it returns.
                const finished = try self.finishRepBuild(build);
                self.plan.representations.items[@intFromEnum(build.rep_id)] = finished;
                return .{ .done = build.rep_id };
            },
            .host_nominal => |*build| return try self.stepHostNominal(build, input),
        }
    }

    /// Push the frame that builds `rep_id` from the checked type `ty`, or
    /// return `rep_id` when the representation needs no component.
    fn beginBuild(
        self: *Builder,
        frames: *std.ArrayList(RepFrame),
        rep_id: TypeRepId,
        view: ModuleView,
        ty: checked.CheckedTypeId,
        saved_context: ?u32,
    ) Allocator.Error!?TypeRepId {
        var requests = std.ArrayList(RepRequest).empty;
        defer requests.deinit(self.allocator);
        const finish = (try self.planRepBuild(&requests, rep_id, view, ty)) orelse return rep_id;
        var owned_finish = finish;
        errdefer owned_finish.deinit(self.allocator);
        const owned_requests = try requests.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned_requests);
        const results = try self.allocator.alloc(TypeRepId, owned_requests.len);
        errdefer self.allocator.free(results);
        try frames.append(self.allocator, .{ .saved_context = saved_context, .state = .{ .build = .{
            .rep_id = rep_id,
            .requests = owned_requests,
            .results = results,
            .finish = owned_finish,
        } } });
        return null;
    }

    fn checkedRequest(self: *const Builder, view: ModuleView, ty: checked.CheckedTypeId) RepRequest {
        return .{ .checked = .{ .view = view, .ty = ty, .context = self.host_context } };
    }

    /// The request a record field's slot representation needs: the field
    /// value's own, or its presence slot's.
    fn recordFieldRequest(self: *const Builder, view: ModuleView, field: checked.CheckedRecordField) RepRequest {
        return switch (field.kind.tag) {
            .required, .defaulted => self.checkedRequest(view, field.ty),
            .optional, .undetermined => .{ .optional_slot = .{ .view = view, .ty = field.ty, .context = self.host_context } },
            .err => boxyPlanInvariant("checked-error record field reached boxy representation planning"),
        };
    }

    /// List, in order, the component analyses the representation of `ty`
    /// needs, and how it combines them. Null when the representation is
    /// already complete, having been written in place.
    fn planRepBuild(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        rep_id: TypeRepId,
        view: ModuleView,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?RepFinish {
        const source_type = typeRef(view, ty);
        const payload = view.checked_types.payload(ty);
        return switch (payload) {
            .pending => boxyPlanInvariant("checked type payload was pending during boxy planning"),
            .err => boxyPlanInvariant("checked error type reached boxy representation planning"),
            .flex => |flex| if (self.variableRowIsDefaultClosed(view, ty, .empty_tag_union))
                self.completeRep(rep_id, .{ .source_type = source_type, .kind = .empty_tag_union })
            else
                try self.planDynamicRep(requests, source_type, flex.constraints, .flex, if (!self.host_mode and !self.quantified_variables.contains(source_type)) flex else null),
            .rigid => |rigid| try self.planDynamicRep(requests, source_type, rigid.constraints, .rigid, null),
            .alias => |alias| blk: {
                var roles = std.ArrayList(ChildRole).empty;
                defer roles.deinit(self.allocator);
                try roles.append(self.allocator, .alias_backing);
                try requests.append(self.allocator, self.checkedRequest(view, alias.backing));
                for (alias.args, 0..) |arg, index| {
                    try roles.append(self.allocator, .{ .alias_arg = @intCast(index) });
                    try requests.append(self.allocator, self.checkedRequest(view, arg));
                }
                break :blk try self.childrenFinish(source_type, .alias, &roles, requests.items, false);
            },
            .record => |record| try self.planRecordRep(requests, view, source_type, record.fields, record.ext),
            .tuple => |elems| blk: {
                var roles = std.ArrayList(ChildRole).empty;
                defer roles.deinit(self.allocator);
                for (elems, 0..) |elem, index| {
                    try roles.append(self.allocator, .{ .tuple_elem = @intCast(index) });
                    try requests.append(self.allocator, self.checkedRequest(view, elem));
                }
                break :blk try self.childrenFinish(source_type, .tuple, &roles, requests.items, false);
            },
            .nominal => |nominal| try self.planNominalRep(requests, rep_id, view, source_type, nominal),
            .function => |function| blk: {
                var roles = std.ArrayList(ChildRole).empty;
                defer roles.deinit(self.allocator);
                for (function.args, 0..) |arg, index| {
                    try roles.append(self.allocator, .{ .function_arg = @intCast(index) });
                    try requests.append(self.allocator, self.checkedRequest(view, arg));
                }
                try roles.append(self.allocator, .function_ret);
                try requests.append(self.allocator, self.checkedRequest(view, function.ret));
                break :blk try self.childrenFinish(source_type, .erased_callable, &roles, requests.items, false);
            },
            .empty_record => self.completeRep(rep_id, .{ .source_type = source_type, .kind = .empty_record }),
            .tag_union => |tag_union| if (self.host_mode)
                try self.planHostTagUnionRep(requests, view, source_type, tag_union)
            else
                try self.planTagUnionRep(requests, view, source_type, tag_union),
            .empty_tag_union => self.completeRep(rep_id, .{ .source_type = source_type, .kind = .empty_tag_union }),
        };
    }

    /// Write a component-free representation into the slot the frame
    /// reserved for it.
    fn completeRep(self: *Builder, rep_id: TypeRepId, rep: TypeRepresentation) ?RepFinish {
        self.plan.representations.items[@intFromEnum(rep_id)] = rep;
        return null;
    }

    fn childrenFinish(
        self: *Builder,
        source_type: CheckedTypeIdentity,
        kind: RepresentationKind,
        roles: *std.ArrayList(ChildRole),
        requests: []const RepRequest,
        inspect_opaque: bool,
    ) Allocator.Error!RepFinish {
        const sources = try self.allocator.alloc(CheckedTypeIdentity, requests.len);
        errdefer self.allocator.free(sources);
        for (requests, sources) |request, *source| source.* = requestSourceType(request);
        return .{ .children = .{
            .source_type = source_type,
            .kind = kind,
            .roles = try roles.toOwnedSlice(self.allocator),
            .sources = sources,
            .inspect_opaque = inspect_opaque,
        } };
    }

    fn requestSourceType(request: RepRequest) CheckedTypeIdentity {
        return switch (request) {
            .checked => |value| typeRef(value.view, value.ty),
            .host => |key| key.source,
            .optional_slot => |value| typeRef(value.view, value.ty),
        };
    }

    fn planDynamicRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        source_type: CheckedTypeIdentity,
        constraints: []const checked.CheckedStaticDispatchConstraint,
        kind: DynamicKind,
        sealed_default: ?checked.CheckedTypeVariable,
    ) Allocator.Error!RepFinish {
        const dictionaries = if (self.host_mode) Span.empty() else blk: {
            const span = try self.appendDictionaryEntries(source_type, constraints);
            // Analyzing a constraint's signature appends the requirements of
            // the variables it mentions, which belong to those variables' own
            // spans.
            const view = self.moduleForId(source_type.module);
            for (constraints) |constraint| {
                if (self.constraintIsOwnerlessStructuralEquality(source_type, constraint)) continue;
                try requests.append(self.allocator, self.checkedRequest(view, constraint.fn_ty));
            }
            break :blk span;
        };
        return .{ .dynamic = .{
            .source_type = source_type,
            .kind = kind,
            .dictionaries = dictionaries,
            .sealed_default = sealed_default,
        } };
    }

    fn planRecordRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        view: ModuleView,
        source_type: CheckedTypeIdentity,
        fields: []const checked.CheckedRecordField,
        ext: checked.CheckedTypeId,
    ) Allocator.Error!RepFinish {
        var roles = std.ArrayList(ChildRole).empty;
        defer roles.deinit(self.allocator);
        var kinds = std.ArrayList(checked.CheckedFieldKind).empty;
        defer kinds.deinit(self.allocator);
        const Collect = struct {
            fn field(builder: *Builder, reqs: *std.ArrayList(RepRequest), role_list: *std.ArrayList(ChildRole), kind_list: *std.ArrayList(checked.CheckedFieldKind), field_view: ModuleView, record_field: checked.CheckedRecordField) Allocator.Error!void {
                try role_list.append(builder.allocator, .{ .record_field = record_field.name });
                try kind_list.append(builder.allocator, record_field.kind);
                try reqs.append(builder.allocator, builder.recordFieldRequest(field_view, record_field));
            }
        };
        const closed = if (self.host_mode) host: {
            // Flatten checked rows under their explicit ABI substitution
            // context.
            const saved_context = self.host_context;
            defer self.host_context = saved_context;
            for (fields) |field| try Collect.field(self, requests, &roles, &kinds, view, field);
            var current: HostTypeKey = .{ .source = typeRef(view, ext), .context = saved_context };
            var seen = std.AutoHashMap(HostTypeKey, void).init(self.allocator);
            defer seen.deinit();
            while (true) {
                const key = self.resolveHostBinding(current);
                const entry = try seen.getOrPut(key);
                if (entry.found_existing) boxyPlanInvariant("cyclic checked ABI record row");
                self.host_context = key.context;
                const row_view = self.moduleForId(key.source.module);
                switch (row_view.checked_types.payload(key.source.ty)) {
                    .empty_record => break :host true,
                    .record => |row| {
                        // The checked empty-row fixpoint is an empty record whose
                        // extension is itself. It contributes no additional fields.
                        if (row.fields.len == 0 and row.ext == key.source.ty) break :host true;
                        for (row.fields) |field| try Collect.field(self, requests, &roles, &kinds, row_view, field);
                        current = .{ .source = typeRef(row_view, row.ext), .context = key.context };
                    },
                    .alias => |alias| current = .{ .source = typeRef(row_view, alias.backing), .context = key.context },
                    .flex, .rigid => |variable| break :host variable.row_default == .empty_record,
                    .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => boxyPlanInvariant("checked ABI record extension is not a record row"),
                }
            }
        } else structural: {
            for (fields) |field| try Collect.field(self, requests, &roles, &kinds, view, field);
            var seen = std.AutoHashMap(CheckedTypeIdentity, void).init(self.allocator);
            defer seen.deinit();
            var current = ext;
            while (true) {
                const entry = try seen.getOrPut(typeRef(view, current));
                // A cycle here is only reachable through the structural
                // `.record`/`.alias` links below (`.flex`/`.rigid`/
                // `.empty_record` all return on their first visit). The checker
                // encodes a closed row's empty tail as a zero-field record whose
                // extension is itself, so reaching that fixpoint after
                // collecting at least one field means the whole field set is
                // resolved and the record is a closed concrete record. This is
                // what lets a host-facing entry point whose argument is a
                // concrete record (e.g. `FrameInput`) keep its concrete struct
                // layout across the platform boundary instead of erasing to a
                // dynamic box.
                if (entry.found_existing) break :structural roles.items.len > 0;
                switch (view.checked_types.payload(current)) {
                    .empty_record => break :structural true,
                    .record => |record| {
                        for (record.fields) |field| try Collect.field(self, requests, &roles, &kinds, view, field);
                        current = record.ext;
                    },
                    .alias => |alias| current = alias.backing,
                    .flex, .rigid => break :structural self.variableRowIsDefaultClosed(view, current, .empty_record),
                    .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => break :structural false,
                }
            }
        };
        const sources = try self.allocator.alloc(CheckedTypeIdentity, requests.items.len);
        errdefer self.allocator.free(sources);
        for (requests.items, sources) |request, *source| source.* = requestSourceType(request);
        const owned_roles = try roles.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned_roles);
        return .{ .record = .{
            .source_type = source_type,
            .closed = closed,
            .view = view,
            .roles = owned_roles,
            .sources = sources,
            .kinds = try kinds.toOwnedSlice(self.allocator),
        } };
    }

    fn planHostTagUnionRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        view: ModuleView,
        source_type: CheckedTypeIdentity,
        initial: checked.CheckedTagUnionType,
    ) Allocator.Error!RepFinish {
        const PendingTag = struct { view: ModuleView, context: ?u32, tag: checked.CheckedTag };
        var tags = std.ArrayList(PendingTag).empty;
        defer tags.deinit(self.allocator);
        const saved_context = self.host_context;
        defer self.host_context = saved_context;
        for (initial.tags) |tag| try tags.append(self.allocator, .{ .view = view, .context = saved_context, .tag = tag });
        var current: HostTypeKey = .{ .source = typeRef(view, initial.ext), .context = saved_context };
        var seen = std.AutoHashMap(HostTypeKey, void).init(self.allocator);
        defer seen.deinit();
        var open_extension: ?HostTypeKey = null;
        while (true) {
            current = self.resolveHostBinding(current);
            const entry = try seen.getOrPut(current);
            if (entry.found_existing) boxyPlanInvariant("cyclic checked ABI tag row");
            const row_view = self.moduleForId(current.source.module);
            switch (row_view.checked_types.payload(current.source.ty)) {
                .empty_tag_union => break,
                .tag_union => |row| {
                    for (row.tags) |tag| try tags.append(self.allocator, .{ .view = row_view, .context = current.context, .tag = tag });
                    current.source = typeRef(row_view, row.ext);
                },
                .alias => |alias| current.source = typeRef(row_view, alias.backing),
                .flex, .rigid => |variable| {
                    if (variable.row_default != .empty_tag_union) open_extension = current;
                    break;
                },
                .pending, .err, .record, .tuple, .nominal, .function, .empty_record => boxyPlanInvariant("checked ABI tag extension is not a tag row"),
            }
        }
        if (view.canonical_names != null) std.mem.sort(PendingTag, tags.items, {}, struct {
            fn lessThan(_: void, a: PendingTag, b: PendingTag) bool {
                return std.mem.lessThan(u8, a.view.canonical_names.?.tagLabelText(a.tag.name), b.view.canonical_names.?.tagLabelText(b.tag.name));
            }
        }.lessThan);
        var roles = std.ArrayList(ChildRole).empty;
        defer roles.deinit(self.allocator);
        var variants = std.ArrayList(TagVariant).empty;
        defer variants.deinit(self.allocator);
        for (tags.items) |entry| {
            const start: u32 = @intCast(roles.items.len);
            for (entry.tag.argsSlice(entry.view.checked_types), 0..) |arg, index| {
                try roles.append(self.allocator, .{ .tag_payload = .{ .tag = entry.tag.name, .index = @intCast(index) } });
                try requests.append(self.allocator, .{ .checked = .{ .view = entry.view, .ty = arg, .context = entry.context } });
            }
            try variants.append(self.allocator, .{ .name = entry.tag.name, .name_module = entry.view.key, .payloads = .{ .start = start, .len = entry.tag.args_len } });
        }
        if (open_extension) |ext| {
            try roles.append(self.allocator, .tag_ext);
            try requests.append(self.allocator, .{ .checked = .{ .view = self.moduleForId(ext.source.module), .ty = ext.source.ty, .context = ext.context } });
        }
        const sources = try self.allocator.alloc(CheckedTypeIdentity, requests.items.len);
        errdefer self.allocator.free(sources);
        for (requests.items, sources) |request, *source| source.* = requestSourceType(request);
        const owned_roles = try roles.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned_roles);
        return .{ .host_tag_union = .{
            .source_type = source_type,
            .open = open_extension != null,
            .roles = owned_roles,
            .sources = sources,
            .variants = try variants.toOwnedSlice(self.allocator),
        } };
    }

    fn planTagUnionRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        view: ModuleView,
        source_type: CheckedTypeIdentity,
        tag_union: checked.CheckedTagUnionType,
    ) Allocator.Error!RepFinish {
        var tags = std.ArrayList(checked.CheckedTag).empty;
        defer tags.deinit(self.allocator);
        try tags.appendSlice(self.allocator, tag_union.tags);
        var extension = tag_union.ext;
        var seen = std.AutoHashMap(CheckedTypeIdentity, void).init(self.allocator);
        defer seen.deinit();
        try seen.put(source_type, {});
        while (true) {
            if ((try seen.getOrPut(typeRef(view, extension))).found_existing) {
                boxyPlanInvariant("cyclic checked tag row extension");
            }
            switch (view.checked_types.payload(extension)) {
                .tag_union => |row| {
                    try tags.appendSlice(self.allocator, row.tags);
                    extension = row.ext;
                },
                .alias => |alias| extension = alias.backing,
                .flex, .rigid, .empty_tag_union => break,
                .pending, .err, .record, .tuple, .nominal, .function, .empty_record => boxyPlanInvariant("checked tag extension is not a tag row"),
            }
        }
        const closed = try self.tagUnionExtensionIsExplicitlyClosed(view, extension);
        const ordered_tags = try self.layoutOrderedTagUnionTags(view, tags.items);
        const owned_tags = if (ordered_tags.owned) ordered_tags.tags else try self.allocator.dupe(checked.CheckedTag, ordered_tags.tags);
        errdefer self.allocator.free(owned_tags);

        var roles = std.ArrayList(ChildRole).empty;
        defer roles.deinit(self.allocator);
        for (owned_tags) |tag| {
            for (tag.argsSlice(view.checked_types), 0..) |arg, index| {
                try roles.append(self.allocator, .{ .tag_payload = .{ .tag = tag.name, .index = @intCast(index) } });
                try requests.append(self.allocator, self.checkedRequest(view, arg));
            }
        }
        try roles.append(self.allocator, .tag_ext);
        try requests.append(self.allocator, self.checkedRequest(view, extension));
        const sources = try self.allocator.alloc(CheckedTypeIdentity, requests.items.len);
        errdefer self.allocator.free(sources);
        for (requests.items, sources) |request, *source| source.* = requestSourceType(request);
        const owned_roles = try roles.toOwnedSlice(self.allocator);
        return .{ .tag_union = .{
            .source_type = source_type,
            .closed = closed,
            .view = view,
            .roles = owned_roles,
            .sources = sources,
            .tags = owned_tags,
            .owned_tags = true,
        } };
    }

    fn planNominalRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        rep_id: TypeRepId,
        view: ModuleView,
        source_type: CheckedTypeIdentity,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error!?RepFinish {
        var roles = std.ArrayList(ChildRole).empty;
        defer roles.deinit(self.allocator);
        if (nominal.builtin) |builtin| {
            switch (checked.builtinRuntimeEncoding(builtin)) {
                .primitive => |primitive| return self.completeRep(rep_id, .{
                    .source_type = source_type,
                    .kind = .{ .primitive = primitive },
                }),
                .bool_tag_union => {
                    const backing = try self.nominalBackingSource(view, nominal);
                    try requests.append(self.allocator, self.checkedRequest(backing.view, backing.ty));
                    return .{ .bool_nominal = source_type };
                },
                .try_nominal,
                .iterator,
                => {},
                .list => return try self.planUnaryBuiltinRep(requests, &roles, view, source_type, .list, .list_elem, nominal),
                .box => return try self.planUnaryBuiltinRep(requests, &roles, view, source_type, .box, .box_payload, nominal),
                .parse_tag_union_spec => return try self.planGeneratedEvidenceRep(requests, &roles, view, source_type, .generated_tag_union_spec, nominal),
                .fields => return try self.planGeneratedEvidenceRep(requests, &roles, view, source_type, .generated_field_names, nominal),
                .field => return try self.planGeneratedEvidenceRep(requests, &roles, view, source_type, .generated_field, nominal),
                .dict,
                .set,
                .crypto_sha256_digest,
                .crypto_sha256_hasher,
                .crypto_blake3_digest,
                .crypto_blake3_hasher,
                => {},
            }
        }

        var backing_source: ?TypeSource = null;
        if (nominal.representation != .opaque_without_backing) {
            const backing = try self.nominalBackingSource(view, nominal);
            backing_source = backing;
            try roles.append(self.allocator, .nominal_backing);
            try requests.append(self.allocator, self.checkedRequest(backing.view, backing.ty));
        }
        for (nominal.args, 0..) |arg, index| {
            try roles.append(self.allocator, .{ .nominal_arg = @intCast(index) });
            try requests.append(self.allocator, self.checkedRequest(view, arg));
        }
        const padding_source = self.nominalPaddingSource(view, nominal);
        if (padding_source) |padding| {
            for (padding.types, 0..) |padding_ty, index| {
                try roles.append(self.allocator, .{ .nominal_padding_field = @intCast(index) });
                try requests.append(self.allocator, self.checkedRequest(padding.view, padding_ty));
            }
        }
        const child_count = requests.items.len;
        const sources = try self.allocator.alloc(CheckedTypeIdentity, child_count);
        errdefer self.allocator.free(sources);
        for (requests.items, sources) |request, *source| source.* = requestSourceType(request);
        const backing = try self.nominalBackingSource(view, nominal);
        const declared = try self.planNominalDeclaredFields(requests, view, nominal, backing);
        errdefer self.allocator.free(declared);
        const owned_roles = try roles.toOwnedSlice(self.allocator);
        return .{ .nominal = .{
            .source_type = source_type,
            .view = view,
            .nominal = nominal,
            .backing = backing,
            .roles = owned_roles,
            .sources = sources,
            .declared = declared,
            .kind = .{ .nominal = if (nominal.representation == .opaque_without_backing)
                .opaque_nominal
            else if (nominal.builtin != null)
                .builtin_other
            else
                .transparent },
            .record_field_order = if (padding_source != null) .declared else .structural,
        } };
    }

    fn planUnaryBuiltinRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        roles: *std.ArrayList(ChildRole),
        view: ModuleView,
        source_type: CheckedTypeIdentity,
        kind: RepresentationKind,
        role: ChildRole,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error!RepFinish {
        if (nominal.args.len != 1) {
            boxyPlanInvariant("builtin unary nominal had an unexpected checked argument count");
        }
        try roles.append(self.allocator, role);
        try requests.append(self.allocator, self.checkedRequest(view, nominal.args[0]));
        return try self.childrenFinish(source_type, kind, roles, requests.items, false);
    }

    fn planGeneratedEvidenceRep(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        roles: *std.ArrayList(ChildRole),
        view: ModuleView,
        source_type: CheckedTypeIdentity,
        kind: RepresentationKind,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error!RepFinish {
        for (nominal.args, 0..) |arg, index| {
            try roles.append(self.allocator, .{ .nominal_arg = @intCast(index) });
            try requests.append(self.allocator, self.checkedRequest(view, arg));
        }
        return try self.childrenFinish(source_type, kind, roles, requests.items, true);
    }

    /// List a nominal's declared fields, each with its layout index and
    /// source, and append the analyses of their slot representations to
    /// `requests`. The fields' `rep`s are filled from those analyses.
    fn planNominalDeclaredFields(
        self: *Builder,
        requests: *std.ArrayList(RepRequest),
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        backing: TypeSource,
    ) Allocator.Error![]DeclaredField {
        const source = self.nominalDeclaredSource(view, nominal) orelse return &.{};
        const backing_fields = switch (backing.view.checked_types.payload(backing.ty)) {
            .record => |record| record.fields,
            .pending,
            .err,
            .flex,
            .rigid,
            .alias,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => boxyPlanInvariant("checked nominal declared field order had a non-record backing"),
        };

        // Layout field indices are alphabetical-by-name, matching the index
        // space structural records use, so a value that materializes across an
        // erased structural/nominal boundary pairs fields by the same key on
        // both sides. The backing record's stored field order is not relied on.
        const alpha_ranks = try self.nominalBackingFieldAlphabeticalRanks(backing.view, backing_fields);
        defer self.allocator.free(alpha_ranks);

        var pending = std.ArrayList(DeclaredField).empty;
        defer pending.deinit(self.allocator);
        var padding_ordinal: u32 = 0;
        for (source.fields) |declared| {
            switch (declared) {
                .named => |name| {
                    const field = self.nominalBackingField(source.field_view, backing.view, backing_fields, name) orelse
                        boxyPlanInvariant("checked nominal declared named field was missing from backing row");
                    try pending.append(self.allocator, .{
                        .index = alpha_ranks[field.index],
                        .source_type = typeRef(backing.view, field.ty),
                        .rep = undefined,
                    });
                    try requests.append(self.allocator, self.recordFieldRequest(backing.view, backing_fields[field.index]));
                },
                .padding => |index| {
                    const raw_index: usize = @intCast(index);
                    if (raw_index >= source.padding_types.len) {
                        boxyPlanInvariant("checked nominal declared padding field index was out of range");
                    }
                    const padding_ty = source.padding_types[raw_index];
                    try pending.append(self.allocator, .{
                        .index = @intCast(backing_fields.len + padding_ordinal),
                        .source_type = typeRef(source.padding_view, padding_ty),
                        .rep = undefined,
                        .is_padding = true,
                    });
                    try requests.append(self.allocator, self.checkedRequest(source.padding_view, padding_ty));
                    padding_ordinal += 1;
                },
            }
        }
        return try pending.toOwnedSlice(self.allocator);
    }

    fn commitDeclaredFields(self: *Builder, declared: []DeclaredField, reps: []const TypeRepId) Allocator.Error!Span {
        if (declared.len == 0) return Span.empty();
        for (declared, reps) |*field, rep| field.rep = rep;
        const start: u32 = @intCast(self.plan.declared_fields.items.len);
        try self.plan.declared_fields.appendSlice(self.allocator, declared);
        return .{ .start = start, .len = @intCast(declared.len) };
    }

    fn finishRepBuild(self: *Builder, build: *RepBuild) Allocator.Error!TypeRepresentation {
        const results = build.results;
        switch (build.finish) {
            .dynamic => |dynamic| {
                var rep: TypeRepresentation = .{
                    .source_type = dynamic.source_type,
                    .kind = .{ .dynamic = dynamic.kind },
                    .dictionaries = dynamic.dictionaries,
                    .contains_dynamic = true,
                };
                // A default applies only if nothing resolves the variable:
                // when a scheme quantifies it, each instantiation supplies its
                // type and dictionaries through the scheme's uses, so only an
                // unquantified one seals to its default, and its dispatches
                // then resolve against that default.
                if (dynamic.sealed_default) |variable| {
                    rep.sealed_default = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
                    try self.plan.representations.append(self.allocator, .{
                        .source_type = dynamic.source_type,
                        .kind = variableDefaultKind(variable),
                    });
                }
                return rep;
            },
            .children => |value| return .{
                .source_type = value.source_type,
                .kind = value.kind,
                .children = try self.commitChildren(value.roles, value.sources, results),
                .inspect_opaque = value.inspect_opaque,
            },
            .record => |value| {
                const children = try self.allocator.alloc(RepChild, results.len);
                defer self.allocator.free(children);
                for (children, value.roles, value.sources, results, value.kinds) |*child, role, source, rep, kind| {
                    child.* = .{ .role = role, .source_type = source, .rep = rep, .record_field_kind = kind };
                }
                // Record-field children are ordered alphabetically by name so every
                // record representation shares one identity field-index space (the same
                // order structural record types already carry). Nominal declaration
                // backings, which the checker keeps in source-declared order, are
                // canonicalized here so a value pairs fields identically on both sides of
                // an erased structural/nominal boundary.
                if (self.host_mode and value.view.canonical_names != null) {
                    std.mem.sort(RepChild, children, self, struct {
                        fn lessThan(builder: *Builder, a: RepChild, b: RepChild) bool {
                            const a_names = builder.moduleForId(a.source_type.module).canonical_names.?;
                            const b_names = builder.moduleForId(b.source_type.module).canonical_names.?;
                            return std.mem.lessThan(u8, a_names.recordFieldLabelText(a.role.record_field), b_names.recordFieldLabelText(b.role.record_field));
                        }
                    }.lessThan);
                } else {
                    sortRecordFieldChildrenByName(value.view, children);
                }
                const child_span = try self.commitPendingChildren(children);
                if (!value.closed) return .{
                    .source_type = value.source_type,
                    .kind = .{ .dynamic = .flex },
                    .children = child_span,
                    .contains_dynamic = true,
                };
                return .{
                    .source_type = value.source_type,
                    .kind = .record,
                    .children = child_span,
                };
            },
            .tag_union => |value| {
                const child_span = try self.commitChildren(value.roles, value.sources, results);
                const variant_start: u32 = @intCast(self.plan.tag_variants.items.len);
                var payload_start = child_span.start;
                for (value.tags) |tag| {
                    try self.plan.tag_variants.append(self.allocator, .{
                        .name = tag.name,
                        .name_module = value.view.key,
                        .payloads = .{ .start = payload_start, .len = tag.args_len },
                    });
                    payload_start += tag.args_len;
                }
                const tag_variants: Span = .{ .start = variant_start, .len = @intCast(value.tags.len) };
                if (!value.closed) return .{
                    .source_type = value.source_type,
                    .kind = .{ .dynamic = .flex },
                    .children = child_span,
                    .tag_variants = tag_variants,
                    .is_open_tag_row = true,
                    .contains_dynamic = true,
                };
                return .{
                    .source_type = value.source_type,
                    .kind = .tag_union,
                    .children = child_span,
                    .tag_variants = tag_variants,
                };
            },
            .host_tag_union => |value| {
                const child_span = try self.commitChildren(value.roles, value.sources, results);
                for (value.variants) |*variant| variant.payloads.start += child_span.start;
                const variant_start: u32 = @intCast(self.plan.tag_variants.items.len);
                try self.plan.tag_variants.appendSlice(self.allocator, value.variants);
                return .{
                    .source_type = value.source_type,
                    .kind = if (value.open) .{ .dynamic = .flex } else .tag_union,
                    .children = child_span,
                    .tag_variants = .{ .start = variant_start, .len = @intCast(value.variants.len) },
                    .is_open_tag_row = value.open,
                    .contains_dynamic = value.open,
                };
            },
            .bool_nominal => |source_type| {
                const backing_rep = self.plan.representations.items[@intFromEnum(results[0])];
                if (backing_rep.kind != .tag_union) {
                    boxyPlanInvariant("checked Bool backing was not a closed tag union");
                }
                return .{
                    .source_type = source_type,
                    .kind = .bool_tag_union,
                    .children = backing_rep.children,
                    .tag_variants = backing_rep.tag_variants,
                };
            },
            .nominal => |value| {
                const child_count = value.roles.len;
                const children = try self.allocator.alloc(RepChild, child_count);
                defer self.allocator.free(children);
                for (children, value.roles, value.sources, results[0..child_count]) |*child, role, source, rep| {
                    child.* = .{ .role = role, .source_type = source, .rep = rep };
                }
                const declared_fields = try self.commitDeclaredFields(value.declared, results[child_count..]);
                const backing_arg_substitutions = try self.appendNominalBackingArgSubstitutions(
                    value.view,
                    value.nominal,
                    value.backing.?,
                    children,
                );
                return .{
                    .source_type = value.source_type,
                    .kind = value.kind,
                    .children = try self.commitPendingChildren(children),
                    .declared_fields = declared_fields,
                    .record_field_order = value.record_field_order,
                    .nominal_backing_arg_substitutions = backing_arg_substitutions,
                    .inspect_opaque = value.nominal.is_opaque,
                };
            },
        }
    }

    fn commitChildren(
        self: *Builder,
        roles: []const ChildRole,
        sources: []const CheckedTypeIdentity,
        reps: []const TypeRepId,
    ) Allocator.Error!Span {
        const start: u32 = @intCast(self.plan.children.items.len);
        try self.plan.children.ensureUnusedCapacity(self.allocator, roles.len);
        for (roles, sources, reps) |role, source, rep| {
            self.plan.children.appendAssumeCapacity(.{
                .role = role,
                .source_type = source,
                .rep = rep,
            });
        }
        return .{ .start = start, .len = @intCast(roles.len) };
    }

    fn beginHostNominal(
        self: *Builder,
        frames: *std.ArrayList(RepFrame),
        saved_context: ?u32,
        key: HostTypeKey,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error!void {
        const lookup: NominalDeclarationLookup = switch (nominal.representation) {
            .builtin => .{
                .view = view,
                .declaration = view.checked_types.nominalDeclarationForPayload(nominal) orelse
                    boxyPlanInvariant("checked builtin ABI nominal has no declaration"),
                .padding_view = view,
                .padding_types = &.{},
            },
            .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => self.nominalDeclarationFor(view, nominal) orelse
                boxyPlanInvariant("checked ABI nominal has no declaration"),
        };
        const formals = lookup.declaration.formalArgs(lookup.view.checked_types);
        if (formals.len != nominal.args.len) boxyPlanInvariant("checked ABI nominal argument arity mismatch");
        const sources = try self.allocator.alloc(HostTypeKey, nominal.args.len);
        errdefer self.allocator.free(sources);
        const args = try self.allocator.alloc(TypeRepId, nominal.args.len);
        errdefer self.allocator.free(args);
        for (nominal.args, sources) |arg, *source| {
            source.* = self.resolveHostBinding(.{ .source = typeRef(view, arg), .context = key.context });
        }
        try frames.append(self.allocator, .{ .saved_context = saved_context, .state = .{ .host_nominal = .{
            .key = key,
            .view = view,
            .nominal = nominal,
            .lookup = lookup,
            .sources = sources,
            .args = args,
        } } });
    }

    fn stepHostNominal(self: *Builder, build: *HostNominalBuild, input: ?TypeRepId) Allocator.Error!RepStep {
        switch (build.stage) {
            .args => {
                if (input) |rep| {
                    build.args[build.next] = rep;
                    build.next += 1;
                }
                if (build.next < build.sources.len) return .{ .request = .{ .host = build.sources[build.next] } };

                const nominal_key: HostNominalKey = .{ .module = build.lookup.view.key, .declaration = build.lookup.declaration.id, .args = build.args };
                if (self.host_nominals.get(nominal_key)) |existing| {
                    try self.host_types.put(self.allocator, build.key, existing.rep);
                    return .{ .done = existing.rep };
                }
                const context = self.freshHostContext();
                build.rep = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
                try self.host_nominals.put(self.allocator, nominal_key, .{ .context = context, .rep = build.rep });
                build.args_owned = false;
                try self.host_types.put(self.allocator, build.key, build.rep);
                try self.plan.representations.append(self.allocator, .{ .source_type = build.key.source, .kind = .in_progress });
                const formals = build.lookup.declaration.formalArgs(build.lookup.view.checked_types);
                for (formals, build.sources) |formal, source| {
                    try self.host_bindings.put(self.allocator, .{ .source = typeRef(build.lookup.view, formal), .context = context }, source);
                }
                self.host_context = context;
                build.backing = .{ .view = build.lookup.view, .ty = build.lookup.declaration.backing };
                var requests = std.ArrayList(RepRequest).empty;
                defer requests.deinit(self.allocator);
                try requests.append(self.allocator, self.checkedRequest(build.backing.view, build.backing.ty));
                build.declared = try self.planNominalDeclaredFields(&requests, build.view, build.nominal, build.backing);
                build.requests = try requests.toOwnedSlice(self.allocator);
                build.results = try self.allocator.alloc(TypeRepId, build.requests.len);
                build.next = 0;
                build.stage = .backing;
                return .{ .request = build.requests[0] };
            },
            .backing => {
                build.results[build.next] = input.?;
                build.next += 1;
                if (build.next < build.requests.len) return .{ .request = build.requests[build.next] };

                var children = std.ArrayList(RepChild).empty;
                defer children.deinit(self.allocator);
                try children.append(self.allocator, .{
                    .role = .nominal_backing,
                    .source_type = typeRef(build.backing.view, build.backing.ty),
                    .rep = build.results[0],
                });
                for (build.args, build.sources, 0..) |arg, source, index| {
                    try children.append(self.allocator, .{ .role = .{ .nominal_arg = @intCast(index) }, .source_type = source.source, .rep = arg });
                }
                const declared_fields = try self.commitDeclaredFields(build.declared, build.results[1..]);
                const backing_arg_substitutions = try self.appendNominalBackingArgSubstitutions(build.view, build.nominal, build.backing, children.items);
                const child_span = try self.commitPendingChildren(children.items);
                self.plan.representations.items[@intFromEnum(build.rep)] = .{
                    .source_type = build.key.source,
                    .kind = .{ .nominal = if (build.nominal.builtin != null) .builtin_other else .transparent },
                    .children = child_span,
                    .declared_fields = declared_fields,
                    .nominal_backing_arg_substitutions = backing_arg_substitutions,
                    .record_field_order = if (self.nominalPaddingSource(build.view, build.nominal) != null) .declared else .structural,
                    .inspect_opaque = build.nominal.is_opaque,
                };
                return .{ .done = build.rep };
            },
        }
    }

    /// Append a variable's runtime dictionary requirements. Their method
    /// signatures are analyzed by the caller.
    fn appendDictionaryEntries(
        self: *Builder,
        source_type: CheckedTypeIdentity,
        constraints: []const checked.CheckedStaticDispatchConstraint,
    ) Allocator.Error!Span {
        const start: u32 = @intCast(self.plan.dictionaries.items.len);
        var methods = std.AutoHashMapUnmanaged(checked_names.MethodNameId, void).empty;
        defer methods.deinit(self.allocator);
        for (constraints, 0..) |constraint, index| {
            if (self.constraintIsOwnerlessStructuralEquality(source_type, constraint)) continue;
            if (!static_dispatch.requiresRuntimeDictionary(constraint.origin)) continue;
            // Independent callable relations share the checker's target slot.
            // Their signatures are all analyzed below, including duplicates.
            if (constraints.len > 1 and (try methods.getOrPut(self.allocator, constraint.fn_name)).found_existing) continue;
            try self.plan.dictionaries.append(self.allocator, .{
                .source_type = source_type,
                .constraint_index = @intCast(index),
                .slot = try self.internDictionaryMethodSlot(source_type.module, constraint.fn_name),
                .fn_name = constraint.fn_name,
                .fn_ty = .{ .module = source_type.module, .ty = constraint.fn_ty },
                .origin = constraint.origin,
                .binop_negated = constraint.binopNegated(),
                .num_literal = constraint.numeralInfo(),
            });
        }
        return .{
            .start = start,
            .len = @intCast(self.plan.dictionaries.items.len - start),
        };
    }

    fn appendDictionaryRequirements(
        self: *Builder,
        source_type: CheckedTypeIdentity,
        constraints: []const checked.CheckedStaticDispatchConstraint,
    ) Allocator.Error!Span {
        const span = try self.appendDictionaryEntries(source_type, constraints);
        // Analyzing a constraint's signature appends the requirements of the
        // variables it mentions, which belong to those variables' own spans.
        const view = self.moduleForId(source_type.module);
        for (constraints) |constraint| {
            if (self.constraintIsOwnerlessStructuralEquality(source_type, constraint)) continue;
            _ = try self.analyzeType(view, constraint.fn_ty);
        }
        return span;
    }

    /// The representation kind a checked variable seals to when nothing
    /// quantifies it, following Monotype's `lowerCheckedTypeVariable`.
    fn variableDefaultKind(variable: checked.CheckedTypeVariable) RepresentationKind {
        if (variable.numeric_default_phase) |phase| {
            const target = checked.literal_defaulting.defaultTargetForPhase(phase) orelse
                boxyPlanInvariant("checking-finalized numeric variable reached boxy planning unresolved");
            return .{ .primitive = switch (target) {
                .dec => .dec,
                .str => .str,
            } };
        }
        return if (variable.row_default == .empty_record) .empty_record else .empty_tag_union;
    }

    fn finalizeHostNominalStorage(self: *Builder) Allocator.Error!void {
        var visited = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer visited.deinit();
        var nominals = self.host_nominals.valueIterator();
        while (nominals.next()) |entry| {
            const rep = self.plan.representations.items[@intFromEnum(entry.rep)];
            if (!rep.inspect_opaque) continue;
            const backing = self.plan.childSlice(rep.children)[0].rep;
            if (self.plan.representations.items[@intFromEnum(backing)].kind != .record) continue;
            visited.clearRetainingCapacity();
            self.plan.representations.items[@intFromEnum(entry.rep)].abi_boxed_backing = try self.hostShapeContainsCallable(backing, &visited);
        }
    }

    /// Representations nest with types, so the search keeps its pending
    /// representations on a worklist.
    fn hostShapeContainsCallable(self: *Builder, root: TypeRepId, visited: *collections.DenseMap(TypeRepId, void)) Allocator.Error!bool {
        var pending = std.ArrayList(TypeRepId).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |rep_id| {
            if (visited.contains(rep_id)) continue;
            try visited.put(rep_id, {});
            const rep = self.plan.representations.items[@intFromEnum(rep_id)];
            if (rep.kind == .erased_callable) return true;
            for (self.plan.childSlice(rep.children)) |child| {
                if (childCarriesRuntimeDescriptor(child.role)) try pending.append(self.allocator, child.rep);
            }
        }
        return false;
    }

    fn internTypeBinding(self: *Builder, source_type: CheckedTypeIdentity) Allocator.Error!TypeBindingId {
        const entry = try self.by_type.getOrPut(source_type);
        if (entry.found_existing) return entry.value_ptr.*;
        const id: TypeBindingId = @enumFromInt(@as(u32, @intCast(self.plan.type_reps.items.len)));
        entry.value_ptr.* = id;
        try self.plan.type_reps.append(self.allocator, .{ .source_type = source_type });
        return id;
    }

    /// A stored representation waiting on its component analyses, requested
    /// in order. Stored types nest with the values they describe, so each
    /// waits in a frame on an explicit stack rather than in a native call.
    const StoredRepFrame = struct {
        rep_id: TypeRepId,
        store_view: ModuleView,
        checked_source: CheckedTypeIdentity,
        requests: []check.ConstStore.ConstTypeId,
        results: []TypeRepId,
        next: usize = 0,
        finish: StoredRepFinish,

        fn deinit(frame: *StoredRepFrame, allocator: Allocator) void {
            allocator.free(frame.requests);
            allocator.free(frame.results);
            frame.finish.deinit(allocator);
        }
    };

    const StoredRepFinish = union(enum) {
        unary: struct { kind: RepresentationKind, role: ChildRole },
        tuple,
        record: []const check.ConstStore.TypeField,
        function: void,
        /// Tags in layout order, owned.
        tag_union: []check.ConstStore.TypeTag,
        named: StoredNamedFinish,

        fn deinit(finish: *StoredRepFinish, allocator: Allocator) void {
            switch (finish.*) {
                .unary, .tuple, .record, .function, .named => {},
                .tag_union => |tags| allocator.free(tags),
            }
        }
    };

    const StoredNamedFinish = struct {
        kind: RepresentationKind,
        is_alias: bool,
        inspect_opaque: bool,
        has_backing: bool,
        arg_count: usize,
        declared_order: []const check.ConstStore.TypeDeclaredField,
    };

    fn analyzeStoredType(
        self: *Builder,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
        checked_source: CheckedTypeIdentity,
    ) Allocator.Error!TypeRepId {
        var frames: std.ArrayList(StoredRepFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.deinit(self.allocator);
            frames.deinit(self.allocator);
        }
        var input: ?TypeRepId = try self.beginStoredType(&frames, store_view, ty, checked_source);
        if (frames.items.len == 0) return input.?;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            if (input) |rep| {
                frame.results[frame.next] = rep;
                frame.next += 1;
            }
            if (frame.next < frame.requests.len) {
                input = try self.beginStoredType(&frames, frame.store_view, frame.requests[frame.next], frame.checked_source);
                continue;
            }
            var finished = frames.pop().?;
            defer finished.deinit(self.allocator);
            const rep = try self.finishStoredRep(&finished);
            self.plan.representations.items[@intFromEnum(finished.rep_id)] = rep;
            if (frames.items.len == 0) return finished.rep_id;
            input = finished.rep_id;
        }
    }

    /// The stored type's representation when already known or free of
    /// components; otherwise null after pushing the frame that builds it.
    fn beginStoredType(
        self: *Builder,
        frames: *std.ArrayList(StoredRepFrame),
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
        checked_source: CheckedTypeIdentity,
    ) Allocator.Error!?TypeRepId {
        const source_type = StoredTypeIdentity{ .module = store_view.key, .ty = ty };
        const entry = try self.by_stored_type.getOrPut(source_type);
        if (entry.found_existing) return entry.value_ptr.*;

        const rep_id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        entry.value_ptr.* = rep_id;
        try self.plan.representations.append(self.allocator, .{
            .source_type = checked_source,
            .kind = .in_progress,
        });
        try self.plan.stored_type_reps.append(self.allocator, .{
            .source_type = source_type,
            .rep = rep_id,
        });

        const store = store_view.const_store orelse
            boxyPlanInvariant("stored representation planning had no ConstStore");
        var requests = std.ArrayList(check.ConstStore.ConstTypeId).empty;
        defer requests.deinit(self.allocator);
        const finish: StoredRepFinish = switch (store.type_store.get(ty)) {
            .primitive => |primitive| return self.completeStoredRep(rep_id, .{
                .source_type = checked_source,
                .kind = .{ .primitive = primitive },
            }),
            .zst => return self.completeStoredRep(rep_id, .{ .source_type = checked_source, .kind = .empty_record }),
            .erased => return self.completeStoredRep(rep_id, .{
                .source_type = checked_source,
                .kind = .{ .dynamic = .rigid },
                .contains_dynamic = true,
            }),
            .list => |elem| blk: {
                try requests.append(self.allocator, elem);
                break :blk .{ .unary = .{ .kind = .list, .role = .list_elem } };
            },
            .box => |elem| blk: {
                try requests.append(self.allocator, elem);
                break :blk .{ .unary = .{ .kind = .box, .role = .box_payload } };
            },
            .tuple => |items| blk: {
                try requests.appendSlice(self.allocator, store.type_store.typeSpan(items));
                break :blk .tuple;
            },
            .record => |fields| blk: {
                const field_span = store.type_store.fieldSpan(fields);
                for (field_span) |field| try requests.append(self.allocator, field.ty);
                break :blk .{ .record = field_span };
            },
            .tag_union => |tags| blk: {
                const names = store_view.canonical_names orelse
                    boxyPlanInvariant("stored tag-union representation had no resolved tag labels");
                const ordered = try self.allocator.dupe(check.ConstStore.TypeTag, store.type_store.tagSpan(tags));
                errdefer self.allocator.free(ordered);
                std.mem.sort(check.ConstStore.TypeTag, ordered, names, struct {
                    fn lessThan(name_store: *const checked_names.CanonicalNameStore, lhs: check.ConstStore.TypeTag, rhs: check.ConstStore.TypeTag) bool {
                        return name_store.tagLabelTextLessThan(lhs.checked_name, rhs.checked_name);
                    }
                }.lessThan);
                for (ordered) |tag| try requests.appendSlice(self.allocator, store.type_store.typeSpan(tag.payloads));
                break :blk .{ .tag_union = ordered };
            },
            .func => |function| blk: {
                try requests.appendSlice(self.allocator, store.type_store.typeSpan(function.args));
                try requests.append(self.allocator, function.ret);
                break :blk .function;
            },
            .named => |named| (try self.planStoredNamed(&requests, rep_id, store, checked_source, named)) orelse return rep_id,
        };
        var owned_finish = finish;
        errdefer owned_finish.deinit(self.allocator);
        const owned_requests = try requests.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(owned_requests);
        const results = try self.allocator.alloc(TypeRepId, owned_requests.len);
        errdefer self.allocator.free(results);
        try frames.append(self.allocator, .{
            .rep_id = rep_id,
            .store_view = store_view,
            .checked_source = checked_source,
            .requests = owned_requests,
            .results = results,
            .finish = owned_finish,
        });
        return null;
    }

    fn completeStoredRep(self: *Builder, rep_id: TypeRepId, rep: TypeRepresentation) TypeRepId {
        self.plan.representations.items[@intFromEnum(rep_id)] = rep;
        return rep_id;
    }

    /// A stored named type's component analyses: its backing, its
    /// arguments, then its declared padding fields. Null when its
    /// representation is a builtin leaf, written in place.
    fn planStoredNamed(
        self: *Builder,
        requests: *std.ArrayList(check.ConstStore.ConstTypeId),
        rep_id: TypeRepId,
        store: *const check.ConstStore.ConstStore,
        checked_source: CheckedTypeIdentity,
        named: anytype,
    ) Allocator.Error!?StoredRepFinish {
        if (named.builtin_owner) |owner| switch (owner) {
            .bool => return self.completeStoredNamedLeaf(rep_id, checked_source, .bool_tag_union),
            .str => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .str }),
            .u8 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u8 }),
            .i8 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i8 }),
            .u16 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u16 }),
            .i16 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i16 }),
            .u32 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u32 }),
            .i32 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i32 }),
            .u64 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u64 }),
            .i64 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i64 }),
            .u128 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u128 }),
            .i128 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i128 }),
            .f32 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .f32 }),
            .f64 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .f64 }),
            .dec => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .dec }),
            .u8x16 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u8x16 }),
            .i8x16 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i8x16 }),
            .u16x8 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u16x8 }),
            .i16x8 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i16x8 }),
            .u32x4 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u32x4 }),
            .i32x4 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i32x4 }),
            .u64x2 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .u64x2 }),
            .i64x2 => return self.completeStoredNamedLeaf(rep_id, checked_source, .{ .primitive = .i64x2 }),
            .list, .box => {
                const args = store.type_store.typeSpan(named.args);
                if (args.len != 1) boxyPlanInvariant("stored unary builtin had an unexpected argument count");
                try requests.append(self.allocator, args[0]);
                return .{ .unary = if (owner == .list)
                    .{ .kind = .list, .role = .list_elem }
                else
                    .{ .kind = .box, .role = .box_payload } };
            },
            .dict,
            .set,
            .fields,
            .field,
            .parse_tag_union_spec,
            .crypto_sha256_digest,
            .crypto_sha256_hasher,
            .crypto_blake3_digest,
            .crypto_blake3_hasher,
            .iter,
            .stream,
            => {},
        };

        if (named.backing) |backing| try requests.append(self.allocator, backing.ty);
        const args = store.type_store.typeSpan(named.args);
        try requests.appendSlice(self.allocator, args);
        const declared_order = store.type_store.declaredFieldSpan(named.declared_order);
        if (declared_order.len != 0) {
            if (named.kind == .alias) boxyPlanInvariant("stored alias carried nominal declared field order");
            if (named.backing == null) boxyPlanInvariant("stored nominal declared field order had no backing representation");
        }
        for (declared_order) |declared| switch (declared) {
            .named => {},
            .padding => |padding_type| try requests.append(self.allocator, padding_type),
        };
        const kind: RepresentationKind = if (named.kind == .alias)
            .alias
        else if (named.builtin_owner == .fields)
            .generated_field_names
        else if (named.builtin_owner == .field)
            .generated_field
        else if (named.builtin_owner == .parse_tag_union_spec)
            .generated_tag_union_spec
        else
            .{ .nominal = if (named.backing == null)
                .opaque_nominal
            else if (named.builtin_owner != null)
                .builtin_other
            else
                .transparent };
        return .{ .named = .{
            .kind = kind,
            .is_alias = named.kind == .alias,
            .inspect_opaque = named.kind == .@"opaque" or
                kind == .generated_field or
                kind == .generated_field_names or
                kind == .generated_tag_union_spec,
            .has_backing = named.backing != null,
            .arg_count = args.len,
            .declared_order = declared_order,
        } };
    }

    fn completeStoredNamedLeaf(self: *Builder, rep_id: TypeRepId, checked_source: CheckedTypeIdentity, kind: RepresentationKind) ?StoredRepFinish {
        self.plan.representations.items[@intFromEnum(rep_id)] = .{ .source_type = checked_source, .kind = kind };
        return null;
    }

    fn storedChild(self: *const Builder, role: ChildRole, rep: TypeRepId) RepChild {
        return .{
            .role = role,
            .source_type = self.plan.representations.items[@intFromEnum(rep)].source_type,
            .rep = rep,
        };
    }

    fn finishStoredRep(self: *Builder, frame: *StoredRepFrame) Allocator.Error!TypeRepresentation {
        const checked_source = frame.checked_source;
        const results = frame.results;
        var children = std.ArrayList(RepChild).empty;
        defer children.deinit(self.allocator);
        switch (frame.finish) {
            .unary => |unary| {
                try children.append(self.allocator, self.storedChild(unary.role, results[0]));
                return .{
                    .source_type = checked_source,
                    .kind = unary.kind,
                    .children = try self.commitPendingChildren(children.items),
                };
            },
            .tuple => {
                for (results, 0..) |rep, index| try children.append(self.allocator, self.storedChild(.{ .tuple_elem = @intCast(index) }, rep));
                return .{
                    .source_type = checked_source,
                    .kind = .tuple,
                    .children = try self.commitPendingChildren(children.items),
                };
            },
            .record => |fields| {
                for (fields, results) |field, rep| {
                    var child = self.storedChild(.{ .record_field = field.name }, rep);
                    child.record_field_kind = if (field.value_ty != null)
                        checked.CheckedFieldKind.optional
                    else if (field.default != null)
                        .{ .tag = .defaulted }
                    else
                        checked.CheckedFieldKind.required;
                    try children.append(self.allocator, child);
                }
                sortRecordFieldChildrenByName(frame.store_view, children.items);
                return .{
                    .source_type = checked_source,
                    .kind = if (children.items.len == 0) .empty_record else .record,
                    .children = try self.commitPendingChildren(children.items),
                };
            },
            .function => {
                for (results[0 .. results.len - 1], 0..) |rep, index| try children.append(self.allocator, self.storedChild(.{ .function_arg = @intCast(index) }, rep));
                try children.append(self.allocator, self.storedChild(.function_ret, results[results.len - 1]));
                return .{
                    .source_type = checked_source,
                    .kind = .erased_callable,
                    .children = try self.commitPendingChildren(children.items),
                };
            },
            .tag_union => |ordered| {
                const store = frame.store_view.const_store.?;
                var next: usize = 0;
                for (ordered) |tag| {
                    const payloads = store.type_store.typeSpan(tag.payloads);
                    for (0..payloads.len) |index| {
                        try children.append(self.allocator, self.storedChild(.{ .tag_payload = .{ .tag = tag.checked_name, .index = @intCast(index) } }, results[next]));
                        next += 1;
                    }
                }
                const child_span = try self.commitPendingChildren(children.items);
                const variant_start: u32 = @intCast(self.plan.tag_variants.items.len);
                var payload_start = child_span.start;
                for (ordered) |tag| {
                    const payloads = store.type_store.typeSpan(tag.payloads);
                    try self.plan.tag_variants.append(self.allocator, .{
                        .name = tag.checked_name,
                        .name_module = frame.store_view.key,
                        .payloads = .{ .start = payload_start, .len = @intCast(payloads.len) },
                    });
                    payload_start += @intCast(payloads.len);
                }
                return .{
                    .source_type = checked_source,
                    .kind = if (ordered.len == 0) .empty_tag_union else .tag_union,
                    .children = child_span,
                    .tag_variants = .{ .start = variant_start, .len = @intCast(ordered.len) },
                };
            },
            .named => |named| return try self.finishStoredNamed(&children, checked_source, named, results),
        }
    }

    fn finishStoredNamed(
        self: *Builder,
        children: *std.ArrayList(RepChild),
        checked_source: CheckedTypeIdentity,
        named: StoredNamedFinish,
        results: []const TypeRepId,
    ) Allocator.Error!TypeRepresentation {
        var next: usize = 0;
        var backing_rep: ?TypeRepId = null;
        if (named.has_backing) {
            backing_rep = results[0];
            try children.append(self.allocator, self.storedChild(if (named.is_alias) .alias_backing else .nominal_backing, results[0]));
            next = 1;
        }
        for (0..named.arg_count) |index| {
            try children.append(self.allocator, self.storedChild(if (named.is_alias)
                .{ .alias_arg = @intCast(index) }
            else
                .{ .nominal_arg = @intCast(index) }, results[next]));
            next += 1;
        }
        var declared_fields = Span.empty();
        var record_field_order: RecordFieldOrder = .structural;
        var has_declared_padding = false;
        for (named.declared_order) |field| {
            has_declared_padding = has_declared_padding or field == .padding;
        }
        if (named.declared_order.len != 0) {
            const backing_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(backing_rep.?)].children);
            var pending = std.ArrayList(DeclaredField).empty;
            defer pending.deinit(self.allocator);
            var padding_ordinal: u32 = 0;
            var backing_field_count: usize = 0;
            for (backing_children) |child| {
                if (child.role == .record_field) backing_field_count += 1;
            }
            if (backing_field_count > std.math.maxInt(u32)) {
                boxyPlanInvariant("stored nominal backing field count exceeded Boxy layout range");
            }
            // Each backing field by label, so every declared field resolves in
            // constant time.
            var backing_fields: std.AutoHashMapUnmanaged(RecordFieldLabelId, DeclaredField) = .empty;
            defer backing_fields.deinit(self.allocator);
            try backing_fields.ensureTotalCapacity(self.allocator, @intCast(backing_field_count));
            var field_index: u32 = 0;
            for (backing_children) |child| {
                if (child.role != .record_field) continue;
                const entry = backing_fields.getOrPutAssumeCapacity(child.role.record_field);
                if (entry.found_existing) boxyPlanInvariant("stored nominal backing had a duplicate declared field");
                entry.value_ptr.* = .{
                    .index = field_index,
                    .source_type = child.source_type,
                    .rep = child.rep,
                };
                field_index += 1;
            }
            for (named.declared_order) |declared| switch (declared) {
                .named => |name| {
                    try pending.append(self.allocator, backing_fields.get(name) orelse
                        boxyPlanInvariant("stored nominal declared field was absent from its backing record"));
                },
                .padding => {
                    const padding_rep = results[next];
                    next += 1;
                    try children.append(self.allocator, self.storedChild(.{ .nominal_padding_field = padding_ordinal }, padding_rep));
                    if (padding_ordinal > std.math.maxInt(u32) - backing_field_count) {
                        boxyPlanInvariant("stored nominal declared field count exceeded Boxy layout range");
                    }
                    try pending.append(self.allocator, .{
                        .index = @intCast(backing_field_count + padding_ordinal),
                        .source_type = self.plan.representations.items[@intFromEnum(padding_rep)].source_type,
                        .rep = padding_rep,
                        .is_padding = true,
                    });
                    padding_ordinal += 1;
                },
            };
            const start: u32 = @intCast(self.plan.declared_fields.items.len);
            try self.plan.declared_fields.appendSlice(self.allocator, pending.items);
            declared_fields = .{ .start = start, .len = @intCast(pending.items.len) };
            if (has_declared_padding) record_field_order = .declared;
        }
        return .{
            .source_type = checked_source,
            .kind = named.kind,
            .children = try self.commitPendingChildren(children.items),
            .declared_fields = declared_fields,
            .record_field_order = record_field_order,
            .inspect_opaque = named.inspect_opaque,
        };
    }

    /// Whether the checked constraint is the ownerless structural-equality
    /// placeholder on a bare flex variable that no enclosing scheme quantifies.
    /// Check leaves that placeholder on undetermined variables inside values
    /// compared with structural equality; it discharges by comparing
    /// structurally with no owner (Check's ambiguity judgment applies the same
    /// carve-out), so planning seals the variable like an unconstrained one and
    /// records no dictionary for it. A quantified variable's `is_eq` erased
    /// requirement
    /// is owned instead—the scheme forwards it as compiler-derived structural
    /// evidence—so it keeps its dictionary requirement.
    fn constraintIsOwnerlessStructuralEquality(
        self: *Builder,
        source_type: CheckedTypeIdentity,
        constraint: checked.CheckedStaticDispatchConstraint,
    ) bool {
        if (self.quantified_variables.contains(source_type)) return false;
        const names = self.moduleForId(source_type.module).canonical_names orelse return false;
        for (static_dispatch.structural_method_kinds) |entry| {
            if (entry.kind != .equality) continue;
            if (std.mem.eql(u8, names.methodNameText(constraint.fn_name), entry.method_name)) return true;
        }
        return false;
    }

    /// Sort a record representation's record-field children alphabetically by
    /// name. All children of a record representation carry the `record_field`
    /// role, so the whole slice is sorted. When the view has no name store, or a
    /// label has no interned text (minimal test fixtures), the checker-supplied
    /// order is left in place.
    fn sortRecordFieldChildrenByName(view: ModuleView, children: []RepChild) void {
        const names = view.canonical_names orelse return;
        for (children) |child| {
            if (child.role != .record_field) return;
            if (!names.recordFieldLabelTextInterned(child.role.record_field)) return;
        }
        const SortContext = struct {
            names: *const checked_names.CanonicalNameStore,
            fn lessThan(ctx: @This(), a: RepChild, b: RepChild) bool {
                if (a.role != .record_field or b.role != .record_field) return false;
                const a_label = a.role.record_field;
                const b_label = b.role.record_field;
                return ctx.names.recordFieldLabelTextLessThan(a_label, b_label);
            }
        };
        std.mem.sort(RepChild, children, SortContext{ .names = names }, SortContext.lessThan);
    }

    fn appendNominalBackingArgSubstitutions(
        self: *Builder,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        backing: TypeSource,
        children: []const RepChild,
    ) Allocator.Error!NominalBackingSubstitutions {
        if (nominal.args.len == 0) return .{};

        const FormalSource = struct {
            view: ModuleView,
            declaration: checked.CheckedNominalDeclaration,
        };
        const formal_source: FormalSource = if (backing.view.checked_types.nominalDeclarationForPayload(nominal)) |declaration|
            .{ .view = backing.view, .declaration = declaration }
        else if (self.nominalDeclarationFor(view, nominal)) |lookup|
            .{ .view = lookup.view, .declaration = lookup.declaration }
        else
            boxyPlanInvariant("checked nominal arguments had no declaration formals");
        const formal_args = formal_source.declaration.formalArgs(formal_source.view.checked_types);
        if (formal_args.len != nominal.args.len) {
            boxyPlanInvariant("checked nominal backing substitution arity disagreed with nominal arguments");
        }

        const entry = try self.nominal_declaration_formals.getOrPut(.{
            .module = formal_source.view.key,
            .declaration = formal_source.declaration.id,
        });
        if (!entry.found_existing) {
            const start: u32 = @intCast(self.plan.nominal_backing_formals.items.len);
            try self.plan.nominal_backing_formals.ensureUnusedCapacity(self.allocator, formal_args.len);
            for (formal_args) |formal_ty| {
                const binding = try self.internTypeBinding(typeRef(formal_source.view, formal_ty));
                self.plan.nominal_backing_formals.appendAssumeCapacity(binding);
            }
            entry.value_ptr.* = .{ .start = start, .len = @intCast(formal_args.len) };
        }
        const formals = entry.value_ptr.*;
        std.debug.assert(formals.len == nominal.args.len);

        const start: u32 = @intCast(self.plan.nominal_backing_uses.items.len);
        try self.plan.nominal_backing_uses.ensureUnusedCapacity(self.allocator, 1 + nominal.args.len);
        self.plan.nominal_backing_uses.appendAssumeCapacity(formals.start);
        var next_arg: u32 = 0;
        for (children) |child| {
            if (child.role != .nominal_arg) continue;
            if (child.role.nominal_arg != next_arg) {
                boxyPlanInvariant("checked nominal argument children were not in declaration order");
            }
            self.plan.nominal_backing_uses.appendAssumeCapacity(@intFromEnum(child.rep));
            next_arg += 1;
        }
        if (next_arg != formals.len) {
            boxyPlanInvariant("checked nominal representation was missing an argument child");
        }
        return .{ .start = start, .len = formals.len };
    }

    const NominalPaddingSource = struct {
        view: ModuleView,
        types: []const checked.CheckedTypeId,
    };

    const TypeSource = struct {
        view: ModuleView,
        ty: checked.CheckedTypeId,
    };

    const NominalDeclaredSource = struct {
        field_view: ModuleView,
        fields: []const checked.CheckedDeclaredField,
        padding_view: ModuleView,
        padding_types: []const checked.CheckedTypeId,
    };

    const NominalDeclarationLookup = struct {
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
        padding_view: ModuleView,
        padding_types: []const checked.CheckedTypeId,
    };

    fn nominalBackingSource(
        self: *Builder,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error!TypeSource {
        return switch (nominal.representation) {
            .local_box_payload_capability => |capability| .{
                .view = view,
                .ty = view.interface_capabilities.boxPayloadCapability(capability.capability).backing_ty,
            },
            .imported_box_payload_capability => |capability| blk: {
                const source_view = self.moduleForId(checked.importedBoxPayloadCapabilityModuleId(capability));
                const source_capability = source_view.interface_capabilities.boxPayloadCapability(capability.capability);
                break :blk .{ .view = source_view, .ty = source_capability.backing_ty };
            },
            .builtin,
            .local_declaration,
            .imported_declaration,
            => .{ .view = view, .ty = view.checked_types.nominalBackingTemplateForPayload(nominal) orelse
                boxyPlanInvariant("checked nominal representation had no declaration backing") },
            .opaque_without_backing => boxyPlanInvariant("opaque nominal without backing reached Boxy backing planning"),
        };
    }

    fn nominalPaddingSource(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) ?NominalPaddingSource {
        if (nominal.padding_field_types.len != 0) return .{
            .view = view,
            .types = nominal.padding_field_types,
        };
        if (nominal.builtin != null) return null;
        const lookup = self.nominalDeclarationFor(view, nominal) orelse return null;
        if (lookup.padding_types.len == 0) return null;
        return .{
            .view = lookup.padding_view,
            .types = lookup.padding_types,
        };
    }

    fn nominalDeclaredSource(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) ?NominalDeclaredSource {
        if (nominal.declared_fields.len != 0) {
            return .{
                .field_view = view,
                .fields = nominal.declared_fields,
                .padding_view = view,
                .padding_types = nominal.padding_field_types,
            };
        }
        if (nominal.builtin != null) return null;
        const lookup = self.nominalDeclarationFor(view, nominal) orelse return null;
        const fields = lookup.declaration.declaredFields(lookup.view.checked_types);
        if (fields.len == 0) return null;
        return .{
            .field_view = lookup.view,
            .fields = fields,
            .padding_view = lookup.padding_view,
            .padding_types = lookup.padding_types,
        };
    }

    fn nominalDeclarationFor(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) ?NominalDeclarationLookup {
        return switch (nominal.representation) {
            .local_declaration => |id| blk: {
                const declaration = view.checked_types.nominalDeclarationById(id);
                break :blk .{
                    .view = view,
                    .declaration = declaration,
                    .padding_view = view,
                    .padding_types = declaration.paddingFieldTypes(view.checked_types),
                };
            },
            .imported_declaration => |imported| blk: {
                const source_view = self.moduleForId(checked.importedNominalDeclarationModuleId(imported));
                const declaration = source_view.checked_types.nominalDeclarationById(imported.declaration);
                break :blk .{
                    .view = source_view,
                    .declaration = declaration,
                    .padding_view = source_view,
                    .padding_types = declaration.paddingFieldTypes(source_view.checked_types),
                };
            },
            .local_box_payload_capability => |capability_ref| blk: {
                const capability = view.interface_capabilities.boxPayloadCapability(capability_ref.capability);
                const declaration = view.checked_types.nominalDeclaration(capability.nominal) orelse break :blk null;
                break :blk .{
                    .view = view,
                    .declaration = declaration,
                    .padding_view = view,
                    .padding_types = capability.paddingFieldTys(view.interface_capabilities),
                };
            },
            .imported_box_payload_capability => |capability_ref| blk: {
                const source_view = self.moduleForId(checked.importedBoxPayloadCapabilityModuleId(capability_ref));
                const capability = source_view.interface_capabilities.boxPayloadCapability(capability_ref.capability);
                const declaration = source_view.checked_types.nominalDeclaration(capability.nominal) orelse break :blk null;
                break :blk .{
                    .view = source_view,
                    .declaration = declaration,
                    .padding_view = source_view,
                    .padding_types = capability.paddingFieldTys(source_view.interface_capabilities),
                };
            },
            .builtin => |builtin_nominal| blk: {
                const declaration = view.checked_types.builtinNominalDeclaration(builtin_nominal) orelse break :blk null;
                break :blk .{
                    .view = view,
                    .declaration = declaration,
                    .padding_view = view,
                    .padding_types = declaration.paddingFieldTypes(view.checked_types),
                };
            },
            .opaque_without_backing => null,
        };
    }

    /// For each backing-record field position, its rank when the backing
    /// record's field names are ordered alphabetically. This is the identity
    /// field index space (shared with structural records). When the backing
    /// view has no name store to compare text with, the backing order is taken
    /// as checked_names.
    fn nominalBackingFieldAlphabeticalRanks(
        self: *Builder,
        backing_view: ModuleView,
        backing_fields: []const checked.CheckedRecordField,
    ) Allocator.Error![]u32 {
        const ranks = try self.allocator.alloc(u32, backing_fields.len);
        errdefer self.allocator.free(ranks);
        const names = backing_view.canonical_names orelse {
            for (ranks, 0..) |*rank, index| rank.* = @intCast(index);
            return ranks;
        };
        for (backing_fields) |field| {
            if (!names.recordFieldLabelTextInterned(field.name)) {
                for (ranks, 0..) |*rank, index| rank.* = @intCast(index);
                return ranks;
            }
        }

        const order = try self.allocator.alloc(u32, backing_fields.len);
        defer self.allocator.free(order);
        for (order, 0..) |*slot, index| slot.* = @intCast(index);

        const SortContext = struct {
            names: *const checked_names.CanonicalNameStore,
            fields: []const checked.CheckedRecordField,
            fn lessThan(ctx: @This(), lhs: u32, rhs: u32) bool {
                return ctx.names.recordFieldLabelTextLessThan(ctx.fields[lhs].name, ctx.fields[rhs].name);
            }
        };
        std.mem.sort(u32, order, SortContext{ .names = names, .fields = backing_fields }, SortContext.lessThan);

        for (order, 0..) |backing_pos, rank| ranks[backing_pos] = @intCast(rank);
        return ranks;
    }

    const NominalBackingField = struct {
        index: u32,
        ty: checked.CheckedTypeId,
    };

    fn nominalBackingField(
        _: *Builder,
        field_view: ModuleView,
        backing_view: ModuleView,
        backing_fields: []const checked.CheckedRecordField,
        name: RecordFieldLabelId,
    ) ?NominalBackingField {
        for (backing_fields, 0..) |field, index| {
            if (recordFieldNameMatches(moduleNamesOf(field_view), name, moduleNamesOf(backing_view), field.name)) return .{
                .index = @intCast(index),
                .ty = field.ty,
            };
        }
        return null;
    }

    const OrderedTags = struct {
        tags: []const checked.CheckedTag,
        owned: bool,
    };

    fn layoutOrderedTagUnionTags(
        self: *Builder,
        view: ModuleView,
        tags: []const checked.CheckedTag,
    ) Allocator.Error!OrderedTags {
        const names = view.canonical_names orelse return .{
            .tags = tags,
            .owned = false,
        };
        if (tags.len < 2) return .{
            .tags = tags,
            .owned = false,
        };

        const sorted = try self.allocator.dupe(checked.CheckedTag, tags);
        errdefer self.allocator.free(sorted);
        std.mem.sort(checked.CheckedTag, sorted, names, struct {
            fn lessThan(name_store: *const checked_names.CanonicalNameStore, lhs: checked.CheckedTag, rhs: checked.CheckedTag) bool {
                return name_store.tagLabelTextLessThan(lhs.name, rhs.name);
            }
        }.lessThan);

        for (sorted[1..], 1..) |tag, index| {
            if (names.tagLabelTextEql(sorted[index - 1].name, tag.name)) {
                boxyPlanInvariant("boxy tag-union representation encountered duplicate tag names");
            }
        }

        return .{
            .tags = sorted,
            .owned = true,
        };
    }

    fn tagUnionExtensionIsExplicitlyClosed(
        self: *Builder,
        view: ModuleView,
        ext_ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(CheckedTypeIdentity, void).init(self.allocator);
        defer seen.deinit();
        // Aliases chain to the row's closing type.
        var current = ext_ty;
        while (true) {
            const entry = try seen.getOrPut(typeRef(view, current));
            if (entry.found_existing) return false;
            switch (view.checked_types.payload(current)) {
                .empty_tag_union => return true,
                .alias => |alias| current = alias.backing,
                .flex, .rigid => return self.variableRowIsDefaultClosed(view, current, .empty_tag_union),
                .pending, .err, .record, .tuple, .nominal, .function, .empty_record, .tag_union => return false,
            }
        }
    }

    fn internDictionaryMethodSlot(
        self: *Builder,
        module: checked.ModuleId,
        method: MethodNameId,
    ) Allocator.Error!u32 {
        const source_names = self.moduleForId(module).canonical_names;
        for (self.plan.dictionary_method_slots.items, 0..) |existing, slot| {
            const existing_names = self.moduleForId(existing.module).canonical_names;
            const same_method = if (source_names != null and existing_names != null)
                std.mem.eql(
                    u8,
                    source_names.?.methodNameText(method),
                    existing_names.?.methodNameText(existing.method),
                )
            else
                std.meta.eql(module, existing.module) and method == existing.method;
            if (same_method) return @intCast(slot);
        }

        const slot: u32 = @intCast(self.plan.dictionary_method_slots.items.len);
        try self.plan.dictionary_method_slots.append(self.allocator, .{
            .module = module,
            .method = method,
        });
        return slot;
    }

    fn commitPendingChildren(self: *Builder, pending: []const RepChild) Allocator.Error!Span {
        const start: u32 = @intCast(self.plan.children.items.len);
        try self.plan.children.appendSlice(self.allocator, pending);
        return .{ .start = start, .len = @intCast(pending.len) };
    }

    fn materializeGeneratedParserTagUnionPlans(self: *Builder) Allocator.Error!void {
        for (self.plan.generated_codec_calls.items) |call| {
            const method_view = self.moduleForId(call.method_module);
            const method_names = method_view.canonical_names orelse
                boxyPlanInvariant("generated parser tag-union method module had no checked names");
            if (!std.mem.eql(u8, method_names.methodNameText(call.method), "parse_tag_union")) continue;

            const shape_type = call.subject_type orelse
                boxyPlanInvariant("generated parse_tag_union call had no checked subject type");
            var reachable = std.ArrayList(WorkerPlanId).empty;
            defer reachable.deinit(self.allocator);
            try reachable.append(self.allocator, call.worker);

            var index: usize = 0;
            while (index < reachable.items.len) : (index += 1) {
                const worker = reachable.items[index];
                if (self.intrinsicForWorker(worker)) |intrinsic| {
                    if (intrinsic == .parse_tag_union) {
                        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
                        if (arg_types.len != 3) {
                            boxyPlanInvariant("generated parse_tag_union call had an unexpected argument count");
                        }
                        try self.appendGeneratedParserTagUnionPlan(
                            worker,
                            call.caller,
                            shape_type,
                            call.dispatch_type,
                            arg_types[2],
                        );
                    }
                }
                for (self.plan.direct_calls.items) |direct| {
                    if (direct.caller != worker) continue;
                    var already_reachable = false;
                    for (reachable.items) |existing| {
                        if (existing == direct.worker) {
                            already_reachable = true;
                            break;
                        }
                    }
                    if (already_reachable) continue;
                    try reachable.append(self.allocator, direct.worker);
                }
            }
        }
    }

    fn appendGeneratedParserTagUnionPlan(
        self: *Builder,
        intrinsic_worker: WorkerPlanId,
        contract_worker: WorkerPlanId,
        shape_type: CheckedTypeIdentity,
        encoding_type: CheckedTypeIdentity,
        state_type: CheckedTypeIdentity,
    ) Allocator.Error!void {
        for (self.plan.generated_parser_tag_union_plans.items) |existing| {
            if (existing.intrinsic_worker != intrinsic_worker) continue;
            if (existing.contract_worker != contract_worker or !typeRefEql(existing.shape_type, shape_type)) continue;
            if (!typeRefEql(existing.encoding_type, encoding_type) or !typeRefEql(existing.state_type, state_type)) {
                boxyPlanInvariant("generated tag-union parser plan had conflicting exact argument types");
            }
            return;
        }

        const start: u32 = @intCast(self.plan.generated_parser_tag_union_record_types.items.len);
        for (self.plan.generated_parser_field_captures.items) |capture| {
            if (capture.worker != contract_worker) continue;
            const current = self.plan.generated_parser_tag_union_record_types.items[start..];
            var found = false;
            for (current) |record_type| {
                if (typeRefEql(record_type, capture.record_type)) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                try self.plan.generated_parser_tag_union_record_types.append(self.allocator, capture.record_type);
            }
        }
        const len: u32 = @intCast(self.plan.generated_parser_tag_union_record_types.items.len - start);
        const runtime_id: u32 = @intCast(self.plan.generated_parser_tag_union_plans.items.len);
        try self.plan.generated_parser_tag_union_plans.append(self.allocator, .{
            .runtime_id = runtime_id,
            .intrinsic_worker = intrinsic_worker,
            .contract_worker = contract_worker,
            .shape_type = shape_type,
            .encoding_type = encoding_type,
            .state_type = state_type,
            .record_types = .{ .start = start, .len = len },
        });
    }

    fn intrinsicForWorker(self: *Builder, worker: WorkerPlanId) ?checked.IntrinsicId {
        const source = self.plan.workers.items[@intFromEnum(worker)].source;
        return switch (source) {
            .generated_codec,
            .generated_field_iterator,
            .generated_interpolation_step,
            => null,
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            => switch (self.rootWorkerBody(source)) {
                .intrinsic_wrapper => |intrinsic| intrinsic.wrapper.intrinsic,
                .checked_expr, .hosted_proc, .unimplemented => null,
            },
        };
    }

    fn observeNumeralEvidence(self: *Builder, root_view: ModuleView, root_entries: []const static_dispatch.CheckedEvidence, root_schema: ?WorkerEvidenceParams) Allocator.Error!void {
        const Cursor = struct { view: ModuleView, entries: []const static_dispatch.CheckedEvidence, schema: ?WorkerEvidenceParams, index: usize = 0 };
        var cursors: std.ArrayList(Cursor) = .empty;
        defer cursors.deinit(self.allocator);
        try cursors.append(self.allocator, .{ .view = root_view, .entries = root_entries, .schema = root_schema });
        while (cursors.items.len != 0) {
            const top = &cursors.items[cursors.items.len - 1];
            if (top.index == top.entries.len) {
                cursors.items.len -= 1;
                continue;
            }
            const index = top.index;
            top.index += 1;
            const view = top.view;
            const entry = top.entries[index];
            if (top.schema) |params| {
                if (index >= params.params.len) boxyPlanInvariant("checked numeral evidence exceeded its declared scheme");
                const param = params.params[index];
                if (std.mem.eql(u8, params.view.canonical_names.?.methodNameText(param.method), "from_numeral")) {
                    const owner = methodOwnerForModuleType(view, entry.dispatcher_ty);
                    if (owner != null and owner.? == .nominal and !self.has_custom_numeral) {
                        self.has_custom_numeral = true;
                        // Method discovery can reveal a custom numeral after
                        // earlier workers' ordinary ABIs were planned.
                        var cached = self.scheme_dictionary_params.valueIterator();
                        while (cached.next()) |params_| self.allocator.free(params_.*);
                        self.scheme_dictionary_params.clearRetainingCapacity();
                    }
                }
            }
            if (entry.resolution != .direct) continue;
            const edge = DictionaryMethodEvidence.EvidenceEdge{ .module = view.key, .node = entry.resolution.direct };
            if ((try self.observed_numeral_evidence.getOrPut(self.allocator, edge)).found_existing) continue;
            const node = view.static_dispatch_plans.evidenceNode(edge.node);
            const nested_schema: ?WorkerEvidenceParams = switch (node.target.kind) {
                .procedure => |procedure| self.templateEvidenceParams(procedure.template),
                .local_proc => |local| self.nestedExprEvidenceParams(view, self.nestedCallableSiteExprForExpr(view, local.expr) orelse local.expr),
                .structural => null,
            };
            switch (node.nested) {
                .resolved => try cursors.append(self.allocator, .{ .view = view, .entries = view.static_dispatch_plans.nestedEvidence(node), .schema = nested_schema }),
                // The target's nested evidence travels with the callable value
                // and is observed through that callable's own use.
                .from_callable => {},
            }
        }
    }

    /// Resolve the owner recorded by a checked lexical evidence coordinate.
    fn workerEvidenceKey(self: *Builder, worker_id: WorkerPlanId, index: static_dispatch.EvidenceChainIndex) SchemeDictionaryKey {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const own = self.workerEvidenceParams(worker.source);
        if (index.depth == 0) if (own) |schema| {
            if (index.index >= schema.params.len) boxyPlanInvariant("numeral evidence index exceeded its checked scheme");
            return .{ .module = schema.view.key, .param = schema.start + index.index };
        };
        if (worker.source != .nested_expr) boxyPlanInvariant("numeral evidence depth exceeded its checked worker");
        const expr = worker.source.nested_expr;
        const view = self.moduleForId(expr.module);
        const site_expr = self.nestedCallableSiteExprForExpr(view, expr.expr) orelse expr.expr;
        const site = for (view.nested_proc_sites.sites) |candidate| {
            if (candidate.checked_expr == site_expr) break candidate;
        } else boxyPlanInvariant("nested numeral evidence omitted its lexical site");
        var scope = site.lexical_scope;
        var depth: u32 = index.depth;
        if (own != null) {
            // The site's lexical scope is its enclosing scope; its own
            // generalized scheme has already consumed the first coordinate.
            depth -= 1;
        }
        while (scope == .generalized) {
            const current = view.checked_procedure_templates.dispatch_scopes[@intFromEnum(scope.generalized)];
            if (depth == 0) {
                if (index.index >= current.evidence_params.len) boxyPlanInvariant("numeral evidence index exceeded its lexical scheme");
                return .{ .module = view.key, .param = current.evidence_params.start + index.index };
            }
            depth -= 1;
            scope = if (current.parent) |parent| .{ .generalized = parent } else .root;
        }
        if (depth != 0 or site.owner != .template) boxyPlanInvariant("numeral evidence escaped its checked template");
        const root = self.templateEvidenceParams(site.owner.template);
        if (index.index >= root.params.len) boxyPlanInvariant("numeral evidence index exceeded its template scheme");
        return .{ .module = root.view.key, .param = root.start + index.index };
    }

    fn activateCustomNumeralSites(self: *Builder) Allocator.Error!void {
        if (!self.has_custom_numeral) return;
        while (self.activated_numeral_sites < self.generic_numeral_sites.items.len) : (self.activated_numeral_sites += 1) {
            const site = self.generic_numeral_sites.items[self.activated_numeral_sites];
            const view = self.moduleForId(site.source.module);
            const dispatch = view.static_dispatch_plans.plans[@intFromEnum(site.dispatch)];
            const evidence = dispatch.resolution.evidence_dependent;
            const key = if (evidence.scheme_param) |param| SchemeDictionaryKey{ .module = view.key, .param = param } else self.workerEvidenceKey(site.worker, evidence.index);
            try self.analyzeDispatchPlanTypes(view, site.dispatch);
            const dictionary = try self.requireWorkerSchemeDictionary(site.worker, key);
            try self.plan.literal_sites.append(self.allocator, site);
            try self.plan.dictionary_dispatches.append(self.allocator, .{
                .call = site.source,
                .caller = site.worker,
                .dispatcher_rep = dictionary.rep,
                .scheme_requirement = @enumFromInt(dictionary.dictionaries.start),
                .method = dispatch.method,
                .source_fn_type = typeRef(view, dispatch.callable_ty),
                .operands = try self.appendDispatchCallOperands(dispatch, view.static_dispatch_plans),
            });
        }
    }

    fn analyzePlannedEvidenceTypes(self: *Builder) Allocator.Error!void {
        while (self.evidence_workers_walked < self.plan.workers.items.len) : (self.evidence_workers_walked += 1) {
            const worker = self.plan.workers.items[self.evidence_workers_walked];
            if (self.workerEvidenceParams(worker.source)) |worker_evidence| {
                for (worker_evidence.params) |param| _ = try self.analyzeType(worker_evidence.view, param.dispatcher_ty);
            }
        }
        while (self.evidence_calls_walked < self.plan.direct_calls.items.len) : (self.evidence_calls_walked += 1) {
            const direct = self.plan.direct_calls.items[self.evidence_calls_walked];
            const call_evidence = self.checkedEvidenceForDirectCall(direct);
            if (call_evidence.entries) |entries| {
                try self.observeNumeralEvidence(call_evidence.view, entries, self.workerEvidenceParams(self.plan.workers.items[@intFromEnum(direct.worker)].source));
                for (entries) |entry| _ = try self.analyzeType(call_evidence.view, entry.dispatcher_ty);
            }
        }
        inline for (.{ .{ "nested_callable_uses", "evidence_nested_uses_walked" }, .{ "callable_uses", "evidence_callable_uses_walked" } }) |channel| {
            const cursor = &@field(self, channel[1]);
            while (cursor.* < @field(self.plan, channel[0]).items.len) : (cursor.* += 1) {
                const use = @field(self.plan, channel[0]).items[cursor.*];
                const use_evidence = self.checkedEvidenceForProcedureUse(use.use);
                if (use_evidence.entries) |entries| {
                    try self.observeNumeralEvidence(use_evidence.view, entries, self.workerEvidenceParams(self.plan.workers.items[@intFromEnum(use.worker)].source));
                    for (entries) |entry| _ = try self.analyzeType(use_evidence.view, entry.dispatcher_ty);
                }
            }
        }
    }

    const CheckedCallEvidence = struct {
        view: ModuleView,
        entries: ?[]const static_dispatch.CheckedEvidence,
    };

    /// The checked evidence one procedure use supplies to its target. A
    /// platform requirement has no use-site scheme in the platform module:
    /// checking records its root evidence from the app definition's complete
    /// scheme, in the app CheckedModule's evidence table (design.md
    /// "Platform/App Relation"). Every other use carries its own site evidence.
    fn checkedEvidenceForProcedureUse(self: *Builder, use: CheckedExprIdentity) CheckedCallEvidence {
        const view = self.moduleForId(use.module);
        const use_expr = view.checked_bodies.expr(use.expr);
        if (use_expr.data == .lookup_required) {
            if (use_expr.data.lookup_required) |ref_id| {
                const record = self.resolvedValueRecord(view, ref_id);
                if (record.ref == .platform_required_proc) {
                    if (record.ref.platform_required_proc.root_evidence) |root_evidence| {
                        const app_view = self.moduleForCheckedModuleId(root_evidence.checked_module);
                        const span = root_evidence.span;
                        return .{
                            .view = app_view,
                            .entries = app_view.static_dispatch_plans.evidence_refs[span.start .. span.start + span.len],
                        };
                    }
                }
            }
        }
        // A dispatch that uses a local procedure as a callable instantiates
        // it at the evidence edge its plan selected.
        if (dispatchPlanOfExpr(view, use.expr)) |plan| {
            return .{ .view = view, .entries = self.nestedEvidenceForDirectDispatch(view, plan) };
        }
        return .{ .view = view, .entries = view.static_dispatch_plans.siteEvidence(use.expr) };
    }

    fn checkedEvidenceForDirectCall(self: *Builder, direct: DirectCallPlan) CheckedCallEvidence {
        const view = self.moduleForId(direct.call.module);
        const call_expr = view.checked_bodies.expr(direct.call.expr);
        if (call_expr.data == .call) {
            return self.checkedEvidenceForProcedureUse(.{ .module = direct.call.module, .expr = call_expr.data.call.func });
        }
        const entries = if (call_expr.data == .dispatch_call)
            self.nestedEvidenceForDirectDispatch(view, call_expr.data.dispatch_call)
        else if (call_expr.data == .type_dispatch_call)
            self.nestedEvidenceForDirectDispatch(view, call_expr.data.type_dispatch_call)
        else if (call_expr.data == .method_eq)
            self.nestedEvidenceForDirectDispatch(view, call_expr.data.method_eq)
        else if (call_expr.data == .str_from_quote)
            self.nestedEvidenceForDirectDispatch(view, call_expr.data.str_from_quote.plan)
        else if (call_expr.data == .interpolation)
            self.nestedEvidenceForDirectDispatch(view, call_expr.data.interpolation.plan)
        else if (call_expr.data == .numeral)
            self.nestedEvidenceForDirectDispatch(view, call_expr.data.numeral.plan)
        else
            boxyPlanInvariant("boxy direct call plan referenced a checked expression that is not lowered as a worker call");
        return .{ .view = view, .entries = entries };
    }

    fn propagateDynamicRequirements(self: *Builder) void {
        var changed = true;
        while (changed) {
            changed = false;
            for (self.plan.representations.items) |*rep| {
                if (!rep.contains_dynamic and self.representationContainsDynamic(rep.*)) {
                    rep.contains_dynamic = true;
                    changed = true;
                }
            }
        }
    }

    fn representationContainsDynamic(self: *const Builder, rep: TypeRepresentation) bool {
        switch (rep.kind) {
            .dynamic => return true,
            .in_progress => return false,
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => return false,
            .primitive,
            .bool_tag_union,
            .erased_callable,
            .alias,
            .record,
            .tuple,
            .nominal,
            .list,
            .box,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => {},
        }
        for (self.plan.childSlice(rep.children)) |child| {
            if (!childCarriesRuntimeDescriptor(child.role)) continue;
            if (self.plan.representations.items[@intFromEnum(child.rep)].contains_dynamic) return true;
        }
        return false;
    }

    fn materializeDescriptorRequirements(self: *Builder) Allocator.Error!void {
        for (self.plan.representations.items, 0..) |*rep, index| {
            if (!rep.contains_dynamic) continue;
            if (rep.descriptor != null) continue;
            const reason = descriptorReason(rep.kind) orelse continue;
            const id: DescriptorRequirementId = @enumFromInt(@as(u32, @intCast(self.plan.descriptors.items.len)));
            try self.plan.descriptors.append(self.allocator, .{
                .source_type = rep.source_type,
                .rep = @enumFromInt(@as(u32, @intCast(index))),
                .reason = reason,
            });
            rep.descriptor = id;
        }
    }

    /// An unsealed type variable whose values a worker must describe through a
    /// hidden descriptor.
    fn isDescriptorLeaf(self: *const Builder, rep_id: TypeRepId) bool {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor == null or rep.sealed_default != null) return false;
        return (rep.kind == .dynamic and rep.children.len == 0 and rep.tag_variants.len == 0) or
            self.plan.repIsOpenRecord(rep_id);
    }

    /// The row variable that leaves an open record's row open.
    fn openRecordRowVariable(self: *Builder, rep_id: TypeRepId) ?CheckedTypeIdentity {
        const source = self.plan.representations.items[@intFromEnum(rep_id)].source_type;
        const view = self.moduleForId(source.module);
        var current = source.ty;
        while (true) {
            switch (view.checked_types.payload(current)) {
                .record => |record| {
                    if (record.ext == current) return null;
                    current = record.ext;
                },
                .alias => |alias| current = alias.backing,
                .flex, .rigid => return typeRef(view, current),
                .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union, .empty_record => return null,
            }
        }
    }

    /// Whether a worker's own scheme quantifies the row variable of an open
    /// record, so the worker's own frame describes it.
    fn openRecordOwnedByScheme(self: *Builder, worker_id: WorkerPlanId, rep_id: TypeRepId) bool {
        if (!self.plan.repIsOpenRecord(rep_id)) return false;
        const row = self.openRecordRowVariable(rep_id) orelse return false;
        const scheme = self.workerSchemeVars(self.plan.workers.items[@intFromEnum(worker_id)].source) orelse return false;
        for (scheme.vars) |variable| {
            if (typeRefEql(typeRef(scheme.view, variable), row)) return true;
        }
        return false;
    }

    /// Open records inside a dictionary requirement's signature, including
    /// its function-typed positions, in a fixed order: the positions a frame
    /// holding the dictionary can read a descriptor for.
    fn collectRequirementOpenRecords(
        self: *Builder,
        rep_id: TypeRepId,
        out: *std.ArrayList(TypeRepId),
        seen: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!void {
        if ((try seen.getOrPut(rep_id)).found_existing) return;
        if (self.plan.repIsOpenRecord(rep_id) and self.plan.representations.items[@intFromEnum(rep_id)].descriptor != null) {
            const identity = self.repQuery().descriptorArgumentIdentityRep(rep_id);
            for (out.items) |existing| {
                if (self.repQuery().descriptorArgumentIdentityRep(existing) == identity) break;
            } else try out.append(self.allocator, rep_id);
        }
        var index: usize = 0;
        while (index < self.plan.representations.items[@intFromEnum(rep_id)].children.len) : (index += 1) {
            const child = self.plan.children.items[self.plan.representations.items[@intFromEnum(rep_id)].children.start + index];
            if (self.plan.childIsSharedBackingTemplate(rep_id, child)) continue;
            try self.collectRequirementOpenRecords(child.rep, out, seen);
        }
    }

    /// The number of requirement descriptors a dictionary method's call
    /// supplies for its requirement's runtime values.
    fn requirementRuntimeDescriptorCount(self: *Builder, requirement_rep: TypeRepId) Allocator.Error!u32 {
        const requirement_function = (self.repQuery().functionChildren(requirement_rep)) orelse
            boxyPlanInvariant("dictionary method requirement was not callable");
        var params = std.ArrayList(HiddenDescriptorParam).empty;
        defer params.deinit(self.allocator);
        var seen_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(DescriptorRequirementId, void).init(self.allocator);
        defer seen_descs.deinit();
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(requirement_function.rep)].children);
        for (children[requirement_function.args_start..][0..requirement_function.arg_count]) |arg| {
            try self.collectRuntimeHiddenDescriptorsForRep(arg.rep, &params, &seen_reps, &seen_descs);
        }
        try self.collectRuntimeHiddenDescriptorsForRep(requirement_function.ret, &params, &seen_reps, &seen_descs);
        return @intCast(params.items.len);
    }

    /// The requirement of one of a worker's own dictionaries whose signature
    /// names an open record, and where the dictionary describes it.
    fn workerDictionaryDescriptorForLeaf(
        self: *Builder,
        worker: WorkerPlan,
        leaf: TypeRepId,
    ) Allocator.Error!?WorkerDictionaryDescriptor {
        if (!self.plan.repIsOpenRecord(leaf)) return null;
        var roots = std.ArrayList(TypeRepId).empty;
        defer roots.deinit(self.allocator);
        try roots.append(self.allocator, worker.rep);
        if (self.workerSchemeVars(worker.source)) |scheme| {
            for (scheme.vars) |variable| {
                const rep = self.plan.repForSourceType(typeRef(scheme.view, variable)) orelse continue;
                try roots.append(self.allocator, rep);
            }
        }
        var dispatchers = std.ArrayList(TypeRepId).empty;
        defer dispatchers.deinit(self.allocator);
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        for (roots.items) |root| try self.collectRepsWithDictionaries(root, &dispatchers, &seen);

        const leaf_identity = self.repQuery().descriptorArgumentIdentityRep(leaf);
        for (dispatchers.items) |dispatcher| {
            const dictionaries = self.plan.representations.items[@intFromEnum(dispatcher)].dictionaries;
            var offset: u32 = 0;
            while (offset < dictionaries.len) : (offset += 1) {
                const requirement_id: DictionaryRequirementId = @enumFromInt(dictionaries.start + offset);
                const requirement = self.plan.dictionaries.items[@intFromEnum(requirement_id)];
                if (requirement.compile_time_only) continue;
                const requirement_rep = self.plan.repForSourceType(requirement.fn_ty) orelse continue;
                if (self.repQuery().functionChildren(requirement_rep) == null) continue;
                var leaves = std.ArrayList(TypeRepId).empty;
                defer leaves.deinit(self.allocator);
                var leaf_seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
                defer leaf_seen.deinit();
                try self.collectRequirementOpenRecords(requirement_rep, &leaves, &leaf_seen);
                for (leaves.items, 0..) |candidate, index| {
                    if (self.repQuery().descriptorArgumentIdentityRep(candidate) != leaf_identity) continue;
                    return .{
                        .rep = leaf,
                        .requirement = requirement_id,
                        .hidden_index = try self.requirementRuntimeDescriptorCount(requirement_rep) + @as(u32, @intCast(index)),
                    };
                }
            }
        }
        return null;
    }

    fn collectRepsWithDictionaries(
        self: *Builder,
        rep_id: TypeRepId,
        out: *std.ArrayList(TypeRepId),
        seen: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!void {
        if ((try seen.getOrPut(rep_id)).found_existing) return;
        if (self.plan.representations.items[@intFromEnum(rep_id)].dictionaries.len != 0) try out.append(self.allocator, rep_id);
        var index: usize = 0;
        while (index < self.plan.representations.items[@intFromEnum(rep_id)].children.len) : (index += 1) {
            const child = self.plan.children.items[self.plan.representations.items[@intFromEnum(rep_id)].children.start + index];
            try self.collectRepsWithDictionaries(child.rep, out, seen);
        }
    }

    /// Add the descriptor leaves `root` reaches to `leaves`, in pre-order.
    fn collectDescriptorLeaves(
        self: *Builder,
        root: TypeRepId,
        leaves: *WorkerDescriptorLeaves,
        seen: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList(TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |rep_id| {
            if ((try seen.getOrPut(rep_id)).found_existing) continue;
            if (self.isDescriptorLeaf(rep_id)) _ = try leaves.add(self.allocator, rep_id);
            const children = self.plan.representations.items[@intFromEnum(rep_id)].children;
            var index: usize = children.len;
            while (index > 0) {
                index -= 1;
                const child = self.plan.children.items[children.start + index];
                if (self.plan.childIsSharedBackingTemplate(rep_id, child)) continue;
                try pending.append(self.allocator, child.rep);
            }
        }
    }

    const WorkerDescriptorLeaves = struct {
        set: collections.DenseMap(TypeRepId, void),
        order: std.ArrayList(TypeRepId) = .empty,

        fn add(self: *WorkerDescriptorLeaves, allocator: Allocator, rep: TypeRepId) Allocator.Error!bool {
            if ((try self.set.getOrPut(rep)).found_existing) return false;
            try self.order.append(allocator, rep);
            return true;
        }

        fn deinit(self: *WorkerDescriptorLeaves, allocator: Allocator) void {
            self.set.deinit();
            self.order.deinit(allocator);
        }
    };

    /// Every descriptor leaf each worker's body needs: the leaves of the types
    /// its own body mentions, plus whatever each callable it creates or calls
    /// needs beyond that callable's own scheme variables, which the use
    /// instantiates. The relation is monotone over finitely many leaves, so
    /// propagation reaches its fixpoint.
    fn computeWorkerDescriptorLeaves(self: *Builder) Allocator.Error![]WorkerDescriptorLeaves {
        const worker_count = self.plan.workers.items.len;
        const needs = try self.allocator.alloc(WorkerDescriptorLeaves, worker_count);
        for (needs) |*need| need.* = .{ .set = collections.DenseMap(TypeRepId, void).init(self.allocator) };
        errdefer {
            for (needs) |*need| need.deinit(self.allocator);
            self.allocator.free(needs);
        }

        const body_types = try self.allocator.dupe(WorkerDictionaryUse, self.worker_body_types.items);
        defer self.allocator.free(body_types);
        std.mem.sort(WorkerDictionaryUse, body_types, {}, struct {
            fn lessThan(_: void, a: WorkerDictionaryUse, b: WorkerDictionaryUse) bool {
                return @intFromEnum(a.worker) < @intFromEnum(b.worker);
            }
        }.lessThan);
        var edges = std.ArrayList(WorkerEdge).empty;
        defer edges.deinit(self.allocator);
        var edge_substitutions = std.ArrayList(?SchemeCallSubstitution).empty;
        defer edge_substitutions.deinit(self.allocator);
        var edge_stored_substitutions = std.ArrayList(?Span).empty;
        defer edge_stored_substitutions.deinit(self.allocator);
        for (self.plan.nested_callable_uses.items) |use| {
            try edges.append(self.allocator, .{ .caller = use.caller, .callee = use.worker });
            try edge_substitutions.append(self.allocator, self.useSchemeSubstitution(use.worker, use.use));
            try edge_stored_substitutions.append(self.allocator, null);
        }
        for (self.plan.callable_uses.items) |use| {
            // A stored callable's descriptors come from its stored value, not
            // from the frame restoring it.
            if (use.stored_fn != null) continue;
            try edges.append(self.allocator, .{ .caller = use.caller, .callee = use.worker });
            try edge_substitutions.append(self.allocator, self.useSchemeSubstitution(use.worker, use.use));
            // A stored function value's use fixes every variable of its
            // worker's type, including those of the scope that created it.
            try edge_stored_substitutions.append(self.allocator, if (use.stored_fn != null)
                try self.storedUseSchemeRepSubstitutions(
                    self.plan.workers.items[@intFromEnum(use.worker)].rep,
                    self.plan.repForSourceType(use.callable_ty) orelse
                        boxyPlanInvariant("boxy stored callable use type was not analyzed"),
                )
            else
                null);
        }
        for (self.plan.direct_calls.items) |call| {
            try edges.append(self.allocator, .{ .caller = call.caller, .callee = call.worker });
            try edge_substitutions.append(self.allocator, self.directCallSchemeSubstitution(call));
            try edge_stored_substitutions.append(self.allocator, null);
        }

        var scopes = try self.computeWorkerScopeChains(edges.items);
        defer scopes.deinit(self.allocator);

        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        var direct = WorkerDescriptorLeaves{ .set = collections.DenseMap(TypeRepId, void).init(self.allocator) };
        defer direct.deinit(self.allocator);
        var index: usize = 0;
        while (index < body_types.len) {
            const worker = body_types[index].worker;
            seen.clearRetainingCapacity();
            direct.set.clearRetainingCapacity();
            direct.order.clearRetainingCapacity();
            while (index < body_types.len and body_types[index].worker == worker) : (index += 1) {
                try self.collectDescriptorLeaves(body_types[index].rep, &direct, &seen);
            }
            for (direct.order.items) |leaf| {
                if (scopes.allows(worker, leaf)) _ = try needs[@intFromEnum(worker)].add(self.allocator, leaf);
            }
        }

        const own_scheme = try self.allocator.alloc(collections.DenseMap(TypeRepId, void), worker_count);
        for (own_scheme) |*set| set.* = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer {
            for (own_scheme) |*set| set.deinit();
            self.allocator.free(own_scheme);
        }
        const signature = try self.allocator.alloc(WorkerDescriptorLeaves, worker_count);
        for (signature) |*leaves| leaves.* = .{ .set = collections.DenseMap(TypeRepId, void).init(self.allocator) };
        defer {
            for (signature) |*leaves| leaves.deinit(self.allocator);
            self.allocator.free(signature);
        }
        for (self.plan.workers.items, 0..) |worker, worker_index| {
            seen.clearRetainingCapacity();
            try self.collectDescriptorLeaves(worker.rep, &signature[worker_index], &seen);
            const scheme = self.workerSchemeVars(worker.source) orelse continue;
            for (scheme.vars) |variable| {
                const rep = self.plan.repForSourceType(typeRef(scheme.view, variable)) orelse continue;
                try own_scheme[worker_index].put(rep, {});
            }
        }

        // A use instantiates each callee scheme variable with a type the
        // caller supplies. A variable of that type which the caller's own
        // scheme or an enclosing local scope quantifies is described by the
        // caller's frame; one reached only through a constraint signature
        // appears in no type the caller's body mentions, so the substitution is
        // the only place it is named. The images depend only on the edge, so
        // they are computed once.
        var image_arena = std.heap.ArenaAllocator.init(self.allocator);
        defer image_arena.deinit();
        const image_allocator = image_arena.allocator();
        const edge_images = try image_allocator.alloc(std.AutoHashMapUnmanaged(TypeRepId, []const TypeRepId), edges.items.len);
        var image_leaves = WorkerDescriptorLeaves{ .set = collections.DenseMap(TypeRepId, void).init(self.allocator) };
        defer image_leaves.deinit(self.allocator);
        var caller_images = std.ArrayList(TypeRepId).empty;
        defer caller_images.deinit(self.allocator);
        var edge_pairs = std.ArrayList(SchemeRepSubstitution).empty;
        defer edge_pairs.deinit(self.allocator);
        for (edges.items, edge_substitutions.items, edge_stored_substitutions.items, edge_images) |edge, substitution, stored_substitution, *images| {
            images.* = .empty;
            edge_pairs.clearRetainingCapacity();
            if (substitution) |sub| {
                for (sub.scheme_vars, sub.site_types) |variable, site_type| {
                    if (sub.site_view.checked_types.payload(site_type) == .err) continue;
                    const scheme_rep = self.plan.repForSourceType(typeRef(sub.callee_view, variable)) orelse continue;
                    const site_rep = self.plan.repForSourceType(typeRef(sub.site_view, site_type)) orelse
                        boxyPlanInvariant("callable use substitution type was not analyzed");
                    try edge_pairs.append(self.allocator, .{ .scheme_rep = scheme_rep, .site_rep = site_rep });
                }
            }
            if (stored_substitution) |stored| {
                try edge_pairs.appendSlice(self.allocator, self.plan.schemeRepSubstitutionSlice(stored));
            }
            for (edge_pairs.items) |pair| {
                const scheme_rep = pair.scheme_rep;
                const site_rep = pair.site_rep;
                seen.clearRetainingCapacity();
                image_leaves.set.clearRetainingCapacity();
                image_leaves.order.clearRetainingCapacity();
                try self.collectDescriptorLeaves(site_rep, &image_leaves, &seen);
                caller_images.clearRetainingCapacity();
                for (image_leaves.order.items) |image_leaf| {
                    if (!own_scheme[@intFromEnum(edge.caller)].contains(image_leaf) and
                        scopes.owner.get(image_leaf) == null) continue;
                    if (!scopes.allows(edge.caller, image_leaf)) continue;
                    try caller_images.append(self.allocator, image_leaf);
                }
                if (caller_images.items.len == 0) continue;
                const entry = try images.getOrPut(image_allocator, scheme_rep);
                entry.value_ptr.* = if (entry.found_existing)
                    try std.mem.concat(image_allocator, TypeRepId, &.{ entry.value_ptr.*, caller_images.items })
                else
                    try image_allocator.dupe(TypeRepId, caller_images.items);
            }
        }

        var changed = true;
        while (changed) {
            changed = false;
            for (edges.items, edge_stored_substitutions.items, edge_images) |edge, stored_substitution, images| {
                if (edge.caller == edge.callee) continue;
                const callee = @intFromEnum(edge.callee);
                const caller = &needs[@intFromEnum(edge.caller)];
                for ([_][]const TypeRepId{ signature[callee].order.items, needs[callee].order.items }) |leaves| {
                    for (leaves) |leaf| {
                        if (stored_substitution) |stored| {
                            if (schemeRepSubstitutionFor(self.plan.schemeRepSubstitutionSlice(stored), leaf) != null) {
                                for (images.get(leaf) orelse &.{}) |image_leaf| {
                                    if (try caller.add(self.allocator, image_leaf)) changed = true;
                                }
                                continue;
                            }
                        }
                        if (own_scheme[callee].contains(leaf) or self.openRecordOwnedByScheme(edge.callee, leaf)) {
                            // A scheme variable the callee's signature names
                            // is described by the use's own argument and
                            // result values.
                            if (signature[callee].set.contains(leaf)) continue;
                            for (images.get(leaf) orelse &.{}) |image_leaf| {
                                if (try caller.add(self.allocator, image_leaf)) changed = true;
                            }
                            continue;
                        }
                        if (!scopes.allows(edge.caller, leaf)) continue;
                        if (try caller.add(self.allocator, leaf)) changed = true;
                    }
                }
            }
        }
        return needs;
    }

    fn schemeRepSubstitutionFor(pairs: []const SchemeRepSubstitution, scheme_rep: TypeRepId) ?TypeRepId {
        for (pairs) |pair| {
            if (pair.scheme_rep == scheme_rep) return pair.site_rep;
        }
        return null;
    }

    const WorkerEdge = struct { caller: WorkerPlanId, callee: WorkerPlanId };

    const ScopeKey = struct { module: checked.ModuleId, scope: u32 };

    /// The generalized-local scopes whose quantified variables each worker's
    /// frame describes. A local scope's variables reach a worker's body types
    /// uninstantiated only through that scope's own binders, so a worker may
    /// supply one only when the scope is its own or lexically encloses it.
    const WorkerScopeChains = struct {
        owner: collections.DenseMap(TypeRepId, ScopeKey),
        chains: []std.AutoHashMap(ScopeKey, void),

        fn allows(self: *const WorkerScopeChains, worker: WorkerPlanId, leaf: TypeRepId) bool {
            const owner = self.owner.get(leaf) orelse return true;
            return self.chains[@intFromEnum(worker)].contains(owner);
        }

        fn deinit(self: *WorkerScopeChains, allocator: Allocator) void {
            self.owner.deinit();
            for (self.chains) |*chain| chain.deinit();
            allocator.free(self.chains);
        }
    };

    /// Index each generalized-local scope variable by the outermost scope that
    /// lists it. A scope's list names the enclosing variables its scheme
    /// mentions as well as its own; the variable belongs to the outermost of
    /// them, and a variable a template's own scheme lists belongs to no local.
    fn indexScopeVariables(self: *Builder, view: ModuleView, owner: *collections.DenseMap(TypeRepId, ScopeKey)) Allocator.Error!void {
        const templates = view.checked_procedure_templates;
        var root_owned = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer root_owned.deinit();
        for (templates.templates.items) |*template| {
            for (templates.templateSchemeVars(template)) |variable| {
                const rep = self.plan.repForSourceType(typeRef(view, variable)) orelse continue;
                try root_owned.put(rep, {});
            }
        }
        var depths = collections.DenseMap(TypeRepId, u32).init(self.allocator);
        defer depths.deinit();
        for (templates.dispatch_scopes, 0..) |*scope, scope_index| {
            var depth: u32 = 0;
            var parent = scope.parent;
            while (parent) |ancestor| : (depth += 1) parent = templates.dispatch_scopes[@intFromEnum(ancestor)].parent;
            for (templates.scopeSchemeVars(scope)) |variable| {
                const rep = self.plan.repForSourceType(typeRef(view, variable)) orelse continue;
                if (root_owned.contains(rep)) continue;
                const entry = try depths.getOrPut(rep);
                if (entry.found_existing and entry.value_ptr.* <= depth) continue;
                entry.value_ptr.* = depth;
                try owner.put(rep, .{ .module = view.key, .scope = @intCast(scope_index) });
            }
        }
    }

    fn computeWorkerScopeChains(self: *Builder, edges: []const WorkerEdge) Allocator.Error!WorkerScopeChains {
        var owner = collections.DenseMap(TypeRepId, ScopeKey).init(self.allocator);
        errdefer owner.deinit();
        try self.indexScopeVariables(self.root_view, &owner);
        for (self.extra_module_views) |view| try self.indexScopeVariables(view, &owner);
        for (self.imports) |imported| try self.indexScopeVariables(moduleViewFromImported(imported), &owner);
        for (self.relation_modules) |imported| try self.indexScopeVariables(moduleViewFromImported(imported), &owner);

        const chains = try self.allocator.alloc(std.AutoHashMap(ScopeKey, void), self.plan.workers.items.len);
        for (chains) |*chain| chain.* = std.AutoHashMap(ScopeKey, void).init(self.allocator);
        var result = WorkerScopeChains{ .owner = owner, .chains = chains };
        errdefer result.deinit(self.allocator);

        for (self.plan.workers.items, 0..) |worker, worker_index| {
            // A worker's own scope is the generalized-local scope its checked
            // body roots, when that body is itself a local function.
            const view, const site_expr = switch (worker.source) {
                .nested_expr => |expr_ref| blk: {
                    const view = self.moduleForId(expr_ref.module);
                    break :blk .{ view, self.nestedCallableSiteExprForExpr(view, expr_ref.expr) orelse expr_ref.expr };
                },
                .procedure_template, .procedure_binding, .procedure_use => blk: {
                    if (self.root_module == null) continue;
                    switch (self.rootWorkerBody(worker.source)) {
                        .checked_expr => |body| break :blk .{ body.view, body.root_expr },
                        .intrinsic_wrapper, .hosted_proc, .unimplemented => continue,
                    }
                },
                .generated_codec, .generated_field_iterator, .generated_interpolation_step => continue,
            };
            const templates = view.checked_procedure_templates;
            for (templates.dispatch_scopes, 0..) |*scope, scope_index| {
                if (scope.checked_expr != site_expr) continue;
                var current: ?u32 = @intCast(scope_index);
                while (current) |index| {
                    try chains[worker_index].put(.{ .module = view.key, .scope = index }, {});
                    current = if (templates.dispatch_scopes[index].parent) |parent| @intFromEnum(parent) else null;
                }
                break;
            }
        }

        // A nested callable lies inside every frame that creates it, so it
        // sees each scope those frames see.
        var changed = true;
        while (changed) {
            changed = false;
            for (edges) |edge| {
                if (edge.caller == edge.callee) continue;
                if (self.plan.workers.items[@intFromEnum(edge.callee)].source != .nested_expr) continue;
                var keys = chains[@intFromEnum(edge.caller)].keyIterator();
                while (keys.next()) |key| {
                    if (!(try chains[@intFromEnum(edge.callee)].getOrPut(key.*)).found_existing) changed = true;
                }
            }
        }
        return result;
    }

    fn materializeWorkerHiddenDescriptorParams(self: *Builder) Allocator.Error!void {
        const worker_leaves = try self.computeWorkerDescriptorLeaves();
        defer {
            for (worker_leaves) |*leaves| leaves.deinit(self.allocator);
            self.allocator.free(worker_leaves);
        }
        for (self.plan.workers.items, 0..) |worker, worker_index| {
            // A hosted worker's signature can hold its declaration's type
            // variable slots, so its caller describes them like any other
            // worker's; only the extern boundary it calls is descriptor-free.
            var pending = std.ArrayList(HiddenDescriptorParam).empty;
            defer pending.deinit(self.allocator);
            var seen_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
            defer seen_reps.deinit();
            var seen_descs = collections.DenseMap(DescriptorRequirementId, void).init(self.allocator);
            defer seen_descs.deinit();

            if (self.repQuery().functionChildren(worker.rep)) |function| {
                const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
                for (children[function.args_start..][0..function.arg_count]) |child| {
                    try self.collectHiddenDescriptorsForRep(child.rep, &pending, &seen_reps, &seen_descs);
                }
                try self.collectHiddenDescriptorsForRep(function.ret, &pending, &seen_reps, &seen_descs);
            } else {
                try self.collectHiddenDescriptorsForRep(worker.rep, &pending, &seen_reps, &seen_descs);
            }
            const body_start: u32 = @intCast(pending.items.len);
            switch (worker.source) {
                .generated_codec => |codec| switch (codec.kind) {
                    .parser_constructor, .encoder_constructor => {},
                    .parser_runtime, .encoder_runtime => {
                        const capture_type = codec.capture_type orelse
                            boxyPlanInvariant("generated codec runtime had no capture type");
                        const capture_rep = self.plan.repForSourceType(capture_type) orelse
                            boxyPlanInvariant("generated codec runtime capture type was not analyzed");
                        try self.collectHiddenDescriptorsForRep(capture_rep, &pending, &seen_reps, &seen_descs);
                        for (self.plan.generated_parser_field_captures.items) |field_capture| {
                            if (field_capture.worker != worker.id) continue;
                            const field_rep = self.plan.repForSourceType(field_capture.source_type) orelse
                                boxyPlanInvariant("generated codec field capture type was not analyzed");
                            try self.collectHiddenDescriptorsForRep(field_rep, &pending, &seen_reps, &seen_descs);
                        }
                    },
                    .encoder_record_fields,
                    .encoder_dict_fields,
                    .encoder_sequence_elements,
                    .encoder_tag_payload_elements,
                    .encoder_value_thunk,
                    .encoder_dict_key_thunk,
                    => {
                        const capture_type = codec.capture_type orelse
                            boxyPlanInvariant("generated encoder callback had no encoding capture type");
                        const capture_rep = self.plan.repForSourceType(capture_type) orelse
                            boxyPlanInvariant("generated encoder callback capture type was not analyzed");
                        try self.collectHiddenDescriptorsForRep(capture_rep, &pending, &seen_reps, &seen_descs);
                        const value_type = codec.value_type orelse codec.shape;
                        const shape_rep = self.plan.repForSourceType(value_type) orelse
                            boxyPlanInvariant("generated encoder callback shape type was not analyzed");
                        try self.collectHiddenDescriptorsForRep(shape_rep, &pending, &seen_reps, &seen_descs);
                        if (!typeRefEql(value_type, codec.shape)) {
                            const schema_rep = self.plan.repForSourceType(codec.shape) orelse
                                boxyPlanInvariant("generated encoder callback schema type was not analyzed");
                            try self.collectHiddenDescriptorsForRep(schema_rep, &pending, &seen_reps, &seen_descs);
                        }
                        const contract_worker = codec.contract_worker orelse
                            boxyPlanInvariant("generated encoder callback had no contract worker");
                        for (self.plan.generated_parser_field_captures.items) |field_capture| {
                            if (field_capture.worker != contract_worker) continue;
                            const field_rep = self.plan.repForSourceType(field_capture.source_type) orelse
                                boxyPlanInvariant("generated encoder field capture type was not analyzed");
                            try self.collectHiddenDescriptorsForRep(field_rep, &pending, &seen_reps, &seen_descs);
                        }
                    },
                },
                .generated_interpolation_step => |step| {
                    if (step.one_payload_type) |payload_type| {
                        const payload_rep = self.plan.repForSourceType(payload_type) orelse
                            boxyPlanInvariant("generated interpolation payload capture type was not analyzed");
                        try self.collectHiddenDescriptorsForRep(payload_rep, &pending, &seen_reps, &seen_descs);
                    }
                },
                .procedure_template,
                .procedure_binding,
                .procedure_use,
                .nested_expr,
                .generated_field_iterator,
                => {},
            }

            const enclosing_start: u32 = @intCast(pending.items.len);
            const dictionary_descs_start: u32 = @intCast(self.plan.worker_dictionary_descs.items.len);
            {
                var evidence_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
                defer evidence_reps.deinit();
                if (self.workerEvidenceParams(worker.source)) |worker_evidence| {
                    for (worker_evidence.params) |evidence_param| {
                        const rep = self.plan.repForSourceType(typeRef(worker_evidence.view, evidence_param.dispatcher_ty)) orelse continue;
                        try evidence_reps.put(rep, {});
                    }
                }
                for (worker_leaves[worker_index].order.items) |leaf| {
                    if (seen_reps.contains(leaf) or evidence_reps.contains(leaf)) continue;
                    // A dictionary of the worker's own describes an open
                    // record its requirement names, so no caller supplies it.
                    if (try self.workerDictionaryDescriptorForLeaf(self.plan.workers.items[worker_index], leaf)) |entry| {
                        try self.plan.worker_dictionary_descs.append(self.allocator, entry);
                        continue;
                    }
                    try self.collectHiddenDescriptorsForRep(leaf, &pending, &seen_reps, &seen_descs);
                }
            }
            self.plan.workers.items[worker_index].dictionary_descs = .{
                .start = dictionary_descs_start,
                .len = @intCast(self.plan.worker_dictionary_descs.items.len - dictionary_descs_start),
            };

            const evidence_only_start: u32 = @intCast(pending.items.len);
            const evidence_start: u32 = @intCast(self.plan.worker_evidence_descriptor_params.items.len);
            if (self.workerEvidenceParams(worker.source)) |worker_evidence| {
                for (worker_evidence.params, 0..) |evidence_param, evidence_index| {
                    const source_type = typeRef(worker_evidence.view, evidence_param.dispatcher_ty);
                    const rep_id = self.plan.repForSourceType(source_type) orelse
                        boxyPlanInvariant("checked literal evidence dispatcher type was not analyzed for its worker body");
                    const rep = self.plan.representations.items[@intFromEnum(rep_id)];
                    const desc = rep.descriptor orelse continue;
                    // A runtime dictionary supplies this dispatcher's methods, but
                    // a literal at its type still encodes itself against its
                    // descriptor. When the signature does not already describe
                    // the dispatcher, its evidence is the descriptor's source.
                    if (evidence_param.runtime_dictionary and seen_reps.contains(rep_id)) continue;
                    try self.collectHiddenDescriptorsForRep(rep_id, &pending, &seen_reps, &seen_descs);

                    var hidden_desc_index: ?u32 = null;
                    for (pending.items, 0..) |candidate, index| {
                        if (candidate.desc == desc and candidate.rep == rep_id) {
                            hidden_desc_index = @intCast(index);
                            break;
                        }
                    }
                    try self.plan.worker_evidence_descriptor_params.append(self.allocator, .{
                        .evidence_index = @intCast(evidence_index),
                        .hidden_desc_index = hidden_desc_index orelse
                            boxyPlanInvariant("checked literal evidence descriptor was not collected into the worker ABI"),
                    });
                }
            }

            const start: u32 = @intCast(self.plan.hidden_descriptor_params.items.len);
            try self.plan.hidden_descriptor_params.appendSlice(self.allocator, pending.items);
            self.plan.workers.items[worker_index].hidden_descs = .{
                .start = start,
                .len = @intCast(pending.items.len),
            };
            self.plan.workers.items[worker_index].body_hidden_descs = .{
                .start = start + body_start,
                .len = @intCast(pending.items.len - body_start),
            };
            self.plan.workers.items[worker_index].enclosing_descs = .{
                .start = start + enclosing_start,
                .len = evidence_only_start - enclosing_start,
            };
            self.plan.workers.items[worker_index].evidence_only_descs = .{
                .start = start + evidence_only_start,
                .len = @intCast(pending.items.len - evidence_only_start),
            };
            self.plan.workers.items[worker_index].evidence_descs = .{
                .start = evidence_start,
                .len = @intCast(self.plan.worker_evidence_descriptor_params.items.len - evidence_start),
            };
        }
    }

    const WorkerEvidenceParams = struct {
        view: ModuleView,
        start: u32,
        params: []const static_dispatch.EvidenceParamRecord,
    };

    /// A callee scheme's quantified variables in `scheme_vars` order, together
    /// with the checked types one call site substituted for them
    /// (`StaticDispatchPlanTable.siteSubstitution`).
    const SchemeCallSubstitution = struct {
        callee_view: ModuleView,
        scheme_vars: []const checked.CheckedTypeId,
        site_view: ModuleView,
        site_types: []const checked.CheckedTypeId,
        /// Site representations the call itself supplies. Inspection's use of
        /// an override leaves the owner's type variables free; each inspected
        /// value supplies them.
        site_rep_bindings: []const SiteRepBinding = &.{},

        fn siteRep(self: SchemeCallSubstitution, site_rep: TypeRepId) TypeRepId {
            for (self.site_rep_bindings) |binding| {
                if (binding.site == site_rep) return binding.actual;
            }
            return site_rep;
        }
    };

    const SiteRepBinding = struct {
        site: TypeRepId,
        actual: TypeRepId,
    };

    const WorkerSchemeVars = struct {
        view: ModuleView,
        vars: []const checked.CheckedTypeId,
    };

    fn workerSchemeVars(self: *Builder, source: WorkerSource) ?WorkerSchemeVars {
        return switch (source) {
            .procedure_template => |template| self.templateSchemeVars(template),
            .procedure_binding => |binding| self.bindingSchemeVars(self.moduleForId(binding.artifact), binding.binding),
            .procedure_use => |use| switch (use.binding) {
                .top_level => |binding| self.bindingSchemeVars(self.moduleForId(binding.artifact), binding.binding),
                .platform_required => |required| self.bindingSchemeVars(
                    self.moduleForId(required.app_value.artifact),
                    required.procedure_binding,
                ),
                .imported => |imported| blk: {
                    const view = self.moduleForId(imported.artifact);
                    break :blk self.bindingBodySchemeVars(self.importedProcedureBinding(view, imported).body);
                },
                .hosted => null,
            },
            .nested_expr => |expr_ref| blk: {
                const view = self.moduleForId(expr_ref.module);
                const site_expr = self.nestedCallableSiteExprForExpr(view, expr_ref.expr) orelse expr_ref.expr;
                for (view.checked_procedure_templates.dispatch_scopes) |*scope| {
                    if (scope.checked_expr != site_expr) continue;
                    break :blk .{ .view = view, .vars = view.checked_procedure_templates.scopeSchemeVars(scope) };
                }
                break :blk null;
            },
            .generated_codec,
            .generated_field_iterator,
            .generated_interpolation_step,
            => null,
        };
    }

    fn templateSchemeVars(self: *Builder, template_ref: checked_names.ProcedureTemplateRef) WorkerSchemeVars {
        const view = self.moduleForCheckedModuleId(template_ref.artifact);
        const template = &view.checked_procedure_templates.templates.items[@intFromEnum(template_ref.template)];
        return .{ .view = view, .vars = view.checked_procedure_templates.templateSchemeVars(template) };
    }

    fn bindingSchemeVars(self: *Builder, view: ModuleView, binding_ref: checked.TopLevelProcedureBindingRef) ?WorkerSchemeVars {
        return self.bindingBodySchemeVars(view.top_level_procedure_bindings.get(binding_ref).body);
    }

    fn bindingBodySchemeVars(self: *Builder, body: anytype) ?WorkerSchemeVars {
        return switch (body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| self.templateSchemeVars(template),
                .lifted, .synthetic => null,
            },
            .checked_error => null,
            .callable_eval_template => null,
        };
    }

    /// The checked call-site substitution for a direct call's callee scheme.
    /// A call through an instantiated lookup records it at the lookup; a
    /// resolved dispatch call records it on the evidence node its plan
    /// selected, which is authoritative for that edge.
    /// The checked dispatch plan of a direct call lowered from a dispatching
    /// expression.
    fn directCallDispatchPlan(call_expr: anytype) ?static_dispatch.StaticDispatchPlanId {
        return switch (call_expr.data) {
            .dispatch_call => |plan| plan,
            .type_dispatch_call => |plan| plan,
            .method_eq => |plan| plan,
            .str_from_quote => |quote| quote.plan,
            .interpolation => |interpolation| interpolation.plan,
            .numeral => |numeral| numeral.plan,
            else => boxyPlanInvariant("boxy direct call plan referenced a checked expression that is not lowered as a worker call"),
        };
    }

    /// The scheme representation pairs a direct call binds: its checked
    /// substitution, or the relation of a dispatch that derives its evidence
    /// from its callable (`directCallCallableDerivedSubstitution`).
    fn directCallSchemeRepSubstitutions(self: *Builder, direct: DirectCallPlan) Allocator.Error!Span {
        if (self.directCallSchemeSubstitution(direct)) |substitution| return try self.appendSchemeRepSubstitutions(substitution);
        return try self.directCallCallableDerivedSubstitution(direct) orelse .{};
    }

    /// For a dispatch whose target derives its evidence from its callable,
    /// for which checking recorded no substitution, the worker's type related
    /// to the call's function type, which fixes every variable of the
    /// worker's signature exactly as a checked substitution would. Null for
    /// every other call.
    fn directCallCallableDerivedSubstitution(self: *Builder, direct: DirectCallPlan) Allocator.Error!?Span {
        const site_view = self.moduleForId(direct.call.module);
        const call_expr = site_view.checked_bodies.expr(direct.call.expr);
        if (call_expr.data == .call) return null;
        const dispatch_plan = directCallDispatchPlan(call_expr);
        if (dispatchResolutionIsStructural(site_view, dispatch_plan)) return null;
        const node = site_view.static_dispatch_plans.evidenceNode(directDispatchEvidenceNode(site_view, dispatch_plan));
        if (node.nested != .from_callable or node.subst.len != 0) return null;
        const call_rep = self.plan.repForSourceType(direct.source_fn_type) orelse
            boxyPlanInvariant("boxy direct call function type was not analyzed");
        return try self.storedUseSchemeRepSubstitutions(self.plan.workers.items[@intFromEnum(direct.worker)].rep, call_rep);
    }

    fn directCallSchemeSubstitution(self: *Builder, direct: DirectCallPlan) ?SchemeCallSubstitution {
        const site_view = self.moduleForId(direct.call.module);
        const call_expr = site_view.checked_bodies.expr(direct.call.expr);
        if (call_expr.data != .call) {
            const dispatch_plan = directCallDispatchPlan(call_expr);
            // A generated codec constructor is declared at its checked
            // contract's roles and has no evidence scheme to substitute.
            if (dispatchResolutionIsStructural(site_view, dispatch_plan)) return null;
            const node = directDispatchEvidenceNode(site_view, dispatch_plan);
            return self.evidenceEdgeSchemeSubstitution(direct.worker, .{ .module = direct.call.module, .node = node });
        }
        if (site_view.resolved_value_refs.lookupIdByCheckedExpr(call_expr.data.call.func)) |use_id| {
            // An annotated recursive use instantiates the in-flight annotation,
            // whose slots are not the finished worker scheme's slots. Its
            // checked call relation supplies the worker descriptor bindings.
            if (site_view.resolved_value_refs.records[@intFromEnum(use_id)].recursive_reference) return null;
        }
        const site_types = site_view.static_dispatch_plans.siteSubstitution(call_expr.data.call.func) orelse return null;
        if (site_types.len == 0) return null;
        const scheme = self.workerSchemeVars(self.plan.workers.items[@intFromEnum(direct.worker)].source) orelse return null;
        if (scheme.vars.len != site_types.len) {
            boxyPlanInvariant("checked call-site substitution disagreed with its callee scheme's variables");
        }
        return .{
            .callee_view = scheme.view,
            .scheme_vars = scheme.vars,
            .site_view = site_view,
            .site_types = site_types,
        };
    }

    /// A direct call's scheme substitution names caller-side types that
    /// supply its callee's type-variable descriptors; they are analyzed when
    /// the call is planned, before descriptor requirements are fixed.
    /// The checked substitution a callable-value or stored nested-function use
    /// applied to its worker's scheme, when checking instantiated one there.
    fn useSchemeSubstitution(self: *Builder, worker_id: WorkerPlanId, use: CheckedExprIdentity) ?SchemeCallSubstitution {
        const site_view = self.moduleForId(use.module);
        if (dispatchPlanOfExpr(site_view, use.expr)) |plan| {
            return self.evidenceEdgeSchemeSubstitution(worker_id, .{
                .module = use.module,
                .node = directDispatchEvidenceNode(site_view, plan),
            });
        }
        const site_types = site_view.static_dispatch_plans.siteSubstitution(use.expr) orelse return null;
        if (site_types.len == 0) return null;
        const scheme = self.workerSchemeVars(self.plan.workers.items[@intFromEnum(worker_id)].source) orelse return null;
        if (scheme.vars.len != site_types.len) {
            boxyPlanInvariant("checked use-site substitution disagreed with its worker scheme's variables");
        }
        return .{
            .callee_view = scheme.view,
            .scheme_vars = scheme.vars,
            .site_view = site_view,
            .site_types = site_types,
        };
    }

    fn analyzeUseSchemeSubstitution(self: *Builder, worker_id: WorkerPlanId, use: CheckedExprIdentity) Allocator.Error!void {
        const substitution = self.useSchemeSubstitution(worker_id, use) orelse return;
        for (substitution.site_types) |site_type| {
            if (substitution.site_view.checked_types.payload(site_type) == .err) continue;
            _ = try self.analyzeType(substitution.site_view, site_type);
        }
    }

    fn analyzeDirectCallSchemeSubstitution(self: *Builder, direct: DirectCallPlan) Allocator.Error!void {
        const substitution = self.directCallSchemeSubstitution(direct) orelse return;
        for (substitution.site_types) |site_type| {
            // Checking rejected this instantiation; the call is lowered as
            // the reported error, so the slot supplies no descriptor.
            if (substitution.site_view.checked_types.payload(site_type) == .err) continue;
            _ = try self.analyzeType(substitution.site_view, site_type);
        }
    }

    fn workerEvidenceParams(self: *Builder, source: WorkerSource) ?WorkerEvidenceParams {
        return switch (source) {
            .procedure_template => |template| self.templateEvidenceParams(template),
            .procedure_binding => |binding| self.bindingEvidenceParams(self.moduleForId(binding.artifact), binding.binding),
            .procedure_use => |use| switch (use.binding) {
                .top_level => |binding| self.bindingEvidenceParams(self.moduleForId(binding.artifact), binding.binding),
                .platform_required => |required| self.bindingEvidenceParams(
                    self.moduleForId(required.app_value.artifact),
                    required.procedure_binding,
                ),
                .imported => |imported| blk: {
                    const view = self.moduleForId(imported.artifact);
                    const binding = self.importedProcedureBinding(view, imported);
                    break :blk self.bindingBodyEvidenceParams(binding.body);
                },
                .hosted => null,
            },
            .nested_expr => |expr_ref| blk: {
                const view = self.moduleForId(expr_ref.module);
                const site_expr = self.nestedCallableSiteExprForExpr(view, expr_ref.expr) orelse expr_ref.expr;
                break :blk self.nestedExprEvidenceParams(view, site_expr);
            },
            .generated_codec,
            .generated_field_iterator,
            .generated_interpolation_step,
            => null,
        };
    }

    fn templateEvidenceParams(
        self: *Builder,
        template_ref: checked_names.ProcedureTemplateRef,
    ) WorkerEvidenceParams {
        const view = self.moduleForCheckedModuleId(template_ref.artifact);
        const template = &view.checked_procedure_templates.templates.items[@intFromEnum(template_ref.template)];
        return .{
            .view = view,
            .start = template.evidence_params.start,
            .params = view.checked_procedure_templates.evidenceParams(template),
        };
    }

    fn nestedExprEvidenceParams(
        _: *Builder,
        view: ModuleView,
        expr: checked.CheckedExprId,
    ) ?WorkerEvidenceParams {
        for (view.checked_procedure_templates.dispatch_scopes) |scope| {
            if (scope.checked_expr != expr) continue;
            const start: usize = scope.evidence_params.start;
            const len: usize = scope.evidence_params.len;
            if (start > view.checked_procedure_templates.evidence_params_pool.len or
                len > view.checked_procedure_templates.evidence_params_pool.len - start)
            {
                boxyPlanInvariant("nested procedure evidence span was outside the checked parameter pool");
            }
            return .{ .view = view, .start = @intCast(start), .params = view.checked_procedure_templates.evidence_params_pool[start..][0..len] };
        }
        return null;
    }

    fn bindingEvidenceParams(
        self: *Builder,
        view: ModuleView,
        binding_ref: checked.TopLevelProcedureBindingRef,
    ) ?WorkerEvidenceParams {
        return self.bindingBodyEvidenceParams(view.top_level_procedure_bindings.get(binding_ref).body);
    }

    fn bindingBodyEvidenceParams(
        self: *Builder,
        body: anytype,
    ) ?WorkerEvidenceParams {
        return switch (body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| self.templateEvidenceParams(template),
                .lifted, .synthetic => null,
            },
            .checked_error => null,
            .callable_eval_template => null,
        };
    }

    /// Requirements outside the callable signature, and independent callable
    /// contracts, have explicit checked identities in the worker's scheme.
    /// Their dictionaries cannot be enumerated from signature representations.
    fn schemeDictionaryParams(self: *Builder, worker: WorkerPlan) Allocator.Error![]const HiddenDictionaryParam {
        if (self.scheme_dictionary_params.get(worker.id)) |params| return params;
        var pending = std.ArrayList(HiddenDictionaryParam).empty;
        errdefer pending.deinit(self.allocator);
        var groups = std.AutoHashMapUnmanaged(Span, void).empty;
        defer groups.deinit(self.allocator);
        if (self.workerEvidenceParams(worker.source)) |schema| {
            for (schema.params, 0..) |param, index| {
                const param_index = schema.start + @as(u32, @intCast(index));
                const literal_numeral = self.has_custom_numeral and
                    std.mem.eql(u8, schema.view.canonical_names.?.methodNameText(param.method), "from_numeral");
                if ((param.runtime_dictionary and param.source != .scheme_callable) or literal_numeral) {
                    var hidden = try self.schemeDictionary(.{ .module = schema.view.key, .param = param_index });
                    hidden.evidence_index = @intCast(index);
                    if (!(try groups.getOrPut(self.allocator, hidden.dictionaries)).found_existing)
                        try pending.append(self.allocator, hidden);
                }
                if (param.runtime_dictionary) for (0..param.callable_contracts.len) |contract| {
                    var hidden = try self.schemeDictionary(.{
                        .module = schema.view.key,
                        .param = param_index,
                        .callable_contract = @intCast(contract),
                    });
                    hidden.evidence_index = @intCast(index);
                    try pending.append(self.allocator, hidden);
                };
            }
        }
        const params = try pending.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(params);
        try self.scheme_dictionary_params.put(worker.id, params);
        return params;
    }

    fn compileTimeDictionary(self: *const Builder, dictionaries: Span) bool {
        return dictionaries.len != 0 and self.plan.dictionaries.items[dictionaries.start].compile_time_only;
    }

    fn schemeDictionary(self: *Builder, key: SchemeDictionaryKey) Allocator.Error!HiddenDictionaryParam {
        if (self.scheme_dictionaries.get(key)) |param| return param;
        const view = self.moduleForId(key.module);
        const schema = view.checked_procedure_templates.evidence_params_pool;
        if (key.param >= schema.len)
            boxyPlanInvariant("dictionary did not name a checked evidence parameter");
        const param = schema[key.param];
        // When the program has custom numerals, a numeral requirement outside the
        // scheme's own requirements is proved at compile time; every other owned
        // dictionary is passed at runtime.
        const compile_time_only = self.has_custom_numeral and
            key.callable_contract == null and param.source != .scheme_requirement and
            std.mem.eql(u8, view.canonical_names.?.methodNameText(param.method), "from_numeral");
        const callable_ty = if (key.callable_contract) |contract| blk: {
            if (contract >= param.callable_contracts.len)
                boxyPlanInvariant("dictionary callable contract was outside its checked parameter");
            break :blk view.checked_procedure_templates.evidence_param_callables[param.callable_contracts.start + contract];
        } else if ((param.runtime_dictionary and param.source != .scheme_callable) or compile_time_only)
            param.callable_ty
        else
            boxyPlanInvariant("owned dictionary did not name a checked requirement outside the callable signature");
        const rep = try self.analyzeType(view, param.dispatcher_ty);
        _ = try self.analyzeType(view, callable_ty);
        // The signature and checked owner describe the same dictionary when
        // they name the same receiver and primary callable. Share its group so
        // an inline closure captures that dictionary instead of introducing a
        // second requirement for the identical checked variable. Independent
        // callable contracts, composite scheme requirements, and compile-time
        // literal proofs own separate ABIs.
        if (key.callable_contract == null and param.source != .scheme_requirement and !compile_time_only) {
            const group = self.plan.representations.items[@intFromEnum(rep)].dictionaries;
            for (self.plan.dictionarySlice(group), 0..) |requirement, index| {
                if (requirement.fn_name != param.method) continue;
                if (!typeRefEql(requirement.fn_ty, typeRef(view, callable_ty)))
                    boxyPlanInvariant("checked dictionary owner disagreed with its primary callable");
                const hidden = HiddenDictionaryParam{
                    .scheme_param = key,
                    .dispatch_requirement = @enumFromInt(group.start + @as(u32, @intCast(index))),
                    .source_type = typeRef(view, param.dispatcher_ty),
                    .rep = rep,
                    .dictionaries = group,
                };
                try self.scheme_dictionaries.put(key, hidden);
                return hidden;
            }
        }
        // Literal requirements exposed only through constraints have no raw
        // signature slot; their checked schema explicitly supplies this slot.
        const start: u32 = @intCast(self.plan.dictionaries.items.len);
        try self.plan.dictionaries.append(self.allocator, .{
            .compile_time_only = compile_time_only,
            .source_type = typeRef(view, param.dispatcher_ty),
            .constraint_index = key.param,
            .slot = try self.internDictionaryMethodSlot(view.key, param.method),
            .fn_name = param.method,
            .fn_ty = typeRef(view, callable_ty),
            .origin = .method_call,
            .binop_negated = false,
            .num_literal = null,
        });
        const hidden = HiddenDictionaryParam{
            .scheme_param = key,
            .dispatch_requirement = @enumFromInt(start),
            .source_type = typeRef(view, param.dispatcher_ty),
            .rep = rep,
            .dictionaries = .{ .start = start, .len = 1 },
        };
        try self.scheme_dictionaries.put(key, hidden);
        return hidden;
    }

    /// A lexical capture carries the same checked requirement identity as its
    /// owner. Add that dictionary to the worker ABI through the existing fixed
    /// point, so arbitrary closure depth needs no type or method matching.
    fn requireWorkerSchemeDictionary(self: *Builder, worker: WorkerPlanId, key: SchemeDictionaryKey) Allocator.Error!HiddenDictionaryParam {
        const param = try self.schemeDictionary(key);
        if (self.workerBindsDictionarySpan(worker, param.dictionaries)) return param;
        for (self.scheme_dictionary_uses.items) |use| {
            if (use.worker == worker and use.param.dictionaries.start == param.dictionaries.start) return param;
        }
        try self.scheme_dictionary_uses.append(self.allocator, .{ .worker = worker, .param = param });
        return param;
    }

    fn materializeWorkerHiddenDictionaryParams(self: *Builder) Allocator.Error!void {
        for (self.plan.workers.items, 0..) |worker, worker_index| {
            if (self.workerResolvesToHosted(worker.source) or
                worker.source == .generated_codec or
                worker.source == .generated_field_iterator or
                worker.source == .generated_interpolation_step)
            {
                self.plan.workers.items[worker_index].hidden_dicts = .{};
                continue;
            }

            var pending = std.ArrayList(HiddenDictionaryParam).empty;
            defer pending.deinit(self.allocator);
            var seen_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
            defer seen_reps.deinit();

            if (self.repQuery().functionChildren(worker.rep)) |function| {
                const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
                for (children[function.args_start..][0..function.arg_count]) |child| {
                    try self.collectHiddenDictionariesForRep(child.rep, &pending, &seen_reps);
                }
                try self.collectHiddenDictionariesForRep(function.ret, &pending, &seen_reps);
            } else {
                try self.collectHiddenDictionariesForRep(worker.rep, &pending, &seen_reps);
            }

            for (try self.schemeDictionaryParams(worker)) |param| {
                // A signature group and its checked owner share one ABI slot.
                // Retain the owner's exact evidence index on that slot.
                const existing = for (pending.items, 0..) |candidate, index| {
                    if (std.meta.eql(candidate.dictionaries, param.dictionaries)) break index;
                } else null;
                if (existing) |index| {
                    pending.items[index] = param;
                } else {
                    try pending.append(self.allocator, param);
                }
            }
            const body_start: u32 = @intCast(pending.items.len);
            // A checked requirement can be used only by a forwarded call or
            // nested callable. Its dictionary still belongs to this worker's
            // ABI even when no value in the public signature reaches it.
            if (self.workerEvidenceParams(worker.source)) |schema| {
                for (schema.params) |param| {
                    if (!param.runtime_dictionary or param.source == .scheme_requirement) continue;
                    const rep = self.plan.repForSourceType(typeRef(schema.view, param.dispatcher_ty)) orelse
                        boxyPlanInvariant("worker dictionary requirement dispatcher was not analyzed");
                    try self.collectHiddenDictionariesForRep(rep, &pending, &seen_reps);
                }
            }
            for (self.scheme_dictionary_uses.items) |use| {
                if (use.worker != worker.id) continue;
                const present = for (pending.items) |param| {
                    if (param.dictionaries.start == use.param.dictionaries.start and param.dictionaries.len == use.param.dictionaries.len) break true;
                } else false;
                if (!present) try pending.append(self.allocator, use.param);
            }
            for (self.worker_dictionary_uses.items) |use| {
                if (use.worker != worker.id) continue;
                try self.collectHiddenDictionariesForRep(use.rep, &pending, &seen_reps);
            }

            const start: u32 = @intCast(self.plan.hidden_dictionary_params.items.len);
            try self.plan.hidden_dictionary_params.appendSlice(self.allocator, pending.items);
            self.plan.workers.items[worker_index].hidden_dicts = .{
                .start = start,
                .len = @intCast(pending.items.len),
            };
            self.plan.workers.items[worker_index].body_hidden_dicts = .{
                .start = start + body_start,
                .len = @intCast(pending.items.len - body_start),
            };
        }
    }

    fn materializeWorkerErasedCaptures(self: *Builder) Allocator.Error!void {
        for (self.plan.workers.items, 0..) |worker, worker_index| {
            var pending = std.ArrayList(ErasedCapture).empty;
            defer pending.deinit(self.allocator);

            switch (worker.source) {
                .nested_expr => |expr_ref| {
                    const view = self.moduleForId(expr_ref.module);
                    for (nestedCallableRuntimeCaptures(view, expr_ref.expr)) |capture| {
                        const pattern = view.checked_bodies.pattern(capture.pattern);
                        const rep = self.plan.repForSourceType(typeRef(view, pattern.ty)) orelse
                            boxyPlanInvariant("boxy erased capture pattern type was not analyzed");
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = typeRef(view, pattern.ty),
                            .rep = rep,
                            .capture_id = capture.capture_id,
                        });
                    }
                },
                .procedure_template,
                .procedure_binding,
                .procedure_use,
                => {},
                .generated_codec => |codec| switch (codec.kind) {
                    .parser_constructor,
                    .encoder_constructor,
                    => {},
                    .parser_runtime,
                    .encoder_runtime,
                    => {
                        const capture_type = codec.capture_type orelse
                            boxyPlanInvariant("generated codec runtime had no encoding capture type");
                        const capture_rep = self.plan.repForSourceType(capture_type) orelse
                            boxyPlanInvariant("generated codec encoding capture type was not analyzed");
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = capture_type,
                            .rep = capture_rep,
                            .capture_id = checked.CaptureId.generatedCheck(0),
                        });
                        if (codec.kind == .parser_runtime or codec.kind == .encoder_runtime) {
                            var capture_index: u32 = 1;
                            for (self.plan.generated_parser_field_captures.items) |field_capture| {
                                if (field_capture.worker != worker.id) continue;
                                const field_rep = self.plan.repForSourceType(field_capture.source_type) orelse
                                    boxyPlanInvariant("generated parser field capture type was not analyzed");
                                try pending.append(self.allocator, .{
                                    .kind = .captured_value,
                                    .source_type = field_capture.source_type,
                                    .rep = field_rep,
                                    .capture_id = checked.CaptureId.generatedCheck(capture_index),
                                });
                                capture_index += 1;
                            }
                        }
                    },
                    .encoder_record_fields,
                    .encoder_dict_fields,
                    .encoder_sequence_elements,
                    .encoder_tag_payload_elements,
                    => {
                        const capture_type = codec.capture_type orelse
                            boxyPlanInvariant("generated encoder record callback had no encoding capture type");
                        const capture_rep = self.plan.repForSourceType(capture_type) orelse
                            boxyPlanInvariant("generated encoder record callback encoding type was not analyzed");
                        const value_type = codec.value_type orelse codec.shape;
                        const shape_rep = self.plan.repForSourceType(value_type) orelse
                            boxyPlanInvariant("generated encoder record callback shape type was not analyzed");
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = capture_type,
                            .rep = capture_rep,
                            .capture_id = checked.CaptureId.generatedCheck(0),
                        });
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = value_type,
                            .rep = shape_rep,
                            .capture_id = checked.CaptureId.generatedCheck(1),
                        });
                        const contract_worker = codec.contract_worker orelse
                            boxyPlanInvariant("generated encoder record callback had no contract worker");
                        var capture_index: u32 = 2;
                        for (self.plan.generated_parser_field_captures.items) |field_capture| {
                            if (field_capture.worker != contract_worker) continue;
                            const field_rep = self.plan.repForSourceType(field_capture.source_type) orelse
                                boxyPlanInvariant("generated encoder field-name capture type was not analyzed");
                            try pending.append(self.allocator, .{
                                .kind = .captured_value,
                                .source_type = field_capture.source_type,
                                .rep = field_rep,
                                .capture_id = checked.CaptureId.generatedCheck(capture_index),
                            });
                            capture_index += 1;
                        }
                    },
                    .encoder_value_thunk, .encoder_dict_key_thunk => {
                        const capture_type = codec.capture_type orelse
                            boxyPlanInvariant("generated encoder value thunk had no encoding capture type");
                        const capture_rep = self.plan.repForSourceType(capture_type) orelse
                            boxyPlanInvariant("generated encoder value thunk encoding type was not analyzed");
                        const value_type = codec.value_type orelse codec.shape;
                        const shape_rep = self.plan.repForSourceType(value_type) orelse
                            boxyPlanInvariant("generated encoder value thunk shape type was not analyzed");
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = capture_type,
                            .rep = capture_rep,
                            .capture_id = checked.CaptureId.generatedCheck(0),
                        });
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = value_type,
                            .rep = shape_rep,
                            .capture_id = checked.CaptureId.generatedCheck(1),
                        });
                        const contract_worker = codec.contract_worker orelse
                            boxyPlanInvariant("generated encoder value thunk had no contract worker");
                        var capture_index: u32 = 2;
                        for (self.plan.generated_parser_field_captures.items) |field_capture| {
                            if (field_capture.worker != contract_worker) continue;
                            const field_rep = self.plan.repForSourceType(field_capture.source_type) orelse
                                boxyPlanInvariant("generated encoder value thunk field-name capture type was not analyzed");
                            try pending.append(self.allocator, .{
                                .kind = .captured_value,
                                .source_type = field_capture.source_type,
                                .rep = field_rep,
                                .capture_id = checked.CaptureId.generatedCheck(capture_index),
                            });
                            capture_index += 1;
                        }
                    },
                },
                .generated_field_iterator => |iterator| {
                    const fields_rep = self.plan.repForSourceType(iterator.field_names_type) orelse
                        boxyPlanInvariant("generated FieldNames iterator capture type was not analyzed");
                    try pending.append(self.allocator, .{
                        .kind = .captured_value,
                        .source_type = iterator.field_names_type,
                        .rep = fields_rep,
                        .capture_id = checked.CaptureId.generatedCheck(0),
                    });
                    const index_rep = self.plan.repForSourceType(iterator.index_type) orelse
                        boxyPlanInvariant("generated FieldNames iterator index type was not analyzed");
                    try pending.append(self.allocator, .{
                        .kind = .captured_value,
                        .source_type = iterator.index_type,
                        .rep = index_rep,
                        .capture_id = checked.CaptureId.generatedCheck(1),
                    });
                    try pending.append(self.allocator, .{
                        .kind = .captured_value,
                        .source_type = iterator.index_type,
                        .rep = index_rep,
                        .capture_id = checked.CaptureId.generatedCheck(2),
                    });
                    if (iterator.size_type) |size_type| {
                        const size_rep = self.plan.repForSourceType(size_type) orelse
                            boxyPlanInvariant("generated FieldNames iterator size type was not analyzed");
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = size_type,
                            .rep = size_rep,
                            .capture_id = checked.CaptureId.generatedCheck(3),
                        });
                    }
                },
                .generated_interpolation_step => |step| {
                    if (step.one_payload_type) |payload_type| {
                        const payload_rep = self.plan.repForSourceType(payload_type) orelse
                            boxyPlanInvariant("generated interpolation payload capture type was not analyzed");
                        try pending.append(self.allocator, .{
                            .kind = .captured_value,
                            .source_type = payload_type,
                            .rep = payload_rep,
                            .capture_id = checked.CaptureId.generatedCheck(0),
                        });
                    }
                },
            }

            for (self.plan.hiddenDescriptorParamSlice(worker.hidden_descs), 0..) |param, param_index| {
                try pending.append(self.allocator, .{
                    .kind = .hidden_desc,
                    .source_type = param.source_type,
                    .rep = param.rep,
                    .desc = param.desc,
                    .body_descriptor = worker.body_hidden_descs.len != 0 and
                        worker.hidden_descs.start + param_index >= worker.body_hidden_descs.start and
                        worker.hidden_descs.start + param_index < worker.body_hidden_descs.start + worker.body_hidden_descs.len,
                });
            }

            for (self.plan.hiddenDictionaryParamSlice(worker.hidden_dicts), 0..) |param, param_index| {
                try pending.append(self.allocator, .{
                    .kind = .hidden_dict,
                    .source_type = param.source_type,
                    .rep = param.rep,
                    .dictionaries = param.dictionaries,
                    .body_dictionary = worker.body_hidden_dicts.len != 0 and
                        worker.hidden_dicts.start + param_index >= worker.body_hidden_dicts.start and
                        worker.hidden_dicts.start + param_index < worker.body_hidden_dicts.start + worker.body_hidden_dicts.len,
                });
            }

            for (self.plan.contextInputSlice(worker.context), 0..) |input, input_index| {
                if (!input.isValue()) continue;
                try pending.append(self.allocator, .{
                    .kind = .captured_value,
                    .source_type = input.callable_type.?,
                    .rep = input.rep.?,
                    .context_input = @intCast(input_index),
                });
            }

            const start: u32 = @intCast(self.plan.erased_captures.items.len);
            try self.plan.erased_captures.appendSlice(self.allocator, pending.items);
            self.plan.workers.items[worker_index].erased_captures = .{
                .start = start,
                .len = @intCast(pending.items.len),
            };
        }
    }

    fn materializeStoredCallableCaptureSources(self: *Builder) Allocator.Error!void {
        for (self.plan.callable_uses.items) |*use| {
            const stored_fn = use.stored_fn orelse continue;
            use.stored_capture_sources = try self.appendStoredCallableCaptureSources(stored_fn, use.worker);
        }
        for (self.plan.static_fns.items) |*static_fn| {
            static_fn.capture_sources = try self.appendStoredCallableCaptureSources(.{
                .module = static_fn.store_module,
                .fn_id = static_fn.fn_id,
            }, static_fn.worker);
        }
    }

    /// A stored callable value fixes its worker's instantiation: every type
    /// variable its worker's descriptors describe occupies some position of
    /// the stored function type or of a stored capture's type, and the stored
    /// representation at that position is that descriptor's concrete source.
    /// A checked use supplies its signature and evidence descriptors as any
    /// callable use does; the variables of the scope that created the stored
    /// closure appear in no type the use names, so the stored value supplies
    /// those.
    fn materializeStoredCallableHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        for (self.plan.callable_uses.items) |use| {
            const stored_fn = use.stored_fn orelse continue;
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            if (worker.enclosing_descs.len == 0) continue;
            const value_rep = self.plan.repForSourceType(use.callable_ty) orelse
                boxyPlanInvariant("stored callable use type was not analyzed");
            const args = self.plan.direct_call_hidden_desc_args.items[use.hidden_desc_args.start..][0..use.hidden_desc_args.len];
            const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
            if (args.len != params.len) boxyPlanInvariant("stored callable use did not plan every worker descriptor");
            const enclosing_start = worker.enclosing_descs.start - worker.hidden_descs.start;
            for (params[enclosing_start..][0..worker.enclosing_descs.len], args[enclosing_start..][0..worker.enclosing_descs.len]) |param, *arg| {
                const rep = try self.storedCallableDescriptorRep(stored_fn, worker, value_rep, param.rep);
                arg.* = .{
                    .worker_desc = param.desc,
                    .worker_rep = param.rep,
                    .source_type = self.plan.representations.items[@intFromEnum(rep)].source_type,
                    .rep = rep,
                };
            }
        }
        for (self.plan.static_fns.items) |*static_fn| {
            const stored_fn = StoredFnSource{ .module = static_fn.store_module, .fn_id = static_fn.fn_id };
            const worker = self.plan.workers.items[@intFromEnum(static_fn.worker)];
            const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
            const start: u32 = @intCast(self.plan.direct_call_hidden_desc_args.items.len);
            for (params) |param| {
                const rep = try self.storedCallableDescriptorRep(stored_fn, worker, static_fn.rep, param.rep);
                try self.plan.direct_call_hidden_desc_args.append(self.allocator, .{
                    .worker_desc = param.desc,
                    .worker_rep = param.rep,
                    .source_type = self.plan.representations.items[@intFromEnum(rep)].source_type,
                    .rep = rep,
                });
            }
            static_fn.hidden_desc_args = .{ .start = start, .len = @intCast(params.len) };
        }
    }

    /// The concrete representation a stored callable gives one worker
    /// descriptor representation. `value_rep` is the callable value's own
    /// concrete function type.
    fn storedCallableDescriptorRep(
        self: *Builder,
        stored_fn: StoredFnSource,
        worker: WorkerPlan,
        value_rep: TypeRepId,
        desc_rep: TypeRepId,
    ) Allocator.Error!TypeRepId {
        if (try self.repAtTypePosition(worker.rep, desc_rep, value_rep)) |found| return found;
        const store_view = self.moduleForId(stored_fn.module);
        const store = store_view.const_store orelse
            boxyPlanInvariant("stored callable descriptor planning had no ConstStore");
        const fn_value = store.getFn(stored_fn.fn_id);
        for (self.plan.erasedCaptureSlice(worker.erased_captures)) |capture| {
            if (capture.kind != .captured_value) continue;
            const capture_id = capture.capture_id orelse
                boxyPlanInvariant("stored callable value capture had no checked capture id");
            const persisted = for (fn_value.captures) |persisted| {
                if (std.meta.eql(persisted.id, capture_id)) break persisted;
            } else continue;
            const persisted_rep = self.plan.repForStoredType(.{ .module = stored_fn.module, .ty = persisted.ty }) orelse
                boxyPlanInvariant("stored callable capture type was not analyzed");
            if (try self.repAtTypePosition(capture.rep, desc_rep, persisted_rep)) |found| return found;
        }
        boxyPlanInvariant("stored callable worker descriptor was absent from its stored types");
    }

    fn appendStoredCallableCaptureSources(
        self: *Builder,
        stored_fn: StoredFnSource,
        worker_id: WorkerPlanId,
    ) Allocator.Error!Span {
        const store_view = self.moduleForId(stored_fn.module);
        const store = store_view.const_store orelse
            boxyPlanInvariant("stored callable use had no checked ConstStore");
        if (@intFromEnum(stored_fn.fn_id) >= store.fns.items.len) {
            boxyPlanInvariant("stored callable use referenced a missing ConstStore function");
        }
        const fn_value = store.getFn(stored_fn.fn_id);
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const captures = self.plan.erasedCaptureSlice(worker.erased_captures);
        const start: u32 = @intCast(self.plan.stored_callable_capture_sources.items.len);
        var const_capture_count: usize = 0;

        for (captures) |capture| {
            if (capture.kind != .captured_value) continue;
            const capture_id = capture.capture_id orelse
                boxyPlanInvariant("stored callable value capture had no checked capture id");
            var persisted_capture: ?check.ConstStore.ConstCapture = null;
            for (fn_value.captures) |persisted| {
                if (std.meta.eql(persisted.id, capture_id)) {
                    persisted_capture = persisted;
                    break;
                }
            }
            const source: StoredCallableCaptureSource.Source = if (persisted_capture) |persisted| blk: {
                const_capture_count += 1;
                break :blk .{ .const_node = .{
                    .store_module = stored_fn.module,
                    .node = persisted.value,
                    .stored_type = persisted.ty,
                } };
            } else .{ .checked_expr = self.storedGeneratedEncodingCaptureExpr(worker, capture_id) };
            try self.plan.stored_callable_capture_sources.append(self.allocator, .{
                .capture_id = capture_id,
                .source = source,
            });
        }
        if (const_capture_count != fn_value.captures.len) {
            boxyPlanInvariant("stored callable worker did not consume every persisted capture");
        }
        return .{
            .start = start,
            .len = @intCast(self.plan.stored_callable_capture_sources.items.len - start),
        };
    }

    fn storedGeneratedEncodingCaptureExpr(
        self: *Builder,
        worker: WorkerPlan,
        capture_id: checked.CaptureId,
    ) CheckedExprIdentity {
        if (capture_id != checked.CaptureId.generatedCheck(0)) {
            boxyPlanInvariant("stored callable capture was absent from ConstStore without a checked producer expression");
        }
        const codec = switch (worker.source) {
            .generated_codec => |codec| switch (codec.kind) {
                .parser_runtime, .encoder_runtime => codec,
                .parser_constructor,
                .encoder_constructor,
                .encoder_record_fields,
                .encoder_dict_fields,
                .encoder_sequence_elements,
                .encoder_tag_payload_elements,
                .encoder_value_thunk,
                .encoder_dict_key_thunk,
                => boxyPlanInvariant("non-runtime generated codec had an unpersisted stored capture"),
            },
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .nested_expr,
            .generated_field_iterator,
            .generated_interpolation_step,
            => boxyPlanInvariant("non-codec callable had an unpersisted stored capture"),
        };
        const contract_expr = codec.contract_expr orelse
            boxyPlanInvariant("stored generated codec had no checked contract expression");
        const view = self.moduleForId(contract_expr.module);
        const dispatch = self.dispatchPlanForGeneratedRuntime(view, contract_expr.expr);
        const operands = dispatch.argsSlice(view.static_dispatch_plans);
        if (operands.len != 1) {
            boxyPlanInvariant("stored generated codec constructor did not have one checked operand");
        }
        return switch (operands[0]) {
            .checked_expr => |expr| .{ .module = view.key, .expr = expr },
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => boxyPlanInvariant("stored generated codec encoding was not a checked expression operand"),
        };
    }

    fn workerResolvesToHosted(self: *Builder, source: WorkerSource) bool {
        if (source == .generated_codec or
            source == .generated_field_iterator or
            source == .generated_interpolation_step)
        {
            return false;
        }
        if (self.root_module == null) return workerSourceIsHosted(source);
        return switch (self.rootWorkerBody(source)) {
            .hosted_proc => true,
            .checked_expr,
            .intrinsic_wrapper,
            .unimplemented,
            => false,
        };
    }

    const CallOperandTypeRep = struct {
        type: CheckedTypeIdentity,
        rep: TypeRepId,
    };

    fn analyzeCallOperandTypeRep(
        self: *Builder,
        call_view: ModuleView,
        operand: CallOperand,
        call_type: CheckedTypeIdentity,
        call_rep: TypeRepId,
        caller: WorkerPlanId,
    ) Allocator.Error!CallOperandTypeRep {
        return switch (operand) {
            .checked_expr => |call_arg| blk: {
                const actual_expr = call_view.checked_bodies.expr(call_arg);
                if (actual_expr.data == .lambda or actual_expr.data == .closure) {
                    try self.recordNestedCallableExprUseForCaller(
                        call_view,
                        call_arg,
                        call_type,
                        caller,
                    );
                }
                break :blk .{
                    .type = typeRef(call_view, actual_expr.ty),
                    .rep = try self.analyzeType(call_view, actual_expr.ty),
                };
            },
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => .{ .type = call_type, .rep = call_rep },
        };
    }

    fn materializeDirectCallTypeSubstitutions(self: *Builder) Allocator.Error!void {
        var direct_index: usize = 0;
        while (direct_index < self.plan.direct_calls.items.len) : (direct_index += 1) {
            const direct = self.plan.direct_calls.items[direct_index];
            if (direct.ret_substitution != null) continue;
            const call_view = self.moduleForId(direct.call.module);
            const call_operands = self.plan.callOperandSlice(direct.operands);

            const source_view = self.moduleForId(direct.source_fn_type.module);
            const source_function = checkedFunctionPayload(source_view, direct.source_fn_type.ty);
            if (source_function.args.len != call_operands.len) {
                boxyPlanInvariant("boxy direct call instantiated function type arity disagreed with call args");
            }

            const worker = self.plan.workers.items[@intFromEnum(direct.worker)];
            const worker_function = (self.repQuery().functionChildren(worker.rep)) orelse
                boxyPlanInvariant("boxy direct call worker substitution target was not a function");
            if (worker_function.arg_count != source_function.args.len) {
                boxyPlanInvariant("boxy direct call worker arity disagreed with its instantiated function type");
            }
            const worker_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(worker_function.rep)].children);
            const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];

            const start: u32 = @intCast(self.plan.call_type_substitutions.items.len);
            for (source_function.args, worker_args, call_operands) |call_arg_ty, worker_arg, operand| {
                const call_type = CheckedTypeIdentity{ .module = direct.source_fn_type.module, .ty = call_arg_ty };
                const call_rep = try self.analyzeType(source_view, call_arg_ty);
                const operand_info = try self.analyzeCallOperandTypeRep(call_view, operand, call_type, call_rep, direct.caller);
                try self.plan.call_type_substitutions.append(self.allocator, .{
                    .operand_type = operand_info.type,
                    .operand_rep = operand_info.rep,
                    .call_type = call_type,
                    .call_rep = call_rep,
                    .worker_rep = worker_arg.rep,
                });
            }

            const call_ret_type = CheckedTypeIdentity{
                .module = direct.source_fn_type.module,
                .ty = source_function.ret,
            };
            const call_ret_rep = try self.analyzeType(source_view, source_function.ret);
            self.plan.direct_calls.items[direct_index].arg_substitutions = .{
                .start = start,
                .len = @intCast(source_function.args.len),
            };
            self.plan.direct_calls.items[direct_index].ret_substitution = .{
                .operand_type = self.plan.representations.items[@intFromEnum(worker_function.ret)].source_type,
                .operand_rep = worker_function.ret,
                .call_type = call_ret_type,
                .call_rep = call_ret_rep,
                .worker_rep = worker_function.ret,
            };
        }
    }

    fn materializeDictionaryDispatchTypeSubstitutions(self: *Builder) Allocator.Error!void {
        for (self.plan.dictionary_dispatches.items, 0..) |dispatch, dispatch_index| {
            if (dispatch.ret_substitution != null) continue;

            const call_view = self.moduleForId(dispatch.call.module);
            const source_view = self.moduleForId(dispatch.source_fn_type.module);
            const source_function = checkedFunctionPayload(source_view, dispatch.source_fn_type.ty);
            const operands = self.plan.callOperandSlice(dispatch.operands);
            if (source_function.args.len != operands.len) {
                boxyPlanInvariant("boxy dictionary dispatch callable arity disagreed with its operands");
            }

            const start: u32 = @intCast(self.plan.call_type_substitutions.items.len);
            for (source_function.args, operands) |call_arg_ty, operand| {
                const call_type = CheckedTypeIdentity{ .module = dispatch.source_fn_type.module, .ty = call_arg_ty };
                const call_rep = try self.analyzeType(source_view, call_arg_ty);
                const operand_info = try self.analyzeCallOperandTypeRep(call_view, operand, call_type, call_rep, dispatch.caller);
                try self.plan.call_type_substitutions.append(self.allocator, .{
                    .operand_type = operand_info.type,
                    .operand_rep = operand_info.rep,
                    .call_type = call_type,
                    .call_rep = call_rep,
                    .worker_rep = call_rep,
                });
            }

            const result_expr = call_view.checked_bodies.expr(dispatch.call.expr);
            const result_type = typeRef(call_view, result_expr.ty);
            const result_rep = try self.analyzeType(call_view, result_expr.ty);
            const call_ret_type = CheckedTypeIdentity{
                .module = dispatch.source_fn_type.module,
                .ty = source_function.ret,
            };
            const call_ret_rep = try self.analyzeType(source_view, source_function.ret);
            self.plan.dictionary_dispatches.items[dispatch_index].arg_substitutions = .{
                .start = start,
                .len = @intCast(source_function.args.len),
            };
            self.plan.dictionary_dispatches.items[dispatch_index].ret_substitution = .{
                .operand_type = result_type,
                .operand_rep = result_rep,
                .call_type = call_ret_type,
                .call_rep = call_ret_rep,
                .worker_rep = call_ret_rep,
            };
        }
    }

    fn materializeDictionaryCallPlans(self: *Builder) Allocator.Error!void {
        while (true) {
            const worker_count = self.plan.workers.items.len;
            const direct_call_count = self.plan.direct_calls.items.len;
            const dictionary_dispatch_count = self.plan.dictionary_dispatches.items.len;
            const representation_count = self.plan.representations.items.len;
            const dictionary_count = self.plan.dictionaries.items.len;
            const inspect_method_count = self.plan.inspect_methods.items.len;
            const inspect_demand_count = self.inspect_demand_count;
            const generated_codec_call_count = self.plan.generated_codec_calls.items.len;
            const worker_dictionary_use_count = self.worker_dictionary_uses.items.len;
            const scheme_dictionary_use_count = self.scheme_dictionary_uses.items.len;
            const nested_callable_use_count = self.plan.nested_callable_uses.items.len;
            const derived_root_count = self.derived_roots.items.len;
            const derived_call_count = self.plan.derived_component_calls.items.len;

            try self.analyzePlannedEvidenceTypes();
            try self.activateCustomNumeralSites();
            try self.materializeDirectCallTypeSubstitutions();
            try self.materializeDictionaryDispatchTypeSubstitutions();
            // Dictionary-dispatch worker discovery can analyze method bodies
            // that append direct calls. Inspect planning consumes their exact
            // substitutions in this iteration.
            try self.materializeDirectCallTypeSubstitutions();
            try self.materializeInspectMethodPlans();
            // Inspect worker discovery analyzes method bodies and can append
            // direct calls; materialize those substitutions before any hidden
            // argument phase consumes them in this fixed-point iteration.
            try self.materializeDirectCallTypeSubstitutions();
            try self.materializeDictionaryDispatchTypeSubstitutions();
            try self.materializeWorkerHiddenDictionaryParams();
            try self.materializeRootHiddenDictionaryArgs();
            try self.materializeDirectCallHiddenDictionaryArgs();
            try self.materializeConstEvalCallHiddenDictionaryArgs();
            try self.materializeIteratorCallHiddenDictionaryArgs();
            try self.materializeInspectMethodHiddenDictionaryArgs();
            try self.materializeGeneratedCodecCallHiddenDictionaryArgs();
            try self.planNestedCallableUseDictionaries();
            try self.materializeDerivedComponentPlans();
            try self.materializeDerivedComponentCallHiddenDictionaryArgs();

            if (worker_count == self.plan.workers.items.len and
                direct_call_count == self.plan.direct_calls.items.len and
                dictionary_dispatch_count == self.plan.dictionary_dispatches.items.len and
                representation_count == self.plan.representations.items.len and
                dictionary_count == self.plan.dictionaries.items.len and
                inspect_method_count == self.plan.inspect_methods.items.len and
                inspect_demand_count == self.inspect_demand_count and
                generated_codec_call_count == self.plan.generated_codec_calls.items.len and
                worker_dictionary_use_count == self.worker_dictionary_uses.items.len and
                scheme_dictionary_use_count == self.scheme_dictionary_uses.items.len and
                nested_callable_use_count == self.plan.nested_callable_uses.items.len and
                derived_root_count == self.derived_roots.items.len and
                derived_call_count == self.plan.derived_component_calls.items.len)
            {
                return;
            }
        }
    }

    const DerivedRoot = struct {
        frame: ?WorkerPlanId,
        method: DerivedMethod,
        rep: TypeRepId,
        env: u32,
        /// The derivation's second argument type: its operand type for
        /// equality, its hasher type for hashing.
        second_type: CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
    };

    /// Record a derived `is_eq`/`to_hash` over `rep` lowered in `worker`,
    /// whose checked signature is `rep, second_type -> ret_type`, under the
    /// formal bindings of environment `env`.
    fn registerDerivedRoot(
        self: *Builder,
        worker: ?WorkerPlanId,
        method: DerivedMethod,
        rep: TypeRepId,
        env: u32,
        second_type: CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
    ) Allocator.Error!void {
        if (env == 0) try self.recordFrameContextProcs(rep, method);
        const frame = try self.plan.derivedFrame(self.allocator, worker, rep, env);
        const key = DerivedComponentKey{ .frame = frame, .method = method, .rep = rep, .env = env };
        if ((try self.derived_roots_seen.getOrPut(self.allocator, key)).found_existing) return;
        try self.derived_roots.append(self.allocator, .{
            .frame = frame,
            .method = method,
            .rep = rep,
            .env = env,
            .second_type = second_type,
            .ret_type = ret_type,
        });
    }

    /// Register the derivation a structural dictionary method performs over
    /// `rep` for the dictionary a call in `caller` passes.
    fn registerStructuralDictionaryDerivation(
        self: *Builder,
        caller: ?WorkerPlanId,
        rep: TypeRepId,
        env: u32,
        method: DictionaryMethodEvidence,
    ) Allocator.Error!void {
        const kind = switch (method.resolution) {
            .structural => |kind| kind,
            .worker, .builtin_numeral, .constraint, .checked_error, .unreachable_value => return,
        };
        const derived: DerivedMethod = switch (kind) {
            .equality => .equality,
            .hash => .hash,
            .parser, .encoder, .map, .map_effectful => return,
        };
        const function_rep = self.plan.repForSourceType(method.callable_type) orelse
            boxyPlanInvariant("structural dictionary method callable type was not analyzed");
        const function = self.repQuery().functionChildren(function_rep) orelse
            boxyPlanInvariant("structural dictionary method callable was not a function");
        if (function.arg_count != 2) boxyPlanInvariant("structural dictionary method did not take two arguments");
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
        try self.registerDerivedRoot(
            caller,
            derived,
            rep,
            env,
            children[function.args_start + 1].source_type,
            self.plan.representations.items[@intFromEnum(function.ret)].source_type,
        );
    }

    fn registerStructuralDictionaryDerivations(
        self: *Builder,
        caller: ?WorkerPlanId,
        rep: TypeRepId,
        env: u32,
        method_evidence: Span,
    ) Allocator.Error!void {
        var index: usize = 0;
        while (index < method_evidence.len) : (index += 1) {
            const method = self.plan.dictionary_method_evidence.items[method_evidence.start + index];
            try self.registerStructuralDictionaryDerivation(caller, rep, env, method);
        }
    }

    /// Register the derivation an unresolved dispatch permitted to compare or
    /// hash structurally performs over its dispatcher.
    fn registerStructuralDispatchDerivation(
        self: *Builder,
        view: ModuleView,
        caller: WorkerPlanId,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        dispatcher_rep: TypeRepId,
    ) Allocator.Error!void {
        const method: DerivedMethod = switch (dispatch.result_mode) {
            .equality => |eq| if (eq.structural_allowed) .equality else return,
            .hash => |hash| if (hash.structural_allowed) .hash else return,
            .value, .parser_for, .encoder_for, .map, .map_effectful => return,
        };
        const function_rep = try self.analyzeType(view, dispatch.callable_ty);
        const function = self.repQuery().functionChildren(function_rep) orelse
            boxyPlanInvariant("structural dispatch callable was not a function");
        if (function.arg_count != 2) boxyPlanInvariant("structural dispatch did not take two arguments");
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
        try self.registerDerivedRoot(
            caller,
            method,
            dispatcher_rep,
            0,
            children[function.args_start + 1].source_type,
            self.plan.representations.items[@intFromEnum(function.ret)].source_type,
        );
    }

    /// The environment of the ordered form of `stack`, recorded once.
    fn internDerivedEnv(self: *Builder, stack: []const DerivedBinding) Allocator.Error!u32 {
        const ordered = try orderedDerivedEnv(self.allocator, stack);
        defer self.allocator.free(ordered);
        if (self.plan.findDerivedEnv(ordered)) |env| return env;
        const start: u32 = @intCast(self.plan.derived_env_bindings.items.len);
        try self.plan.derived_env_bindings.appendSlice(self.allocator, ordered);
        try self.plan.derived_envs.append(self.allocator, .{ .start = start, .len = @intCast(ordered.len) });
        return @intCast(self.plan.derived_envs.items.len);
    }

    /// The nominal formals a derived walk is inside, innermost last, and the
    /// ordered environment they form.
    const DerivedWalk = struct {
        root: DerivedRoot,
        bindings: std.ArrayList(DerivedBinding) = .empty,
        env: u32 = 0,
        visited: std.AutoHashMapUnmanaged(struct { rep: TypeRepId, env: u32 }, void) = .{},

        fn deinit(self: *DerivedWalk, allocator: Allocator) void {
            self.bindings.deinit(allocator);
            self.visited.deinit(allocator);
        }

        fn actualFor(self: *const DerivedWalk, rep: TypeRepId) ?TypeRepId {
            var index = self.bindings.items.len;
            while (index > 0) {
                index -= 1;
                if (self.bindings.items[index].formal == rep) return self.bindings.items[index].actual;
            }
            return null;
        }
    };

    /// Decide every list, nominal, and type-variable component each new
    /// derived root reaches, planning a worker call for each component whose
    /// type has its own method.
    fn materializeDerivedComponentPlans(self: *Builder) Allocator.Error!void {
        while (self.derived_roots_walked < self.derived_roots.items.len) {
            const root = self.derived_roots.items[self.derived_roots_walked];
            self.derived_roots_walked += 1;
            var walk = DerivedWalk{ .root = root, .env = root.env };
            defer walk.deinit(self.allocator);
            try walk.bindings.appendSlice(self.allocator, self.plan.derivedEnvBindings(root.env));
            try self.walkDerivedComponent(&walk, root.rep);
        }
    }

    /// Whether a scheme in `frame`'s lexical chain quantifies `variable`.
    /// Checking copies a generalized variable at every use, so a variable in
    /// a frame's checked types that no scheme in its chain quantifies is
    /// shared with its definition: the open variable of a monomorphic value.
    fn frameLexicallyQuantifies(self: *Builder, frame: ?WorkerPlanId, variable: CheckedTypeIdentity) bool {
        const worker_id = frame orelse return true;
        const source = self.plan.workers.items[@intFromEnum(worker_id)].source;
        switch (source) {
            .procedure_template, .procedure_binding, .procedure_use => {
                const own = self.workerSchemeVars(source) orelse return false;
                return schemeVarsContain(own, variable);
            },
            .nested_expr => |expr_ref| {
                if (self.workerSchemeVars(source)) |own| {
                    if (schemeVarsContain(own, variable)) return true;
                }
                const view = self.moduleForId(expr_ref.module);
                const site_expr = self.nestedCallableSiteExprForExpr(view, expr_ref.expr) orelse expr_ref.expr;
                const site = for (view.nested_proc_sites.sites) |candidate| {
                    if (candidate.checked_expr == site_expr) break candidate;
                } else boxyPlanInvariant("nested worker omitted its lexical site");
                var scope = site.lexical_scope;
                while (scope == .generalized) {
                    const current = &view.checked_procedure_templates.dispatch_scopes[@intFromEnum(scope.generalized)];
                    if (schemeVarsContain(.{ .view = view, .vars = view.checked_procedure_templates.scopeSchemeVars(current) }, variable)) return true;
                    scope = if (current.parent) |parent| .{ .generalized = parent } else .root;
                }
                return switch (site.owner) {
                    .template => |template| schemeVarsContain(self.templateSchemeVars(template), variable),
                    .default_root => false,
                };
            },
            // Generated workers take their types from checked contracts
            // rather than from a lexical scheme chain.
            .generated_codec, .generated_field_iterator, .generated_interpolation_step => return true,
        }
    }

    fn schemeVarsContain(scheme: WorkerSchemeVars, variable: CheckedTypeIdentity) bool {
        if (!moduleKeyEqual(scheme.view.key, variable.module)) return false;
        for (scheme.vars) |candidate| {
            if (candidate == variable.ty) return true;
        }
        return false;
    }

    /// The variable a dynamic representation stands for: its own, or for an
    /// open row the extension variable its listed variants end in.
    fn sharedVariableIdentity(self: *const Builder, rep_id: TypeRepId) CheckedTypeIdentity {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        if (!rep.is_open_tag_row) return rep.source_type;
        return self.plan.representations.items[@intFromEnum(self.openRowExtensionRep(rep))].source_type;
    }

    fn openRowExtensionRep(self: *const Builder, rep: TypeRepresentation) TypeRepId {
        for (self.plan.childSlice(rep.children)) |child| {
            if (child.role == .tag_ext) return child.rep;
        }
        boxyPlanInvariant("open tag row representation had no extension child");
    }

    /// What leaves a variable unbound: a worker frame whose lexical chain
    /// does not quantify it, or the absence of any caller at all.
    const SharedVariableBinder = enum { frame, no_caller };

    /// A shared variable at its checked default, or an open row with its
    /// shared extension at that default: exactly the listed variants.
    fn sharedVariableClosedRep(self: *Builder, rep_id: TypeRepId, binder: SharedVariableBinder) Allocator.Error!TypeRepId {
        if (self.plan.shared_closed_reps.get(rep_id)) |closed| return closed;
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const closed = if (rep.is_open_tag_row) blk: {
            const extension = try self.sharedVariableClosedRep(self.openRowExtensionRep(rep), binder);
            const children_start: u32 = @intCast(self.plan.children.items.len);
            // Read by index: appending grows the child table.
            for (0..rep.children.len) |index| {
                var child = self.plan.children.items[rep.children.start + index];
                if (child.role == .tag_ext) child.rep = extension;
                try self.plan.children.append(self.allocator, child);
            }
            const variants_start: u32 = @intCast(self.plan.tag_variants.items.len);
            for (0..rep.tag_variants.len) |index| {
                var variant = self.plan.tag_variants.items[rep.tag_variants.start + index];
                variant.payloads.start = variant.payloads.start - rep.children.start + children_start;
                try self.plan.tag_variants.append(self.allocator, variant);
            }
            const closed_id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
            try self.plan.representations.append(self.allocator, .{
                .source_type = rep.source_type,
                .kind = .tag_union,
                .children = .{ .start = children_start, .len = rep.children.len },
                .tag_variants = .{ .start = variants_start, .len = rep.tag_variants.len },
            });
            break :blk closed_id;
        } else blk: {
            const view = self.moduleForId(rep.source_type.module);
            const variable = switch (view.checked_types.payload(rep.source_type.ty)) {
                .flex => |flex| flex,
                .rigid => |rigid| switch (binder) {
                    // No caller binds a variable a root or a caller-less call
                    // still holds, whether flexible or rigid; it is at its
                    // checked default there.
                    .no_caller => rigid,
                    .frame => boxyPlanInvariant("a rigid variable was shared outside its scheme"),
                },
                .pending, .err, .alias, .record, .tuple, .nominal, .function, .tag_union, .empty_record, .empty_tag_union => boxyPlanInvariant("a shared dynamic representation was not a variable"),
            };
            const closed_id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
            try self.plan.representations.append(self.allocator, .{
                .source_type = rep.source_type,
                .kind = variableDefaultKind(variable),
            });
            break :blk closed_id;
        };
        try self.plan.shared_closed_reps.put(self.allocator, rep_id, closed);
        return closed;
    }

    /// One pending step of a derived component walk.
    const DerivedWalkAction = union(enum) {
        visit: TypeRepId,
        /// Leave a nominal's backing: drop its formal bindings.
        restore: struct { bindings_len: usize, env: u32 },
    };

    /// Walk the components `root` reaches in pre-order.
    fn walkDerivedComponent(self: *Builder, walk: *DerivedWalk, root: TypeRepId) Allocator.Error!void {
        var actions: std.ArrayList(DerivedWalkAction) = .empty;
        defer actions.deinit(self.allocator);
        try actions.append(self.allocator, .{ .visit = root });
        while (actions.pop()) |action| switch (action) {
            .visit => |rep_id| try self.visitDerivedComponent(walk, rep_id, &actions),
            .restore => |saved| {
                walk.bindings.shrinkRetainingCapacity(saved.bindings_len);
                walk.env = saved.env;
            },
        };
    }

    fn visitDerivedComponent(self: *Builder, walk: *DerivedWalk, rep_id: TypeRepId, actions: *std.ArrayList(DerivedWalkAction)) Allocator.Error!void {
        if ((try walk.visited.getOrPut(self.allocator, .{ .rep = rep_id, .env = walk.env })).found_existing) return;
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        switch (rep.kind) {
            .alias => try actions.append(self.allocator, .{ .visit = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep }),
            .dynamic => {
                // A formal position holds its use's actual, and a sealed
                // variable its sealed type.
                if (walk.actualFor(rep_id)) |actual| return try actions.append(self.allocator, .{ .visit = actual });
                if (rep.sealed_default) |sealed| return try actions.append(self.allocator, .{ .visit = sealed });
                if (!self.frameLexicallyQuantifies(walk.root.frame, self.sharedVariableIdentity(rep_id))) {
                    const closed = try self.sharedVariableClosedRep(rep_id, .frame);
                    try self.recordDerivedDecision(walk, rep_id, .{ .shared_closed = closed });
                    return try actions.append(self.allocator, .{ .visit = closed });
                }
                const requirement = self.derivedSchemeRequirement(rep_id, walk.root.method) orelse
                    boxyPlanInvariant("derived method reached a type variable without its scheme requirement");
                try self.recordDerivedDecision(walk, rep_id, .{ .scheme_dictionary = requirement });
            },
            .list => switch (self.derivedMethodTarget(rep_id, walk.root.method) orelse
                boxyPlanInvariant("derived method reached a List without its method")) {
                .target => |lookup| try self.planDerivedComponentCall(walk, rep_id, lookup),
                .rejected => boxyPlanInvariant("builtin List derivation target was a rejected declaration"),
            },
            .box => try actions.append(self.allocator, .{ .visit = self.repQuery().requiredSingleChild(rep_id, .box_payload).rep }),
            .nominal => |kind| {
                if (self.derivedMethodTarget(rep_id, walk.root.method)) |found| switch (found) {
                    .target => |lookup| return try self.planDerivedComponentCall(walk, rep_id, lookup),
                    .rejected => return try self.recordDerivedDecision(walk, rep_id, .checked_error),
                };
                try self.recordDerivedDecision(walk, rep_id, .structural);
                switch (kind) {
                    .transparent, .builtin_other, .opaque_nominal => {
                        // Each actual is resolved in the enclosing bindings
                        // before this nominal's formals shadow any of them.
                        var substitutions = self.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                        var resolved = std.ArrayList(DerivedBinding).empty;
                        defer resolved.deinit(self.allocator);
                        while (substitutions.next()) |substitution| {
                            const formal = substitution.formal_rep orelse continue;
                            const actual = walk.actualFor(substitution.actual_rep) orelse substitution.actual_rep;
                            if (formal == actual) continue;
                            try resolved.append(self.allocator, .{ .formal = formal, .actual = actual });
                        }
                        try actions.ensureUnusedCapacity(self.allocator, 2);
                        actions.appendAssumeCapacity(.{ .restore = .{ .bindings_len = walk.bindings.items.len, .env = walk.env } });
                        actions.appendAssumeCapacity(.{ .visit = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep });
                        try walk.bindings.appendSlice(self.allocator, resolved.items);
                        walk.env = try self.internDerivedEnv(walk.bindings.items);
                    },
                }
            },
            .record, .tuple => {
                var index = rep.children.len;
                while (index > 0) {
                    index -= 1;
                    const child = self.plan.children.items[rep.children.start + index];
                    switch (child.role) {
                        .record_field, .tuple_elem => try actions.append(self.allocator, .{ .visit = child.rep }),
                        .record_ext,
                        .alias_backing,
                        .alias_arg,
                        .nominal_backing,
                        .nominal_arg,
                        .nominal_padding_field,
                        .function_arg,
                        .function_ret,
                        .tag_payload,
                        .tag_ext,
                        .list_elem,
                        .box_payload,
                        => {},
                    }
                }
            },
            .tag_union => {
                var variant_index = rep.tag_variants.len;
                while (variant_index > 0) {
                    variant_index -= 1;
                    const payloads = self.plan.tag_variants.items[rep.tag_variants.start + variant_index].payloads;
                    var payload_index = payloads.len;
                    while (payload_index > 0) {
                        payload_index -= 1;
                        try actions.append(self.allocator, .{ .visit = self.plan.children.items[payloads.start + payload_index].rep });
                    }
                }
            },
            .in_progress,
            .primitive,
            .bool_tag_union,
            .erased_callable,
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            .empty_record,
            .empty_tag_union,
            => {},
        }
    }

    fn derivedMethodText(method: DerivedMethod) []const u8 {
        return switch (method) {
            .equality => "is_eq",
            .hash => "to_hash",
        };
    }

    /// The component type's own method, when it declares one. A derived
    /// marker resolves structurally and expands instead.
    fn derivedMethodTarget(self: *Builder, rep_id: TypeRepId, method: DerivedMethod) ?MethodLookupResult {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const view = self.moduleForId(rep.source_type.module);
        const owner = methodOwnerForModuleType(view, rep.source_type.ty) orelse return null;
        const found = self.lookupMethodTargetByText(view, owner, derivedMethodText(method)) orelse return null;
        return switch (found) {
            .rejected => found,
            .target => |lookup| switch (lookup.target.kind) {
                .procedure, .local_proc => found,
                .structural => null,
            },
        };
    }

    /// The scheme requirement a type-variable component's comparison
    /// discharges against: checking gave the enclosing scheme this method.
    fn derivedSchemeRequirement(self: *Builder, rep_id: TypeRepId, method: DerivedMethod) ?DictionaryRequirementId {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const requirements = self.plan.dictionarySlice(rep.dictionaries);
        for (requirements, 0..) |requirement, index| {
            const view = self.moduleForId(requirement.source_type.module);
            if (!std.mem.eql(u8, view.canonical_names.?.methodNameText(requirement.fn_name), derivedMethodText(method))) continue;
            return @enumFromInt(rep.dictionaries.start + @as(u32, @intCast(index)));
        }
        return null;
    }

    fn recordDerivedDecision(
        self: *Builder,
        walk: *const DerivedWalk,
        rep_id: TypeRepId,
        decision: DerivedComponentDecision,
    ) Allocator.Error!void {
        const root = walk.root;
        const key = DerivedComponentKey{ .frame = root.frame, .method = root.method, .rep = rep_id, .env = walk.env };
        const entry = try self.plan.derived_component_decisions.getOrPut(key);
        if (entry.found_existing) {
            if (!std.meta.eql(entry.value_ptr.*, decision)) {
                boxyPlanInvariant("derived component received two different decisions");
            }
            return;
        }
        entry.value_ptr.* = decision;
    }

    fn planDerivedComponentCall(
        self: *Builder,
        walk: *const DerivedWalk,
        rep_id: TypeRepId,
        lookup: MethodTargetLookup,
    ) Allocator.Error!void {
        const root = walk.root;
        const key = DerivedComponentKey{ .frame = root.frame, .method = root.method, .rep = rep_id, .env = walk.env };
        if (self.plan.derived_component_decisions.get(key)) |existing| {
            return try self.recordDerivedDecision(walk, rep_id, existing);
        }
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const source = self.workerSourceForMethodTarget(lookup, rep.source_type, null);
        const fn_type = CheckedTypeIdentity{ .module = lookup.view.key, .ty = lookup.target.callable_ty };
        _ = try self.analyzeType(lookup.view, lookup.target.callable_ty);
        const worker = try self.ensureWorker(source, fn_type, null);
        const index: u32 = @intCast(self.plan.derived_component_calls.items.len);
        try self.plan.derived_component_calls.append(self.allocator, .{
            .frame = root.frame,
            .env = walk.env,
            .worker = worker,
            .arg_types = .{
                rep.source_type,
                switch (root.method) {
                    .equality => rep.source_type,
                    .hash => root.second_type,
                },
            },
            .ret_type = root.ret_type,
        });
        try self.recordDerivedDecision(walk, rep_id, .{ .call = index });
    }

    fn materializeDerivedComponentCallHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.derived_component_calls.items.len) : (index += 1) {
            const call = self.plan.derived_component_calls.items[index];
            const hidden_dict_args = try self.materializeWorkerCallHiddenDictionaryArgsWithEvidence(call.worker, call.frame, &call.arg_types, call.ret_type, null, null, null, call.env);
            self.plan.derived_component_calls.items[index].hidden_dict_args = hidden_dict_args;
            const context = try self.contextualizeDirectLocalProcCall(call.worker, call.frame, hidden_dict_args);
            self.plan.derived_component_calls.items[index].worker = context.worker;
            self.plan.derived_component_calls.items[index].context_args = context.args;
        }
    }

    fn materializeDerivedComponentCallHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.derived_component_calls.items.len) : (index += 1) {
            const call = self.plan.derived_component_calls.items[index];
            self.plan.derived_component_calls.items[index].hidden_desc_args =
                try self.materializeWorkerCallHiddenDescriptorArgs(call.worker, &call.arg_types, &call.arg_types, call.ret_type, call.hidden_dict_args);
        }
    }

    fn materializeInspectMethodPlans(self: *Builder) Allocator.Error!void {
        const direct_count = self.plan.direct_calls.items.len;
        var direct_index: usize = 0;
        while (direct_index < direct_count) : (direct_index += 1) {
            const direct = self.plan.direct_calls.items[direct_index];
            if (!self.workerIsStrInspectIntrinsic(direct.worker)) continue;
            const substitutions = self.plan.callTypeSubstitutionSlice(direct.arg_substitutions);
            if (substitutions.len != 1) {
                boxyPlanInvariant("Str.inspect direct call plan had unexpected substitution arity");
            }
            try self.materializeInspectMethodsForRep(substitutions[0].operand_rep);
        }

        const nested_callable_count = self.plan.nested_callable_uses.items.len;
        var nested_callable_index: usize = 0;
        while (nested_callable_index < nested_callable_count) : (nested_callable_index += 1) {
            const use = self.plan.nested_callable_uses.items[nested_callable_index];
            if (!self.workerIsStrInspectIntrinsic(use.worker)) continue;
            const callable_rep = self.plan.repForSourceType(use.callable_ty) orelse
                boxyPlanInvariant("Str.inspect function-value use type was not analyzed");
            const function = (self.repQuery().functionChildren(callable_rep)) orelse
                boxyPlanInvariant("Str.inspect function-value use was not callable");
            if (function.arg_count != 1) {
                boxyPlanInvariant("Str.inspect function-value use had unexpected arity");
            }
            const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
            const arg_rep = children[function.args_start].rep;
            try self.materializeInspectMethodsForRep(arg_rep);
        }

        if (self.inspect_demand_count == 0) return;
        // Reuse the call-site type relations already recorded by planning.
        // Demands cross generic boundaries before descriptor construction, so
        // a descriptor carries the worker required by any of its consumers.
        var pairs = std.AutoHashMap(u64, void).init(self.allocator);
        defer pairs.deinit();
        const substitution_count = self.plan.call_type_substitutions.items.len;
        for (0..substitution_count) |index| {
            const substitution = self.plan.call_type_substitutions.items[index];
            try self.propagateInspectDemand(substitution.worker_rep, substitution.call_rep, &pairs);
            try self.propagateInspectDemand(substitution.call_rep, substitution.operand_rep, &pairs);
        }
        const call_count = self.plan.direct_calls.items.len;
        for (0..call_count) |index| {
            const call = self.plan.direct_calls.items[index];
            const ret = call.ret_substitution orelse continue;
            try self.propagateInspectDemand(ret.worker_rep, ret.call_rep, &pairs);
        }
        inline for (.{ "callable_uses", "nested_callable_uses" }) |field| {
            const count = @field(self.plan, field).items.len;
            for (0..count) |index| {
                const use = @field(self.plan, field).items[index];
                const call_rep = self.plan.repForSourceType(use.callable_ty) orelse
                    boxyPlanInvariant("inspect callable use had no planned type");
                try self.propagateInspectDemand(self.plan.workers.items[@intFromEnum(use.worker)].rep, call_rep, &pairs);
            }
        }
    }

    /// Propagate inspection demand between each worker/call representation
    /// pair `(root_worker, root_call)` reaches, in pre-order.
    fn propagateInspectDemand(
        self: *Builder,
        root_worker: TypeRepId,
        root_call: TypeRepId,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList([2]TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ root_worker, root_call });
        while (pending.pop()) |pair| {
            const worker_rep_id = pair[0];
            const call_rep_id = pair[1];
            if (worker_rep_id == call_rep_id) continue;
            const key = (@as(u64, @intFromEnum(worker_rep_id)) << 32) | @intFromEnum(call_rep_id);
            if ((try seen.getOrPut(key)).found_existing) continue;
            const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
            const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
            if (worker_rep.inspect_demanded) try self.materializeInspectMethodsForRep(call_rep_id);
            if (call_rep.inspect_demanded) try self.materializeInspectMethodsForRep(worker_rep_id);

            // Aliases and transparent nominal backings are explicit checked edges.
            if (self.repQuery().structuralWrapperBackingRep(worker_rep_id)) |backing| {
                const call_side = self.repQuery().structuralWrapperBackingRep(call_rep_id) orelse call_rep_id;
                try pending.append(self.allocator, .{ backing, call_side });
                continue;
            }
            if (self.repQuery().structuralWrapperBackingRep(call_rep_id)) |backing| {
                try pending.append(self.allocator, .{ worker_rep_id, backing });
                continue;
            }
            const call_children = self.plan.childSlice(call_rep.children);
            var index = worker_rep.children.len;
            while (index > 0) {
                index -= 1;
                const child = self.plan.children.items[@as(usize, worker_rep.children.start) + index];
                if (self.namedQuery().rowInstantiationTarget(worker_rep_id, call_rep_id, child)) |row| {
                    try pending.append(self.allocator, .{ child.rep, row });
                } else if (self.namedQuery().findMatchingChildByRole(call_children, child)) |call_child| {
                    try pending.append(self.allocator, .{ child.rep, call_child.rep });
                }
            }
        }
    }

    fn workerIsStrInspectIntrinsic(self: *Builder, worker_id: WorkerPlanId) bool {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        if (worker.source == .generated_codec or
            worker.source == .generated_field_iterator or
            worker.source == .generated_interpolation_step)
        {
            return false;
        }
        return switch (self.rootWorkerBody(worker.source)) {
            .intrinsic_wrapper => |intrinsic| intrinsic.wrapper.intrinsic == .str_inspect,
            .checked_expr, .hosted_proc, .unimplemented => false,
        };
    }

    fn materializeDirectCallHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        var direct_index: usize = 0;
        while (direct_index < self.plan.direct_calls.items.len) : (direct_index += 1) {
            const direct = self.plan.direct_calls.items[direct_index];
            const substitutions = self.plan.callTypeSubstitutionSlice(direct.arg_substitutions);
            if (substitutions.len != direct.operands.len) {
                boxyPlanInvariant("boxy direct call descriptor substitution arity disagreed with call args");
            }
            const operand_types = try self.callSubstitutionTypes(direct.arg_substitutions, .operand);
            defer self.allocator.free(operand_types);
            const call_types = try self.callSubstitutionTypes(direct.arg_substitutions, .call);
            defer self.allocator.free(call_types);
            const evidence = self.checkedEvidenceForDirectCall(direct);
            const hidden_desc_args = try self.materializeWorkerCallHiddenDescriptorArgsWithSubstitution(
                direct.worker,
                call_types,
                operand_types,
                direct.ret_substitution.?.call_type,
                evidence.view,
                evidence.entries,
                self.directCallSchemeSubstitution(direct),
                direct.hidden_dict_args,
            );
            self.plan.direct_calls.items[direct_index].hidden_desc_args = hidden_desc_args;
        }
    }

    fn materializeCallableUseHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        for (self.plan.callable_uses.items) |*use| {
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            if (worker.hidden_descs.len == 0) continue;
            const evidence = self.checkedEvidenceForProcedureUse(use.use);
            if (evidence.entries == null and self.workerHasPathlessEvidence(worker)) continue;
            use.hidden_desc_args = try self.materializeCallableUseHiddenDescriptorArgsAtType(
                use.worker,
                use.callable_ty,
                evidence.view,
                evidence.entries,
                self.useSchemeSubstitution(use.worker, use.use),
                if (use.stored_fn != null) try self.storedUseSchemeRepSubstitutions(worker.rep, self.plan.repForSourceType(use.callable_ty) orelse
                    boxyPlanInvariant("boxy stored callable use type was not analyzed")) else null,
                use.hidden_dict_args,
            );
        }
        for (self.plan.nested_callable_uses.items) |*use| {
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            if (worker.hidden_descs.len == 0) continue;
            const evidence = self.checkedEvidenceForProcedureUse(use.use);
            if (evidence.entries == null and self.workerHasPathlessEvidence(worker)) continue;
            use.hidden_desc_args = try self.materializeCallableUseHiddenDescriptorArgsAtType(
                use.worker,
                use.callable_ty,
                evidence.view,
                evidence.entries,
                self.useSchemeSubstitution(use.worker, use.use),
                null,
                use.hidden_dict_args,
            );
        }

        for (self.plan.static_fns.items) |*static_fn| {
            const worker = self.plan.workers.items[@intFromEnum(static_fn.worker)];
            if (worker.hidden_descs.len == 0) continue;
            // The stored value is described at its own stored type.
            const call_rep = static_fn.rep;
            const function = (self.repQuery().functionChildren(call_rep)) orelse
                boxyPlanInvariant("stored function value representation was not callable");
            const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
            const arg_reps = try self.allocator.alloc(TypeRepId, function.arg_count);
            defer self.allocator.free(arg_reps);
            const arg_types = try self.allocator.alloc(CheckedTypeIdentity, function.arg_count);
            defer self.allocator.free(arg_types);
            for (arg_reps, arg_types, children[function.args_start..][0..function.arg_count]) |*arg_rep, *arg_type, child| {
                arg_rep.* = child.rep;
                arg_type.* = child.source_type;
            }
            static_fn.hidden_desc_args = try self.materializeWorkerCallHiddenDescriptorArgsForRepsWithEvidence(
                static_fn.worker,
                arg_reps,
                arg_reps,
                function.ret,
                arg_types,
                self.plan.representations.items[@intFromEnum(function.ret)].source_type,
                null,
                null,
                null,
                try self.storedUseSchemeRepSubstitutions(worker.rep, call_rep),
                .{},
            );
        }

        // A context callable instantiates its worker at the evidence edge
        // that selected its dictionary method.
        for (self.plan.context_constructs.items) |*construct| {
            const worker = self.plan.workers.items[@intFromEnum(construct.worker)];
            if (worker.hidden_descs.len == 0) continue;
            const edge = construct.evidence_edge;
            const edge_view = if (edge) |known| self.moduleForId(known.module) else self.moduleForId(construct.callable_type.module);
            const nested: ?[]const static_dispatch.CheckedEvidence = if (edge) |known| blk: {
                const node = edge_view.static_dispatch_plans.evidenceNode(known.node);
                break :blk switch (node.nested) {
                    .resolved => edge_view.static_dispatch_plans.nestedEvidence(node),
                    .from_callable => null,
                };
            } else null;
            construct.hidden_desc_args = try self.materializeCallableUseHiddenDescriptorArgsAtType(
                construct.worker,
                construct.callable_type,
                edge_view,
                nested,
                if (edge) |known| self.evidenceEdgeSchemeSubstitution(construct.worker, known) else null,
                null,
                construct.hidden_dict_args,
            );
        }

        for (self.plan.callable_uses.items) |*use| {
            try self.fillCallableUseHiddenDescriptorArgs(use.worker, use.caller, &use.hidden_desc_args);
        }
        for (self.plan.nested_callable_uses.items) |*use| {
            try self.fillCallableUseHiddenDescriptorArgs(use.worker, use.caller, &use.hidden_desc_args);
        }
        for (self.plan.context_constructs.items) |*construct| {
            try self.fillCallableUseHiddenDescriptorArgs(construct.worker, construct.caller, &construct.hidden_desc_args);
        }
    }

    /// An inspect slot invokes its worker as `to_inspect(value)` with the
    /// inspected representation as the argument, so the slot's hidden
    /// descriptors are that call's descriptor arguments.
    fn materializeInspectMethodHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.inspect_methods.items.len) : (index += 1) {
            const method = self.plan.inspect_methods.items[index];
            const worker = self.plan.workers.items[@intFromEnum(method.worker)];
            if (worker.hidden_descs.len == 0) continue;
            const function = (self.repQuery().functionChildren(worker.rep)) orelse
                boxyPlanInvariant("boxy inspect worker was not callable");
            if (function.arg_count != 1) boxyPlanInvariant("boxy inspect worker did not take exactly one argument");
            const source_type = self.plan.representations.items[@intFromEnum(method.source_rep)].source_type;
            const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
            const evidence_view = self.moduleForId(method.evidence.module);
            var bindings = std.ArrayList(SiteRepBinding).empty;
            defer bindings.deinit(self.allocator);
            const hidden_desc_args = try self.materializeWorkerCallHiddenDescriptorArgsForRepsWithEvidence(
                method.worker,
                &.{method.source_rep},
                &.{method.source_rep},
                function.ret,
                &.{source_type},
                ret_type,
                evidence_view,
                inspectUseNestedEvidence(evidence_view, method.evidence.node),
                try self.inspectUseSchemeSubstitution(method, &bindings),
                null,
                method.hidden_dict_args,
            );
            self.plan.inspect_methods.items[index].hidden_desc_args = hidden_desc_args;
        }
    }

    fn materializeCallableUseHiddenDescriptorArgsAtType(
        self: *Builder,
        worker: WorkerPlanId,
        callable_type: CheckedTypeIdentity,
        view: ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: ?SchemeCallSubstitution,
        stored_substitution: ?Span,
        dictionary_args: Span,
    ) Allocator.Error!Span {
        const callable_rep = self.plan.repForSourceType(callable_type) orelse
            boxyPlanInvariant("boxy callable use type was not analyzed for descriptor captures");
        const function = (self.repQuery().functionChildren(callable_rep)) orelse
            boxyPlanInvariant("boxy callable use descriptor capture type was not callable");
        const arg_types = try self.allocator.alloc(CheckedTypeIdentity, function.arg_count);
        defer self.allocator.free(arg_types);
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
        for (arg_types, children[function.args_start..][0..function.arg_count]) |*arg_type, child| {
            arg_type.* = self.plan.representations.items[@intFromEnum(child.rep)].source_type;
        }
        const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
        return try self.materializeWorkerCallHiddenDescriptorArgsWithStoredSubstitution(
            worker,
            arg_types,
            arg_types,
            ret_type,
            view,
            evidence,
            scheme_substitution,
            stored_substitution,
            dictionary_args,
        );
    }

    /// Whether one of the worker's hidden descriptors can only be sourced from a
    /// use's checked evidence vector.
    fn workerHasPathlessEvidence(self: *Builder, worker: WorkerPlan) bool {
        const evidence = self.workerEvidenceParams(worker.source) orelse return false;
        for (self.plan.workerEvidenceDescriptorParamSlice(worker.evidence_descs)) |mapping| {
            const param = evidence.params[mapping.evidence_index];
            if (param.path.len == 0) return true;
        }
        return false;
    }

    fn fillCallableUseHiddenDescriptorArgs(
        self: *Builder,
        worker_id: WorkerPlanId,
        caller: WorkerPlanId,
        target: *Span,
    ) Allocator.Error!void {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        if (worker.hidden_descs.len == 0 or target.len != 0) return;

        var source: ?Span = null;
        var ambiguous = false;
        for (self.plan.callable_uses.items) |candidate| {
            if (candidate.worker != worker_id or candidate.caller != caller or
                candidate.hidden_desc_args.len != worker.hidden_descs.len) continue;
            self.mergeHiddenDescriptorArgSource(&source, &ambiguous, candidate.hidden_desc_args);
        }
        for (self.plan.nested_callable_uses.items) |candidate| {
            if (candidate.worker != worker_id or candidate.caller != caller or
                candidate.hidden_desc_args.len != worker.hidden_descs.len) continue;
            self.mergeHiddenDescriptorArgSource(&source, &ambiguous, candidate.hidden_desc_args);
        }
        for (self.plan.direct_calls.items) |candidate| {
            if (candidate.worker != worker_id or candidate.caller != caller or
                candidate.hidden_desc_args.len != worker.hidden_descs.len) continue;
            self.mergeHiddenDescriptorArgSource(&source, &ambiguous, candidate.hidden_desc_args);
        }
        if (!ambiguous) {
            if (source) |planned| {
                target.* = planned;
                return;
            }
        }
        boxyPlanInvariant("callable value had no unambiguous checked descriptor capture source");
    }

    fn mergeHiddenDescriptorArgSource(
        self: *Builder,
        source: *?Span,
        ambiguous: *bool,
        candidate: Span,
    ) void {
        if (ambiguous.*) return;
        if (source.*) |existing| {
            if (!std.meta.eql(
                self.plan.directCallHiddenDescriptorArgSlice(existing),
                self.plan.directCallHiddenDescriptorArgSlice(candidate),
            )) {
                source.* = null;
                ambiguous.* = true;
            }
        } else {
            source.* = candidate;
        }
    }

    /// A root has no caller, so a variable its type still holds is bound by
    /// nothing and is at its checked default, as a root's monomorphic request
    /// makes it; plan that default for each one.
    fn materializeRootSharedVariableDefaults(self: *Builder) Allocator.Error!void {
        var visited = std.AutoHashMapUnmanaged(TypeRepId, void).empty;
        defer visited.deinit(self.allocator);
        var pending = std.ArrayList(TypeRepId).empty;
        defer pending.deinit(self.allocator);
        for (self.plan.roots.items) |root| try pending.append(self.allocator, root.source_rep);
        while (pending.pop()) |rep_id| {
            if ((try visited.getOrPut(self.allocator, rep_id)).found_existing) continue;
            const rep = self.plan.representations.items[@intFromEnum(rep_id)];
            if (rep.kind == .dynamic and rep.sealed_default == null and
                rep.children.len == 0 and rep.tag_variants.len == 0)
            {
                _ = try self.sharedVariableClosedRep(rep_id, .no_caller);
                continue;
            }
            for (0..rep.children.len) |index| {
                try pending.append(self.allocator, self.plan.children.items[rep.children.start + index].rep);
            }
        }
    }

    fn materializeRootHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        for (self.plan.roots.items, 0..) |root, root_index| {
            const worker = self.plan.workers.items[@intFromEnum(root.worker)];
            if (worker.hidden_descs.len == 0) {
                self.plan.roots.items[root_index].hidden_desc_args = .{};
                continue;
            }

            const function = (self.repQuery().functionChildren(root.source_rep)) orelse
                boxyPlanInvariant("boxy root with hidden descriptors had no callable source type");
            const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
            const arg_types = try self.allocator.alloc(CheckedTypeIdentity, function.arg_count);
            defer self.allocator.free(arg_types);
            for (arg_types, children[function.args_start..][0..function.arg_count]) |*arg_type, child| {
                arg_type.* = child.source_type;
            }
            const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
            const hidden_desc_args = try self.materializeWorkerCallHiddenDescriptorArgs(root.worker, arg_types, arg_types, ret_type, root.hidden_dict_args);
            self.plan.roots.items[root_index].hidden_desc_args = hidden_desc_args;
            // A root instantiates its worker's scheme at the root's own
            // type, so a quantified variable no host type determines is
            // instantiated by nothing: it takes its checked default, as an
            // unquantified variable does.
            for (self.plan.direct_call_hidden_desc_args.items[hidden_desc_args.start..][0..hidden_desc_args.len]) |*arg| {
                arg.rep = try self.rootInstantiationRep(arg.rep);
            }
        }
    }

    fn rootInstantiationRep(self: *Builder, rep_id: TypeRepId) Allocator.Error!TypeRepId {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.kind != .dynamic or rep.children.len != 0) return rep_id;
        if (rep.sealed_default) |sealed| return sealed;
        const source_type = rep.source_type;
        const variable = switch (self.moduleForId(source_type.module).checked_types.payload(source_type.ty)) {
            .flex, .rigid => |variable| variable,
            .pending, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => return rep_id,
        };
        if (variable.constraints.len != 0 or !self.quantified_variables.contains(source_type)) return rep_id;
        const default_rep: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        try self.plan.representations.append(self.allocator, .{
            .source_type = source_type,
            .kind = variableDefaultKind(variable),
        });
        return default_rep;
    }

    fn materializeConstEvalCallHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.const_eval_calls.items.len) : (index += 1) {
            const call = self.plan.const_eval_calls.items[index];
            self.plan.const_eval_calls.items[index].hidden_desc_args =
                try self.materializeWorkerCallHiddenDescriptorArgs(call.worker, &.{}, &.{}, call.ret_substitution.call_type, call.hidden_dict_args);
        }
    }

    fn materializeGeneratedCodecCallHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.generated_codec_calls.items.len) : (index += 1) {
            const call = self.plan.generated_codec_calls.items[index];
            const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
            const call_view = self.moduleForId(call.method_module);
            const checked_evidence = call_view.static_dispatch_plans.evidence_refs[call.checked_evidence.start .. call.checked_evidence.start + call.checked_evidence.len];
            self.plan.generated_codec_calls.items[index].hidden_desc_args =
                try self.materializeWorkerCallHiddenDescriptorArgsWithSubstitution(
                    call.worker,
                    arg_types,
                    arg_types,
                    call.ret_type,
                    call_view,
                    checked_evidence,
                    if (call.evidence_edge) |edge| self.evidenceEdgeSchemeSubstitution(call.worker, edge) else null,
                    call.hidden_dict_args,
                );
        }
    }

    fn materializeConstEvalCallHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.const_eval_calls.items.len) : (index += 1) {
            const call = self.plan.const_eval_calls.items[index];
            self.plan.const_eval_calls.items[index].hidden_dict_args =
                try self.materializeWorkerCallHiddenDictionaryArgs(call.worker, null, &.{}, call.ret_type);
        }
    }

    fn materializeRootHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        for (self.plan.roots.items, 0..) |root, root_index| {
            const worker = self.plan.workers.items[@intFromEnum(root.worker)];
            if (worker.hidden_dicts.len == 0) {
                self.plan.roots.items[root_index].hidden_dict_args = .{};
                continue;
            }

            const function = (self.repQuery().functionChildren(root.source_rep)) orelse
                boxyPlanInvariant("boxy root with hidden dictionaries had no callable source type");
            const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
            const arg_types = try self.allocator.alloc(CheckedTypeIdentity, function.arg_count);
            defer self.allocator.free(arg_types);
            for (arg_types, children[function.args_start..][0..function.arg_count]) |*arg_type, child| {
                arg_type.* = child.source_type;
            }
            const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
            self.plan.roots.items[root_index].hidden_dict_args =
                try self.materializeWorkerCallHiddenDictionaryArgs(root.worker, null, arg_types, ret_type);
        }
    }

    fn materializeIteratorCallHiddenDescriptorArgs(self: *Builder) Allocator.Error!void {
        for (self.plan.iterator_calls.items, 0..) |call, call_index| {
            const operand_types = try self.callSubstitutionTypes(call.arg_substitutions, .operand);
            defer self.allocator.free(operand_types);
            const call_types = try self.callSubstitutionTypes(call.arg_substitutions, .call);
            defer self.allocator.free(call_types);
            self.plan.iterator_calls.items[call_index].hidden_desc_args =
                try self.materializeWorkerCallHiddenDescriptorArgs(call.worker, call_types, operand_types, call.ret_substitution.call_type, call.hidden_dict_args);
        }
    }

    fn materializeDirectCallHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        const call_count = self.plan.direct_calls.items.len;
        var direct_index: usize = 0;
        while (direct_index < call_count) : (direct_index += 1) {
            const direct = self.plan.direct_calls.items[direct_index];
            const call_evidence = self.checkedEvidenceForDirectCall(direct);
            const call_view = call_evidence.view;
            const checked_evidence = call_evidence.entries;

            const substitutions = self.plan.callTypeSubstitutionSlice(direct.arg_substitutions);
            if (substitutions.len != direct.operands.len) {
                boxyPlanInvariant("boxy direct call dictionary substitution arity disagreed with call args");
            }
            const arg_types = try self.callSubstitutionTypes(direct.arg_substitutions, .operand);
            defer self.allocator.free(arg_types);
            // A dispatch deriving its evidence from its callable relates the
            // worker's variables to the call's types exactly as a stored
            // function's use does, so its dictionaries' adapters read the
            // same pairs.
            var machine = DictionaryArgsMachine{};
            defer machine.deinit(self.allocator);
            const hidden_dict_args = if (try self.beginDictionaryCallArgs(&machine, .{
                .worker_id = direct.worker,
                .caller_id = direct.caller,
                .arg_types = arg_types,
                .ret_type = direct.ret_substitution.?.call_type,
                .evidence_view = call_view,
                .evidence = checked_evidence,
                .scheme_substitution = self.directCallSchemeSubstitution(direct),
                .relation = try self.directCallCallableDerivedSubstitution(direct),
                .env = 0,
            })) |span| span else blk: {
                try self.runDictionaryArgs(&machine);
                break :blk machine.span_result;
            };
            self.plan.direct_calls.items[direct_index].hidden_dict_args = hidden_dict_args;
            const context = try self.contextualizeCall(direct.worker, direct.caller, hidden_dict_args);
            self.plan.direct_calls.items[direct_index].worker = context.worker;
            self.plan.direct_calls.items[direct_index].context_args = context.args;
        }
    }

    // Context specialization //
    //
    // A worker that needs values of a function body's frame (a local
    // procedure with runtime captures, or a worker specialized as described
    // here) cannot implement a runtime dictionary's method: no dictionary
    // call has that frame. The frame whose checked evidence selects such a
    // method constructs it as an erased callable instead, and every worker
    // that receives the dictionary is specialized to receive the method as
    // a context input: its dispatches on that requirement call the input,
    // and its own calls forward the input to the workers they pass the
    // dictionary on to. A structural comparison or hash of a closed type
    // reaching such procedures is a context input too, with no value: the
    // receiving worker performs the derivation itself and receives the
    // runtime captures of the procedures it reaches.

    const ContextualizedCall = struct {
        worker: WorkerPlanId,
        args: Span = .{},
    };

    const ContextInputs = struct {
        inputs: std.ArrayList(ContextInput) = .empty,
        args: std.ArrayList(ContextArg) = .empty,

        fn deinit(self: *ContextInputs, allocator: Allocator) void {
            self.inputs.deinit(allocator);
            self.args.deinit(allocator);
        }

        fn contains(self: *const ContextInputs, key: ContextInput.Key) bool {
            for (self.inputs.items) |input| {
                if (contextKeyEql(input.key, key)) return true;
            }
            return false;
        }
    };

    /// The worker a call with these hidden dictionary arguments reaches: the
    /// callee itself, or its specialization for the context inputs the
    /// arguments carry, with the `ContextArg`s supplying them.
    fn contextualizeCall(
        self: *Builder,
        callee: WorkerPlanId,
        caller: ?WorkerPlanId,
        hidden_dict_args: Span,
    ) Allocator.Error!ContextualizedCall {
        const base = self.plan.workers.items[@intFromEnum(callee)].context_base orelse callee;
        var collected = ContextInputs{};
        defer collected.deinit(self.allocator);
        try self.collectContextInputs(caller, hidden_dict_args, &collected);
        if (collected.inputs.items.len == 0) return .{ .worker = base };
        const worker = try self.ensureContextWorker(base, collected.inputs.items);
        const start: u32 = @intCast(self.plan.context_args.items.len);
        try self.plan.context_args.appendSlice(self.allocator, collected.args.items);
        return .{ .worker = worker, .args = .{ .start = start, .len = @intCast(collected.args.items.len) } };
    }

    /// Like `contextualizeCall`, for a direct call that may reach a local
    /// procedure with runtime captures outside the closure carrying them: the
    /// call reaches the procedure's specialization receiving its own
    /// captures as context inputs, from the calling frame.
    fn contextualizeDirectLocalProcCall(
        self: *Builder,
        callee: WorkerPlanId,
        caller: ?WorkerPlanId,
        hidden_dict_args: Span,
    ) Allocator.Error!ContextualizedCall {
        const base = self.plan.workers.items[@intFromEnum(callee)].context_base orelse callee;
        if (!self.workerIsCapturingLocalProc(base)) return try self.contextualizeCall(callee, caller, hidden_dict_args);
        var collected = ContextInputs{};
        defer collected.deinit(self.allocator);
        try self.collectContextInputs(caller, hidden_dict_args, &collected);
        try self.collectLocalProcInput(caller, self.plan.workers.items[@intFromEnum(base)].source.nested_expr, &collected);
        const worker = try self.ensureContextWorker(base, collected.inputs.items);
        const start: u32 = @intCast(self.plan.context_args.items.len);
        try self.plan.context_args.appendSlice(self.allocator, collected.args.items);
        return .{ .worker = worker, .args = .{ .start = start, .len = @intCast(collected.args.items.len) } };
    }

    /// The context inputs a callee receiving `hidden_dict_args` from `caller`
    /// needs, with the arguments supplying them.
    fn collectContextInputs(
        self: *Builder,
        caller: ?WorkerPlanId,
        hidden_dict_args: Span,
        collected: *ContextInputs,
    ) Allocator.Error!void {
        var arg_index: usize = 0;
        while (arg_index < hidden_dict_args.len) : (arg_index += 1) {
            const arg = self.plan.direct_call_hidden_dict_args.items[hidden_dict_args.start + arg_index];
            switch (arg.source) {
                .static_rep => |source_rep| {
                    if (arg.method_evidence.len == 0) continue;
                    if (arg.method_evidence.len != arg.worker_dictionaries.len) {
                        boxyPlanInvariant("static dictionary checked evidence did not cover every method requirement");
                    }
                    var method_index: u32 = 0;
                    while (method_index < arg.method_evidence.len) : (method_index += 1) {
                        const method = self.plan.dictionary_method_evidence.items[arg.method_evidence.start + method_index];
                        const requirement: DictionaryRequirementId = @enumFromInt(arg.worker_dictionaries.start + method_index);
                        if (method.context) |context| {
                            const worker = switch (method.resolution) {
                                .worker => |worker| worker,
                                .builtin_numeral, .structural, .constraint, .checked_error, .unreachable_value => boxyPlanInvariant("context dictionary method had no worker"),
                            };
                            const frame = caller orelse
                                boxyPlanInvariant("a dictionary method needing a frame's context was built by no frame");
                            const supplied: ContextArg = .{ .construct = try self.ensureContextConstruct(.{
                                .caller = frame,
                                .worker = worker,
                                .callable_type = method.callable_type,
                                .evidence_edge = method.evidence_edge,
                                .hidden_dict_args = method.nested_dict_args,
                                .context_args = context.context_args,
                            }) };
                            try collected.inputs.append(self.allocator, .{
                                .key = .{ .requirement = requirement },
                                .callable_type = method.callable_type,
                                .rep = try self.analyzeType(self.moduleForId(method.callable_type.module), method.callable_type.ty),
                            });
                            try collected.args.append(self.allocator, supplied);
                            continue;
                        }
                        const derived: DerivedMethod = switch (method.resolution) {
                            .structural => |kind| switch (kind) {
                                .equality => .equality,
                                .hash => .hash,
                                .parser, .encoder, .map, .map_effectful => continue,
                            },
                            .worker, .builtin_numeral, .constraint, .checked_error, .unreachable_value => continue,
                        };
                        const procs = self.plan.frame_context_procs.get(.{ .rep = source_rep, .method = derived }) orelse continue;
                        try collected.inputs.append(self.allocator, .{ .key = .{ .structural = .{
                            .requirement = requirement,
                            .method = derived,
                            .rep = source_rep,
                        } } });
                        try collected.args.append(self.allocator, .structural);
                        for (self.plan.frame_context_proc_ids.items[procs.start..][0..procs.len]) |proc| {
                            try self.collectLocalProcInput(caller, self.plan.workers.items[@intFromEnum(proc)].source.nested_expr, collected);
                        }
                    }
                },
                .bound_dictionaries => |bound| {
                    const frame = caller orelse continue;
                    const frame_inputs = self.plan.contextInputSlice(self.plan.workers.items[@intFromEnum(frame)].context);
                    if (frame_inputs.len == 0) continue;
                    var forwards_structural = false;
                    var offset: u32 = 0;
                    while (offset < arg.worker_dictionaries.len) : (offset += 1) {
                        const requirement: DictionaryRequirementId = @enumFromInt(arg.worker_dictionaries.start + offset);
                        const slot = self.plan.dictionaries.items[@intFromEnum(requirement)].slot;
                        for (frame_inputs, 0..) |frame_input, frame_index| {
                            const frame_requirement = switch (frame_input.key) {
                                .requirement => |frame_requirement| frame_requirement,
                                .structural => |structural| structural.requirement,
                                .capture => continue,
                            };
                            const raw = @intFromEnum(frame_requirement);
                            if (raw < bound.start or raw >= bound.start + bound.len) continue;
                            if (self.plan.dictionaries.items[raw].slot != slot) continue;
                            switch (frame_input.key) {
                                .requirement => {
                                    try collected.inputs.append(self.allocator, .{
                                        .key = .{ .requirement = requirement },
                                        .callable_type = frame_input.callable_type,
                                        .rep = frame_input.rep,
                                    });
                                    try collected.args.append(self.allocator, .{ .forward = @intCast(frame_index) });
                                },
                                .structural => |structural| {
                                    try collected.inputs.append(self.allocator, .{ .key = .{ .structural = .{
                                        .requirement = requirement,
                                        .method = structural.method,
                                        .rep = structural.rep,
                                    } } });
                                    try collected.args.append(self.allocator, .structural);
                                    forwards_structural = true;
                                },
                                .capture => unreachable,
                            }
                            break;
                        }
                    }
                    // A forwarded derivation reaches the procedures the frame
                    // received for its own.
                    if (forwards_structural) for (frame_inputs) |frame_input| switch (frame_input.key) {
                        .capture => |capture| try self.collectLocalProcInput(caller, capture.site, collected),
                        .requirement, .structural => {},
                    };
                },
                .literal => {},
            }
        }
    }

    /// Add a local procedure's runtime captures as inputs, forwarded from
    /// the caller's own inputs or read from the caller's frame.
    fn collectLocalProcInput(self: *Builder, caller: ?WorkerPlanId, site: CheckedExprIdentity, collected: *ContextInputs) Allocator.Error!void {
        if (collected.contains(.{ .capture = .{ .site = site, .index = 0 } })) return;
        const frame = caller orelse
            boxyPlanInvariant("a local procedure needing a frame's context was reached by no frame");
        const view = self.moduleForId(site.module);
        for (nestedCallableRuntimeCaptures(view, site.expr), 0..) |capture, capture_index| {
            const key = LocalProcCapture{ .site = site, .index = @intCast(capture_index) };
            const supplied: ContextArg = if (self.plan.workerContextInput(frame, .{ .capture = key })) |index|
                .{ .forward = index }
            else
                .{ .capture = key };
            const capture_type = typeRef(view, view.checked_bodies.pattern(capture.pattern).ty);
            try collected.inputs.append(self.allocator, .{
                .key = .{ .capture = key },
                .callable_type = capture_type,
                .rep = try self.analyzeType(view, capture_type.ty),
            });
            try collected.args.append(self.allocator, supplied);
        }
    }

    fn ensureContextConstruct(self: *Builder, construct: ContextConstruct) Allocator.Error!ContextConstructId {
        for (self.plan.context_constructs.items, 0..) |existing, index| {
            if (existing.caller == construct.caller and
                existing.worker == construct.worker and
                typeRefEql(existing.callable_type, construct.callable_type) and
                std.meta.eql(existing.evidence_edge, construct.evidence_edge))
            {
                self.plan.context_constructs.items[index].hidden_dict_args = construct.hidden_dict_args;
                self.plan.context_constructs.items[index].context_args = construct.context_args;
                return @enumFromInt(@as(u32, @intCast(index)));
            }
        }
        const id: ContextConstructId = @enumFromInt(@as(u32, @intCast(self.plan.context_constructs.items.len)));
        try self.plan.context_constructs.append(self.allocator, construct);
        return id;
    }

    fn contextInputsEql(self: *const Builder, span: Span, inputs: []const ContextInput) bool {
        const existing = self.plan.contextInputSlice(span);
        if (existing.len != inputs.len) return false;
        for (existing, inputs) |a, b| {
            if (!contextKeyEql(a.key, b.key)) return false;
            if (a.callable_type != null and !typeRefEql(a.callable_type.?, b.callable_type.?)) return false;
        }
        return true;
    }

    /// The specialization of `base` that receives `inputs`, planning its body
    /// under that specialization the first time.
    fn ensureContextWorker(self: *Builder, base: WorkerPlanId, inputs: []const ContextInput) Allocator.Error!WorkerPlanId {
        for (self.plan.workers.items) |worker| {
            if (worker.context_base == base and self.contextInputsEql(worker.context, inputs)) return worker.id;
        }
        const base_worker = self.plan.workers.items[@intFromEnum(base)];
        switch (base_worker.source) {
            .procedure_template, .procedure_binding, .procedure_use, .nested_expr => {},
            .generated_codec, .generated_field_iterator, .generated_interpolation_step => boxyPlanInvariant("a generated worker received a dictionary needing a frame's context"),
        }
        const start: u32 = @intCast(self.plan.context_inputs.items.len);
        try self.plan.context_inputs.appendSlice(self.allocator, inputs);
        const worker_id: WorkerPlanId = @enumFromInt(@as(u32, @intCast(self.plan.workers.items.len)));
        // The specialization plans the same body, so it starts from its
        // base's hidden inputs; later planning passes recompute both alike.
        var specialized = base_worker;
        specialized.id = worker_id;
        specialized.root_request = null;
        specialized.erased_captures = .{};
        specialized.context = .{ .start = start, .len = @intCast(inputs.len) };
        specialized.context_base = base;
        try self.plan.workers.append(self.allocator, specialized);
        // Each structural input is a derivation this worker performs.
        for (inputs) |input| switch (input.key) {
            .structural => |structural| {
                const requirement = self.plan.dictionaries.items[@intFromEnum(structural.requirement)];
                const function_rep = self.plan.repForSourceType(requirement.fn_ty) orelse
                    boxyPlanInvariant("structural context requirement callable type was not analyzed");
                const function = self.repQuery().functionChildren(function_rep) orelse
                    boxyPlanInvariant("structural context requirement was not a function");
                if (function.arg_count != 2) boxyPlanInvariant("structural context requirement did not take two arguments");
                const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
                try self.registerDerivedRoot(
                    worker_id,
                    structural.method,
                    structural.rep,
                    0,
                    children[function.args_start + 1].source_type,
                    self.plan.representations.items[@intFromEnum(function.ret)].source_type,
                );
            },
            .requirement, .capture => {},
        };
        const previous = self.active_worker;
        self.active_worker = worker_id;
        defer self.active_worker = previous;
        try self.runPlanActions(.{ .worker_body = self.rootWorkerBody(base_worker.source) });
        return worker_id;
    }

    /// Whether `worker` needs values of the frame calling it: a local
    /// procedure with runtime captures, or a context-specialized worker.
    fn workerNeedsFrameContext(self: *Builder, worker_id: WorkerPlanId) bool {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        if (worker.context.len != 0) return true;
        return self.workerIsCapturingLocalProc(worker_id);
    }

    fn workerIsCapturingLocalProc(self: *Builder, worker_id: WorkerPlanId) bool {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        if (worker.context_base != null) return false;
        return switch (worker.source) {
            .nested_expr => |expr_ref| !self.nestedCallableHasNoCaptures(expr_ref),
            .procedure_template, .procedure_binding, .procedure_use, .generated_codec, .generated_field_iterator, .generated_interpolation_step => false,
        };
    }

    /// Mark a dictionary method whose worker needs the building frame's
    /// context, specializing a worker that receives such methods through its
    /// own dictionaries.
    fn contextualizeDictionaryMethod(self: *Builder, method: *DictionaryMethodEvidence, caller: ?WorkerPlanId) Allocator.Error!void {
        const worker = switch (method.resolution) {
            .worker => |worker| worker,
            .builtin_numeral, .structural, .constraint, .checked_error, .unreachable_value => return,
        };
        const context = try self.contextualizeCall(worker, caller, method.nested_dict_args);
        method.resolution = .{ .worker = context.worker };
        method.context = if (self.workerNeedsFrameContext(context.worker))
            .{ .context_args = context.args }
        else
            null;
    }

    /// Record the local procedures with runtime captures a structural
    /// comparison or hash over the closed `rep` reaches, through component
    /// methods and the components a derivation expands into.
    fn recordFrameContextProcs(self: *Builder, rep_id: TypeRepId, method: DerivedMethod) Allocator.Error!void {
        if (!self.has_capturing_local_methods) return;
        if (self.plan.frame_context_procs.contains(.{ .rep = rep_id, .method = method })) return;
        if (try self.plan.namesTypeVariable(self.allocator, rep_id)) return;
        var procs = std.ArrayList(WorkerPlanId).empty;
        defer procs.deinit(self.allocator);
        var visited = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer visited.deinit();
        var pending = std.ArrayList(TypeRepId).empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, rep_id);
        while (pending.pop()) |current| {
            if ((try visited.getOrPut(current)).found_existing) continue;
            const rep = self.plan.representations.items[@intFromEnum(current)];
            if (rep.kind == .nominal) {
                if (self.derivedMethodTarget(current, method)) |found| switch (found) {
                    .target => |lookup| {
                        switch (lookup.target.kind) {
                            .local_proc => {
                                const source = self.workerSourceForMethodTarget(lookup, rep.source_type, null);
                                const worker = try self.ensureWorker(source, .{ .module = lookup.view.key, .ty = lookup.target.callable_ty }, null);
                                if (self.workerIsCapturingLocalProc(worker)) {
                                    if (std.mem.findScalar(WorkerPlanId, procs.items, worker) == null) try procs.append(self.allocator, worker);
                                }
                            },
                            .procedure, .structural => {},
                        }
                        // A component method's own evidence comes from the
                        // nominal's arguments.
                        for (self.plan.childSlice(rep.children)) |child| {
                            if (child.role == .nominal_arg) try pending.append(self.allocator, child.rep);
                        }
                        continue;
                    },
                    .rejected => continue,
                };
            }
            for (self.plan.childSlice(rep.children)) |child| try pending.append(self.allocator, child.rep);
            for (self.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                for (self.plan.childSlice(variant.payloads)) |payload| try pending.append(self.allocator, payload.rep);
            }
        }
        if (procs.items.len == 0) return;
        const start: u32 = @intCast(self.plan.frame_context_proc_ids.items.len);
        try self.plan.frame_context_proc_ids.appendSlice(self.allocator, procs.items);
        try self.plan.frame_context_procs.put(self.allocator, .{ .rep = rep_id, .method = method }, .{ .start = start, .len = @intCast(procs.items.len) });
    }

    fn dispatchResolutionIsStructural(
        view: ModuleView,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
    ) bool {
        const plan_id = maybe_plan orelse
            boxyPlanInvariant("direct dispatch call had no checked dispatch plan");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.plans.len) {
            boxyPlanInvariant("direct dispatch call referenced a missing checked dispatch plan");
        }
        return view.static_dispatch_plans.plans[raw].resolution == .structural;
    }

    /// The evidence node a resolved direct dispatch plan selected.
    fn directDispatchEvidenceNode(
        view: ModuleView,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
    ) static_dispatch.EvidenceNodeId {
        const plan_id = maybe_plan orelse
            boxyPlanInvariant("direct dispatch call had no checked dispatch plan");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.plans.len) {
            boxyPlanInvariant("direct dispatch call referenced a missing checked dispatch plan");
        }
        return switch (view.static_dispatch_plans.plans[raw].resolution) {
            .direct_closed, .direct_parametric => |direct| direct.evidence,
            .direct_pending => boxyPlanInvariant("unfinalized direct call reached Boxy planning"),
            .evidence_dependent,
            .structural,
            .checked_error,
            .@"unreachable",
            => boxyPlanInvariant("direct call plan referenced a dispatch plan that did not select a direct target"),
        };
    }

    fn nestedEvidenceForDirectDispatch(
        _: *Builder,
        view: ModuleView,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
    ) ?[]const static_dispatch.CheckedEvidence {
        const plan_id = maybe_plan orelse
            boxyPlanInvariant("direct dispatch call had no checked dispatch plan");
        const raw = @intFromEnum(plan_id);
        if (raw >= view.static_dispatch_plans.plans.len) {
            boxyPlanInvariant("direct dispatch call referenced a missing checked dispatch plan");
        }
        return switch (view.static_dispatch_plans.plans[raw].resolution) {
            .direct_closed, .direct_parametric => |direct| blk: {
                const node = view.static_dispatch_plans.evidenceNode(direct.evidence);
                break :blk switch (node.nested) {
                    .resolved => view.static_dispatch_plans.nestedEvidence(node),
                    .from_callable => null,
                };
            },
            .direct_pending => boxyPlanInvariant("unfinalized direct call reached Boxy planning"),
            .evidence_dependent,
            .structural,
            .checked_error,
            .@"unreachable",
            => null,
        };
    }

    /// An inspect slot invokes its worker at the method's checked `T -> Str`
    /// instance; the checked evidence of that use supplies the worker's
    /// dictionaries.
    fn materializeInspectMethodHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.inspect_methods.items.len) : (index += 1) {
            const method = self.plan.inspect_methods.items[index];
            const worker = self.plan.workers.items[@intFromEnum(method.worker)];
            if (worker.hidden_dicts.len == 0) continue;
            const function = (self.repQuery().functionChildren(worker.rep)) orelse
                boxyPlanInvariant("boxy inspect worker was not callable");
            if (function.arg_count != 1) boxyPlanInvariant("boxy inspect worker did not take exactly one argument");
            const source_type = self.plan.representations.items[@intFromEnum(method.source_rep)].source_type;
            const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
            const evidence_view = self.moduleForId(method.evidence.module);
            var bindings = std.ArrayList(SiteRepBinding).empty;
            defer bindings.deinit(self.allocator);
            self.plan.inspect_methods.items[index].hidden_dict_args = try self.materializeWorkerCallHiddenDictionaryArgsWithEvidence(
                method.worker,
                null,
                &.{source_type},
                ret_type,
                evidence_view,
                inspectUseNestedEvidence(evidence_view, method.evidence.node),
                try self.inspectUseSchemeSubstitution(method, &bindings),
                0,
            );
        }
    }

    fn inspectUseNestedEvidence(view: ModuleView, node: static_dispatch.EvidenceNodeId) []const static_dispatch.CheckedEvidence {
        return view.static_dispatch_plans.nestedEvidence(view.static_dispatch_plans.evidenceNode(node));
    }

    /// The checked substitution of inspection's use of an override. The use
    /// leaves the owner's type variables free, so each is bound to the
    /// inspected value's corresponding type argument.
    fn inspectUseSchemeSubstitution(
        self: *Builder,
        method: InspectMethodPlan,
        bindings: *std.ArrayList(SiteRepBinding),
    ) Allocator.Error!?SchemeCallSubstitution {
        var substitution = self.evidenceEdgeSchemeSubstitution(method.worker, method.evidence) orelse return null;
        const worker = self.plan.workers.items[@intFromEnum(method.worker)];
        const function = (self.repQuery().functionChildren(worker.rep)) orelse
            boxyPlanInvariant("boxy inspect worker was not callable");
        const worker_arg_rep = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children)[function.args_start].rep;
        var owner_args = self.plan.nominalBackingSubstitutions(self.plan.representations.items[@intFromEnum(worker_arg_rep)].nominal_backing_arg_substitutions);
        while (owner_args.next()) |owner_arg| {
            const actual = self.nominalBackingArgActualRep(method.source_rep, owner_arg.arg_index) orelse
                boxyPlanInvariant("inspected value had no type argument for an override's owner variable");
            try bindings.append(self.allocator, .{ .site = owner_arg.actual_rep, .actual = actual });
        }
        substitution.site_rep_bindings = bindings.items;
        return substitution;
    }

    fn materializeIteratorCallHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        var call_index: usize = 0;
        while (call_index < self.plan.iterator_calls.items.len) : (call_index += 1) {
            const call = self.plan.iterator_calls.items[call_index];
            const arg_types = try self.callSubstitutionTypes(call.arg_substitutions, .operand);
            defer self.allocator.free(arg_types);
            const hidden_dict_args = try self.materializeWorkerCallHiddenDictionaryArgs(call.worker, call.caller, arg_types, call.ret_type);
            self.plan.iterator_calls.items[call_index].hidden_dict_args = hidden_dict_args;
            const context = try self.contextualizeDirectLocalProcCall(call.worker, call.caller, hidden_dict_args);
            self.plan.iterator_calls.items[call_index].worker = context.worker;
            self.plan.iterator_calls.items[call_index].context_args = context.args;
        }
    }

    fn materializeGeneratedCodecCallHiddenDictionaryArgs(self: *Builder) Allocator.Error!void {
        var index: usize = 0;
        while (index < self.plan.generated_codec_calls.items.len) : (index += 1) {
            const call = self.plan.generated_codec_calls.items[index];
            const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
            const call_view = self.moduleForId(call.method_module);
            const checked_evidence = call_view.static_dispatch_plans.evidence_refs[call.checked_evidence.start .. call.checked_evidence.start + call.checked_evidence.len];
            self.plan.generated_codec_calls.items[index].hidden_dict_args =
                try self.materializeWorkerCallHiddenDictionaryArgsWithEvidence(
                    call.worker,
                    call.caller,
                    arg_types,
                    call.ret_type,
                    call_view,
                    checked_evidence,
                    if (call.evidence_edge) |edge| self.evidenceEdgeSchemeSubstitution(call.worker, edge) else null,
                    0,
                );
        }
    }

    const SubstitutionTypeKind = enum { operand, call };

    fn callSubstitutionTypes(
        self: *Builder,
        span: Span,
        kind: SubstitutionTypeKind,
    ) Allocator.Error![]CheckedTypeIdentity {
        const substitutions = self.plan.callTypeSubstitutionSlice(span);
        const types = try self.allocator.alloc(CheckedTypeIdentity, substitutions.len);
        errdefer self.allocator.free(types);
        for (substitutions, types) |substitution, *ty| {
            ty.* = switch (kind) {
                .operand => substitution.operand_type,
                .call => substitution.call_type,
            };
        }
        return types;
    }

    fn materializeWorkerCallHiddenDescriptorArgs(
        self: *Builder,
        worker_id: WorkerPlanId,
        call_arg_types: []const CheckedTypeIdentity,
        operand_arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        dictionary_args: Span,
    ) Allocator.Error!Span {
        return try self.materializeWorkerCallHiddenDescriptorArgsWithSubstitution(
            worker_id,
            call_arg_types,
            operand_arg_types,
            ret_type,
            null,
            null,
            null,
            dictionary_args,
        );
    }

    fn materializeWorkerCallHiddenDescriptorArgsWithSubstitution(
        self: *Builder,
        worker_id: WorkerPlanId,
        call_arg_types: []const CheckedTypeIdentity,
        operand_arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        evidence_view: ?ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: ?SchemeCallSubstitution,
        dictionary_args: Span,
    ) Allocator.Error!Span {
        return try self.materializeWorkerCallHiddenDescriptorArgsWithStoredSubstitution(
            worker_id,
            call_arg_types,
            operand_arg_types,
            ret_type,
            evidence_view,
            evidence,
            scheme_substitution,
            null,
            dictionary_args,
        );
    }

    fn materializeWorkerCallHiddenDescriptorArgsWithStoredSubstitution(
        self: *Builder,
        worker_id: WorkerPlanId,
        call_arg_types: []const CheckedTypeIdentity,
        operand_arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        evidence_view: ?ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: ?SchemeCallSubstitution,
        stored_substitution: ?Span,
        dictionary_args: Span,
    ) Allocator.Error!Span {
        if (call_arg_types.len != operand_arg_types.len) {
            boxyPlanInvariant("boxy worker call hidden descriptor mapping saw mismatched function arity");
        }

        const call_arg_reps = try self.allocator.alloc(TypeRepId, call_arg_types.len);
        defer self.allocator.free(call_arg_reps);
        const operand_arg_reps = try self.allocator.alloc(TypeRepId, operand_arg_types.len);
        defer self.allocator.free(operand_arg_reps);
        for (call_arg_types, operand_arg_types, call_arg_reps, operand_arg_reps) |call_arg_type, operand_arg_type, *call_arg_rep, *operand_arg_rep| {
            call_arg_rep.* = self.plan.repForSourceType(call_arg_type) orelse
                boxyPlanInvariant("boxy worker call argument type was not analyzed");
            operand_arg_rep.* = self.plan.repForSourceType(operand_arg_type) orelse
                boxyPlanInvariant("boxy worker call operand type was not analyzed");
        }
        const ret_rep = self.plan.repForSourceType(ret_type) orelse
            boxyPlanInvariant("boxy worker call result type was not analyzed");
        return try self.materializeWorkerCallHiddenDescriptorArgsForRepsWithEvidence(
            worker_id,
            call_arg_reps,
            operand_arg_reps,
            ret_rep,
            call_arg_types,
            ret_type,
            evidence_view,
            evidence,
            scheme_substitution,
            stored_substitution,
            dictionary_args,
        );
    }

    /// `dictionary_args` are this call's planned hidden dictionary arguments
    /// (empty when the worker takes none): a requirement whose receiver the
    /// call derives from its callable takes the representation its dictionary
    /// was planned at.
    fn materializeWorkerCallHiddenDescriptorArgsForRepsWithEvidence(
        self: *Builder,
        worker_id: WorkerPlanId,
        call_arg_reps: []const TypeRepId,
        operand_arg_reps: []const TypeRepId,
        ret_rep: TypeRepId,
        call_arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        evidence_view: ?ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: ?SchemeCallSubstitution,
        stored_substitution: ?Span,
        dictionary_args: Span,
    ) Allocator.Error!Span {
        if (call_arg_reps.len != operand_arg_reps.len) {
            boxyPlanInvariant("boxy worker call hidden descriptor mapping saw mismatched operand arity");
        }
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        if (params.len == 0) return .{};

        const worker_function = (self.repQuery().functionChildren(worker.rep)) orelse
            boxyPlanInvariant("boxy worker call target with hidden descriptors was not a function worker");
        if (worker_function.arg_count != call_arg_reps.len) {
            boxyPlanInvariant("boxy worker call hidden descriptor mapping saw mismatched function arity");
        }

        var pending = std.ArrayList(DirectCallHiddenDescriptorArg).empty;
        defer pending.deinit(self.allocator);
        var seen_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen_reps.deinit();
        var seen_descriptor_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen_descriptor_reps.deinit();
        var substitutions = CallDescriptorRepSubstitutionMap{};
        defer substitutions.deinit(self.allocator);
        // The checker's call-site substitution is the authority for each of
        // the callee scheme's variables: it names exactly the caller type a
        // variable stood for, including a row extension's residual tags,
        // which a whole-row call representation has no child for.
        if (scheme_substitution) |substitution| {
            for (substitution.scheme_vars, substitution.site_types) |scheme_var, site_type| {
                if (substitution.site_view.checked_types.payload(site_type) == .err) continue;
                const worker_var_rep = self.plan.repForSourceType(typeRef(substitution.callee_view, scheme_var)) orelse continue;
                const call_rep = substitution.siteRep(self.plan.repForSourceType(typeRef(substitution.site_view, site_type)) orelse
                    boxyPlanInvariant("checked call-site substitution type was not analyzed"));
                // A bound site can be the scheme variable itself.
                if (call_rep == worker_var_rep) continue;
                try substitutions.put(self.allocator, worker_var_rep, call_rep);
            }
        }
        // A stored function value was produced at the one instantiation of its
        // worker that its use's type fixes, including the variables of the
        // scope that created it.
        if (stored_substitution) |stored| {
            for (self.plan.schemeRepSubstitutionSlice(stored)) |pair| {
                try substitutions.put(self.allocator, pair.scheme_rep, pair.site_rep);
            }
        }
        // A call that derived its evidence from its callable named, when it
        // planned its dictionaries, the variables no checked substitution
        // supplies: receivers reached only through another requirement's
        // constraint callable, and variables only its requirements name.
        for (self.plan.directCallHiddenDictionaryArgSlice(dictionary_args)) |arg| {
            if (arg.derived_substitution.len == 0) continue;
            for (self.plan.schemeRepSubstitutionSlice(arg.derived_substitution)) |pair| {
                if (substitutions.get(pair.scheme_rep) != null) continue;
                try substitutions.put(self.allocator, pair.scheme_rep, pair.site_rep);
            }
            break;
        }
        substitutions.scheme_entries_len = substitutions.entries.items.len;
        const evidence_only_start: usize = if (worker.evidence_only_descs.len == 0)
            params.len
        else
            worker.evidence_only_descs.start - worker.hidden_descs.start;
        if (evidence_only_start > params.len or
            worker.evidence_only_descs.start + worker.evidence_only_descs.len != worker.hidden_descs.start + worker.hidden_descs.len)
        {
            boxyPlanInvariant("boxy evidence-only worker descriptors were not a suffix of hidden descriptors");
        }
        const enclosing_start: usize = worker.enclosing_descs.start - worker.hidden_descs.start;
        if (enclosing_start + worker.enclosing_descs.len != evidence_only_start) {
            boxyPlanInvariant("boxy enclosing worker descriptors did not precede its evidence-only descriptors");
        }
        const ordinary_params = params[0..enclosing_start];
        var next_param: usize = 0;

        const worker_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(worker_function.rep)].children);
        for (
            worker_children[worker_function.args_start..][0..worker_function.arg_count],
            call_arg_reps,
            operand_arg_reps,
            0..,
        ) |worker_child, call_arg_rep, operand_arg_rep, arg_index| {
            try self.collectCallHiddenDescriptorArgs(
                worker_child.rep,
                call_arg_rep,
                call_arg_rep,
                operand_arg_rep,
                @intCast(arg_index),
                ordinary_params,
                &next_param,
                &pending,
                &seen_reps,
                &seen_descriptor_reps,
                &substitutions,
                false,
            );
        }
        try self.collectCallHiddenDescriptorArgs(worker_function.ret, ret_rep, ret_rep, ret_rep, null, ordinary_params, &next_param, &pending, &seen_reps, &seen_descriptor_reps, &substitutions, false);
        // A descriptor for a worker argument's own type describes that whole
        // operand.
        const final_worker_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(worker_function.rep)].children);
        for (pending.items) |*arg| {
            const index = arg.source_arg_index orelse continue;
            const worker_arg = final_worker_children[worker_function.args_start + index];
            arg.whole_operand = self.repQuery().descriptorArgumentIdentityRep(arg.worker_rep) ==
                self.repQuery().descriptorArgumentIdentityRep(worker_arg.rep);
            if (!arg.whole_operand) {
                arg.source_operand_rep = try self.operandRepAtWorkerPosition(worker_arg.rep, arg.worker_rep, operand_arg_reps[index]);
            }
        }

        if (next_param != ordinary_params.len or pending.items.len != ordinary_params.len) {
            boxyPlanInvariant("boxy worker call hidden descriptor mapping did not cover every ordinary worker descriptor param");
        }

        // A callee scheme variable takes this call's checked instantiation. Any
        // other body descriptor names a variable of the scope creating this
        // use, which the calling frame describes.
        for (params[enclosing_start..evidence_only_start]) |param| {
            const rep = substitutions.get(param.rep) orelse param.rep;
            try pending.append(self.allocator, .{
                .worker_desc = param.desc,
                .worker_rep = param.rep,
                .source_type = self.plan.representations.items[@intFromEnum(rep)].source_type,
                .rep = rep,
            });
        }

        try self.appendEvidenceOnlyCallHiddenDescriptorArgs(
            worker,
            params,
            call_arg_types,
            call_arg_reps,
            ret_type,
            evidence_view,
            evidence,
            substitutions.entries.items[0..substitutions.scheme_entries_len],
            &pending,
        );
        if (pending.items.len != params.len) {
            boxyPlanInvariant("boxy worker call evidence mapping did not cover every worker descriptor param");
        }

        const start: u32 = @intCast(self.plan.direct_call_hidden_desc_args.items.len);
        try self.plan.direct_call_hidden_desc_args.appendSlice(self.allocator, pending.items);
        return .{
            .start = start,
            .len = @intCast(pending.items.len),
        };
    }

    fn appendEvidenceOnlyCallHiddenDescriptorArgs(
        self: *Builder,
        worker: WorkerPlan,
        params: []const HiddenDescriptorParam,
        call_arg_types: []const CheckedTypeIdentity,
        call_arg_reps: []const TypeRepId,
        ret_type: CheckedTypeIdentity,
        maybe_view: ?ModuleView,
        maybe_evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: []const CallDescriptorRepSubstitution,
        pending: *std.ArrayList(DirectCallHiddenDescriptorArg),
    ) Allocator.Error!void {
        const mappings = self.plan.workerEvidenceDescriptorParamSlice(worker.evidence_descs);
        if (mappings.len == 0) return;
        const evidence_only_start: usize = @intCast(worker.evidence_only_descs.start - worker.hidden_descs.start);

        // Evidence that aliases an ordinary signature descriptor must select
        // the same concrete call representation already chosen by the normal
        // function-boundary substitution.
        for (mappings) |mapping| {
            if (mapping.hidden_desc_index >= params.len) {
                boxyPlanInvariant("worker literal-evidence descriptor mapping exceeded its checked vectors");
            }
            // The checked call-site substitution names the evidence variable's
            // instantiation exactly.
            if (self.schemeSubstitutedRep(scheme_substitution, params[mapping.hidden_desc_index].rep) != null) continue;
            const source = try self.workerEvidenceDescriptorCallSource(
                worker,
                mapping.evidence_index,
                call_arg_types,
                call_arg_reps,
                ret_type,
                maybe_view,
                maybe_evidence,
            );
            if (mapping.hidden_desc_index < evidence_only_start and
                !self.callDescriptorRepsAgreeAcrossPresenceSlot(
                    pending.items[mapping.hidden_desc_index].rep,
                    source.rep,
                ))
            {
                boxyPlanInvariant("literal evidence disagreed with the concrete signature descriptor substitution");
            }
        }

        var hidden_index = evidence_only_start;
        while (hidden_index < params.len) : (hidden_index += 1) {
            var source_type: ?CheckedTypeIdentity = null;
            var source_rep: ?TypeRepId = null;
            var source_arg_index: ?u32 = null;
            var source_value_rep: ?TypeRepId = null;
            var whole_operand = false;
            const substituted = self.schemeSubstitutedRep(scheme_substitution, params[hidden_index].rep);
            if (substituted) |rep| {
                source_type = self.plan.representations.items[@intFromEnum(rep)].source_type;
                source_rep = rep;
            }
            for (mappings) |mapping| {
                if (substituted != null) break;
                if (mapping.hidden_desc_index != hidden_index) continue;
                const source = try self.workerEvidenceDescriptorCallSource(
                    worker,
                    mapping.evidence_index,
                    call_arg_types,
                    call_arg_reps,
                    ret_type,
                    maybe_view,
                    maybe_evidence,
                );
                if (source_rep) |existing| {
                    if (existing != source.rep) {
                        boxyPlanInvariant("one worker descriptor parameter received conflicting literal evidence types");
                    }
                } else {
                    source_type = source.source_type;
                    source_rep = source.rep;
                    source_arg_index = source.source_arg_index;
                    source_value_rep = source.source_value_rep;
                    whole_operand = source.whole_operand;
                }
            }
            const param = params[hidden_index];
            if (source_rep == null) {
                // A descriptor collected inside an evidence dispatcher's
                // representation sits at the same position of that
                // dispatcher's call source.
                if (pending.items.len != hidden_index) {
                    boxyPlanInvariant("evidence-only worker descriptors were not planned in parameter order");
                }
                for (mappings) |mapping| {
                    if (mapping.hidden_desc_index >= hidden_index) continue;
                    const root = pending.items[mapping.hidden_desc_index];
                    const rep = try self.operandRepAtWorkerPosition(params[mapping.hidden_desc_index].rep, param.rep, root.rep) orelse continue;
                    if (source_rep) |existing| {
                        if (existing != rep) boxyPlanInvariant("one evidence-only worker descriptor sat inside two evidence sources");
                        continue;
                    }
                    source_type = self.plan.representations.items[@intFromEnum(rep)].source_type;
                    source_rep = rep;
                }
            }
            try pending.append(self.allocator, .{
                .worker_desc = param.desc,
                .worker_rep = param.rep,
                .source_type = source_type orelse
                    boxyPlanInvariant("evidence-only worker descriptor had no checked evidence mapping"),
                .rep = source_rep.?,
                .source_arg_index = source_arg_index,
                .source_value_rep = source_value_rep,
                .whole_operand = whole_operand,
            });
        }
    }

    const EvidenceDescriptorCallSource = struct {
        source_type: CheckedTypeIdentity,
        rep: TypeRepId,
        source_arg_index: ?u32,
        source_value_rep: ?TypeRepId,
        whole_operand: bool,
    };

    fn workerEvidenceDescriptorCallSource(
        self: *Builder,
        worker: WorkerPlan,
        evidence_index: u32,
        call_arg_types: []const CheckedTypeIdentity,
        call_arg_reps: []const TypeRepId,
        ret_type: CheckedTypeIdentity,
        maybe_view: ?ModuleView,
        maybe_evidence: ?[]const static_dispatch.CheckedEvidence,
    ) Allocator.Error!EvidenceDescriptorCallSource {
        if (call_arg_types.len != call_arg_reps.len) {
            boxyPlanInvariant("worker evidence descriptor call source saw mismatched argument metadata");
        }
        const worker_evidence = self.workerEvidenceParams(worker.source) orelse
            boxyPlanInvariant("worker evidence descriptor had no checked parameters");
        if (evidence_index >= worker_evidence.params.len) {
            boxyPlanInvariant("worker evidence descriptor index exceeded its checked parameter vector");
        }
        const param = worker_evidence.params[evidence_index];
        const path_view = worker_evidence.view;
        var path_steps = std.ArrayListUnmanaged(static_dispatch.EvidencePathStep).empty;
        defer path_steps.deinit(self.allocator);
        const path = try path_view.checked_procedure_templates.evidenceParamPath(self.allocator, param, &path_steps);
        const call_path: []const static_dispatch.EvidencePathStep = switch (param.source) {
            .scheme_callable => path,
            .scheme_requirement, .constraint_callable, .use_site_only, .explicit_default, .erased_row_remainder => &.{},
        };
        const source_arg_index = evidencePathSourceArgIndex(call_path, call_arg_types.len);

        const source_type = if (maybe_evidence) |evidence| blk: {
            const view = maybe_view orelse
                boxyPlanInvariant("worker literal evidence had no checked call-site module");
            if (evidence_index >= evidence.len) {
                boxyPlanInvariant("worker literal evidence index exceeded the checked call-site vector");
            }
            break :blk typeRef(view, evidence[evidence_index].dispatcher_ty);
        } else try self.checkedTypeAtEvidenceCallPath(
            worker_evidence.view,
            call_path,
            call_arg_types,
            ret_type,
        );
        const rep = try self.evidenceCallRepAtPath(path_view, call_path, source_type, call_arg_reps, ret_type);
        return .{
            .source_type = source_type,
            .rep = rep,
            .source_arg_index = source_arg_index,
            .source_value_rep = if (source_arg_index) |index| call_arg_reps[index] else null,
            .whole_operand = source_arg_index != null and
                call_path[call_path.len - 1].stepKind() == .fn_arg,
        };
    }

    fn evidenceCallRepAtPath(
        self: *Builder,
        path_view: ModuleView,
        path: []const static_dispatch.EvidencePathStep,
        pathless_type: CheckedTypeIdentity,
        call_arg_reps: []const TypeRepId,
        ret_type: CheckedTypeIdentity,
    ) Allocator.Error!TypeRepId {
        if (path.len == 0) {
            return self.plan.repForSourceType(pathless_type) orelse
                boxyPlanInvariant("pathless worker evidence type was not analyzed");
        }
        const start = switch (path[0].stepKind()) {
            .fn_arg => blk: {
                if (path[0].data >= call_arg_reps.len) {
                    boxyPlanInvariant("worker evidence representation path function argument exceeded arity");
                }
                break :blk call_arg_reps[path[0].data];
            },
            .fn_ret => self.plan.repForSourceType(ret_type) orelse
                boxyPlanInvariant("worker evidence representation path result type was not analyzed"),
            .alias_arg,
            .alias_backing,
            .nominal_arg,
            .nominal_backing,
            .tuple_elem,
            .record_field,
            .tag_payload_tag,
            .tag_payload_index,
            => boxyPlanInvariant("worker evidence representation path did not begin at its callable boundary"),
        };
        return try self.walkEvidenceRepPath(path_view, start, path[1..]);
    }

    fn walkEvidenceRepPath(
        self: *Builder,
        path_view: ModuleView,
        start: TypeRepId,
        path: []const static_dispatch.EvidencePathStep,
    ) Allocator.Error!TypeRepId {
        // A path can pass through a nominal's shared backing into another use
        // of the same declaration. Each use binds its formals afresh, with
        // actuals resolved against the bindings of the uses enclosing it; the
        // innermost binding of a formal is the one in effect.
        var bindings = std.ArrayList(CallDescriptorRepSubstitution).empty;
        defer bindings.deinit(self.allocator);

        var current = start;
        var path_index: usize = 0;
        while (path_index < path.len) {
            const path_step = path[path_index];
            // An alias is transparent: a use can instantiate a path's structural
            // step at an alias of that structure, and the step applies to its
            // backing.
            switch (path_step.stepKind()) {
                .alias_arg, .alias_backing => {},
                .fn_arg, .fn_ret, .nominal_arg, .nominal_backing, .tuple_elem, .record_field, .tag_payload_tag, .tag_payload_index => {
                    while (self.plan.representations.items[@intFromEnum(current)].kind == .alias) {
                        current = self.repQuery().requiredSingleChild(current, .alias_backing).rep;
                    }
                },
            }
            const current_rep = self.plan.representations.items[@intFromEnum(current)];
            const children = self.plan.childSlice(current_rep.children);
            if (current_rep.kind == .nominal) {
                const enclosing_len = bindings.items.len;
                var substitution_iter = self.plan.nominalBackingSubstitutions(current_rep.nominal_backing_arg_substitutions);
                while (substitution_iter.next()) |substitution| {
                    const formal_rep = substitution.formal_rep orelse continue;
                    const actual = innermostEvidencePathBinding(bindings.items[0..enclosing_len], substitution.actual_rep) orelse substitution.actual_rep;
                    if (formal_rep == actual) continue;
                    try bindings.append(self.allocator, .{ .worker_rep = formal_rep, .call_rep = actual });
                }
            }
            // The path is written against the callee's type. Where that type
            // names a structure and the call site names a wrapper that
            // checking related to it, the structural step applies to the
            // wrapper's backing, under the formal bindings recorded above.
            switch (path_step.stepKind()) {
                .fn_arg, .fn_ret, .tuple_elem, .record_field, .tag_payload_tag => {
                    if (self.repQuery().structureBackingRep(current)) |backing| {
                        current = backing;
                        continue;
                    }
                },
                .alias_arg, .alias_backing, .nominal_arg, .nominal_backing, .tag_payload_index => {},
            }
            const selected = switch (path_step.stepKind()) {
                .fn_arg => for (children) |child| {
                    if (child.role == .function_arg and child.role.function_arg == path_step.data) break child.rep;
                } else boxyPlanInvariant("worker evidence representation path expected a function argument"),
                .fn_ret => for (children) |child| {
                    if (child.role == .function_ret) break child.rep;
                } else boxyPlanInvariant("worker evidence representation path expected a function return"),
                .alias_arg => for (children) |child| {
                    if (child.role == .alias_arg and child.role.alias_arg == path_step.data) break child.rep;
                } else boxyPlanInvariant("worker evidence representation path expected an alias argument"),
                .alias_backing => for (children) |child| {
                    if (child.role == .alias_backing) break child.rep;
                } else boxyPlanInvariant("worker evidence representation path expected an alias backing"),
                .nominal_arg => self.nominalBackingArgActualRep(current, path_step.data) orelse switch (current_rep.kind) {
                    .list => if (path_step.data == 0)
                        requiredSingleChildOf(&self.plan, current, .list_elem).rep
                    else
                        boxyPlanInvariant("worker evidence representation path list argument exceeded arity"),
                    .box => if (path_step.data == 0)
                        requiredSingleChildOf(&self.plan, current, .box_payload).rep
                    else
                        boxyPlanInvariant("worker evidence representation path box argument exceeded arity"),
                    .in_progress,
                    .dynamic,
                    .primitive,
                    .bool_tag_union,
                    .erased_callable,
                    .alias,
                    .record,
                    .tuple,
                    .nominal,
                    .generated_field,
                    .generated_field_names,
                    .generated_tag_union_spec,
                    .empty_record,
                    .tag_union,
                    .empty_tag_union,
                    => for (children) |child| {
                        if (child.role == .nominal_arg and child.role.nominal_arg == path_step.data) break child.rep;
                    } else boxyPlanInvariant("worker evidence representation path expected a nominal argument"),
                },
                .nominal_backing => for (children) |child| {
                    if (child.role == .nominal_backing) break child.rep;
                } else boxyPlanInvariant("worker evidence representation path expected a nominal backing"),
                .tuple_elem => for (children) |child| {
                    if (child.role == .tuple_elem and child.role.tuple_elem == path_step.data) break child.rep;
                } else boxyPlanInvariant("worker evidence representation path expected a tuple element"),
                .record_field => blk: {
                    const path_name: RecordFieldLabelId = @enumFromInt(path_step.data);
                    for (children) |child| {
                        if (child.role != .record_field) continue;
                        const child_view = self.moduleForId(child.source_type.module);
                        if (recordFieldNameMatches(moduleNamesOf(path_view), path_name, moduleNamesOf(child_view), child.role.record_field)) {
                            break :blk child.rep;
                        }
                    }
                    boxyPlanInvariant("worker evidence representation path field was absent from the checked record");
                },
                .tag_payload_tag => blk: {
                    if (path_index + 1 >= path.len or path[path_index + 1].stepKind() != .tag_payload_index) {
                        boxyPlanInvariant("worker evidence representation tag path had no payload index");
                    }
                    const path_tag: TagLabelId = @enumFromInt(path_step.data);
                    const payload_index = path[path_index + 1].data;
                    for (children) |child| {
                        if (child.role != .tag_payload) continue;
                        const payload = child.role.tag_payload;
                        const child_view = self.moduleForId(child.source_type.module);
                        if (payload.index == payload_index and
                            tagLabelNameMatches(moduleNamesOf(path_view), path_tag, moduleNamesOf(child_view), payload.tag))
                        {
                            path_index += 1;
                            break :blk child.rep;
                        }
                    }
                    boxyPlanInvariant("worker evidence representation path tag payload was absent from the checked union");
                },
                .tag_payload_index => boxyPlanInvariant("worker evidence representation payload index had no preceding tag"),
            };
            current = innermostEvidencePathBinding(bindings.items, selected) orelse selected;
            path_index += 1;
        }
        return current;
    }

    fn innermostEvidencePathBinding(bindings: []const CallDescriptorRepSubstitution, formal_rep: TypeRepId) ?TypeRepId {
        var index = bindings.len;
        while (index > 0) {
            index -= 1;
            if (bindings[index].worker_rep == formal_rep) return bindings[index].call_rep;
        }
        return null;
    }

    fn evidencePathSourceArgIndex(path: []const static_dispatch.EvidencePathStep, arg_count: usize) ?u32 {
        for (path) |path_step| switch (path_step.stepKind()) {
            .fn_arg => {
                if (path_step.data >= arg_count) {
                    boxyPlanInvariant("worker evidence path function argument exceeded call arity");
                }
                return path_step.data;
            },
            .fn_ret => return null,
            .alias_arg,
            .alias_backing,
            .nominal_arg,
            .nominal_backing,
            .tuple_elem,
            .record_field,
            .tag_payload_tag,
            .tag_payload_index,
            => {},
        };
        return null;
    }

    fn checkedTypeAtEvidenceCallPath(
        self: *Builder,
        path_view: ModuleView,
        path: []const static_dispatch.EvidencePathStep,
        call_arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
    ) Allocator.Error!CheckedTypeIdentity {
        if (path.len == 0) {
            boxyPlanInvariant("compiler-generated call could not resolve a pathless worker evidence parameter");
        }
        const start = switch (path[0].stepKind()) {
            .fn_arg => blk: {
                if (path[0].data >= call_arg_types.len) {
                    boxyPlanInvariant("worker evidence path function argument exceeded call arity");
                }
                break :blk call_arg_types[path[0].data];
            },
            .fn_ret => ret_type,
            .alias_arg,
            .alias_backing,
            .nominal_arg,
            .nominal_backing,
            .tuple_elem,
            .record_field,
            .tag_payload_tag,
            .tag_payload_index,
            => boxyPlanInvariant("worker evidence path did not begin at its callable boundary"),
        };
        return try self.walkCheckedEvidencePath(path_view, start, path[1..]);
    }

    fn walkCheckedEvidencePath(
        self: *Builder,
        path_view: ModuleView,
        start: CheckedTypeIdentity,
        path: []const static_dispatch.EvidencePathStep,
    ) Allocator.Error!CheckedTypeIdentity {
        var current = start;
        var path_index: usize = 0;
        while (path_index < path.len) {
            const path_step = path[path_index];
            const view = self.moduleForId(current.module);
            current = switch (path_step.stepKind()) {
                .fn_arg => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .function) boxyPlanInvariant("worker evidence path expected a function argument");
                    if (path_step.data >= payload.function.args.len) {
                        boxyPlanInvariant("worker evidence path nested function argument exceeded arity");
                    }
                    break :blk typeRef(view, payload.function.args[path_step.data]);
                },
                .fn_ret => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .function) boxyPlanInvariant("worker evidence path expected a function return");
                    break :blk typeRef(view, payload.function.ret);
                },
                .alias_arg => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .alias) boxyPlanInvariant("worker evidence path expected an alias argument");
                    if (path_step.data >= payload.alias.args.len) {
                        boxyPlanInvariant("worker evidence path alias argument exceeded arity");
                    }
                    break :blk typeRef(view, payload.alias.args[path_step.data]);
                },
                .alias_backing => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .alias) boxyPlanInvariant("worker evidence path expected an alias backing");
                    break :blk typeRef(view, payload.alias.backing);
                },
                .nominal_arg => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .nominal) boxyPlanInvariant("worker evidence path expected a nominal argument");
                    if (path_step.data >= payload.nominal.args.len) {
                        boxyPlanInvariant("worker evidence path nominal argument exceeded arity");
                    }
                    break :blk typeRef(view, payload.nominal.args[path_step.data]);
                },
                .nominal_backing => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .nominal) boxyPlanInvariant("worker evidence path expected a nominal backing");
                    const backing = try self.nominalBackingSource(view, payload.nominal);
                    break :blk typeRef(backing.view, backing.ty);
                },
                .tuple_elem => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .tuple) boxyPlanInvariant("worker evidence path expected a tuple element");
                    if (path_step.data >= payload.tuple.len) {
                        boxyPlanInvariant("worker evidence path tuple element exceeded arity");
                    }
                    break :blk typeRef(view, payload.tuple[path_step.data]);
                },
                .record_field => blk: {
                    const payload = view.checked_types.payload(current.ty);
                    if (payload == .record) {
                        break :blk self.checkedRecordFieldAtEvidencePath(path_view, @enumFromInt(path_step.data), view, payload.record.fields);
                    }
                    boxyPlanInvariant("worker evidence path expected a record field");
                },
                .tag_payload_tag => blk: {
                    if (path_index + 1 >= path.len or path[path_index + 1].stepKind() != .tag_payload_index) {
                        boxyPlanInvariant("worker evidence tag path had no payload index");
                    }
                    const payload_index = path[path_index + 1].data;
                    const payload = view.checked_types.payload(current.ty);
                    if (payload != .tag_union) boxyPlanInvariant("worker evidence path expected a tag union payload");
                    const tag_union = payload.tag_union;
                    const path_tag: TagLabelId = @enumFromInt(path_step.data);
                    for (tag_union.tags) |tag| {
                        if (!tagLabelNameMatches(moduleNamesOf(path_view), path_tag, moduleNamesOf(view), tag.name)) continue;
                        const args = tag.argsSlice(view.checked_types);
                        if (payload_index >= args.len) {
                            boxyPlanInvariant("worker evidence path tag payload exceeded arity");
                        }
                        path_index += 1;
                        break :blk typeRef(view, args[payload_index]);
                    }
                    boxyPlanInvariant("worker evidence path tag was absent from the checked union");
                },
                .tag_payload_index => boxyPlanInvariant("worker evidence payload index had no preceding tag"),
            };
            path_index += 1;
        }
        return current;
    }

    fn checkedRecordFieldAtEvidencePath(
        _: *Builder,
        path_view: ModuleView,
        path_name: RecordFieldLabelId,
        record_view: ModuleView,
        fields: []const checked.CheckedRecordField,
    ) CheckedTypeIdentity {
        for (fields) |field| {
            if (recordFieldNameMatches(moduleNamesOf(path_view), path_name, moduleNamesOf(record_view), field.name)) {
                return typeRef(record_view, field.ty);
            }
        }
        boxyPlanInvariant("worker evidence path field was absent from the checked record");
    }

    fn materializeWorkerCallHiddenDictionaryArgs(
        self: *Builder,
        worker_id: WorkerPlanId,
        caller_id: ?WorkerPlanId,
        arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
    ) Allocator.Error!Span {
        return try self.materializeWorkerCallHiddenDictionaryArgsWithEvidence(
            worker_id,
            caller_id,
            arg_types,
            ret_type,
            null,
            null,
            null,
            0,
        );
    }

    /// `env` names the derived-method formal bindings the call's types are
    /// written under: a dictionary source that is one of those formals is its
    /// actual, and one that reads them is instantiated at them.
    fn materializeWorkerCallHiddenDictionaryArgsWithEvidence(
        self: *Builder,
        worker_id: WorkerPlanId,
        caller_id: ?WorkerPlanId,
        arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        evidence_view: ?ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: ?SchemeCallSubstitution,
        env: u32,
    ) Allocator.Error!Span {
        var machine = DictionaryArgsMachine{};
        defer machine.deinit(self.allocator);
        if (try self.beginDictionaryCallArgs(&machine, .{
            .worker_id = worker_id,
            .caller_id = caller_id,
            .arg_types = arg_types,
            .ret_type = ret_type,
            .evidence_view = evidence_view,
            .evidence = evidence,
            .scheme_substitution = scheme_substitution,
            .env = env,
        })) |span| return span;
        try self.runDictionaryArgs(&machine);
        return machine.span_result;
    }

    fn evidenceDictionarySource(
        self: *Builder,
        maybe_view: ?ModuleView,
        maybe_entries: ?[]const static_dispatch.CheckedEvidence,
        next_evidence: *usize,
        dictionaries: Span,
        requirement_substitution: Span,
        caller_id: ?WorkerPlanId,
        callable_contract: ?u32,
        indexed_evidence: bool,
    ) Allocator.Error!CallableEvidenceSource {
        var machine = DictionaryArgsMachine{};
        defer machine.deinit(self.allocator);
        if (try self.beginEvidenceDictionarySource(&machine, maybe_view, maybe_entries, next_evidence, dictionaries, requirement_substitution, caller_id, callable_contract, indexed_evidence)) |source| return source;
        try self.runDictionaryArgs(&machine);
        return machine.source_result;
    }

    // Hidden dictionary arguments //
    //
    // A worker call's hidden dictionary arguments come from checked evidence
    // or from static dictionaries built for the call's types, and each
    // method of such a dictionary is itself a worker call with hidden
    // dictionary arguments of its own. That nesting follows the nesting of
    // the types the dictionaries are for, so each call, evidence source, and
    // static dictionary still waiting on a nested call is a frame on one
    // heap-backed stack. Frames plan workers, evidence, and argument spans in
    // the order a direct recursive planner would.

    const DictionaryArgsMachine = struct {
        frames: std.ArrayList(DictionaryArgsFrame) = .empty,
        /// The argument span of the most recently finished call frame.
        span_result: Span = .{},
        /// The source of the most recently finished evidence source frame.
        source_result: CallableEvidenceSource = .{},

        fn deinit(self: *DictionaryArgsMachine, allocator: Allocator) void {
            for (self.frames.items) |frame| frame.destroy(allocator);
            self.frames.deinit(allocator);
        }
    };

    const DictionaryArgsFrame = union(enum) {
        call: *DictionaryCallArgs,
        source: *EvidenceSourceState,
        static_workers: *StaticDictionaryWorkers,

        fn destroy(frame: DictionaryArgsFrame, allocator: Allocator) void {
            switch (frame) {
                inline .call, .source, .static_workers => |state| {
                    state.deinit(allocator);
                    allocator.destroy(state);
                },
            }
        }
    };

    const DictionaryCallRequest = struct {
        worker_id: WorkerPlanId,
        caller_id: ?WorkerPlanId,
        arg_types: []const CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        evidence_view: ?ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        scheme_substitution: ?SchemeCallSubstitution,
        /// The worker's types related to the call's, for a call checking
        /// recorded no substitution for (a stored function's use, or a
        /// dispatch whose target derives its evidence from its callable):
        /// it names the worker's variables exactly as a checked substitution.
        relation: ?Span = null,
        env: u32,
    };

    /// One worker call's hidden dictionary arguments, collected parameter by
    /// parameter.
    const DictionaryCallArgs = struct {
        worker_id: WorkerPlanId,
        caller_id: ?WorkerPlanId,
        arg_types: []CheckedTypeIdentity,
        ret_type: CheckedTypeIdentity,
        evidence_view: ?ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        env: u32,
        hidden_dicts: Span,
        requirement_substitution: Span,
        worker_function: FunctionChildren,
        fn_children_span: Span,
        body_param_start: usize,
        substitutions: CallDictionaryRepSubstitutionMap = .{},
        pending: std.ArrayList(DirectCallHiddenDictionaryArg) = .empty,
        next_evidence: usize = 0,
        param_index: usize = 0,
        /// `requirement_substitution` names receivers this call derived from
        /// its callable, which no checked substitution supplied.
        derived_receivers: bool = false,
        /// The call has no checked substitution, so the variables only its
        /// callee's requirements name are bound by the methods it selects.
        binds_requirement_variables: bool = false,
        /// `requirement_substitution` relates the worker's types to the
        /// call's (`DictionaryCallRequest.relation`).
        relates_types: bool = false,
        stage: union(enum) {
            next_param,
            /// Waiting on the parameter's evidence source.
            after_source,
            /// Waiting on the parameter's static dictionary methods.
            after_static: struct { source_rep: TypeRepId, source_env: u32 },
        } = .next_param,

        fn deinit(self: *DictionaryCallArgs, allocator: Allocator) void {
            allocator.free(self.arg_types);
            self.substitutions.deinit(allocator);
            self.pending.deinit(allocator);
        }
    };

    /// The callable dictionary evidence selected for one requirement group,
    /// planned entry by entry.
    const EvidenceSourceState = struct {
        view: ModuleView,
        dictionaries: Span,
        requirement_substitution: Span,
        caller_id: ?WorkerPlanId,
        callable_contract: ?u32,
        selected: std.ArrayList(static_dispatch.CheckedEvidence) = .empty,
        methods: std.ArrayList(DictionaryMethodEvidence) = .empty,
        found: ?TypeRepId = null,
        bound_evidence: ?SchemeDictionaryKey = null,
        index: usize = 0,
        /// The planned method waiting on its nested dictionary arguments.
        awaiting: ?DictionaryMethodEvidence = null,

        fn deinit(self: *EvidenceSourceState, allocator: Allocator) void {
            self.selected.deinit(allocator);
            self.methods.deinit(allocator);
        }
    };

    /// A static dictionary's methods for one call parameter, planned method
    /// by method.
    const StaticDictionaryWorkers = struct {
        /// The call whose parameter this dictionary fills.
        call: *DictionaryCallArgs,
        source_rep_id: TypeRepId,
        env: u32,
        worker_dictionaries: Span,
        method_evidence: Span,
        // Planning one method can plan a nested dictionary's methods, which
        // append their own entries; this dictionary's entries are collected
        // first and appended contiguously.
        planned: std.ArrayList(DictionaryMethodEvidence) = .empty,
        method_index: usize = 0,
        /// The planned method waiting on its nested dictionary arguments,
        /// and the requirement substitution its checked evidence fixes.
        awaiting: ?struct { method: DictionaryMethodEvidence, requirement_substitution: ?Span } = null,

        fn deinit(self: *StaticDictionaryWorkers, allocator: Allocator) void {
            self.planned.deinit(allocator);
        }
    };

    /// Push `frame`, which the machine then owns.
    fn pushDictionaryFrame(self: *Builder, machine: *DictionaryArgsMachine, frame: DictionaryArgsFrame) Allocator.Error!void {
        machine.frames.append(self.allocator, frame) catch |err| {
            frame.destroy(self.allocator);
            return err;
        };
    }

    fn runDictionaryArgs(self: *Builder, machine: *DictionaryArgsMachine) Allocator.Error!void {
        while (machine.frames.items.len != 0) {
            const frame = machine.frames.items[machine.frames.items.len - 1];
            const frames_before = machine.frames.items.len;
            const done = switch (frame) {
                .call => |state| try self.stepDictionaryCallArgs(machine, state),
                .source => |state| try self.stepEvidenceDictionarySource(machine, state),
                .static_workers => |state| try self.stepStaticDictionaryWorkers(machine, state),
            };
            if (!done) continue;
            std.debug.assert(machine.frames.items.len == frames_before);
            machine.frames.items.len -= 1;
            frame.destroy(self.allocator);
        }
    }

    /// Begin a worker call's hidden dictionary arguments: the span directly
    /// when the worker takes none, or null with the call's frame pushed.
    fn beginDictionaryCallArgs(self: *Builder, machine: *DictionaryArgsMachine, request: DictionaryCallRequest) Allocator.Error!?Span {
        const worker = self.plan.workers.items[@intFromEnum(request.worker_id)];
        if (worker.hidden_dicts.len == 0) return .{};
        // Nested planning can grow the table `request.arg_types` points into.
        const arg_types = try self.allocator.dupe(CheckedTypeIdentity, request.arg_types);
        var arg_types_owned = true;
        defer if (arg_types_owned) self.allocator.free(arg_types);
        const relation = request.relation orelse self.active_stored_substitution;
        const requirement_substitution = relation orelse
            try self.appendSchemeRepSubstitutions(request.scheme_substitution);

        const worker_function = (self.repQuery().functionChildren(worker.rep)) orelse
            boxyPlanInvariant("boxy worker call target with hidden dictionaries was not a function worker");
        if (worker_function.arg_count != arg_types.len) {
            boxyPlanInvariant("boxy worker call hidden dictionary mapping saw mismatched function arity");
        }

        const state = try self.allocator.create(DictionaryCallArgs);
        arg_types_owned = false;
        state.* = .{
            .worker_id = request.worker_id,
            .caller_id = request.caller_id,
            .arg_types = arg_types,
            .ret_type = request.ret_type,
            .evidence_view = request.evidence_view,
            .evidence = request.evidence,
            .env = request.env,
            .hidden_dicts = worker.hidden_dicts,
            .requirement_substitution = requirement_substitution,
            .binds_requirement_variables = request.scheme_substitution == null,
            .relates_types = relation != null,
            .worker_function = worker_function,
            .fn_children_span = self.plan.representations.items[@intFromEnum(worker_function.rep)].children,
            .body_param_start = @intCast(worker.body_hidden_dicts.start - worker.hidden_dicts.start),
        };
        errdefer {
            state.deinit(self.allocator);
            self.allocator.destroy(state);
        }
        var seen_substitutions = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen_substitutions.deinit();

        // The checked scheme substitution also names receivers reachable only
        // through method constraints. Argument/result traversal cannot supply
        // those body dictionaries; consume their exact producer-owned slots.
        for (self.plan.schemeRepSubstitutionSlice(requirement_substitution)) |pair| {
            if (self.plan.representations.items[@intFromEnum(pair.scheme_rep)].dictionaries.len != 0) {
                try state.substitutions.put(self.allocator, pair.scheme_rep, pair.site_rep);
            }
        }

        const definition_type = self.workerCheckedTypeForSource(worker.source, worker.checked_type);
        if (!typeRefEql(definition_type, worker.checked_type)) {
            const definition_rep = self.plan.repForSourceType(definition_type) orelse
                boxyPlanInvariant("boxy specialized worker definition type was not analyzed");
            const definition_function = (self.repQuery().functionChildren(definition_rep)) orelse
                boxyPlanInvariant("boxy specialized worker definition was not callable");
            if (definition_function.arg_count != worker_function.arg_count) {
                boxyPlanInvariant("boxy specialized worker definition arity disagreed with worker boundary");
            }
            const definition_children_span = self.plan.representations.items[@intFromEnum(definition_function.rep)].children;
            for (0..worker_function.arg_count) |index| {
                const definition_arg = self.plan.children.items[definition_children_span.start + definition_function.args_start + index];
                const worker_arg = self.plan.children.items[state.fn_children_span.start + worker_function.args_start + index];
                try self.collectCallDictionaryRepSubstitutions(
                    definition_arg.rep,
                    worker_arg.rep,
                    &state.substitutions,
                    &seen_substitutions,
                );
            }
            try self.collectCallDictionaryRepSubstitutions(
                definition_function.ret,
                worker_function.ret,
                &state.substitutions,
                &seen_substitutions,
            );
        }

        var arg_index: usize = 0;
        while (arg_index < worker_function.arg_count) : (arg_index += 1) {
            const worker_child = self.plan.children.items[state.fn_children_span.start + worker_function.args_start + arg_index];
            const arg_rep = self.plan.repForSourceType(state.arg_types[arg_index]) orelse
                boxyPlanInvariant("boxy worker call argument type was not analyzed");
            try self.collectCallDictionaryRepSubstitutions(worker_child.rep, arg_rep, &state.substitutions, &seen_substitutions);
        }
        const ret_rep = self.plan.repForSourceType(state.ret_type) orelse
            boxyPlanInvariant("boxy worker call result type was not analyzed");
        try self.collectCallDictionaryRepSubstitutions(worker_function.ret, ret_rep, &state.substitutions, &seen_substitutions);

        if (state.body_param_start > state.hidden_dicts.len) {
            boxyPlanInvariant("boxy worker body dictionary span was outside its hidden dictionary span");
        }
        try self.pushDictionaryFrame(machine, .{ .call = state });
        return null;
    }

    /// The call's types at the callee's argument and result positions.
    fn requirementCallInstantiation(self: *const Builder, call: *const DictionaryCallArgs) RequirementCallInstantiation {
        return .{
            .substitutions = &call.substitutions,
            .scheme_pairs = self.plan.schemeRepSubstitutionSlice(call.requirement_substitution),
            .worker_arg_reps = self.plan.children.items[call.fn_children_span.start + call.worker_function.args_start ..][0..call.worker_function.arg_count],
            .call_arg_types = call.arg_types,
            .worker_ret_rep = call.worker_function.ret,
            .call_ret_type = call.ret_type,
        };
    }

    fn stepDictionaryCallArgs(self: *Builder, machine: *DictionaryArgsMachine, state: *DictionaryCallArgs) Allocator.Error!bool {
        switch (state.stage) {
            .next_param => {},
            .after_source => {
                const evidence_source = machine.source_result;
                state.stage = .next_param;
                try self.continueDictionaryParam(machine, state, evidence_source);
                return false;
            },
            .after_static => |pending_static| {
                state.stage = .next_param;
                try self.finishStaticDictionaryParam(state, pending_static.source_rep, pending_static.source_env, machine.span_result);
                return false;
            },
        }
        if (state.param_index == state.hidden_dicts.len) {
            if (state.pending.items.len != state.hidden_dicts.len) {
                boxyPlanInvariant("boxy worker call hidden dictionary mapping did not cover every worker dictionary param");
            }
            if (state.evidence) |entries| {
                if (state.next_evidence > entries.len) {
                    boxyPlanInvariant("boxy callable use exhausted its checked dictionary evidence");
                }
            }
            if (state.binds_requirement_variables) try self.bindRequirementVariables(state);
            if (state.derived_receivers) {
                for (state.pending.items) |*arg| arg.derived_substitution = state.requirement_substitution;
            }
            const start: u32 = @intCast(self.plan.direct_call_hidden_dict_args.items.len);
            try self.plan.direct_call_hidden_dict_args.appendSlice(self.allocator, state.pending.items);
            machine.span_result = .{ .start = start, .len = @intCast(state.pending.items.len) };
            return true;
        }
        const param = self.plan.hidden_dictionary_params.items[state.hidden_dicts.start + state.param_index];
        if (param.scheme_param != null and param.evidence_index == null) {
            const caller = state.caller_id orelse boxyPlanInvariant("captured codec dictionary had no calling worker");
            const source = try self.requireWorkerSchemeDictionary(caller, param.scheme_param.?);
            try state.pending.append(self.allocator, .{
                .worker_dictionaries = param.dictionaries,
                .source_type = source.source_type,
                .rep = source.rep,
                .source = .{ .bound_dictionaries = source.dictionaries },
            });
            state.param_index += 1;
            return false;
        }
        if (param.evidence_index) |index| state.next_evidence = index;
        const evidence_source = try self.beginEvidenceDictionarySource(
            machine,
            state.evidence_view,
            state.evidence,
            &state.next_evidence,
            param.dictionaries,
            state.requirement_substitution,
            state.caller_id,
            if (param.scheme_param) |key| key.callable_contract else null,
            param.evidence_index != null,
        ) orelse {
            state.stage = .after_source;
            return false;
        };
        try self.continueDictionaryParam(machine, state, evidence_source);
        return false;
    }

    /// Name, in the call's requirement substitution, each scheme variable of
    /// the callee that only its requirements name and that no substitution
    /// names yet: relating a requirement's type to the call types of the
    /// method this call selected for it binds the variable, as checking binds
    /// it when it instantiates the requirement against that method.
    fn bindRequirementVariables(self: *Builder, state: *DictionaryCallArgs) Allocator.Error!void {
        const worker = self.plan.workers.items[@intFromEnum(state.worker_id)];
        const scheme = self.workerSchemeVars(worker.source) orelse return;
        var bound = std.AutoHashMapUnmanaged(TypeRepId, TypeRepId).empty;
        defer bound.deinit(self.allocator);
        var scheme_reps = std.AutoHashMapUnmanaged(TypeRepId, void).empty;
        defer scheme_reps.deinit(self.allocator);
        for (scheme.vars) |scheme_var| {
            const rep = self.plan.repForSourceType(typeRef(scheme.view, scheme_var)) orelse continue;
            try scheme_reps.put(self.allocator, rep, {});
        }
        for (self.plan.schemeRepSubstitutionSlice(state.requirement_substitution)) |pair| {
            try bound.put(self.allocator, pair.scheme_rep, pair.site_rep);
        }
        var added = std.ArrayList(SchemeRepSubstitution).empty;
        defer added.deinit(self.allocator);
        for (state.pending.items, 0..) |arg, arg_index| {
            const hidden = self.plan.hidden_dictionary_params.items[state.hidden_dicts.start + arg_index];
            if (arg.method_evidence.len != hidden.dictionaries.len) continue;
            for (self.plan.dictionarySlice(hidden.dictionaries), 0..) |requirement, method_index| {
                const method = self.plan.dictionary_method_evidence.items[arg.method_evidence.start + method_index];
                switch (method.resolution) {
                    .worker, .builtin_numeral => {},
                    .structural, .constraint, .checked_error, .unreachable_value => continue,
                }
                const requirement_rep = self.plan.repForSourceType(requirement.fn_ty) orelse
                    boxyPlanInvariant("dictionary requirement type was not analyzed");
                const function = self.repQuery().functionChildren(requirement_rep) orelse
                    boxyPlanInvariant("dictionary requirement type was not callable");
                const instantiated = method.instantiation_rep != null or method.instantiation_ret_type != null;
                const shape = try self.dictionaryMethodCallShape(method, instantiated);
                defer self.allocator.free(shape.arg_reps);
                if (shape.arg_reps.len != function.arg_count) {
                    boxyPlanInvariant("planned dictionary method arity disagreed with its requirement");
                }
                for (0..function.arg_count + 1) |position| {
                    const requirement_position = if (position == function.arg_count)
                        function.ret
                    else
                        self.plan.children.items[self.plan.representations.items[@intFromEnum(function.rep)].children.start + function.args_start + position].rep;
                    const call_position = if (position == function.arg_count) shape.ret_rep else shape.arg_reps[position];
                    const pairs = try self.storedUseSchemeRepSubstitutions(requirement_position, call_position);
                    for (self.plan.schemeRepSubstitutionSlice(pairs)) |pair| {
                        if (!scheme_reps.contains(pair.scheme_rep)) continue;
                        const entry = try bound.getOrPut(self.allocator, pair.scheme_rep);
                        if (entry.found_existing) continue;
                        entry.value_ptr.* = pair.site_rep;
                        try added.append(self.allocator, pair);
                    }
                }
            }
        }
        if (added.items.len == 0) return;
        const start: u32 = @intCast(self.plan.scheme_rep_substitutions.items.len);
        try self.plan.scheme_rep_substitutions.ensureUnusedCapacity(self.allocator, state.requirement_substitution.len + added.items.len);
        for (0..state.requirement_substitution.len) |index| {
            self.plan.scheme_rep_substitutions.appendAssumeCapacity(self.plan.scheme_rep_substitutions.items[state.requirement_substitution.start + index]);
        }
        self.plan.scheme_rep_substitutions.appendSliceAssumeCapacity(added.items);
        state.requirement_substitution = .{ .start = start, .len = state.requirement_substitution.len + @as(u32, @intCast(added.items.len)) };
        state.derived_receivers = true;
    }

    /// The representation of a requirement whose receiver checking reached
    /// only through another requirement's constraint callable, when the call
    /// derives its evidence from the callable (no checked evidence vector, or
    /// a `from_callable` slot). The receiver is the checked path walked over
    /// the call types of the method this call selected for the requirement
    /// owning that constraint callable. Null for every other requirement.
    fn constraintCallableDerivedRep(
        self: *Builder,
        state: *const DictionaryCallArgs,
        param: HiddenDictionaryParam,
        evidence_source: CallableEvidenceSource,
    ) Allocator.Error!?TypeRepId {
        if (evidence_source.rep != null or evidence_source.bound_evidence != null) return null;
        const evidence_index = param.evidence_index orelse return null;
        const scheme_param = param.scheme_param orelse return null;
        if (scheme_param.callable_contract != null) return null;
        if (state.evidence) |entries| {
            if (evidence_index >= entries.len or entries[evidence_index].resolution != .from_callable) return null;
        }
        const worker = self.plan.workers.items[@intFromEnum(state.worker_id)];
        const schema = self.workerEvidenceParams(worker.source) orelse
            boxyPlanInvariant("evidence-indexed worker dictionary had no checked evidence parameters");
        if (evidence_index >= schema.params.len) {
            boxyPlanInvariant("worker dictionary evidence index exceeded its checked parameter vector");
        }
        const schema_param = schema.params[evidence_index];
        const root = switch (schema_param.source) {
            .constraint_callable => |root| root,
            .scheme_callable, .scheme_requirement, .use_site_only, .explicit_default, .erased_row_remainder => return null,
        };
        var path_steps = std.ArrayListUnmanaged(static_dispatch.EvidencePathStep).empty;
        defer path_steps.deinit(self.allocator);
        const path = try schema.view.checked_procedure_templates.evidenceParamPath(self.allocator, schema_param, &path_steps);
        if (path.len == 0) boxyPlanInvariant("constraint-callable evidence parameter had no checked path");

        // The requirement owning the constraint callable is planned earlier
        // in this call; its selected method's call types instantiate the
        // callable the path is written against.
        const root_fn_ty = typeRef(schema.view, root.callable_ty);
        for (state.pending.items, 0..) |arg, arg_index| {
            const hidden = self.plan.hidden_dictionary_params.items[state.hidden_dicts.start + arg_index];
            for (self.plan.dictionarySlice(hidden.dictionaries), 0..) |requirement, method_index| {
                if (!typeRefEql(requirement.fn_ty, root_fn_ty)) continue;
                if (arg.method_evidence.len != hidden.dictionaries.len) {
                    boxyPlanInvariant("constraint callable owner had no method selected at this call");
                }
                const method = self.plan.dictionary_method_evidence.items[arg.method_evidence.start + method_index];
                switch (method.resolution) {
                    .worker, .builtin_numeral => {},
                    .structural, .constraint, .checked_error, .unreachable_value => boxyPlanInvariant("constraint callable owner's method had no concrete call types"),
                }
                const instantiated = method.instantiation_rep != null or method.instantiation_ret_type != null;
                const shape = try self.dictionaryMethodCallShape(method, instantiated);
                defer self.allocator.free(shape.arg_reps);
                const start = switch (path[0].stepKind()) {
                    .fn_arg => if (path[0].data < shape.arg_reps.len)
                        shape.arg_reps[path[0].data]
                    else
                        boxyPlanInvariant("constraint-callable evidence path argument exceeded its method's arity"),
                    .fn_ret => shape.ret_rep,
                    .alias_arg,
                    .alias_backing,
                    .nominal_arg,
                    .nominal_backing,
                    .tuple_elem,
                    .record_field,
                    .tag_payload_tag,
                    .tag_payload_index,
                    => boxyPlanInvariant("constraint-callable evidence path did not begin at its callable boundary"),
                };
                return try self.walkEvidenceRepPath(schema.view, start, path[1..]);
            }
        }
        boxyPlanInvariant("constraint-callable requirement preceded the requirement owning its constraint callable");
    }

    /// Plan the current parameter's dictionary once its evidence source is
    /// known.
    fn continueDictionaryParam(
        self: *Builder,
        machine: *DictionaryArgsMachine,
        state: *DictionaryCallArgs,
        evidence_source: CallableEvidenceSource,
    ) Allocator.Error!void {
        const param = self.plan.hidden_dictionary_params.items[state.hidden_dicts.start + state.param_index];
        const caller_id = state.caller_id;
        if (evidence_source.bound_evidence) |bound| {
            const caller = caller_id orelse boxyPlanInvariant("forwarded checked dictionary had no calling worker");
            const source = try self.requireWorkerSchemeDictionary(caller, bound);
            try state.pending.append(self.allocator, .{
                .worker_dictionaries = param.dictionaries,
                .source_type = source.source_type,
                .rep = source.rep,
                .method_evidence = evidence_source.method_evidence,
                .source = .{ .bound_dictionaries = source.dictionaries },
            });
            state.param_index += 1;
            return;
        }
        const derived_rep = try self.constraintCallableDerivedRep(state, param, evidence_source);
        if (derived_rep) |rep| {
            // The receiver is one of the callee's scheme variables, which
            // requirement types are written in; the call's substitution now
            // names it.
            const start: u32 = @intCast(self.plan.scheme_rep_substitutions.items.len);
            try self.plan.scheme_rep_substitutions.ensureUnusedCapacity(self.allocator, state.requirement_substitution.len + 1);
            for (0..state.requirement_substitution.len) |index| {
                self.plan.scheme_rep_substitutions.appendAssumeCapacity(self.plan.scheme_rep_substitutions.items[state.requirement_substitution.start + index]);
            }
            self.plan.scheme_rep_substitutions.appendAssumeCapacity(.{ .scheme_rep = param.rep, .site_rep = rep });
            state.requirement_substitution = .{ .start = start, .len = state.requirement_substitution.len + 1 };
            state.derived_receivers = true;
        }
        const substituted_rep = derived_rep orelse state.substitutions.get(param.rep);
        if (state.param_index < state.body_param_start and substituted_rep == null and evidence_source.rep == null) {
            boxyPlanInvariant("boxy callable dictionary parameter had no checked call substitution or dispatch evidence");
        }
        const env_bindings = self.plan.derivedEnvBindings(state.env);
        const call_rep = evidence_source.rep orelse substituted_rep orelse param.rep;
        // A source that is a formal of the enclosing derived backing is
        // its use's actual; one that reads such formals is instantiated
        // at them.
        const argument_rep = self.repQuery().dictionaryArgumentIdentityRep(derivedEnvActual(env_bindings, call_rep) orelse call_rep);
        // A call no worker makes (a root or a compile-time evaluation)
        // has nothing to bind a variable its types still hold, so the
        // variable is at its checked default there.
        const source_rep = if (caller_id == null and self.repIsUnboundVariable(argument_rep))
            try self.sharedVariableClosedRep(argument_rep, .no_caller)
        else
            argument_rep;
        const source_env: u32 = if (try self.plan.repReadsDerivedFormal(self.allocator, source_rep, env_bindings)) state.env else 0;
        const source_rep_dictionaries = self.plan.representations.items[@intFromEnum(source_rep)].dictionaries;
        const bound_dictionaries = if (substituted_rep == null and evidence_source.rep == null)
            param.dictionaries
        else
            source_rep_dictionaries;
        const source_is_bound = evidence_source.rep == null and caller_id != null and
            self.workerBindsDictionarySpan(caller_id.?, bound_dictionaries);
        const source_is_defaulted = evidence_source.rep == null and substituted_rep == null and
            self.defaultedDictionaryOwner(source_rep) != null;
        if (!source_is_bound and !source_is_defaulted and substituted_rep == null and evidence_source.rep == null) {
            boxyPlanInvariant("boxy callable body dictionary had neither a bound caller dictionary nor concrete checked use-site evidence");
        }
        if (source_is_bound) {
            try state.pending.append(self.allocator, .{
                .worker_dictionaries = param.dictionaries,
                .source_type = self.plan.representations.items[@intFromEnum(source_rep)].source_type,
                .rep = source_rep,
                .method_evidence = evidence_source.method_evidence,
                .source = .{ .bound_dictionaries = bound_dictionaries },
                .env = 0,
            });
            state.param_index += 1;
            return;
        }
        if (evidence_source.method_evidence.len != 0 and evidence_source.method_evidence.len != param.dictionaries.len) {
            boxyPlanInvariant("static dictionary checked evidence did not cover every method requirement");
        }
        const workers = try self.allocator.create(StaticDictionaryWorkers);
        workers.* = .{
            .call = state,
            .source_rep_id = source_rep,
            .env = source_env,
            .worker_dictionaries = param.dictionaries,
            .method_evidence = evidence_source.method_evidence,
        };
        state.stage = .{ .after_static = .{ .source_rep = source_rep, .source_env = source_env } };
        try self.pushDictionaryFrame(machine, .{ .static_workers = workers });
    }

    fn finishStaticDictionaryParam(
        self: *Builder,
        state: *DictionaryCallArgs,
        source_rep: TypeRepId,
        source_env: u32,
        planned_method_evidence: Span,
    ) Allocator.Error!void {
        const param = self.plan.hidden_dictionary_params.items[state.hidden_dicts.start + state.param_index];
        // A call relating the worker's variables to its types, and one that
        // derives receivers from its callable, names them exactly as a
        // checked site substitution does, so its dictionaries' adapters read
        // the same pairs.
        if (state.derived_receivers or state.relates_types) {
            const substitution = state.requirement_substitution;
            for (0..planned_method_evidence.len) |index| {
                const method = &self.plan.dictionary_method_evidence.items[planned_method_evidence.start + index];
                if (method.requirement_substitution.len == 0) method.requirement_substitution = substitution;
            }
        }
        try self.registerStructuralDictionaryDerivations(state.caller_id, source_rep, source_env, planned_method_evidence);
        try state.pending.append(self.allocator, .{
            .worker_dictionaries = param.dictionaries,
            .source_type = self.plan.representations.items[@intFromEnum(source_rep)].source_type,
            .rep = source_rep,
            .method_evidence = planned_method_evidence,
            .source = .{ .static_rep = source_rep },
            .env = source_env,
        });
        state.param_index += 1;
    }

    /// Select the checked evidence for a requirement group: the source
    /// directly when it needs no nested call, or null with its frame pushed.
    fn beginEvidenceDictionarySource(
        self: *Builder,
        machine: *DictionaryArgsMachine,
        maybe_view: ?ModuleView,
        maybe_entries: ?[]const static_dispatch.CheckedEvidence,
        next_evidence: *usize,
        dictionaries: Span,
        requirement_substitution: Span,
        caller_id: ?WorkerPlanId,
        callable_contract: ?u32,
        indexed_evidence: bool,
    ) Allocator.Error!?CallableEvidenceSource {
        const entries = maybe_entries orelse return .{};
        const view = maybe_view orelse
            boxyPlanInvariant("boxy callable evidence had no checked module view");
        if (next_evidence.* + dictionaries.len > entries.len) return .{};

        const state = try self.allocator.create(EvidenceSourceState);
        state.* = .{
            .view = view,
            .dictionaries = dictionaries,
            .requirement_substitution = requirement_substitution,
            .caller_id = caller_id,
            .callable_contract = callable_contract,
        };
        var pushed = false;
        defer if (!pushed) {
            state.deinit(self.allocator);
            self.allocator.destroy(state);
        };
        try state.selected.ensureTotalCapacity(self.allocator, dictionaries.len);
        while (state.selected.items.len < dictionaries.len and next_evidence.* < entries.len) {
            var entry = entries[next_evidence.*];
            next_evidence.* += 1;
            // An indexed singleton is the exact schema requirement, including
            // literals reached only through constraints. Signature groups still
            // exclude standalone entries that require no runtime dictionary.
            if ((!indexed_evidence or dictionaries.len != 1) and !entry.runtime_dictionary and
                !self.plan.dictionaries.items[dictionaries.start].compile_time_only) continue;
            if (callable_contract) |contract| {
                if (entry.callable_contracts.len != 0) {
                    if (contract >= entry.callable_contracts.len)
                        boxyPlanInvariant("checked dictionary contract index exceeded its side vector");
                    entry = view.static_dispatch_plans.evidence_refs[entry.callable_contracts.start + contract];
                } else {
                    // Omitted contracts explicitly authorize deriving this
                    // target's callable from the receiving relation.
                    entry.resolution = .from_callable;
                }
            }
            state.selected.appendAssumeCapacity(entry);
        }
        if (state.selected.items.len != dictionaries.len) return .{};
        try state.methods.ensureTotalCapacity(self.allocator, state.selected.items.len);
        pushed = true;
        try self.pushDictionaryFrame(machine, .{ .source = state });
        return null;
    }

    fn stepEvidenceDictionarySource(self: *Builder, machine: *DictionaryArgsMachine, state: *EvidenceSourceState) Allocator.Error!bool {
        if (state.awaiting) |awaiting| {
            var planned = awaiting;
            planned.nested_dict_args = machine.span_result;
            planned.requirement_substitution = state.requirement_substitution;
            try self.contextualizeDictionaryMethod(&planned, state.caller_id);
            state.methods.appendAssumeCapacity(planned);
            state.awaiting = null;
            state.index += 1;
        }
        const view = state.view;
        while (state.index < state.selected.items.len) {
            const entry = state.selected.items[state.index];
            // Analysis below can append requirements, so each one is read by id.
            const requirement = self.plan.dictionaries.items[state.dictionaries.start + state.index];
            var planned: DictionaryMethodEvidence = switch (entry.resolution) {
                .direct => |node_id| blk: {
                    const node = view.static_dispatch_plans.evidenceNode(node_id);
                    const dispatcher = node.dispatcher_ty orelse entry.dispatcher_ty;
                    const dispatcher_type = typeRef(view, dispatcher);
                    const rep = try self.analyzeType(view, dispatcher);
                    if (state.found) |existing| {
                        if (existing != rep) {
                            boxyPlanInvariant("one callable dictionary captured evidence for two dispatcher types");
                        }
                    } else {
                        state.found = rep;
                    }
                    const target_view = switch (node.target.kind) {
                        .procedure => |procedure| self.moduleForCheckedModuleId(procedure.template.artifact),
                        .local_proc, .structural => view,
                    };
                    const callable_type = selectedDispatchCallableType(view, target_view, node);
                    const source = self.workerSourceForMethodTarget(.{
                        .view = target_view,
                        .target = node.target,
                    }, dispatcher_type, node.generated_codec_derivation);
                    _ = try self.analyzeType(target_view, node.target.callable_ty);
                    _ = try self.analyzeType(self.moduleForId(callable_type.module), callable_type.ty);
                    if (requirement.compile_time_only) {
                        const owner = methodOwnerForModuleType(view, dispatcher) orelse self.defaultedDictionaryOwner(rep);
                        if (owner != null and owner.? == .builtin) break :blk .{
                            .requirement_type = requirement.fn_ty,
                            .callable_type = callable_type,
                            .resolution = .builtin_numeral,
                        };
                    }
                    const worker = try self.ensureWorker(
                        source,
                        self.workerCheckedTypeForSource(source, callable_type),
                        null,
                    );
                    const evidence_edge: DictionaryMethodEvidence.EvidenceEdge = .{ .module = view.key, .node = node_id };
                    try self.analyzeEvidenceEdgeSchemeSubstitution(evidence_edge);
                    const method: DictionaryMethodEvidence = .{
                        .requirement_type = requirement.fn_ty,
                        .callable_type = callable_type,
                        .resolution = .{ .worker = worker },
                        .evidence_edge = evidence_edge,
                    };
                    const nested = try self.beginDictionaryMethodHiddenArgs(
                        machine,
                        worker,
                        callable_type,
                        view,
                        // A target reached through a procedure alias derives
                        // its evidence from its callable.
                        switch (node.nested) {
                            .resolved => view.static_dispatch_plans.nestedEvidence(node),
                            .from_callable => null,
                        },
                        evidence_edge,
                        state.caller_id,
                    ) orelse {
                        state.awaiting = method;
                        return false;
                    };
                    var with_nested = method;
                    with_nested.nested_dict_args = nested;
                    try self.contextualizeDictionaryMethod(&with_nested, state.caller_id);
                    break :blk with_nested;
                },
                .structural => |structural| blk: {
                    const rep = try self.analyzeType(view, structural.dispatcher_ty);
                    if (state.found) |existing| {
                        if (existing != rep) {
                            boxyPlanInvariant("one callable dictionary captured evidence for two dispatcher types");
                        }
                    } else {
                        state.found = rep;
                    }
                    const callable_type = typeRef(view, structural.callable_ty);
                    _ = try self.analyzeType(view, structural.callable_ty);
                    const structural_kind = structural.derivation.kind();
                    const resolution: DictionaryMethodEvidence.Resolution = switch (structural_kind) {
                        .equality, .hash => .{ .structural = structural_kind },
                        .parser, .encoder => blk_worker: {
                            const derivation_id = structural.generated_codec_derivation orelse
                                boxyPlanInvariant("structural codec evidence had no checked derivation reference");
                            if (@intFromEnum(derivation_id) >= view.static_dispatch_plans.generated_codec_derivations.len) {
                                boxyPlanInvariant("structural codec evidence referenced a missing checked derivation");
                            }
                            break :blk_worker .{ .worker = try self.ensureWorker(
                                .{ .generated_codec = .{
                                    .kind = if (structural_kind == .parser) .parser_constructor else .encoder_constructor,
                                    .shape = typeRef(view, structural.dispatcher_ty),
                                    .contract_derivation = derivation_id,
                                } },
                                callable_type,
                                null,
                            ) };
                        },
                        .map, .map_effectful => boxyPlanInvariant("derived map evidence reached runtime dictionary planning"),
                    };
                    break :blk .{
                        .requirement_type = requirement.fn_ty,
                        .callable_type = callable_type,
                        .resolution = resolution,
                    };
                },
                .constraint => |constraint| blk: {
                    if (state.selected.items.len == 1) {
                        if (constraint.scheme_param) |param| {
                            state.bound_evidence = .{ .module = view.key, .param = param, .callable_contract = constraint.callable_contract };
                        } else if (requirement.compile_time_only) {
                            const caller = state.caller_id orelse boxyPlanInvariant("forwarded numeral proof had no lexical caller");
                            state.bound_evidence = self.workerEvidenceKey(caller, constraint.index);
                        }
                    }
                    break :blk .{
                        .requirement_type = requirement.fn_ty,
                        .callable_type = requirement.fn_ty,
                        .resolution = .constraint,
                    };
                },
                .from_callable, .from_scheme => blk: {
                    if (state.callable_contract != null) state.found = try self.analyzeType(view, entry.dispatcher_ty);
                    break :blk .{
                        .requirement_type = requirement.fn_ty,
                        .callable_type = requirement.fn_ty,
                        .resolution = .constraint,
                    };
                },
                .checked_error => .{
                    .requirement_type = requirement.fn_ty,
                    .callable_type = requirement.fn_ty,
                    .resolution = .checked_error,
                },
                .unreachable_value => .{
                    .requirement_type = requirement.fn_ty,
                    .callable_type = requirement.fn_ty,
                    .resolution = .unreachable_value,
                },
            };
            planned.requirement_substitution = state.requirement_substitution;
            state.methods.appendAssumeCapacity(planned);
            state.index += 1;
        }
        const method_start: u32 = @intCast(self.plan.dictionary_method_evidence.items.len);
        try self.plan.dictionary_method_evidence.appendSlice(self.allocator, state.methods.items);
        machine.source_result = .{
            .rep = state.found,
            .bound_evidence = state.bound_evidence,
            .method_evidence = .{ .start = method_start, .len = @intCast(state.methods.items.len) },
        };
        return true;
    }

    /// Begin a dictionary method worker's own hidden dictionary arguments at
    /// its evidence callable's types.
    fn beginDictionaryMethodHiddenArgs(
        self: *Builder,
        machine: *DictionaryArgsMachine,
        worker_id: WorkerPlanId,
        callable_type: CheckedTypeIdentity,
        evidence_view: ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
        evidence_edge: DictionaryMethodEvidence.EvidenceEdge,
        caller_id: ?WorkerPlanId,
    ) Allocator.Error!?Span {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        if (worker.hidden_dicts.len == 0) return .{};

        const callable_rep = self.plan.repForSourceType(callable_type) orelse
            boxyPlanInvariant("dictionary method callable type was not analyzed");
        const function = (self.repQuery().functionChildren(callable_rep)) orelse
            boxyPlanInvariant("dictionary method checked target was not callable");
        const arg_types = try self.allocator.alloc(CheckedTypeIdentity, function.arg_count);
        defer self.allocator.free(arg_types);
        const children_span = self.plan.representations.items[@intFromEnum(function.rep)].children;
        for (arg_types, 0..) |*arg_type, index| {
            const child = self.plan.children.items[children_span.start + function.args_start + index];
            arg_type.* = self.plan.representations.items[@intFromEnum(child.rep)].source_type;
        }
        const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
        // A nested dictionary the checker forwards from a scheme requirement
        // is the dictionary the frame building this one holds for it.
        return try self.beginDictionaryCallArgs(machine, .{
            .worker_id = worker_id,
            .caller_id = caller_id,
            .arg_types = arg_types,
            .ret_type = ret_type,
            .evidence_view = evidence_view,
            .evidence = evidence,
            .scheme_substitution = self.evidenceEdgeSchemeSubstitution(worker_id, evidence_edge),
            .relation = try self.evidenceEdgeCallableRelation(worker_id, callable_type, evidence_edge),
            .env = 0,
        });
    }

    fn stepStaticDictionaryWorkers(self: *Builder, machine: *DictionaryArgsMachine, state: *StaticDictionaryWorkers) Allocator.Error!bool {
        if (state.awaiting) |awaiting| {
            var method = awaiting.method;
            method.nested_dict_args = machine.span_result;
            if (awaiting.requirement_substitution) |substitution| method.requirement_substitution = substitution;
            try self.contextualizeDictionaryMethod(&method, state.call.caller_id);
            try state.planned.append(self.allocator, method);
            state.awaiting = null;
            state.method_index += 1;
        }
        // analyzeType/ensureWorker can append dictionary requirements, growing
        // the pool and invalidating any held slice; requirements are re-read
        // by index on every iteration.
        while (state.method_index < state.worker_dictionaries.len) {
            const requirement = self.plan.dictionaries.items[state.worker_dictionaries.start + state.method_index];
            // Checked evidence fixes a method unless it only names the
            // constraint, whose method is planned here at the checked
            // requirement substitution.
            var checked_substitution: ?Span = null;
            if (state.method_evidence.len != 0) {
                const method = self.plan.dictionary_method_evidence.items[state.method_evidence.start + state.method_index];
                const fixed = switch (method.resolution) {
                    // A rejected or unreachable dispatch fixes a slot whose
                    // method crashes when called.
                    .worker, .builtin_numeral, .checked_error, .unreachable_value => true,
                    .structural => |kind| switch (kind) {
                        .equality, .hash => true,
                        .parser, .encoder => boxyPlanInvariant("structural codec dictionary evidence had no generated worker"),
                        .map, .map_effectful => boxyPlanInvariant("derived map evidence reached static dictionary worker planning"),
                    },
                    .constraint => false,
                };
                if (fixed) {
                    try state.planned.append(self.allocator, method);
                    state.method_index += 1;
                    continue;
                }
                checked_substitution = method.requirement_substitution;
            }
            const planned = try self.beginStaticDictionaryMethodEvidence(machine, state, requirement, checked_substitution) orelse return false;
            var method = planned;
            try self.contextualizeDictionaryMethod(&method, state.call.caller_id);
            if (checked_substitution) |substitution| method.requirement_substitution = substitution;
            try state.planned.append(self.allocator, method);
            state.method_index += 1;
        }
        const start: u32 = @intCast(self.plan.dictionary_method_evidence.items.len);
        try self.plan.dictionary_method_evidence.appendSlice(self.allocator, state.planned.items);
        machine.span_result = .{ .start = start, .len = @intCast(state.planned.items.len) };
        return true;
    }

    /// Plan a static dictionary's method for `requirement`: the evidence
    /// directly when it needs no nested call, or null with the method
    /// waiting in `state` and the nested call's frame pushed.
    fn beginStaticDictionaryMethodEvidence(
        self: *Builder,
        machine: *DictionaryArgsMachine,
        state: *StaticDictionaryWorkers,
        requirement: DictionaryRequirement,
        checked_substitution: ?Span,
    ) Allocator.Error!?DictionaryMethodEvidence {
        const source_rep_id = state.source_rep_id;
        const source_rep = self.plan.representations.items[@intFromEnum(source_rep_id)];
        const source_view = self.moduleForId(source_rep.source_type.module);
        const requirement_view = self.moduleForId(requirement.source_type.module);
        _ = try self.analyzeType(requirement_view, requirement.fn_ty.ty);
        const owner = methodOwnerForModuleType(source_view, source_rep.source_type.ty) orelse
            self.defaultedDictionaryOwner(source_rep_id);
        if (owner) |method_owner| {
            if (self.lookupMethodTarget(source_view, method_owner, requirement_view, requirement.fn_name)) |lookup| {
                // A compiler-derived equality or hash has no worker: the slot
                // runs the structural method over the owner's type.
                if (lookup.target.kind == .structural) switch (lookup.target.kind.structural) {
                    .equality, .hash => |kind| {
                        _ = try self.analyzeType(requirement_view, requirement.fn_ty.ty);
                        return .{
                            .requirement_type = requirement.fn_ty,
                            .callable_type = requirement.fn_ty,
                            .resolution = .{ .structural = kind },
                        };
                    },
                    .parser, .encoder, .map, .map_effectful => {},
                };
                const source = self.workerSourceForMethodTarget(lookup, source_rep.source_type, null);
                const callable_type = CheckedTypeIdentity{ .module = lookup.view.key, .ty = lookup.target.callable_ty };
                _ = try self.analyzeType(lookup.view, lookup.target.callable_ty);
                const worker = try self.ensureWorker(source, callable_type, null);
                const instantiation = try self.staticDictionaryMethodInstantiation(self.requirementCallInstantiation(state.call), source_rep_id, requirement, callable_type);
                const method: DictionaryMethodEvidence = .{
                    .requirement_type = requirement.fn_ty,
                    .callable_type = callable_type,
                    .resolution = .{ .worker = worker },
                    .instantiation_arg_types = instantiation.arg_types,
                    .instantiation_ret_type = instantiation.ret_type,
                    .instantiation_rep = instantiation.rep,
                };
                state.awaiting = .{ .method = method, .requirement_substitution = checked_substitution };
                const nested = try self.beginDictionaryCallArgs(machine, .{
                    .worker_id = worker,
                    .caller_id = state.call.caller_id,
                    .arg_types = self.plan.dictionaryMethodCallTypeSlice(instantiation.arg_types),
                    .ret_type = instantiation.ret_type,
                    .evidence_view = null,
                    .evidence = null,
                    .scheme_substitution = null,
                    .env = state.env,
                }) orelse return null;
                state.awaiting = null;
                var with_nested = method;
                with_nested.nested_dict_args = nested;
                return with_nested;
            }
        }
        if (owner == null and self.repSealsUninhabited(source_rep)) {
            switch (static_dispatch.unpinnedDispatchResolution(self.structuralKindForRequirement(requirement, requirement_view))) {
                .structural => {},
                .unreachable_value => return .{
                    .requirement_type = requirement.fn_ty,
                    .callable_type = requirement.fn_ty,
                    .resolution = .unreachable_value,
                },
            }
        }
        return try self.structuralDictionaryMethodEvidence(source_rep, requirement, requirement_view);
    }

    fn collectHiddenDescriptorsForRep(
        self: *Builder,
        root: TypeRepId,
        pending: *std.ArrayList(HiddenDescriptorParam),
        seen_reps: *collections.DenseMap(TypeRepId, void),
        seen_descs: *collections.DenseMap(DescriptorRequirementId, void),
    ) Allocator.Error!void {
        var reps: std.ArrayList(TypeRepId) = .empty;
        defer reps.deinit(self.allocator);
        try reps.append(self.allocator, root);
        while (reps.pop()) |rep_id| {
            const rep_entry = try seen_reps.getOrPut(rep_id);
            if (rep_entry.found_existing) continue;

            const rep = self.plan.representations.items[@intFromEnum(rep_id)];
            if (rep.descriptor) |desc| {
                const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
                const identity_desc = self.plan.representations.items[@intFromEnum(identity_rep)].descriptor orelse desc;
                const desc_entry = try seen_descs.getOrPut(identity_desc);
                if (!desc_entry.found_existing) {
                    try pending.append(self.allocator, .{
                        .source_type = rep.source_type,
                        .rep = rep_id,
                        .desc = desc,
                    });
                }
            }

            const children = self.plan.childSlice(rep.children);
            var index = children.len;
            while (index > 0) {
                index -= 1;
                const child = children[index];
                if (self.plan.childIsSharedBackingTemplate(rep_id, child)) continue;
                try reps.append(self.allocator, child.rep);
            }
        }
    }

    fn collectRuntimeHiddenDescriptorsForRep(
        self: *Builder,
        root: TypeRepId,
        pending: *std.ArrayList(HiddenDescriptorParam),
        seen_reps: *collections.DenseMap(TypeRepId, void),
        seen_descs: *collections.DenseMap(DescriptorRequirementId, void),
    ) Allocator.Error!void {
        var reps: std.ArrayList(TypeRepId) = .empty;
        defer reps.deinit(self.allocator);
        try reps.append(self.allocator, root);
        while (reps.pop()) |rep_id| {
            const rep_entry = try seen_reps.getOrPut(rep_id);
            if (rep_entry.found_existing) continue;

            const rep = self.plan.representations.items[@intFromEnum(rep_id)];
            if (rep.descriptor) |desc| {
                const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
                const identity_desc = self.plan.representations.items[@intFromEnum(identity_rep)].descriptor orelse desc;
                const desc_entry = try seen_descs.getOrPut(identity_desc);
                if (!desc_entry.found_existing) {
                    try pending.append(self.allocator, .{
                        .source_type = rep.source_type,
                        .rep = rep_id,
                        .desc = desc,
                    });
                }
            }

            if (rep.kind == .erased_callable) continue;
            const children = self.plan.childSlice(rep.children);
            var index = children.len;
            while (index > 0) {
                index -= 1;
                const child = children[index];
                if (!self.plan.childCarriesHiddenDescriptor(rep_id, child)) continue;
                try reps.append(self.allocator, child.rep);
            }
        }
    }

    fn collectHiddenDictionariesForRep(
        self: *Builder,
        root: TypeRepId,
        pending: *std.ArrayList(HiddenDictionaryParam),
        seen_reps: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!void {
        var reps: std.ArrayList(TypeRepId) = .empty;
        defer reps.deinit(self.allocator);
        try reps.append(self.allocator, root);
        while (reps.pop()) |rep_id| {
            const rep_entry = try seen_reps.getOrPut(rep_id);
            if (rep_entry.found_existing) continue;

            const rep = self.plan.representations.items[@intFromEnum(rep_id)];
            if (rep.dictionaries.len != 0) {
                const present = for (pending.items) |param| {
                    if (std.meta.eql(param.dictionaries, rep.dictionaries)) break true;
                } else false;
                if (!present) try pending.append(self.allocator, .{
                    .source_type = rep.source_type,
                    .rep = rep_id,
                    .dictionaries = rep.dictionaries,
                });
            }

            // Visit children in dictionary order.
            const children_start = reps.items.len;
            var child_index: usize = 0;
            while (self.plan.dictionaryChildAt(rep_id, child_index)) |child| : (child_index += 1) {
                if (self.plan.childIsSharedBackingTemplate(rep_id, child)) continue;
                try reps.append(self.allocator, child.rep);
            }
            std.mem.reverse(TypeRepId, reps.items[children_start..]);
        }
    }

    /// The fixed inputs of one call's hidden descriptor argument walk.
    const CallDescriptorWalk = struct {
        call_value_rep: TypeRepId,
        source_value_rep: TypeRepId,
        source_arg_index: ?u32,
        params: []const HiddenDescriptorParam,
        next_param: *usize,
        pending: *std.ArrayList(DirectCallHiddenDescriptorArg),
        seen_reps: *collections.DenseMap(TypeRepId, void),
        seen_descriptor_reps: *collections.DenseMap(TypeRepId, void),
        substitutions: *CallDescriptorRepSubstitutionMap,
        runtime_value_only: bool,
    };

    /// A worker representation whose descriptor arguments are being
    /// collected, inside its own substitution scope.
    const CallDescriptorFrame = struct {
        worker_rep_id: TypeRepId,
        aligned_call_rep_id: TypeRepId,
        enclosing_scope: usize,
        phase: enum { start, nominal_formals, structure, children } = .start,
        structure_call_rep_id: TypeRepId = undefined,
        through_wrapper: bool = false,
        child_index: usize = 0,
        /// What the child walk in flight leaves to undo once it finishes.
        child: union(enum) {
            none,
            nominal_formal: struct { enclosing_len: usize, before: usize },
            child: struct { scope: usize, first_arg: usize, tag_ext: bool },
        } = .none,
    };

    fn collectCallHiddenDescriptorArgs(
        self: *Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        call_value_rep: TypeRepId,
        source_value_rep: TypeRepId,
        source_arg_index: ?u32,
        params: []const HiddenDescriptorParam,
        next_param: *usize,
        pending: *std.ArrayList(DirectCallHiddenDescriptorArg),
        seen_reps: *collections.DenseMap(TypeRepId, void),
        seen_descriptor_reps: *collections.DenseMap(TypeRepId, void),
        substitutions: *CallDescriptorRepSubstitutionMap,
        runtime_value_only: bool,
    ) Allocator.Error!void {
        const walk = CallDescriptorWalk{
            .call_value_rep = call_value_rep,
            .source_value_rep = source_value_rep,
            .source_arg_index = source_arg_index,
            .params = params,
            .next_param = next_param,
            .pending = pending,
            .seen_reps = seen_reps,
            .seen_descriptor_reps = seen_descriptor_reps,
            .substitutions = substitutions,
            .runtime_value_only = runtime_value_only,
        };
        var frames: std.ArrayList(CallDescriptorFrame) = .empty;
        defer frames.deinit(self.allocator);
        errdefer while (frames.pop()) |frame| {
            switch (frame.child) {
                .none => {},
                .nominal_formal => |formal| substitutions.entries.shrinkRetainingCapacity(formal.enclosing_len),
                .child => |child| substitutions.exitScope(child.scope),
            }
            substitutions.exitScope(frame.enclosing_scope);
        };
        try self.enterCallDescriptorRep(&walk, &frames, worker_rep_id, call_rep_id);
        while (frames.items.len != 0) try self.stepCallDescriptorFrame(&walk, &frames);
    }

    /// Collect `worker_rep_id`'s own descriptor argument and push the frame
    /// that walks its children, unless it was already walked.
    fn enterCallDescriptorRep(
        self: *Builder,
        walk: *const CallDescriptorWalk,
        frames: *std.ArrayList(CallDescriptorFrame),
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
    ) Allocator.Error!void {
        const rep_entry = try walk.seen_reps.getOrPut(worker_rep_id);
        if (rep_entry.found_existing) return;

        const enclosing_scope = walk.substitutions.enterScope();
        errdefer walk.substitutions.exitScope(enclosing_scope);
        const inherited_call_rep_id = walk.substitutions.get(worker_rep_id) orelse call_rep_id;
        try self.recordCallDescriptorWrapperSubstitutions(worker_rep_id, inherited_call_rep_id, walk.substitutions);
        const aligned_call_rep_id = walk.substitutions.get(worker_rep_id) orelse inherited_call_rep_id;

        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];

        if (worker_rep.descriptor) |worker_desc| {
            const worker_identity = self.repQuery().descriptorArgumentIdentityRep(worker_rep_id);
            const identity_entry = try walk.seen_descriptor_reps.getOrPut(worker_identity);
            if (!identity_entry.found_existing) {
                if (walk.next_param.* >= walk.params.len or walk.params[walk.next_param.*].desc != worker_desc) {
                    boxyPlanInvariant("boxy direct call hidden descriptor order disagreed with worker descriptor params");
                }
                walk.next_param.* += 1;
                // Nominal result backings introduce declaration formals, but
                // their actuals can be callable parameters already supplied by
                // an operand. Retain that exact argument provenance across the
                // scoped nominal descent, including dynamic actuals.
                const call_identity = self.repQuery().descriptorArgumentIdentityRep(aligned_call_rep_id);
                const worker_parameter = self.plan.representations.items[@intFromEnum(worker_identity)];
                const call_parameter = self.plan.representations.items[@intFromEnum(call_identity)];
                const bare_parameter = worker_parameter.kind == .dynamic and worker_parameter.children.len == 0 and worker_parameter.tag_variants.len == 0 and
                    call_parameter.kind == .dynamic and call_parameter.children.len == 0 and call_parameter.tag_variants.len == 0;
                const source_index = if (bare_parameter and walk.source_arg_index == null) blk: {
                    const sources = if (walk.substitutions.argument_sources) |*sources| sources else break :blk null;
                    break :blk sources.get(call_identity);
                } else null;
                const descriptor_arg: DirectCallHiddenDescriptorArg = if (source_index) |index| blk: {
                    var source = walk.pending.items[index];
                    source.worker_desc = worker_desc;
                    source.worker_rep = worker_rep_id;
                    source.source_descriptor_index = index;
                    break :blk source;
                } else blk: {
                    const operand_nominal_actual = (try self.nominalBackingActualForCallRep(
                        walk.call_value_rep,
                        walk.source_value_rep,
                        aligned_call_rep_id,
                    ));
                    const desc_arg_rep_id = self.repQuery().descriptorArgumentIdentityRep(
                        operand_nominal_actual orelse aligned_call_rep_id,
                    );
                    const desc_arg_rep = self.plan.representations.items[@intFromEnum(desc_arg_rep_id)];
                    break :blk .{
                        .worker_desc = worker_desc,
                        .worker_rep = worker_rep_id,
                        .source_type = desc_arg_rep.source_type,
                        .rep = desc_arg_rep_id,
                        .source_arg_index = walk.source_arg_index,
                        .source_value_rep = walk.source_value_rep,
                    };
                };
                if (bare_parameter and walk.source_arg_index != null) {
                    if (walk.substitutions.argument_sources == null) {
                        walk.substitutions.argument_sources = collections.DenseMap(TypeRepId, u32).init(self.allocator);
                    }
                    const source_entry = try walk.substitutions.argument_sources.?.getOrPut(call_identity);
                    if (!source_entry.found_existing) source_entry.value_ptr.* = @intCast(walk.pending.items.len);
                }
                try walk.pending.append(self.allocator, descriptor_arg);
            }
        }

        try frames.append(self.allocator, .{
            .worker_rep_id = worker_rep_id,
            .aligned_call_rep_id = aligned_call_rep_id,
            .enclosing_scope = enclosing_scope,
        });
    }

    fn stepCallDescriptorFrame(self: *Builder, walk: *const CallDescriptorWalk, frames: *std.ArrayList(CallDescriptorFrame)) Allocator.Error!void {
        const substitutions = walk.substitutions;
        const frame = &frames.items[frames.items.len - 1];
        switch (frame.child) {
            .none => {},
            .nominal_formal => |formal| {
                if (walk.next_param.* == formal.before) {
                    boxyPlanInvariant("requested nominal formal did not consume its descriptor parameter");
                }
                substitutions.entries.shrinkRetainingCapacity(formal.enclosing_len);
            },
            .child => |child| {
                substitutions.exitScope(child.scope);
                if (child.tag_ext) {
                    for (walk.pending.items[child.first_arg..]) |*arg| arg.argument_source = .original;
                }
            },
        }
        frame.child = .none;
        const worker_rep_id = frame.worker_rep_id;
        const aligned_call_rep_id = frame.aligned_call_rep_id;
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        const call_rep = self.plan.representations.items[@intFromEnum(aligned_call_rep_id)];
        switch (frame.phase) {
            .start => {
                if (walk.runtime_value_only and worker_rep.kind == .erased_callable) return finishCallDescriptorFrame(walk, frames);
                frame.phase = .nominal_formals;
            },
            .nominal_formals => {
                // The parameter list fixes the call ABI. A requested declaration
                // formal is resolved in this nominal use, without walking its shared
                // backing or adding parameters for the call's actual type.
                if (worker_rep.kind == .nominal and call_rep.kind == .nominal and walk.next_param.* < walk.params.len) {
                    const requested_rep = walk.params[walk.next_param.*].rep;
                    var bindings = self.plan.nominalBackingSubstitutions(worker_rep.nominal_backing_arg_substitutions);
                    const found_actual = while (bindings.next()) |binding| {
                        if (binding.formal_rep != requested_rep) continue;
                        break self.nominalBackingArgActualRep(aligned_call_rep_id, binding.arg_index) orelse
                            boxyPlanInvariant("checked nominal call was missing a requested formal's actual");
                    } else null;
                    if (found_actual) |actual| {
                        const enclosing_len = substitutions.entries.items.len;
                        frame.child = .{ .nominal_formal = .{ .enclosing_len = enclosing_len, .before = walk.next_param.* } };
                        const scoped_actual = substitutions.get(actual) orelse actual;
                        try substitutions.entries.append(self.allocator, .{ .worker_rep = requested_rep, .call_rep = scoped_actual });
                        return try self.enterCallDescriptorRep(walk, frames, requested_rep, actual);
                    }
                }
                frame.phase = .structure;
            },
            .structure => {
                if (worker_rep.children.len == 0) return finishCallDescriptorFrame(walk, frames);
                // The descriptor above belongs to the call's own value. Its children
                // align with the structure that value stands for, which is the call
                // representation itself unless a structural worker position was
                // instantiated by a wrapper of that structure.
                frame.structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(self.allocator, worker_rep_id, aligned_call_rep_id, substitutions);
                frame.through_wrapper = frame.structure_call_rep_id != aligned_call_rep_id;
                frame.phase = .children;
            },
            .children => {
                const structure_call_rep_id = frame.structure_call_rep_id;
                const through_wrapper = frame.through_wrapper;
                // Walking a child can analyze new types, growing the children
                // pool and invalidating any held slice; children are re-read
                // by index.
                while (frame.child_index < worker_rep.children.len) {
                    const worker_child = self.plan.children.items[worker_rep.children.start + frame.child_index];
                    frame.child_index += 1;
                    const structure_rep = self.plan.representations.items[@intFromEnum(structure_call_rep_id)];
                    if (walk.runtime_value_only and !self.plan.childCarriesHiddenDescriptor(worker_rep_id, worker_child)) continue;
                    if (self.plan.childIsSharedBackingTemplate(worker_rep_id, worker_child)) continue;
                    if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
                    if (structure_rep.kind == .empty_tag_union) {
                        frame.child = .{ .child = .{ .scope = substitutions.enterScope(), .first_arg = walk.pending.items.len, .tag_ext = false } };
                        if (childIsInNominalDeclarationScope(worker_child.role)) {
                            try self.bindCallNominalFormals(worker_rep_id, aligned_call_rep_id, substitutions);
                        }
                        return try self.enterCallDescriptorRep(walk, frames, worker_child.rep, aligned_call_rep_id);
                    }
                    const call_children = self.plan.childSlice(structure_rep.children);
                    // A generic argument reachable through an unwrapped sibling (e.g. an
                    // alias's arg that also appears inside its backing) contributes its
                    // descriptor once, via that sibling; skip the duplicate here to
                    // mirror the worker param collection's per-rep dedup.
                    if (walk.seen_reps.contains(worker_child.rep)) continue;
                    frame.child = .{ .child = .{
                        .scope = substitutions.enterScope(),
                        .first_arg = walk.pending.items.len,
                        .tag_ext = worker_child.role == .tag_ext,
                    } };
                    if (childIsInNominalDeclarationScope(worker_child.role)) {
                        try self.bindCallNominalFormals(worker_rep_id, aligned_call_rep_id, substitutions);
                    }
                    const target: TypeRepId = target: {
                        if (self.rowInstantiationTarget(worker_rep_id, structure_call_rep_id, worker_child)) |structure_row_target| {
                            // The residual checked type does not replace the complete
                            // caller row's storage descriptor or its tag discriminants.
                            // A complete row seen through a wrapper is the wrapper's value.
                            const row_target = if (structure_row_target == structure_call_rep_id)
                                aligned_call_rep_id
                            else
                                structureChildCallRep(substitutions, through_wrapper, structure_row_target);
                            try substitutions.bindScoped(self.allocator, worker_child.rep, row_target);
                            break :target row_target;
                        }
                        // An explicit substitution (the checker's call-site substitution,
                        // or a wrapper argument recorded above) names this child's call
                        // representation exactly.
                        if (substitutions.get(worker_child.rep)) |call_child_rep| break :target call_child_rep;
                        if (self.namedQuery().findMatchingChildByRole(call_children, worker_child)) |call_child| {
                            break :target structureChildCallRep(substitutions, through_wrapper, call_child.rep);
                        }
                        if (self.repQuery().structuralWrapperBackingRep(aligned_call_rep_id)) |call_backing| {
                            const backing_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(call_backing)].children);
                            if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |call_child| break :target call_child.rep;
                        }
                        if (self.workerPresenceSlotPayloadMatchesUnwrappedCallRep(worker_rep_id, aligned_call_rep_id, worker_child)) break :target aligned_call_rep_id;
                        if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(worker_rep_id, worker_child)) break :target aligned_call_rep_id;
                        if (worker_child.role == .tag_ext and call_children.len == 0 and call_rep.descriptor != null) break :target aligned_call_rep_id;
                        boxyPlanInvariant("boxy direct call hidden descriptor mapping saw mismatched child roles");
                    };
                    return try self.enterCallDescriptorRep(walk, frames, worker_child.rep, target);
                }
                finishCallDescriptorFrame(walk, frames);
            },
        }
    }

    fn finishCallDescriptorFrame(walk: *const CallDescriptorWalk, frames: *std.ArrayList(CallDescriptorFrame)) void {
        const frame = frames.pop().?;
        walk.substitutions.exitScope(frame.enclosing_scope);
    }

    /// The representation inside `operand_root` at the position `target`
    /// occupies inside `worker_root`: the worker's runtime path to `target`,
    /// followed role by role through the operand.
    fn operandRepAtWorkerPosition(
        self: *Builder,
        worker_root: TypeRepId,
        target: TypeRepId,
        operand_root: TypeRepId,
    ) Allocator.Error!?TypeRepId {
        var path = std.ArrayList(RepChild).empty;
        defer path.deinit(self.allocator);
        var active = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer active.deinit();
        if (!try self.findWorkerRuntimePath(worker_root, self.repQuery().descriptorArgumentIdentityRep(target), &path, &active)) return null;

        var current = operand_root;
        for (path.items) |step| {
            var candidate = current;
            const next: RepChild = while (true) {
                const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(candidate)].children);
                if (self.namedQuery().findMatchingChildByRole(children, step)) |child| break child;
                candidate = self.repQuery().structuralWrapperBackingRep(candidate) orelse return null;
            };
            current = next.rep;
        }
        return current;
    }

    /// Find the first runtime path, in child order, from `root` to a
    /// representation whose descriptor identity is `target`. `path` holds
    /// the children stepped through; `active` holds the representations on
    /// the path, so a recursive type is not re-entered.
    /// The representation at the position `target` occupies in `worker_root`,
    /// read from `value_root`, a representation of the same type structure.
    /// Unlike a runtime descriptor path, a type position may lie inside a
    /// function's arguments or result.
    fn repAtTypePosition(
        self: *Builder,
        worker_root: TypeRepId,
        target: TypeRepId,
        value_root: TypeRepId,
    ) Allocator.Error!?TypeRepId {
        var path = std.ArrayList(RepChild).empty;
        defer path.deinit(self.allocator);
        var active = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer active.deinit();
        if (!try self.findTypePositionPath(worker_root, self.repQuery().descriptorArgumentIdentityRep(target), &path, &active)) return null;

        var current = value_root;
        for (path.items) |step| {
            var candidate = current;
            const next: RepChild = while (true) {
                const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(candidate)].children);
                if (self.namedQuery().findMatchingChildByRole(children, step)) |child| break child;
                candidate = self.repQuery().structuralWrapperBackingRep(candidate) orelse return null;
            };
            current = next.rep;
        }
        return current;
    }

    fn findTypePositionPath(
        self: *Builder,
        root: TypeRepId,
        target: TypeRepId,
        path: *std.ArrayList(RepChild),
        active: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!bool {
        if (self.repQuery().descriptorArgumentIdentityRep(root) == target) return true;
        if ((try active.getOrPut(root)).found_existing) return false;
        const Frame = struct { rep: TypeRepId, index: usize = 0 };
        var frames: std.ArrayList(Frame) = .empty;
        defer {
            for (frames.items) |frame| _ = active.remove(frame.rep);
            frames.deinit(self.allocator);
        }
        frames.append(self.allocator, .{ .rep = root }) catch |err| {
            _ = active.remove(root);
            return err;
        };
        while (frames.items.len != 0) {
            const top = &frames.items[frames.items.len - 1];
            const children = self.plan.representations.items[@intFromEnum(top.rep)].children;
            if (top.index == children.len) {
                _ = active.remove(top.rep);
                frames.items.len -= 1;
                if (frames.items.len != 0) path.items.len -= 1;
                continue;
            }
            const current = top.rep;
            const child = self.plan.children.items[children.start + top.index];
            top.index += 1;
            switch (child.role) {
                .function_arg, .function_ret => {},
                .alias_backing, .nominal_backing, .record_field, .record_ext, .tuple_elem, .tag_payload, .tag_ext, .list_elem, .box_payload, .alias_arg, .nominal_arg, .nominal_padding_field => {
                    if (!childCarriesRuntimeDescriptor(child.role)) continue;
                },
            }
            if (self.plan.childIsSharedBackingTemplate(current, child)) continue;
            try path.append(self.allocator, child);
            if (self.repQuery().descriptorArgumentIdentityRep(child.rep) == target) return true;
            if ((try active.getOrPut(child.rep)).found_existing) {
                path.items.len -= 1;
                continue;
            }
            frames.append(self.allocator, .{ .rep = child.rep }) catch |err| {
                _ = active.remove(child.rep);
                return err;
            };
        }
        return false;
    }

    fn findWorkerRuntimePath(
        self: *Builder,
        root: TypeRepId,
        target: TypeRepId,
        path: *std.ArrayList(RepChild),
        active: *collections.DenseMap(TypeRepId, void),
    ) Allocator.Error!bool {
        if (self.repQuery().descriptorArgumentIdentityRep(root) == target) return true;
        if ((try active.getOrPut(root)).found_existing) return false;
        const Frame = struct { rep: TypeRepId, index: usize = 0 };
        var frames: std.ArrayList(Frame) = .empty;
        defer {
            for (frames.items) |frame| _ = active.remove(frame.rep);
            frames.deinit(self.allocator);
        }
        frames.append(self.allocator, .{ .rep = root }) catch |err| {
            _ = active.remove(root);
            return err;
        };
        while (frames.items.len != 0) {
            const top = &frames.items[frames.items.len - 1];
            const children = self.plan.representations.items[@intFromEnum(top.rep)].children;
            if (top.index == children.len) {
                _ = active.remove(top.rep);
                frames.items.len -= 1;
                if (frames.items.len != 0) path.items.len -= 1;
                continue;
            }
            const current = top.rep;
            const child = self.plan.children.items[children.start + top.index];
            top.index += 1;
            if (!childCarriesRuntimeDescriptor(child.role)) continue;
            if (self.plan.childIsSharedBackingTemplate(current, child)) continue;
            try path.append(self.allocator, child);
            if (self.repQuery().descriptorArgumentIdentityRep(child.rep) == target) return true;
            if ((try active.getOrPut(child.rep)).found_existing) {
                path.items.len -= 1;
                continue;
            }
            frames.append(self.allocator, .{ .rep = child.rep }) catch |err| {
                _ = active.remove(child.rep);
                return err;
            };
        }
        return false;
    }

    /// The call representation the checked call-site substitution names for
    /// one worker scheme variable.
    fn schemeSubstitutedRep(
        self: *Builder,
        scheme_substitution: []const CallDescriptorRepSubstitution,
        worker_rep: TypeRepId,
    ) ?TypeRepId {
        const identity = self.repQuery().descriptorArgumentIdentityRep(worker_rep);
        for (scheme_substitution) |entry| {
            if (self.repQuery().descriptorArgumentIdentityRep(entry.worker_rep) == identity) return entry.call_rep;
        }
        return null;
    }

    const CallDescriptorRepSubstitution = struct {
        worker_rep: TypeRepId,
        call_rep: TypeRepId,
    };

    /// A lexical environment of call substitutions. Worker representations
    /// map to one call representation wherever they are visible, except
    /// declaration formals: every nominal use binds its declaration's shared
    /// formals for its own backing, so `Try(Try(U64, Str), Str)` binds `ok`
    /// to `Try(U64, Str)` in the outer backing and to `U64` in the inner one.
    /// The innermost binding of a formal shadows the enclosing ones.
    const CallDescriptorRepSubstitutionMap = struct {
        entries: std.ArrayList(CallDescriptorRepSubstitution) = .empty,
        /// The initial entries come from the checked callee-scheme substitution.
        scheme_entries_len: usize = 0,
        // Callable parameters outlive the nested declaration scopes in entries.
        argument_sources: ?collections.DenseMap(TypeRepId, u32) = null,
        /// Entries from this index on belong to the innermost scope.
        scope_start: usize = 0,

        fn deinit(self: *CallDescriptorRepSubstitutionMap, allocator: Allocator) void {
            self.entries.deinit(allocator);
            if (self.argument_sources) |*sources| sources.deinit();
        }

        /// The innermost binding of `worker_rep`: a nested use of a nominal
        /// binds its declaration's formals again, shadowing the bindings of
        /// every enclosing use.
        fn get(self: *const CallDescriptorRepSubstitutionMap, worker_rep: TypeRepId) ?TypeRepId {
            return getIn(self.entries.items, worker_rep);
        }

        /// A scoped nominal binding can shadow a scheme variable; wrapper
        /// traversal must preserve a scheme binding while it remains visible.
        fn hasVisibleSchemeSubstitution(self: *const CallDescriptorRepSubstitutionMap, worker_rep: TypeRepId) bool {
            var index = self.entries.items.len;
            while (index > 0) {
                index -= 1;
                if (self.entries.items[index].worker_rep == worker_rep) return index < self.scheme_entries_len;
            }
            return false;
        }

        fn getIn(entries: []const CallDescriptorRepSubstitution, worker_rep: TypeRepId) ?TypeRepId {
            var index = entries.len;
            while (index > 0) {
                index -= 1;
                if (entries[index].worker_rep == worker_rep) return entries[index].call_rep;
            }
            return null;
        }

        /// Enclosing nominal arguments can themselves be declaration formals.
        /// Compose those explicit substitutions before entering a nested backing.
        fn resolve(self: *const CallDescriptorRepSubstitutionMap, rep: TypeRepId) TypeRepId {
            return resolveIn(self.entries.items, rep);
        }

        /// Resolve in the environment enclosing the innermost scope.
        fn resolveEnclosing(self: *const CallDescriptorRepSubstitutionMap, rep: TypeRepId) TypeRepId {
            return resolveIn(self.entries.items[0..self.scope_start], rep);
        }

        fn resolveIn(entries: []const CallDescriptorRepSubstitution, rep: TypeRepId) TypeRepId {
            var current = rep;
            for (0..entries.len + 1) |_| {
                current = getIn(entries, current) orelse return current;
            }
            boxyPlanInvariant("cyclic nominal descriptor substitution");
        }

        fn enterScope(self: *CallDescriptorRepSubstitutionMap) usize {
            const enclosing = self.scope_start;
            self.scope_start = self.entries.items.len;
            return enclosing;
        }

        fn exitScope(self: *CallDescriptorRepSubstitutionMap, enclosing: usize) void {
            self.entries.shrinkRetainingCapacity(self.scope_start);
            self.scope_start = enclosing;
        }

        /// Map a worker representation wherever it is visible. A
        /// representation that already resolves must resolve to `call_rep`.
        fn put(
            self: *CallDescriptorRepSubstitutionMap,
            allocator: Allocator,
            worker_rep: TypeRepId,
            call_rep: TypeRepId,
        ) Allocator.Error!void {
            if (self.get(worker_rep)) |existing| {
                if (existing != call_rep) {
                    boxyPlanInvariant("one worker descriptor representation mapped to two call representations");
                }
                return;
            }
            try self.entries.append(allocator, .{ .worker_rep = worker_rep, .call_rep = call_rep });
        }

        /// Bind a representation in the innermost scope. Nominal declaration
        /// arguments and row storage each shadow their enclosing type bindings.
        fn bindScoped(
            self: *CallDescriptorRepSubstitutionMap,
            allocator: Allocator,
            formal_rep: TypeRepId,
            call_rep: TypeRepId,
        ) Allocator.Error!void {
            if (getIn(self.entries.items[self.scope_start..], formal_rep)) |existing| {
                if (existing != call_rep) {
                    boxyPlanInvariant("one descriptor scope bound a representation to two call representations");
                }
                return;
            }
            try self.entries.append(allocator, .{ .worker_rep = formal_rep, .call_rep = call_rep });
        }
    };

    fn nominalBackingArgActualRep(
        self: *const Builder,
        nominal_rep_id: TypeRepId,
        arg_index: u32,
    ) ?TypeRepId {
        return self.plan.nominalBackingActual(
            self.plan.representations.items[@intFromEnum(nominal_rep_id)].nominal_backing_arg_substitutions,
            arg_index,
        );
    }

    fn nominalBackingActualForCallRep(
        self: *Builder,
        call_root_rep: TypeRepId,
        operand_root_rep: TypeRepId,
        target_call_rep: TypeRepId,
    ) Allocator.Error!?TypeRepId {
        var seen_pairs = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen_pairs.deinit();
        var found: ?TypeRepId = null;
        try self.collectNominalBackingActualForCallRep(
            call_root_rep,
            operand_root_rep,
            target_call_rep,
            &found,
            &seen_pairs,
        );
        return found;
    }

    /// Find the operand representation at `target_call_rep`'s position,
    /// visiting corresponding pairs in pre-order.
    fn collectNominalBackingActualForCallRep(
        self: *Builder,
        root_call: TypeRepId,
        root_operand: TypeRepId,
        target_call_rep: TypeRepId,
        found: *?TypeRepId,
        seen_pairs: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList([2]TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ root_call, root_operand });
        while (pending.pop()) |pair| {
            const call_rep_id = pair[0];
            const operand_rep_id = pair[1];
            const pair_key = (@as(u64, @intFromEnum(call_rep_id)) << 32) |
                @as(u64, @intFromEnum(operand_rep_id));
            const pair_entry = try seen_pairs.getOrPut(pair_key);
            if (pair_entry.found_existing) continue;

            if (call_rep_id == target_call_rep) {
                if (found.*) |existing| {
                    if (existing != operand_rep_id) {
                        boxyPlanInvariant("one call representation corresponded to two operand representations");
                    }
                } else {
                    found.* = operand_rep_id;
                }
                continue;
            }

            const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
            const operand_rep = self.plan.representations.items[@intFromEnum(operand_rep_id)];
            const children_start = pending.items.len;
            if (call_rep.kind == .nominal and operand_rep.kind == .nominal) {
                var call_substitution_iter = self.plan.nominalBackingSubstitutions(call_rep.nominal_backing_arg_substitutions);
                while (call_substitution_iter.next()) |call_substitution| {
                    const operand_actual = self.nominalBackingArgActualRep(operand_rep_id, call_substitution.arg_index) orelse
                        boxyPlanInvariant("call operand nominal was missing a checked backing argument substitution");
                    try pending.append(self.allocator, .{ call_substitution.actual_rep, operand_actual });
                }
            }

            const operand_children = self.plan.childSlice(operand_rep.children);
            for (self.plan.childSlice(call_rep.children)) |call_child| {
                if (self.plan.childIsSharedBackingTemplate(call_rep_id, call_child)) continue;
                const operand_child = self.namedQuery().findMatchingChildByRole(operand_children, call_child) orelse continue;
                try pending.append(self.allocator, .{ call_child.rep, operand_child.rep });
            }
            std.mem.reverse([2]TypeRepId, pending.items[children_start..]);
        }
    }

    fn recordCallDescriptorWrapperSubstitutions(
        self: *Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        substitutions: *CallDescriptorRepSubstitutionMap,
    ) Allocator.Error!void {
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
        const roles_match = (worker_rep.kind == .alias and call_rep.kind == .alias) or
            (worker_rep.kind == .nominal and call_rep.kind == .nominal);
        if (!roles_match) return;

        const call_children = self.plan.childSlice(call_rep.children);
        for (self.plan.childSlice(worker_rep.children)) |worker_child| {
            if (worker_child.role != .alias_arg and worker_child.role != .nominal_arg) continue;
            // The checked lookup's scheme substitution already names this
            // variable's call type. Wrapper arguments do not replace it.
            if (substitutions.hasVisibleSchemeSubstitution(worker_child.rep)) continue;
            const call_arg_rep = if (worker_child.role == .nominal_arg)
                self.nominalBackingArgActualRep(call_rep_id, worker_child.role.nominal_arg) orelse blk: {
                    // A stored nominal records its arguments only as its own
                    // argument children, in declaration order.
                    if (call_rep.nominal_backing_arg_substitutions.len != 0) {
                        boxyPlanInvariant("checked nominal call was missing a type argument substitution");
                    }
                    const call_child = self.namedQuery().findMatchingChildByRole(call_children, worker_child) orelse
                        boxyPlanInvariant("stored nominal call was missing a type argument");
                    break :blk call_child.rep;
                }
            else blk: {
                const call_child = self.namedQuery().findMatchingChildByRole(call_children, worker_child) orelse
                    boxyPlanInvariant("checked wrapper call was missing a type argument substitution");
                break :blk call_child.rep;
            };
            const exact_call_arg_rep = substitutions.resolve(call_arg_rep);
            if (worker_child.rep == exact_call_arg_rep) continue;
            try substitutions.put(self.allocator, worker_child.rep, exact_call_arg_rep);
        }
    }

    /// Bind the declaration formals of a nominal use for its backing and
    /// padding. Actuals belong to the enclosing environment, so they are
    /// resolved there before the new bindings become visible.
    fn bindCallNominalFormals(
        self: *Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        substitutions: *CallDescriptorRepSubstitutionMap,
    ) Allocator.Error!void {
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
        if (worker_rep.kind != .nominal or call_rep.kind != .nominal) return;

        // Both sides have shared declaration templates. Descending the
        // call-side backing must apply its formals too, e.g. Set(Str)'s
        // backing Dict(item, {}) must supply Str, not the template's item.
        var call_substitutions = self.plan.nominalBackingSubstitutions(call_rep.nominal_backing_arg_substitutions);
        while (call_substitutions.next()) |call_substitution| {
            const formal_rep = call_substitution.formal_rep orelse continue;
            const actual = substitutions.resolveEnclosing(call_substitution.actual_rep);
            if (formal_rep != actual) {
                try substitutions.bindScoped(self.allocator, formal_rep, actual);
            }
        }
        var backing_substitutions = self.plan.nominalBackingSubstitutions(worker_rep.nominal_backing_arg_substitutions);
        while (backing_substitutions.next()) |backing_substitution| {
            const call_arg_rep = self.nominalBackingArgActualRep(call_rep_id, backing_substitution.arg_index) orelse
                boxyPlanInvariant("checked nominal call was missing a backing argument substitution");
            const exact_call_arg_rep = substitutions.resolveEnclosing(call_arg_rep);
            if (backing_substitution.formal_rep) |formal_rep| {
                if (formal_rep != exact_call_arg_rep) {
                    try substitutions.bindScoped(self.allocator, formal_rep, exact_call_arg_rep);
                }
            }
        }
    }

    const CallDictionaryRepSubstitution = struct {
        worker_rep: TypeRepId,
        call_rep: TypeRepId,
    };

    /// A call edge's instantiation of its callee's scheme variables. A static
    /// dictionary built for one of the callee's requirements is called at the
    /// requirement's types under it.
    const RequirementCallInstantiation = struct {
        substitutions: *const CallDictionaryRepSubstitutionMap,
        scheme_pairs: []const SchemeRepSubstitution,
        /// The callee's argument and result representations with the call's
        /// types at those positions: a scheme variable that is a whole
        /// argument or the result stands for the call's type there.
        worker_arg_reps: []const RepChild,
        call_arg_types: []const CheckedTypeIdentity,
        worker_ret_rep: TypeRepId,
        call_ret_type: CheckedTypeIdentity,

        fn get(self: RequirementCallInstantiation, plan: *const ProgramPlan, rep: TypeRepId) ?TypeRepId {
            if (self.substitutions.get(rep)) |call_rep| return call_rep;
            for (self.scheme_pairs) |pair| {
                if (pair.scheme_rep == rep) return pair.site_rep;
            }
            for (self.worker_arg_reps, self.call_arg_types) |worker_arg, call_type| {
                if (worker_arg.rep == rep) return plan.repForSourceType(call_type);
            }
            if (self.worker_ret_rep == rep) return plan.repForSourceType(self.call_ret_type);
            return null;
        }
    };

    const CallDictionaryRepSubstitutionMap = struct {
        entries: std.ArrayList(CallDictionaryRepSubstitution) = .empty,

        fn deinit(self: *CallDictionaryRepSubstitutionMap, allocator: Allocator) void {
            self.entries.deinit(allocator);
        }

        fn get(self: *const CallDictionaryRepSubstitutionMap, worker_rep: TypeRepId) ?TypeRepId {
            for (self.entries.items) |entry| {
                if (entry.worker_rep == worker_rep) return entry.call_rep;
            }
            return null;
        }

        fn put(
            self: *CallDictionaryRepSubstitutionMap,
            allocator: Allocator,
            worker_rep: TypeRepId,
            call_rep: TypeRepId,
        ) Allocator.Error!void {
            for (self.entries.items) |entry| {
                if (entry.worker_rep != worker_rep) continue;
                if (entry.call_rep != call_rep) {
                    boxyPlanInvariant("one worker dictionary representation mapped to two call representations");
                }
                return;
            }
            try self.entries.append(allocator, .{ .worker_rep = worker_rep, .call_rep = call_rep });
        }
    };

    /// A worker representation whose children's dictionary substitutions
    /// are being collected.
    const CallDictionaryFrame = struct {
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        wrapper_bindings: CallWrapperBindings,
        structure_call_rep_id: TypeRepId,
        through_wrapper: bool,
        index: usize = 0,
    };

    fn collectCallDictionaryRepSubstitutions(
        self: *Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        substitutions: *CallDictionaryRepSubstitutionMap,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        var frames: std.ArrayList(CallDictionaryFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.wrapper_bindings.deinit(self.allocator);
            frames.deinit(self.allocator);
        }
        try self.enterCallDictionaryRep(&frames, worker_rep_id, call_rep_id, substitutions, seen);
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            const worker_rep = self.plan.representations.items[@intFromEnum(frame.worker_rep_id)];
            if (frame.index == worker_rep.children.len) {
                var done = frames.pop().?;
                done.wrapper_bindings.deinit(self.allocator);
                continue;
            }
            const worker_child = self.plan.children.items[worker_rep.children.start + frame.index];
            frame.index += 1;
            const target = try self.callDictionaryChildTarget(frame, worker_child, substitutions) orelse continue;
            try self.enterCallDictionaryRep(&frames, worker_child.rep, target, substitutions, seen);
        }
    }

    /// Record `worker_rep_id`'s own substitution and push the frame that
    /// walks its children, unless the pair was already walked.
    fn enterCallDictionaryRep(
        self: *Builder,
        frames: *std.ArrayList(CallDictionaryFrame),
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        substitutions: *CallDictionaryRepSubstitutionMap,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        const seen_key = (@as(u64, @intFromEnum(worker_rep_id)) << 32) | @as(u64, @intFromEnum(call_rep_id));
        const seen_entry = try seen.getOrPut(seen_key);
        if (seen_entry.found_existing) return;

        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        if (worker_rep.dictionaries.len != 0) {
            try substitutions.put(self.allocator, worker_rep_id, call_rep_id);
        }
        if (worker_rep.children.len == 0) return;

        // Children align with the structure the call's value stands for.
        var wrapper_bindings: CallWrapperBindings = .{};
        errdefer wrapper_bindings.deinit(self.allocator);
        const structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(self.allocator, worker_rep_id, call_rep_id, &wrapper_bindings);
        try frames.append(self.allocator, .{
            .worker_rep_id = worker_rep_id,
            .call_rep_id = call_rep_id,
            .wrapper_bindings = wrapper_bindings,
            .structure_call_rep_id = structure_call_rep_id,
            .through_wrapper = structure_call_rep_id != call_rep_id,
        });
    }

    /// The call representation a worker child's substitutions are collected
    /// against, or null when the child contributes none.
    fn callDictionaryChildTarget(
        self: *Builder,
        frame: *CallDictionaryFrame,
        worker_child: RepChild,
        substitutions: *CallDictionaryRepSubstitutionMap,
    ) Allocator.Error!?TypeRepId {
        const worker_rep_id = frame.worker_rep_id;
        const call_rep_id = frame.call_rep_id;
        const structure_call_rep_id = frame.structure_call_rep_id;
        const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
        const structure_rep = self.plan.representations.items[@intFromEnum(structure_call_rep_id)];
        if (self.plan.childIsSharedBackingTemplate(worker_rep_id, worker_child)) return null;
        if (!try self.repQuery().repSubtreeHasDictionary(worker_child.rep)) return null;
        if (structure_rep.kind == .empty_tag_union) return call_rep_id;

        const call_children = self.plan.childSlice(structure_rep.children);
        if (substitutions.get(worker_child.rep) != null) return null;
        if (self.namedQuery().rowInstantiationTarget(worker_rep_id, structure_call_rep_id, worker_child)) |structure_row_target| {
            return if (structure_row_target == structure_call_rep_id)
                call_rep_id
            else
                structureChildCallRep(&frame.wrapper_bindings, frame.through_wrapper, structure_row_target);
        }
        if (worker_child.role == .nominal_arg) {
            const arg_index = worker_child.role.nominal_arg;
            if (self.nominalBackingArgActualRep(call_rep_id, arg_index)) |exact_call_arg_rep| return exact_call_arg_rep;
        }
        if (self.namedQuery().findMatchingChildByRole(call_children, worker_child)) |call_child| {
            return structureChildCallRep(&frame.wrapper_bindings, frame.through_wrapper, call_child.rep);
        }
        if (self.repQuery().structuralWrapperBackingRep(call_rep_id)) |call_backing| {
            const backing_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(call_backing)].children);
            if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |call_child| return call_child.rep;
        }
        if (self.workerPresenceSlotPayloadMatchesUnwrappedCallRep(worker_rep_id, call_rep_id, worker_child)) return call_rep_id;
        if (try self.repQuery().workerChildCanMatchUnwrappedCallRepForDictionaries(worker_rep_id, worker_child)) return call_rep_id;
        if (worker_child.role == .tag_ext and call_children.len == 0 and call_rep.dictionaries.len != 0) return call_rep_id;
        if (structure_rep.kind == .dynamic and structure_rep.children.len == 0 and call_rep.dictionaries.len != 0) return call_rep_id;
        return null;
    }

    const CallableEvidenceSource = struct {
        bound_evidence: ?SchemeDictionaryKey = null,
        rep: ?TypeRepId = null,
        method_evidence: Span = .{},
    };

    const DictionaryMethodRequirementDescriptorPlan = struct {
        args: Span = .{},
        sources: Span = .{},
        leaf_sources: Span = .{},
    };

    const DictionaryMethodCallShape = struct {
        arg_reps: []TypeRepId,
        ret_rep: TypeRepId,
    };

    /// The argument and result representations a dictionary method is called
    /// at: its evidence callable's, or its recorded instantiation's.
    fn dictionaryMethodCallShape(
        self: *Builder,
        method: DictionaryMethodEvidence,
        instantiated: bool,
    ) Allocator.Error!DictionaryMethodCallShape {
        if (method.instantiation_rep) |rep| {
            const function = self.repQuery().functionChildren(rep) orelse boxyPlanInvariant("literal method instantiation was not callable");
            const args = try self.allocator.alloc(TypeRepId, function.arg_count);
            const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
            for (children[function.args_start..][0..function.arg_count], args) |child, *arg| arg.* = child.rep;
            return .{ .arg_reps = args, .ret_rep = function.ret };
        }
        if (instantiated) {
            const arg_types = self.plan.dictionaryMethodCallTypeSlice(method.instantiation_arg_types);
            const arg_reps = try self.allocator.alloc(TypeRepId, arg_types.len);
            for (arg_types, arg_reps) |arg_type, *arg_rep| {
                arg_rep.* = self.plan.repForSourceType(arg_type) orelse
                    boxyPlanInvariant("dictionary method instantiation argument type was not analyzed");
            }
            return .{
                .arg_reps = arg_reps,
                .ret_rep = self.plan.repForSourceType(method.instantiation_ret_type.?) orelse
                    boxyPlanInvariant("dictionary method instantiation result type was not analyzed"),
            };
        }
        const callable_rep = self.plan.repForSourceType(method.callable_type) orelse
            boxyPlanInvariant("dictionary method callable type was not analyzed");
        const callable_function = (self.repQuery().functionChildren(callable_rep)) orelse
            boxyPlanInvariant("dictionary method evidence callable was not callable");
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(callable_function.rep)].children);
        const arg_reps = try self.allocator.alloc(TypeRepId, callable_function.arg_count);
        for (children[callable_function.args_start..][0..callable_function.arg_count], arg_reps) |child, *arg_rep| {
            arg_rep.* = child.rep;
        }
        return .{ .arg_reps = arg_reps, .ret_rep = callable_function.ret };
    }

    fn dictionaryMethodRequirementDescriptorSources(
        self: *Builder,
        requirement_type: CheckedTypeIdentity,
        callable_arg_reps: []const TypeRepId,
        callable_ret_rep: TypeRepId,
    ) Allocator.Error!DictionaryMethodRequirementDescriptorPlan {
        const requirement_rep = self.plan.repForSourceType(requirement_type) orelse
            boxyPlanInvariant("dictionary method requirement type was not analyzed");
        const requirement_function = (self.repQuery().functionChildren(requirement_rep)) orelse
            boxyPlanInvariant("dictionary method requirement was not callable");
        if (requirement_function.arg_count != callable_arg_reps.len) {
            boxyPlanInvariant("dictionary method requirement and evidence callable arity differed");
        }

        var params = std.ArrayList(HiddenDescriptorParam).empty;
        defer params.deinit(self.allocator);
        var param_seen_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer param_seen_reps.deinit();
        var param_seen_descs = collections.DenseMap(DescriptorRequirementId, void).init(self.allocator);
        defer param_seen_descs.deinit();
        const requirement_children = self.plan.childSlice(
            self.plan.representations.items[@intFromEnum(requirement_function.rep)].children,
        );
        for (requirement_children[requirement_function.args_start..][0..requirement_function.arg_count]) |arg| {
            try self.collectRuntimeHiddenDescriptorsForRep(arg.rep, &params, &param_seen_reps, &param_seen_descs);
        }
        try self.collectRuntimeHiddenDescriptorsForRep(
            requirement_function.ret,
            &params,
            &param_seen_reps,
            &param_seen_descs,
        );
        const leaf_sources = try self.requirementLeafSources(
            requirement_function,
            requirement_children,
            callable_arg_reps,
            callable_ret_rep,
        );
        if (params.items.len == 0) return .{ .leaf_sources = leaf_sources };

        var pending = std.ArrayList(DirectCallHiddenDescriptorArg).empty;
        defer pending.deinit(self.allocator);
        var seen_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen_reps.deinit();
        var seen_descriptor_reps = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen_descriptor_reps.deinit();
        var substitutions = CallDescriptorRepSubstitutionMap{};
        defer substitutions.deinit(self.allocator);
        var next_param: usize = 0;
        const requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
        for (requirement_args, callable_arg_reps, 0..) |requirement_arg, callable_arg_rep, arg_index| {
            try self.collectCallHiddenDescriptorArgs(
                requirement_arg.rep,
                callable_arg_rep,
                callable_arg_rep,
                callable_arg_rep,
                @intCast(arg_index),
                params.items,
                &next_param,
                &pending,
                &seen_reps,
                &seen_descriptor_reps,
                &substitutions,
                true,
            );
        }
        try self.collectCallHiddenDescriptorArgs(
            requirement_function.ret,
            callable_ret_rep,
            callable_ret_rep,
            callable_ret_rep,
            null,
            params.items,
            &next_param,
            &pending,
            &seen_reps,
            &seen_descriptor_reps,
            &substitutions,
            true,
        );
        if (next_param != params.items.len or pending.items.len != params.items.len) {
            boxyPlanInvariant("dictionary method descriptor source mapping did not cover every requirement");
        }

        const args_start: u32 = @intCast(self.plan.direct_call_hidden_desc_args.items.len);
        try self.plan.direct_call_hidden_desc_args.appendSlice(self.allocator, pending.items);
        const sources_start: u32 = @intCast(self.plan.dictionary_method_desc_sources.items.len);
        for (pending.items, 0..) |source, source_index| {
            // An argument supplies its own descriptor only. A descriptor for a
            // position nested inside an argument is the method's own storage
            // there, or supplied by the invocation.
            const whole_argument: ?u32 = if (source.source_arg_index) |arg_index|
                if (self.repQuery().descriptorArgumentIdentityRep(source.worker_rep) ==
                    self.repQuery().descriptorArgumentIdentityRep(requirement_args[arg_index].rep))
                    arg_index
                else
                    null
            else
                null;
            try self.plan.dictionary_method_desc_sources.append(self.allocator, .{
                .rep = source.rep,
                .source = if (whole_argument) |arg_index|
                    .{ .argument = arg_index }
                else if (try self.repQuery().repSubtreeHasDescriptor(source.rep))
                    .{ .call = @intCast(source_index) }
                else
                    .static_rep,
            });
        }
        return .{
            .args = .{ .start = args_start, .len = @intCast(pending.items.len) },
            .sources = .{ .start = sources_start, .len = @intCast(pending.items.len) },
            .leaf_sources = leaf_sources,
        };
    }

    /// The evidence callable's representation at each open record position of
    /// the requirement's signature.
    fn requirementLeafSources(
        self: *Builder,
        requirement_function: FunctionChildren,
        requirement_children: []const RepChild,
        callable_arg_reps: []const TypeRepId,
        callable_ret_rep: TypeRepId,
    ) Allocator.Error!Span {
        var leaves = std.ArrayList(TypeRepId).empty;
        defer leaves.deinit(self.allocator);
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        try self.collectRequirementOpenRecords(requirement_function.rep, &leaves, &seen);
        const start: u32 = @intCast(self.plan.requirement_leaf_reps.items.len);
        const requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
        for (leaves.items) |leaf| {
            const source = found: {
                for (requirement_args, callable_arg_reps) |requirement_arg, callable_arg_rep| {
                    if (try self.repAtTypePosition(requirement_arg.rep, leaf, callable_arg_rep)) |rep| break :found rep;
                }
                break :found try self.repAtTypePosition(requirement_function.ret, leaf, callable_ret_rep) orelse
                    boxyPlanInvariant("dictionary method evidence callable had no value at a requirement open record position");
            };
            try self.plan.requirement_leaf_reps.append(self.allocator, source);
        }
        return .{ .start = start, .len = @intCast(leaves.items.len) };
    }

    fn dictionaryMethodWorkerDescriptorArgs(
        self: *Builder,
        worker_id: WorkerPlanId,
        boundary_type: CheckedTypeIdentity,
        evidence_edge: ?DictionaryMethodEvidence.EvidenceEdge,
        dictionary_args: Span,
    ) Allocator.Error!Span {
        const boundary_rep = self.plan.repForSourceType(boundary_type) orelse
            boxyPlanInvariant("dictionary method descriptor boundary type was not analyzed");
        const boundary_function = (self.repQuery().functionChildren(boundary_rep)) orelse
            boxyPlanInvariant("dictionary method descriptor boundary was not callable");
        const boundary_children = self.plan.childSlice(
            self.plan.representations.items[@intFromEnum(boundary_function.rep)].children,
        );
        const arg_types = try self.allocator.alloc(CheckedTypeIdentity, boundary_function.arg_count);
        defer self.allocator.free(arg_types);
        for (arg_types, boundary_children[boundary_function.args_start..][0..boundary_function.arg_count]) |*arg_type, arg| {
            arg_type.* = arg.source_type;
        }
        const ret_type = self.plan.representations.items[@intFromEnum(boundary_function.ret)].source_type;
        return try self.materializeWorkerCallHiddenDescriptorArgsWithSubstitution(
            worker_id,
            arg_types,
            arg_types,
            ret_type,
            null,
            null,
            if (evidence_edge) |edge| self.evidenceEdgeSchemeSubstitution(worker_id, edge) else null,
            dictionary_args,
        );
    }

    /// The checked substitution a dispatch evidence edge applied to its
    /// target's scheme, when checking instantiated one there.
    /// The scheme pairs a worker dictionary method is instantiated at: its
    /// evidence edge's checked substitution, or the relation of an edge
    /// whose target derives its evidence from its callable
    /// (`evidenceEdgeCallableRelation`).
    fn dictionaryMethodSchemeRepSubstitutions(self: *Builder, method: DictionaryMethodEvidence) Allocator.Error!Span {
        const edge = method.evidence_edge orelse return .{};
        const worker = method.resolution.worker;
        if (self.evidenceEdgeSchemeSubstitution(worker, edge)) |substitution| return try self.appendSchemeRepSubstitutions(substitution);
        return try self.evidenceEdgeCallableRelation(worker, method.callable_type, edge) orelse .{};
    }

    /// For an evidence edge whose target derives its evidence from its
    /// callable, for which checking recorded no substitution, the target
    /// worker's type related to the edge's callable type, which fixes every
    /// variable of the worker's signature exactly as a checked substitution
    /// would. Null for every other edge.
    fn evidenceEdgeCallableRelation(
        self: *Builder,
        worker_id: WorkerPlanId,
        callable_type: CheckedTypeIdentity,
        edge: DictionaryMethodEvidence.EvidenceEdge,
    ) Allocator.Error!?Span {
        const node = self.moduleForId(edge.module).static_dispatch_plans.evidenceNode(edge.node);
        if (node.nested != .from_callable or node.subst.len != 0) return null;
        const callable_rep = self.plan.repForSourceType(callable_type) orelse
            boxyPlanInvariant("dictionary method callable type was not analyzed");
        return try self.storedUseSchemeRepSubstitutions(self.plan.workers.items[@intFromEnum(worker_id)].rep, callable_rep);
    }

    fn evidenceEdgeSchemeSubstitution(
        self: *Builder,
        worker_id: WorkerPlanId,
        edge: DictionaryMethodEvidence.EvidenceEdge,
    ) ?SchemeCallSubstitution {
        const site_view = self.moduleForId(edge.module);
        const site_types = evidenceEdgeSiteTypes(site_view, edge.node);
        if (site_types.len == 0) return null;
        const scheme = self.workerSchemeVars(self.plan.workers.items[@intFromEnum(worker_id)].source) orelse return null;
        if (scheme.vars.len != site_types.len) {
            boxyPlanInvariant("checked evidence-edge substitution disagreed with its target scheme's variables");
        }
        return .{
            .callee_view = scheme.view,
            .scheme_vars = scheme.vars,
            .site_view = site_view,
            .site_types = site_types,
        };
    }

    /// A call's checked substitution for its callee scheme, as representation
    /// pairs.
    /// Each variable of a worker's type paired with what a use's type puts in
    /// its position, as checking's site substitution pairs them: a variable
    /// with the call's type, and an open row's extension with the call row's
    /// variants that the row does not list.
    fn storedUseSchemeRepSubstitutions(self: *Builder, worker_rep: TypeRepId, call_rep: TypeRepId) Allocator.Error!Span {
        // Planning passes repeat until they reach a fixpoint; the relation of
        // one worker to one use's type is computed once.
        const key = (@as(u64, @intFromEnum(worker_rep)) << 32) | @as(u64, @intFromEnum(call_rep));
        if (self.stored_use_substitutions.get(key)) |existing| return existing;
        const span = try self.computeStoredUseSchemeRepSubstitutions(worker_rep, call_rep);
        try self.stored_use_substitutions.put(self.allocator, key, span);
        return span;
    }

    fn computeStoredUseSchemeRepSubstitutions(self: *Builder, worker_rep: TypeRepId, call_rep: TypeRepId) Allocator.Error!Span {
        const start: u32 = @intCast(self.plan.scheme_rep_substitutions.items.len);
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        try self.collectStoredUseSchemeRepSubstitutions(worker_rep, call_rep, start, &seen);
        return .{ .start = start, .len = @as(u32, @intCast(self.plan.scheme_rep_substitutions.items.len)) - start };
    }

    fn collectStoredUseSchemeRepSubstitutions(
        self: *Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        start: u32,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        const seen_key = (@as(u64, @intFromEnum(worker_rep_id)) << 32) | @as(u64, @intFromEnum(call_rep_id));
        if ((try seen.getOrPut(seen_key)).found_existing) return;
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        if (worker_rep.kind == .dynamic and !worker_rep.is_open_tag_row) {
            try self.appendStoredUseSchemePair(worker_rep_id, call_rep_id, start);
            return;
        }
        if (worker_rep.children.len == 0) return;

        var wrapper_bindings: CallWrapperBindings = .{};
        defer wrapper_bindings.deinit(self.allocator);
        const structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(self.allocator, worker_rep_id, call_rep_id, &wrapper_bindings);
        const through_wrapper = structure_call_rep_id != call_rep_id;
        const structure_rep = self.plan.representations.items[@intFromEnum(structure_call_rep_id)];
        const call_children = self.plan.childSlice(structure_rep.children);

        for (0..worker_rep.children.len) |index| {
            // Read by index: analysis below can grow the child table.
            const worker_child = self.plan.children.items[worker_rep.children.start + index];
            if (self.plan.childIsSharedBackingTemplate(worker_rep_id, worker_child)) continue;
            if (worker_rep.is_open_tag_row and worker_child.role == .tag_ext) {
                const rest = try self.callRowVariantsOutside(worker_rep, structure_call_rep_id);
                try self.collectStoredUseSchemeRepSubstitutions(worker_child.rep, rest, start, seen);
                continue;
            }
            if (worker_child.role == .nominal_arg) {
                if (self.nominalBackingArgActualRep(call_rep_id, worker_child.role.nominal_arg)) |exact_call_arg_rep| {
                    try self.collectStoredUseSchemeRepSubstitutions(worker_child.rep, exact_call_arg_rep, start, seen);
                    continue;
                }
            }
            if (self.namedQuery().findMatchingChildByRole(call_children, worker_child)) |call_child| {
                try self.collectStoredUseSchemeRepSubstitutions(worker_child.rep, structureChildCallRep(&wrapper_bindings, through_wrapper, call_child.rep), start, seen);
            }
        }
    }

    fn appendStoredUseSchemePair(self: *Builder, scheme_rep: TypeRepId, site_rep: TypeRepId, start: u32) Allocator.Error!void {
        for (self.plan.scheme_rep_substitutions.items[start..]) |pair| {
            if (pair.scheme_rep != scheme_rep) continue;
            if (pair.site_rep != site_rep) boxyPlanInvariant("a stored function's use put two types in one variable's position");
            return;
        }
        try self.plan.scheme_rep_substitutions.append(self.allocator, .{ .scheme_rep = scheme_rep, .site_rep = site_rep });
    }

    /// The closed row of the call row's variants that `row` does not list.
    fn callRowVariantsOutside(self: *Builder, row: TypeRepresentation, call_row_id: TypeRepId) Allocator.Error!TypeRepId {
        const call_row = self.plan.representations.items[@intFromEnum(call_row_id)];
        const children_start: u32 = @intCast(self.plan.children.items.len);
        const variants_start: u32 = @intCast(self.plan.tag_variants.items.len);
        var variant_count: u32 = 0;
        var empty_ext: ?TypeRepId = null;
        for (0..call_row.tag_variants.len) |index| {
            const variant = self.plan.tag_variants.items[call_row.tag_variants.start + index];
            if (self.namedQuery().tagRowNamesVariant(row, variant)) continue;
            const payload_start: u32 = @intCast(self.plan.children.items.len);
            for (0..variant.payloads.len) |payload_index| {
                try self.plan.children.append(self.allocator, self.plan.children.items[variant.payloads.start + payload_index]);
            }
            var copied = variant;
            copied.payloads = .{ .start = payload_start, .len = variant.payloads.len };
            try self.plan.tag_variants.append(self.allocator, copied);
            variant_count += 1;
        }
        const rest_id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        if (variant_count == 0) {
            try self.plan.representations.append(self.allocator, .{ .source_type = call_row.source_type, .kind = .empty_tag_union });
            return rest_id;
        }
        for (0..call_row.children.len) |index| {
            const child = self.plan.children.items[call_row.children.start + index];
            if (child.role == .tag_ext) empty_ext = child.rep;
        }
        const ext = empty_ext orelse boxyPlanInvariant("call tag row representation had no extension child");
        try self.plan.children.append(self.allocator, .{
            .role = .tag_ext,
            .source_type = self.plan.representations.items[@intFromEnum(ext)].source_type,
            .rep = ext,
        });
        try self.plan.representations.append(self.allocator, .{
            .source_type = call_row.source_type,
            .kind = .tag_union,
            .children = .{ .start = children_start, .len = @as(u32, @intCast(self.plan.children.items.len)) - children_start },
            .tag_variants = .{ .start = variants_start, .len = variant_count },
        });
        return rest_id;
    }

    fn appendSchemeRepSubstitutions(self: *Builder, maybe_substitution: ?SchemeCallSubstitution) Allocator.Error!Span {
        const substitution = maybe_substitution orelse return .{};
        const start: u32 = @intCast(self.plan.scheme_rep_substitutions.items.len);
        for (substitution.scheme_vars, substitution.site_types) |scheme_var, site_type| {
            if (substitution.site_view.checked_types.payload(site_type) == .err) continue;
            const scheme_rep = self.plan.repForSourceType(typeRef(substitution.callee_view, scheme_var)) orelse continue;
            const site_rep = substitution.siteRep(self.plan.repForSourceType(typeRef(substitution.site_view, site_type)) orelse
                boxyPlanInvariant("checked call-site substitution type was not analyzed"));
            // A bound site can be the scheme variable itself.
            if (site_rep == scheme_rep) continue;
            try self.plan.scheme_rep_substitutions.append(self.allocator, .{
                .scheme_rep = scheme_rep,
                .site_rep = site_rep,
            });
        }
        return .{ .start = start, .len = @as(u32, @intCast(self.plan.scheme_rep_substitutions.items.len)) - start };
    }

    /// An evidence edge's substitution names caller-side types that supply
    /// its target's type-variable descriptors; they are analyzed when the
    /// edge is planned, before descriptor requirements are fixed.
    fn analyzeEvidenceEdgeSchemeSubstitution(self: *Builder, edge: DictionaryMethodEvidence.EvidenceEdge) Allocator.Error!void {
        const site_view = self.moduleForId(edge.module);
        for (evidenceEdgeSiteTypes(site_view, edge.node)) |site_type| {
            if (site_view.checked_types.payload(site_type) == .err) continue;
            _ = try self.analyzeType(site_view, site_type);
        }
    }

    fn evidenceEdgeSiteTypes(view: ModuleView, node_id: static_dispatch.EvidenceNodeId) []const checked.CheckedTypeId {
        const table = view.static_dispatch_plans;
        const node = table.evidenceNode(node_id);
        const start: usize = node.subst.start;
        const len: usize = node.subst.len;
        if (start > table.site_substitutions.len or len > table.site_substitutions.len - start) {
            boxyPlanInvariant("checked evidence-edge substitution range was outside its checked module");
        }
        return table.site_substitutions[start .. start + len];
    }

    fn repIsUnboundVariable(self: *const Builder, rep_id: TypeRepId) bool {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        return rep.sealed_default == null and self.repIsBareVariable(rep_id);
    }

    fn repIsBareVariable(self: *const Builder, rep_id: TypeRepId) bool {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        return rep.kind == .dynamic and rep.children.len == 0 and
            rep.tag_variants.len == 0 and rep.declared_fields.len == 0;
    }

    fn dictionaryMethodHiddenDescriptorSources(
        self: *Builder,
        worker_id: WorkerPlanId,
        worker_desc_args: Span,
        requirement_desc_args: Span,
    ) Allocator.Error!Span {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        const worker_args = self.plan.directCallHiddenDescriptorArgSlice(worker_desc_args);
        const requirement_args = self.plan.directCallHiddenDescriptorArgSlice(requirement_desc_args);
        if (params.len != worker_args.len) {
            boxyPlanInvariant("dictionary method worker descriptor source count disagreed with worker parameters");
        }
        if (params.len == 0) return .{};

        const start: u32 = @intCast(self.plan.dictionary_method_hidden_desc_sources.items.len);
        var next_slot: u32 = 0;
        for (params, worker_args) |param, worker_arg| {
            if (param.desc != worker_arg.worker_desc or param.rep != worker_arg.worker_rep) {
                boxyPlanInvariant("dictionary method worker descriptor source order disagreed with worker parameters");
            }

            const argument_source: ?u32 = switch (worker.source) {
                .generated_codec => |codec| switch (codec.kind) {
                    .parser_constructor, .encoder_constructor => worker_arg.source_arg_index,
                    .parser_runtime,
                    .encoder_runtime,
                    .encoder_record_fields,
                    .encoder_dict_fields,
                    .encoder_sequence_elements,
                    .encoder_tag_payload_elements,
                    .encoder_value_thunk,
                    .encoder_dict_key_thunk,
                    => null,
                },
                .procedure_template,
                .procedure_binding,
                .procedure_use,
                .nested_expr,
                .generated_field_iterator,
                .generated_interpolation_step,
                => null,
            };
            var call_source: ?u32 = null;
            // A call descriptor describes the requirement's storage of the
            // actual. It serves a worker descriptor for a bare type variable,
            // whose storage is the actual's own, and one whose actual needs
            // runtime instantiation. A structured worker position with a
            // concrete actual gets a static descriptor of the worker's own
            // storage, which differs (a concrete `List(U64)` key reaching a
            // `List(item)` worker stores its items boxed).
            const param_is_bare_variable = self.repIsBareVariable(param.rep);
            if (argument_source == null and
                (param_is_bare_variable or try self.repQuery().repSubtreeHasDescriptor(worker_arg.rep)))
            {
                const requirement_source_identity = self.repQuery().descriptorArgumentIdentityRep(worker_arg.rep);
                for (requirement_args, 0..) |requirement_arg, call_index| {
                    const requirement_call_identity = self.repQuery().descriptorArgumentIdentityRep(requirement_arg.rep);
                    if (requirement_call_identity != requirement_source_identity) continue;
                    if (call_source) |earlier| {
                        // Two requirement variables the call instantiates at
                        // one actual each describe that actual in its own
                        // storage: the same descriptor.
                        if (requirement_args[earlier].rep == requirement_arg.rep and
                            self.repIsBareVariable(requirement_args[earlier].worker_rep) and
                            self.repIsBareVariable(requirement_arg.worker_rep)) continue;
                        boxyPlanInvariant("dictionary method worker descriptor mapped to multiple call descriptors");
                    }
                    call_source = @intCast(call_index);
                }
            }
            const source: DictionaryMethodHiddenDescriptorSource = if (argument_source) |arg_index|
                .{ .argument = arg_index }
            else if (call_source) |call_index|
                .{ .call = call_index }
            else blk: {
                const slot = next_slot;
                next_slot += 1;
                break :blk .{ .slot = slot };
            };
            try self.plan.dictionary_method_hidden_desc_sources.append(self.allocator, source);
        }
        return .{ .start = start, .len = @intCast(params.len) };
    }

    fn materializeDictionaryMethodDescriptorSources(self: *Builder) Allocator.Error!void {
        for (self.plan.dictionary_method_evidence.items) |*method| {
            try self.materializeDictionaryMethodDescriptorSource(method);
        }
    }

    fn materializeDictionaryMethodDescriptorSource(self: *Builder, method: *DictionaryMethodEvidence) Allocator.Error!void {
        switch (method.resolution) {
            .worker => |worker| {
                const instantiated = method.instantiation_rep != null or method.instantiation_ret_type != null;
                const call_shape = try self.dictionaryMethodCallShape(method.*, instantiated);
                defer self.allocator.free(call_shape.arg_reps);
                method.worker_desc_args = if (method.instantiation_rep != null) blk: {
                    const arg_types = try self.allocator.alloc(CheckedTypeIdentity, call_shape.arg_reps.len);
                    defer self.allocator.free(arg_types);
                    for (call_shape.arg_reps, arg_types) |rep, *ty| ty.* = self.plan.representations.items[@intFromEnum(rep)].source_type;
                    break :blk try self.materializeWorkerCallHiddenDescriptorArgsForRepsWithEvidence(worker, call_shape.arg_reps, call_shape.arg_reps, call_shape.ret_rep, arg_types, self.plan.representations.items[@intFromEnum(call_shape.ret_rep)].source_type, null, null, null, null, method.nested_dict_args);
                } else if (method.instantiation_ret_type) |ret_type| blk: {
                    const arg_types = try self.allocator.dupe(CheckedTypeIdentity, self.plan.dictionaryMethodCallTypeSlice(method.instantiation_arg_types));
                    defer self.allocator.free(arg_types);
                    break :blk try self.materializeWorkerCallHiddenDescriptorArgsWithSubstitution(worker, arg_types, arg_types, ret_type, null, null, null, method.nested_dict_args);
                } else try self.dictionaryMethodWorkerDescriptorArgs(worker, method.callable_type, method.evidence_edge, method.nested_dict_args);
                const requirement_plan = try self.dictionaryMethodRequirementDescriptorSources(
                    method.requirement_type,
                    call_shape.arg_reps,
                    call_shape.ret_rep,
                );
                method.requirement_desc_args = requirement_plan.args;
                method.requirement_desc_sources = requirement_plan.sources;
                method.requirement_leaf_sources = requirement_plan.leaf_sources;
                method.hidden_desc_sources = try self.dictionaryMethodHiddenDescriptorSources(
                    worker,
                    method.worker_desc_args,
                    method.requirement_desc_args,
                );
            },
            .builtin_numeral,
            .structural,
            .constraint,
            .checked_error,
            .unreachable_value,
            => {},
        }
    }

    fn workerBindsDictionarySpan(self: *const Builder, worker_id: WorkerPlanId, dictionaries: Span) bool {
        if (dictionaries.len == 0) return false;
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        for (self.plan.hiddenDictionaryParamSlice(worker.hidden_dicts)) |param| {
            if (std.meta.eql(param.dictionaries, dictionaries)) return true;
        }
        return false;
    }

    /// Whether an unquantified variable seals to the empty tag union, so no
    /// value of its type exists and its dispatches follow the unpinned rule.
    fn repSealsUninhabited(self: *const Builder, rep: TypeRepresentation) bool {
        const sealed = rep.sealed_default orelse return false;
        return self.plan.representations.items[@intFromEnum(sealed)].kind == .empty_tag_union;
    }

    const StaticDictionaryMethodInstantiation = struct {
        arg_types: Span,
        ret_type: CheckedTypeIdentity,
        /// The call's argument and result representations, when a position
        /// is the requirement's own position at this call
        /// (`requirementPositionAtCall`), which no checked type names.
        rep: ?TypeRepId = null,
    };

    /// The types a dictionary built for `source_rep_id` calls its method at:
    /// the selected target's declared argument and result types, with each
    /// position the call pins replaced: the constrained variable by the
    /// dictionary's type, and a requirement variable by the type the calling
    /// edge instantiated it to.
    fn staticDictionaryMethodInstantiation(
        self: *Builder,
        call: RequirementCallInstantiation,
        source_rep_id: TypeRepId,
        requirement: DictionaryRequirement,
        target_callable_type: CheckedTypeIdentity,
    ) Allocator.Error!StaticDictionaryMethodInstantiation {
        const source_type = self.plan.representations.items[@intFromEnum(source_rep_id)].source_type;
        const dispatcher_rep = self.plan.repForSourceType(requirement.source_type) orelse
            boxyPlanInvariant("static dictionary requirement dispatcher type was not analyzed");
        const requirement_rep = self.plan.repForSourceType(requirement.fn_ty) orelse
            boxyPlanInvariant("static dictionary requirement type was not analyzed");
        const function = self.repQuery().functionChildren(requirement_rep) orelse
            boxyPlanInvariant("static dictionary requirement was not a function");
        const target_rep = self.plan.repForSourceType(target_callable_type) orelse
            boxyPlanInvariant("static dictionary method target callable type was not analyzed");
        const target = self.repQuery().functionChildren(target_rep) orelse
            boxyPlanInvariant("static dictionary method target was not a function");
        if (target.arg_count != function.arg_count) {
            boxyPlanInvariant("static dictionary method target arity disagreed with its requirement");
        }
        // One type and one representation per argument, then the result.
        var position_types = std.ArrayList(CheckedTypeIdentity).empty;
        defer position_types.deinit(self.allocator);
        var position_reps = std.ArrayList(TypeRepId).empty;
        defer position_reps.deinit(self.allocator);
        var any_at_call = false;
        for (0..function.arg_count + 1) |index| {
            const is_ret = index == function.arg_count;
            const child_rep = if (is_ret) function.ret else self.plan.children.items[self.plan.representations.items[@intFromEnum(function.rep)].children.start + function.args_start + index].rep;
            const target_child_rep = if (is_ret) target.ret else self.plan.children.items[self.plan.representations.items[@intFromEnum(target.rep)].children.start + target.args_start + index].rep;
            const position_type = try self.instantiatedRequirementType(call, dispatcher_rep, source_type, child_rep, target_child_rep);
            try position_types.append(self.allocator, position_type);
            if (try self.requirementPositionAtCall(call, dispatcher_rep, source_rep_id, child_rep, target_child_rep)) |at_call| {
                any_at_call = true;
                try position_reps.append(self.allocator, at_call);
            } else {
                try position_reps.append(self.allocator, self.plan.repForSourceType(position_type) orelse
                    boxyPlanInvariant("static dictionary method instantiation type was not analyzed"));
            }
        }
        const start: u32 = @intCast(self.plan.dictionary_method_call_types.items.len);
        try self.plan.dictionary_method_call_types.appendSlice(self.allocator, position_types.items[0..function.arg_count]);
        return .{
            .arg_types = .{ .start = start, .len = function.arg_count },
            .ret_type = position_types.items[function.arg_count],
            .rep = if (any_at_call) try self.staticMethodCallRep(requirement.fn_ty, position_reps.items) else null,
        };
    }

    /// The requirement's own position at this call, when the selected
    /// target's declared position names variables of the target's scheme
    /// and the requirement's position is written only in variables this call
    /// binds: the dispatcher at the dictionary's type and every other
    /// variable at the calling edge's instantiation. Relating the target's
    /// declared position to it binds the target's variables, so the target
    /// is called there. Null for every other position.
    fn requirementPositionAtCall(
        self: *Builder,
        call: RequirementCallInstantiation,
        dispatcher_rep: TypeRepId,
        source_rep_id: TypeRepId,
        rep_id: TypeRepId,
        target_rep_id: TypeRepId,
    ) Allocator.Error!?TypeRepId {
        if (rep_id == dispatcher_rep) return null;
        if (!try self.plan.namesTypeVariable(self.allocator, target_rep_id)) return null;
        if (call.get(&self.plan, rep_id) != null) return null;
        if (!try self.plan.namesTypeVariable(self.allocator, rep_id)) return null;

        // The key is the position followed by each of its variables and the
        // representation this call binds it to.
        var key = std.ArrayList(u32).empty;
        defer key.deinit(self.allocator);
        try key.appendSlice(self.allocator, &.{ 0, @intFromEnum(rep_id) });
        var pending = std.ArrayList(TypeRepId).empty;
        defer pending.deinit(self.allocator);
        var seen = std.AutoHashMapUnmanaged(TypeRepId, void).empty;
        defer seen.deinit(self.allocator);
        try pending.append(self.allocator, rep_id);
        while (pending.pop()) |current| {
            if ((try seen.getOrPut(self.allocator, current)).found_existing) continue;
            if (self.repIsBareVariable(current)) {
                const site = if (current == dispatcher_rep)
                    source_rep_id
                else
                    call.get(&self.plan, current) orelse return null;
                try key.appendSlice(self.allocator, &.{ @intFromEnum(current), @intFromEnum(site) });
                continue;
            }
            // A nominal's backing is written in its declaration's formals,
            // which its arguments instantiate.
            for (self.plan.childSlice(self.plan.representations.items[@intFromEnum(current)].children)) |child| {
                if (child.role == .nominal_backing) continue;
                try pending.append(self.allocator, child.rep);
            }
        }
        if (self.static_method_call_reps.get(key.items)) |existing| return existing;

        var bindings = std.AutoHashMapUnmanaged(TypeRepId, TypeRepId).empty;
        defer bindings.deinit(self.allocator);
        var binding_index: usize = 2;
        while (binding_index < key.items.len) : (binding_index += 2) {
            try bindings.put(self.allocator, @enumFromInt(key.items[binding_index]), @enumFromInt(key.items[binding_index + 1]));
        }
        const rep = try self.substitutedRep(rep_id, &bindings);
        try self.putStaticMethodCallRep(key.items, rep);
        return rep;
    }

    /// `root` with each variable `bindings` names replaced by its binding:
    /// every representation on the way to a replaced variable is copied with
    /// the replaced children, and one naming no replaced variable is shared.
    /// A nominal's backing template stays shared; its use's actuals are the
    /// replaced arguments.
    fn substitutedRep(
        self: *Builder,
        root: TypeRepId,
        bindings: *const std.AutoHashMapUnmanaged(TypeRepId, TypeRepId),
    ) Allocator.Error!TypeRepId {
        var replaced = std.AutoHashMapUnmanaged(TypeRepId, TypeRepId).empty;
        defer replaced.deinit(self.allocator);
        var expanding = std.AutoHashMapUnmanaged(TypeRepId, void).empty;
        defer expanding.deinit(self.allocator);
        const Frame = struct { rep: TypeRepId, expanded: bool };
        var frames = std.ArrayList(Frame).empty;
        defer frames.deinit(self.allocator);
        try frames.append(self.allocator, .{ .rep = root, .expanded = false });
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            const rep_id = frame.rep;
            if (replaced.contains(rep_id)) {
                _ = frames.pop();
                continue;
            }
            if (bindings.get(rep_id)) |binding| {
                try replaced.put(self.allocator, rep_id, binding);
                _ = frames.pop();
                continue;
            }
            if (!try self.plan.namesTypeVariable(self.allocator, rep_id)) {
                try replaced.put(self.allocator, rep_id, rep_id);
                _ = frames.pop();
                continue;
            }
            const rep = self.plan.representations.items[@intFromEnum(rep_id)];
            if (!frame.expanded) {
                if ((try expanding.getOrPut(self.allocator, rep_id)).found_existing) {
                    boxyPlanInvariant("a substituted representation reached itself through its own variables");
                }
                frame.expanded = true;
                for (0..rep.children.len) |index| {
                    const child = self.plan.children.items[rep.children.start + index];
                    if (child.role == .nominal_backing) continue;
                    try frames.append(self.allocator, .{ .rep = child.rep, .expanded = false });
                }
                continue;
            }
            _ = frames.pop();
            var copy = rep;
            copy.descriptor = null;
            copy.sealed_default = null;
            copy.contains_dynamic = false;
            const children_start: u32 = @intCast(self.plan.children.items.len);
            // Read by index: appending grows the child table.
            for (0..rep.children.len) |index| {
                var child = self.plan.children.items[rep.children.start + index];
                if (child.role != .nominal_backing) child.rep = replaced.get(child.rep).?;
                try self.plan.children.append(self.allocator, child);
            }
            copy.children = .{ .start = children_start, .len = rep.children.len };
            const variants_start: u32 = @intCast(self.plan.tag_variants.items.len);
            for (0..rep.tag_variants.len) |index| {
                var variant = self.plan.tag_variants.items[rep.tag_variants.start + index];
                variant.payloads.start = variant.payloads.start - rep.children.start + children_start;
                try self.plan.tag_variants.append(self.allocator, variant);
            }
            copy.tag_variants = .{ .start = variants_start, .len = rep.tag_variants.len };
            if (rep.nominal_backing_arg_substitutions.len != 0) {
                const uses_start: u32 = @intCast(self.plan.nominal_backing_uses.items.len);
                try self.plan.nominal_backing_uses.append(self.allocator, self.plan.nominal_backing_uses.items[rep.nominal_backing_arg_substitutions.start]);
                for (0..rep.nominal_backing_arg_substitutions.len) |index| {
                    const actual: TypeRepId = @enumFromInt(self.plan.nominal_backing_uses.items[rep.nominal_backing_arg_substitutions.start + 1 + index]);
                    // Each actual is one of the use's argument children.
                    const substituted = replaced.get(actual) orelse if (!try self.plan.namesTypeVariable(self.allocator, actual))
                        actual
                    else
                        boxyPlanInvariant("a substituted nominal use's actual was not one of its arguments");
                    try self.plan.nominal_backing_uses.append(self.allocator, @intFromEnum(substituted));
                }
                copy.nominal_backing_arg_substitutions = .{ .start = uses_start, .len = rep.nominal_backing_arg_substitutions.len };
            }
            if (rep.is_open_tag_row) {
                // A row whose extension is now closed is a closed row.
                const extension = self.plan.representations.items[@intFromEnum(replaced.get(self.openRowExtensionRep(rep)).?)];
                switch (extension.kind) {
                    .empty_tag_union => {
                        copy.kind = .tag_union;
                        copy.is_open_tag_row = false;
                    },
                    .dynamic => {},
                    .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union => boxyPlanInvariant("a substituted open tag row's extension was not a closed empty row or a row variable"),
                }
            }
            const id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
            try self.plan.representations.append(self.allocator, copy);
            try replaced.put(self.allocator, rep_id, id);
        }
        return replaced.get(root).?;
    }

    fn putStaticMethodCallRep(self: *Builder, key: []const u32, rep: TypeRepId) Allocator.Error!void {
        const owned = try self.allocator.dupe(u32, key);
        errdefer self.allocator.free(owned);
        try self.static_method_call_reps.put(self.allocator, owned, rep);
    }

    /// A function representation of `fn_type` whose arguments and result are
    /// `position_reps`, the result last.
    fn staticMethodCallRep(self: *Builder, fn_type: CheckedTypeIdentity, position_reps: []const TypeRepId) Allocator.Error!TypeRepId {
        var key = std.ArrayList(u32).empty;
        defer key.deinit(self.allocator);
        try key.appendSlice(self.allocator, &.{ 1, @intFromEnum(self.plan.repForSourceType(fn_type) orelse
            boxyPlanInvariant("static dictionary requirement type was not analyzed")) });
        for (position_reps) |rep| try key.append(self.allocator, @intFromEnum(rep));
        if (self.static_method_call_reps.get(key.items)) |existing| return existing;
        var children = std.ArrayList(RepChild).empty;
        defer children.deinit(self.allocator);
        const arg_count = position_reps.len - 1;
        for (position_reps, 0..) |rep, index| {
            try children.append(self.allocator, .{
                .role = if (index == arg_count) .function_ret else .{ .function_arg = @intCast(index) },
                .rep = rep,
                .source_type = self.plan.representations.items[@intFromEnum(rep)].source_type,
            });
        }
        const id: TypeRepId = @enumFromInt(@as(u32, @intCast(self.plan.representations.items.len)));
        try self.plan.representations.append(self.allocator, .{
            .source_type = fn_type,
            .kind = .erased_callable,
            .children = try self.commitPendingChildren(children.items),
        });
        try self.putStaticMethodCallRep(key.items, id);
        return id;
    }

    fn instantiatedRequirementType(
        self: *Builder,
        call: RequirementCallInstantiation,
        dispatcher_rep: TypeRepId,
        source_type: CheckedTypeIdentity,
        rep_id: TypeRepId,
        target_rep_id: TypeRepId,
    ) Allocator.Error!CheckedTypeIdentity {
        if (rep_id == dispatcher_rep) return source_type;
        const target_type = self.plan.representations.items[@intFromEnum(target_rep_id)].source_type;
        // The selected target's declared type is the position's exact type
        // wherever it names no variable of the target's own scheme.
        if (!try self.plan.namesTypeVariable(self.allocator, target_rep_id)) return target_type;
        if (call.get(&self.plan, rep_id)) |call_rep| return self.plan.representations.items[@intFromEnum(call_rep)].source_type;
        if (!try self.plan.namesTypeVariable(self.allocator, rep_id)) {
            return self.plan.representations.items[@intFromEnum(rep_id)].source_type;
        }
        // A requirement position built around the dispatcher has no checked
        // type of its own; the call relates it to the target's declared
        // position through the requirement's descriptor sources.
        return target_type;
    }

    fn defaultedDictionaryOwner(self: *Builder, rep_id: TypeRepId) ?static_dispatch.MethodOwner {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const view = self.moduleForId(rep.source_type.module);
        const payload = view.checked_types.payload(rep.source_type.ty);
        const variable = if (payload == .flex)
            payload.flex
        else if (payload == .rigid)
            payload.rigid
        else
            return null;
        const builtin: static_dispatch.BuiltinOwner = switch (variable.numeric_default_phase orelse return null) {
            .mono_specialization => .dec,
            .mono_specialization_str => .str,
            .checking_finalized => return null,
        };
        return .{ .builtin = builtin };
    }

    fn structuralDictionaryMethodEvidence(
        self: *Builder,
        source_rep: TypeRepresentation,
        requirement: DictionaryRequirement,
        requirement_view: ModuleView,
    ) Allocator.Error!DictionaryMethodEvidence {
        const kind = self.structuralKindForRequirement(requirement, requirement_view) orelse
            boxyPlanInvariant("static boxy dictionary could not resolve a checked method target or structural method");
        _ = try self.analyzeType(requirement_view, requirement.fn_ty.ty);
        return switch (kind) {
            .equality, .hash => .{
                .requirement_type = requirement.fn_ty,
                .callable_type = requirement.fn_ty,
                .resolution = .{ .structural = kind },
            },
            .parser, .encoder => try self.generatedCodecStaticDictionaryMethodEvidence(
                source_rep,
                requirement,
                requirement_view,
                kind,
            ),
            .map, .map_effectful => boxyPlanInvariant("derived map evidence reached Boxy runtime dictionary planning"),
        };
    }

    fn generatedCodecStaticDictionaryMethodEvidence(
        self: *Builder,
        source_rep: TypeRepresentation,
        requirement: DictionaryRequirement,
        requirement_view: ModuleView,
        kind: static_dispatch.StructuralKind,
    ) Allocator.Error!DictionaryMethodEvidence {
        const expected_kind: static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
            .parser => .parser,
            .encoder => .encoder,
            .equality, .hash, .map, .map_effectful => boxyPlanInvariant("non-codec dictionary requested a generated codec worker"),
        };
        const source_view = self.moduleForId(source_rep.source_type.module);
        if (!moduleKeyEqual(source_view.key, requirement_view.key) or
            !moduleKeyEqual(requirement.fn_ty.module, requirement_view.key))
        {
            boxyPlanInvariant("generated codec dictionary types belonged to different checked modules");
        }

        const constructor = checkedFunctionPayload(requirement_view, requirement.fn_ty.ty);
        if (constructor.args.len != 1) {
            boxyPlanInvariant("generated codec dictionary constructor had unexpected arity");
        }
        const runtime = checkedFunctionPayload(requirement_view, constructor.ret);
        const state_type = switch (expected_kind) {
            .parser => if (runtime.args.len == 1)
                runtime.args[0]
            else
                boxyPlanInvariant("generated parser dictionary runtime had unexpected arity"),
            .encoder => if (runtime.args.len == 2)
                runtime.args[1]
            else
                boxyPlanInvariant("generated encoder dictionary runtime had unexpected arity"),
        };
        const try_payloads = checkedTryPayloads(requirement_view, runtime.ret) orelse
            boxyPlanInvariant("generated codec dictionary runtime did not return Try");
        const shape_key = source_view.checked_types.rootKey(source_rep.source_type.ty);
        const encoding_key = requirement_view.checked_types.rootKey(constructor.args[0]);
        const state_key = requirement_view.checked_types.rootKey(state_type);
        const error_key = requirement_view.checked_types.rootKey(try_payloads.err);
        if (self.active_stored_fn) |stored| {
            // A stored function carries the evidence its value was produced
            // with. Its structural entry for this shape is the dictionary's
            // method, exactly as the same entry is at a live checked use.
            if (self.storedCodecEvidenceForShape(stored, source_view, expected_kind, shape_key)) |evidence| {
                const derivation_id = evidence.generated_codec_derivation.?;
                const derivation = source_view.static_dispatch_plans.generated_codec_derivations[@intFromEnum(derivation_id)];
                if (!std.meta.eql(encoding_key, source_view.checked_types.rootKey(derivation.encoding_ty)) or
                    !std.meta.eql(state_key, source_view.checked_types.rootKey(derivation.state_ty)))
                {
                    boxyPlanInvariant("stored codec evidence named a contract for another format");
                }
                const callable_type = typeRef(source_view, evidence.callable_ty);
                _ = try self.analyzeType(source_view, evidence.callable_ty);
                return .{
                    .requirement_type = requirement.fn_ty,
                    .callable_type = callable_type,
                    .resolution = .{ .worker = try self.ensureWorker(
                        .{ .generated_codec = .{
                            .kind = if (expected_kind == .parser) .parser_constructor else .encoder_constructor,
                            .shape = typeRef(source_view, evidence.dispatcher_ty),
                            .contract_derivation = derivation_id,
                        } },
                        callable_type,
                        null,
                    ) },
                };
            }
        }
        var found: ?struct {
            id: static_dispatch.GeneratedCodecDerivationId,
            derivation: static_dispatch.GeneratedCodecDerivation,
        } = null;
        for (source_view.static_dispatch_plans.generated_codec_derivations, 0..) |derivation, index| {
            if (derivation.kind != expected_kind or
                !std.meta.eql(shape_key, source_view.checked_types.rootKey(derivation.shape_ty)) or
                !std.meta.eql(encoding_key, source_view.checked_types.rootKey(derivation.encoding_ty)) or
                !std.meta.eql(state_key, source_view.checked_types.rootKey(derivation.state_ty)) or
                !std.meta.eql(error_key, source_view.checked_types.rootKey(derivation.error_ty)))
            {
                continue;
            }
            if (found) |existing| {
                if (!generatedCodecDerivationsEql(source_view.static_dispatch_plans, existing.derivation, derivation)) {
                    boxyPlanInvariant("generated codec dictionary matched multiple checked derivation contracts");
                }
            } else {
                found = .{
                    .id = @enumFromInt(@as(u32, @intCast(index))),
                    .derivation = derivation,
                };
            }
        }

        const selected = found orelse
            boxyPlanInvariant("generated codec dictionary had no matching checked derivation contract");
        const callable_type = typeRef(source_view, selected.derivation.constructor_ty);
        const shape = source_rep.source_type;
        return .{
            .requirement_type = requirement.fn_ty,
            .callable_type = callable_type,
            .resolution = .{ .worker = try self.ensureWorker(
                .{ .generated_codec = .{
                    .kind = if (expected_kind == .parser) .parser_constructor else .encoder_constructor,
                    .shape = shape,
                    .contract_derivation = selected.id,
                } },
                callable_type,
                null,
            ) },
        };
    }

    /// The structural codec evidence a stored function retained for this
    /// dispatcher shape: the entry its value was produced with.
    fn storedCodecEvidenceForShape(
        self: *Builder,
        stored: StoredFnSource,
        shape_view: ModuleView,
        kind: static_dispatch.GeneratedCodecDerivationKind,
        shape_key: anytype,
    ) ?static_dispatch.StructuralEvidence {
        const store_view = self.moduleForId(stored.module);
        const fn_value = (store_view.const_store orelse boxyPlanInvariant("stored function had no ConstStore")).getFn(stored.fn_id);
        const expected: static_dispatch.StructuralKind = switch (kind) {
            .parser => .parser,
            .encoder => .encoder,
        };
        var selected: ?static_dispatch.StructuralEvidence = null;
        for (fn_value.evidence) |entry| {
            const structural = switch (entry) {
                .structural => |structural| structural,
                .target, .from_callable, .from_scheme, .unreachable_value, .checked_error => continue,
            };
            if (structural.derivation.kind() != expected) continue;
            const checked_evidence = structural.checked orelse continue;
            if (checked_evidence.generated_codec_derivation == null) continue;
            if (!std.meta.eql(checked_evidence.view.bytes, shape_view.key.bytes)) {
                boxyPlanInvariant("stored codec evidence named a contract outside its shape's module");
            }
            if (!std.meta.eql(shape_view.checked_types.rootKey(checked_evidence.dispatcher_ty), shape_key)) continue;
            const evidence = static_dispatch.StructuralEvidence{
                .derivation = structural.derivation,
                .dispatcher_ty = checked_evidence.dispatcher_ty,
                .callable_ty = checked_evidence.callable_ty,
                .generated_codec_derivation = checked_evidence.generated_codec_derivation,
            };
            if (selected) |existing| {
                if (existing.generated_codec_derivation != evidence.generated_codec_derivation or
                    !std.meta.eql(shape_view.checked_types.rootKey(existing.callable_ty), shape_view.checked_types.rootKey(evidence.callable_ty)))
                {
                    boxyPlanInvariant("stored codec evidence named two contracts for one shape");
                }
            } else {
                selected = evidence;
            }
        }
        return selected;
    }

    fn structuralKindForRequirement(
        _: *Builder,
        requirement: DictionaryRequirement,
        requirement_view: ModuleView,
    ) ?static_dispatch.StructuralKind {
        const canonical_names = requirement_view.canonical_names orelse return null;
        for (static_dispatch.structural_method_kinds) |entry| {
            const method = canonical_names.lookupMethodName(entry.method_name) orelse continue;
            if (method == requirement.fn_name) return entry.kind;
        }
        return null;
    }

    const MethodTargetLookup = struct {
        view: ModuleView,
        method: ?MethodNameId = null,
        target: static_dispatch.MethodTarget,
        /// For an inspect override, the checked evidence of inspection's use.
        inspect_evidence: ?static_dispatch.EvidenceNodeId = null,
    };

    /// What an exact registry lookup found. `rejected` is a declared method
    /// whose declaration canonicalization or checking rejected: it has no
    /// worker, and a dispatch that lands on it is a `checked_error`.
    const MethodLookupResult = union(enum) {
        target: MethodTargetLookup,
        rejected,
    };

    fn lookupMethodTarget(
        self: *Builder,
        owner_view: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_view: ModuleView,
        method: MethodNameId,
    ) ?MethodTargetLookup {
        const method_text = method_view.canonical_names.?.methodNameText(method);
        return switch (self.lookupMethodTargetByText(owner_view, owner, method_text) orelse return null) {
            .target => |lookup| lookup,
            .rejected => boxyPlanInvariant("a checked requirement's method target was a rejected declaration"),
        };
    }

    fn lookupMethodTargetByText(
        self: *Builder,
        owner_view: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_text: []const u8,
    ) ?MethodLookupResult {
        if (self.lookupMethodTargetInView(owner_view, owner_view, owner, method_text)) |target| return target;
        for (self.imports) |imported| {
            const view = moduleViewFromImported(imported);
            if (moduleKeyEqual(view.key, owner_view.key)) continue;
            if (self.lookupMethodTargetInView(view, owner_view, owner, method_text)) |target| return target;
        }
        for (self.relation_modules) |relation| {
            const view = moduleViewFromImported(relation);
            if (moduleKeyEqual(view.key, owner_view.key)) continue;
            if (self.lookupMethodTargetInView(view, owner_view, owner, method_text)) |target| return target;
        }
        return null;
    }

    /// The checked `to_inspect` override that inspection calls for `owner`,
    /// or null when inspection renders the owner's default form. The view
    /// that declares `owner.to_inspect` is selected exactly as method dispatch
    /// selects it; that declaration's checked eligibility is the answer.
    fn lookupInspectOverride(
        self: *Builder,
        owner_view: ModuleView,
        owner: static_dispatch.MethodOwner,
    ) ?MethodTargetLookup {
        if (inspectOverrideInView(owner_view, owner_view, owner)) |decision| return decision.target;
        for (self.imports) |imported| {
            const view = moduleViewFromImported(imported);
            if (moduleKeyEqual(view.key, owner_view.key)) continue;
            if (inspectOverrideInView(view, owner_view, owner)) |decision| return decision.target;
        }
        for (self.relation_modules) |relation| {
            const view = moduleViewFromImported(relation);
            if (moduleKeyEqual(view.key, owner_view.key)) continue;
            if (inspectOverrideInView(view, owner_view, owner)) |decision| return decision.target;
        }
        return null;
    }

    const InspectOverrideDecision = struct {
        target: ?MethodTargetLookup,
    };

    fn inspectOverrideInView(
        candidate: ModuleView,
        owner_view: ModuleView,
        owner: static_dispatch.MethodOwner,
    ) ?InspectOverrideDecision {
        const owner_names = owner_view.canonical_names orelse return null;
        const candidate_names = candidate.canonical_names orelse return null;
        const candidate_owner = methodOwnerInNames(owner_names, candidate_names, owner) orelse return null;
        const candidate_method = candidate_names.lookupMethodName("to_inspect") orelse return null;
        const key: static_dispatch.MethodKey = .{ .owner = candidate_owner, .method = candidate_method };
        // A declared `to_inspect` decides inspection in this view; the registry
        // records an override only for an eligible, unrejected declaration.
        _ = candidate.method_registry.lookup(key) orelse return null;
        const override = candidate.method_registry.lookupInspectOverride(key) orelse return .{ .target = null };
        // Inspection calls the method at its checked `T -> Str` instance.
        var target = override.target;
        target.callable_ty = override.callable_ty;
        return .{ .target = .{
            .view = candidate,
            .method = candidate_method,
            .target = target,
            .inspect_evidence = override.evidence,
        } };
    }

    fn lookupMethodTargetInView(
        _: *Builder,
        candidate: ModuleView,
        owner_view: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_text: []const u8,
    ) ?MethodLookupResult {
        const owner_names = owner_view.canonical_names orelse return null;
        const candidate_names = candidate.canonical_names orelse return null;
        const candidate_owner = methodOwnerInNames(owner_names, candidate_names, owner) orelse return null;
        const candidate_method = candidate_names.lookupMethodName(method_text) orelse return null;
        return switch (candidate.method_registry.lookup(.{ .owner = candidate_owner, .method = candidate_method }) orelse return null) {
            .rejected => .rejected,
            .target => |target| .{ .target = .{ .view = candidate, .method = candidate_method, .target = target } },
        };
    }

    fn workerSourceForMethodTarget(
        self: *Builder,
        lookup: MethodTargetLookup,
        shape: CheckedTypeIdentity,
        contract_derivation: ?static_dispatch.GeneratedCodecDerivationId,
    ) WorkerSource {
        return switch (lookup.target.kind) {
            .procedure => |procedure| .{ .procedure_template = procedure.template },
            .local_proc => |local| if (self.topLevelProcedureBindingForExpr(lookup.view, local.expr)) |binding|
                .{ .procedure_binding = binding }
            else
                .{ .nested_expr = .{ .module = lookup.view.key, .expr = self.nestedCallableSiteExprForExpr(lookup.view, local.expr) orelse local.expr } },
            .structural => |kind| switch (kind) {
                .parser => .{ .generated_codec = .{
                    .kind = .parser_constructor,
                    .shape = shape,
                    .contract_derivation = contract_derivation,
                } },
                .encoder => .{ .generated_codec = .{
                    .kind = .encoder_constructor,
                    .shape = shape,
                    .contract_derivation = contract_derivation,
                } },
                .equality, .hash, .map, .map_effectful => boxyPlanInvariant("non-codec structural target reached Boxy method worker selection"),
            },
        };
    }

    /// Returns the exact call-side row that instantiates a worker child when
    /// open tag rows expose different tags on each side of a checked function
    /// boundary. When the call contributes unmatched tags, the worker
    /// extension denotes the complete call row with its stored discriminants.
    fn rowInstantiationTarget(
        self: *Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        worker_child: RepChild,
    ) ?TypeRepId {
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
        if ((worker_rep.kind != .tag_union and worker_rep.kind != .dynamic and worker_rep.kind != .bool_tag_union) or
            (call_rep.kind != .tag_union and call_rep.kind != .dynamic and call_rep.kind != .bool_tag_union)) return null;

        switch (worker_child.role) {
            .tag_ext => {
                const worker_variants = self.plan.tagVariantSlice(worker_rep.tag_variants);
                for (self.plan.tagVariantSlice(call_rep.tag_variants)) |call_variant| {
                    var matched = false;
                    for (worker_variants) |worker_variant| {
                        if (tagLabelNameMatches(
                            self.moduleNames(worker_variant.name_module),
                            worker_variant.name,
                            self.moduleNames(call_variant.name_module),
                            call_variant.name,
                        )) {
                            matched = true;
                            break;
                        }
                    }
                    if (!matched) return call_rep_id;
                }
                return null;
            },
            .tag_payload,
            .alias_backing,
            .alias_arg,
            .nominal_backing,
            .nominal_arg,
            .nominal_padding_field,
            .record_field,
            .record_ext,
            .tuple_elem,
            .function_arg,
            .function_ret,
            .list_elem,
            .box_payload,
            => return null,
        }
    }

    fn workerPresenceSlotPayloadMatchesUnwrappedCallRep(
        self: *const Builder,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        worker_child: RepChild,
    ) bool {
        const worker_rep = self.plan.representations.items[@intFromEnum(worker_rep_id)];
        const present_discriminant = worker_rep.presence_slot_present_discriminant orelse return false;
        const call_rep = self.plan.representations.items[@intFromEnum(call_rep_id)];
        if (call_rep.presence_slot_present_discriminant != null) return false;

        const variants = self.plan.tagVariantSlice(worker_rep.tag_variants);
        const present_index: usize = present_discriminant;
        if (present_index >= variants.len) {
            boxyPlanInvariant("presence-slot Present discriminant exceeded its planned variants");
        }
        for (self.plan.childSlice(variants[present_index].payloads)) |payload| {
            if (payload.rep == worker_child.rep and std.meta.eql(payload.role, worker_child.role)) return true;
        }
        return false;
    }

    fn callDescriptorRepsAgreeAcrossPresenceSlot(
        self: *const Builder,
        first: TypeRepId,
        second: TypeRepId,
    ) bool {
        if (first == second) return true;
        if (self.presenceSlotPayloadRep(first)) |payload| {
            if (payload == second) return true;
        }
        if (self.presenceSlotPayloadRep(second)) |payload| {
            if (payload == first) return true;
        }
        return false;
    }

    fn presenceSlotPayloadRep(self: *const Builder, rep_id: TypeRepId) ?TypeRepId {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        const present_discriminant = rep.presence_slot_present_discriminant orelse return null;
        const variants = self.plan.tagVariantSlice(rep.tag_variants);
        const present_index: usize = present_discriminant;
        if (present_index >= variants.len) {
            boxyPlanInvariant("presence-slot Present discriminant exceeded its planned variants");
        }
        const payloads = self.plan.childSlice(variants[present_index].payloads);
        if (payloads.len != 1) {
            boxyPlanInvariant("presence-slot Present variant did not have exactly one planned payload");
        }
        return payloads[0].rep;
    }

    const WorkerBody = union(enum) {
        checked_expr: struct {
            view: ModuleView,
            root_expr: checked.CheckedExprId,
            stored_fn: ?StoredFnSource = null,
        },
        intrinsic_wrapper: struct {
            view: ModuleView,
            wrapper: checked.IntrinsicWrapper,
        },
        hosted_proc: struct {
            view: ModuleView,
            proc: checked.HostedProc,
        },
        /// The declaration behind this worker has a type annotation and no
        /// implementation, so reaching the worker crashes.
        unimplemented,
    };

    fn rootWorkerBody(self: *Builder, source: WorkerSource) WorkerBody {
        return switch (source) {
            .procedure_template => |template| self.rootProcedureTemplateBody(template),
            .procedure_binding => |binding| self.rootProcedureBindingBody(self.moduleForId(binding.artifact), binding.binding),
            .procedure_use => |use| switch (use.binding) {
                .top_level => |top_level| blk: {
                    const view = self.moduleForId(top_level.artifact);
                    break :blk self.rootProcedureBindingBody(view, top_level.binding);
                },
                .platform_required => |required| blk: {
                    const view = self.moduleForId(required.app_value.artifact);
                    break :blk self.rootProcedureBindingBody(view, required.procedure_binding);
                },
                .imported => |imported| self.importedProcedureBindingBody(imported),
                .hosted => |hosted| self.hostedProcedureBody(hosted),
            },
            .nested_expr => |expr_ref| self.nestedExprWorkerBody(expr_ref),
            .generated_codec => boxyPlanInvariant("generated codec worker has no checked procedure body"),
            .generated_field_iterator => boxyPlanInvariant("generated FieldNames iterator worker has no checked procedure body"),
            .generated_interpolation_step => boxyPlanInvariant("generated interpolation step worker has no checked procedure body"),
        };
    }

    fn nestedExprWorkerBody(self: *Builder, expr_ref: CheckedExprIdentity) WorkerBody {
        const view = self.moduleForId(expr_ref.module);
        const expr = view.checked_bodies.expr(expr_ref.expr);
        const root_expr = if (expr.data == .lambda)
            expr_ref.expr
        else if (expr.data == .closure)
            expr.data.closure.lambda
        else
            boxyPlanInvariant("nested callable worker source did not point at a lambda or closure");
        return .{ .checked_expr = .{
            .view = view,
            .root_expr = root_expr,
        } };
    }

    /// Whether this binding's body is a callable-eval whose compile-time root
    /// is still pending (an unfinalized binding the running roots never
    /// reference; `roc test` finalizes only what its expects reach). Such a
    /// body cannot be planned; callers skip eager work for it and the panic is
    /// deferred to an actual attempt to lower it.
    fn procedureBindingBodyIsPendingEval(self: *Builder, view: ModuleView, binding_ref: checked.TopLevelProcedureBindingRef) bool {
        const binding = view.top_level_procedure_bindings.get(binding_ref);
        return switch (binding.body) {
            .direct_template => false,
            .checked_error => false,
            .callable_eval_template => |template_id| blk: {
                const template = self.callableEvalTemplate(view, template_id);
                const root = view.compile_time_roots.root(template.root);
                break :blk root.payload == .pending;
            },
        };
    }

    fn pendingCallableEvalExprForSource(
        self: *Builder,
        source: WorkerSource,
    ) ?CheckedExprIdentity {
        return switch (source) {
            .procedure_binding => |binding_ref| blk: {
                const view = self.moduleForId(binding_ref.artifact);
                const binding = view.top_level_procedure_bindings.get(binding_ref.binding);
                break :blk self.pendingCallableEvalExprForBody(view, binding.body);
            },
            .procedure_use => |procedure| switch (procedure.binding) {
                .top_level => |binding_ref| blk: {
                    const view = self.moduleForId(binding_ref.artifact);
                    const binding = view.top_level_procedure_bindings.get(binding_ref.binding);
                    break :blk self.pendingCallableEvalExprForBody(view, binding.body);
                },
                .platform_required => |required| blk: {
                    const view = self.moduleForId(required.app_value.artifact);
                    const binding = view.top_level_procedure_bindings.get(required.procedure_binding);
                    break :blk self.pendingCallableEvalExprForBody(view, binding.body);
                },
                .imported => |imported| blk: {
                    const view = self.moduleForId(imported.artifact);
                    break :blk self.pendingCallableEvalExprForBody(
                        view,
                        self.importedProcedureBinding(view, imported).body,
                    );
                },
                .hosted => null,
            },
            .procedure_template,
            .nested_expr,
            .generated_codec,
            .generated_field_iterator,
            .generated_interpolation_step,
            => null,
        };
    }

    /// Whether a checked direct target is an exact procedure alias: a local
    /// alias, or a procedure use whose binding is a callable-eval template
    /// (checking classifies only exact procedure aliases of those as direct).
    fn directTargetIsThroughAlias(self: *Builder, view: ModuleView, target: checked.ResolvedValueId) bool {
        const procedure = switch (self.resolvedValueRecord(view, target).ref) {
            .local_proc => |local| return local.is_alias,
            .top_level_proc, .imported_proc, .promoted_top_level_proc => |procedure| procedure,
            .platform_required_proc => |required| required.procedure,
            .hosted_proc => return false,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => boxyPlanInvariant("checked direct call target did not reference a procedure"),
        };
        const body_is_callable_eval = switch (procedure.binding) {
            .top_level => |binding_ref| self.moduleForId(binding_ref.artifact).top_level_procedure_bindings.get(binding_ref.binding).body == .callable_eval_template,
            .platform_required => |required| self.moduleForId(required.app_value.artifact).top_level_procedure_bindings.get(required.procedure_binding).body == .callable_eval_template,
            .imported => |imported| blk: {
                const imported_view = self.moduleForId(imported.artifact);
                break :blk self.importedProcedureBinding(imported_view, imported).body == .callable_eval_template;
            },
            .hosted => false,
        };
        return body_is_callable_eval;
    }

    fn pendingCallableEvalExprForBody(
        self: *Builder,
        view: ModuleView,
        body: anytype,
    ) ?CheckedExprIdentity {
        const template_id = switch (body) {
            .direct_template => return null,
            .checked_error => return null,
            .callable_eval_template => |template| template,
        };
        const template = self.callableEvalTemplate(view, template_id);
        const root = view.compile_time_roots.root(template.root);
        return switch (root.payload) {
            .pending => .{ .module = view.key, .expr = root.expr },
            .fn_value, .const_node, .discarded, .expect, .runtime => null,
        };
    }

    fn rootProcedureBindingBody(self: *Builder, view: ModuleView, binding_ref: checked.TopLevelProcedureBindingRef) WorkerBody {
        const binding = view.top_level_procedure_bindings.get(binding_ref);
        return switch (binding.body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| self.rootProcedureTemplateBody(template),
                .lifted,
                .synthetic,
                => boxyPlanInvariant("non-checked procedure template reached boxy body type planning"),
            },
            .checked_error => |expr| .{ .checked_expr = .{ .view = view, .root_expr = expr } },
            .callable_eval_template => |template| self.callableEvalTemplateBody(view, template),
        };
    }

    fn importedProcedureBindingBody(self: *Builder, binding_ref: checked.ImportedProcedureBindingRef) WorkerBody {
        const view = self.moduleForId(binding_ref.artifact);
        const binding = self.importedProcedureBinding(view, binding_ref);
        return switch (binding.body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| self.rootProcedureTemplateBody(template),
                .lifted,
                .synthetic,
                => boxyPlanInvariant("non-checked imported procedure template reached boxy body type planning"),
            },
            .checked_error => |expr| .{ .checked_expr = .{ .view = view, .root_expr = expr } },
            .callable_eval_template => |template| self.callableEvalTemplateBody(view, template),
        };
    }

    fn hostedProcedureBody(self: *Builder, hosted_ref: checked.HostedProcRef) WorkerBody {
        const view = self.moduleForId(checked.hostedProcedureTemplateModuleId(hosted_ref));
        return .{ .hosted_proc = .{
            .view = view,
            .proc = hostedProcForTemplate(view, hosted_ref.template),
        } };
    }

    fn importedProcedureBinding(
        _: *Builder,
        view: ModuleView,
        binding_ref: checked.ImportedProcedureBindingRef,
    ) checked.ImportedProcedureBindingView {
        for (view.exported_procedure_bindings.bindings) |binding| {
            if (moduleKeyEqual(binding.binding.artifact, binding_ref.artifact) and
                binding.binding.def == binding_ref.def and
                binding.binding.pattern == binding_ref.pattern)
            {
                return binding;
            }
        }
        boxyPlanInvariant("imported procedure binding was not exported by its checked module");
    }

    fn rootProcedureTemplateBody(self: *Builder, template_ref: checked_names.ProcedureTemplateRef) WorkerBody {
        const view = self.moduleForCheckedModuleId(template_ref.artifact);
        const template = view.checked_procedure_templates.get(template_ref.template);
        if (template.target == .hosted) {
            return .{ .hosted_proc = .{
                .view = view,
                .proc = hostedProcForTemplate(view, template_ref),
            } };
        }
        return switch (template.body) {
            .checked_body => |body| .{ .checked_expr = .{
                .view = view,
                .root_expr = view.checked_bodies.body(body).root_expr,
            } },
            .intrinsic_wrapper => |wrapper_id| .{ .intrinsic_wrapper = .{
                .view = view,
                .wrapper = view.intrinsic_wrappers.get(wrapper_id),
            } },
            .entry_wrapper => |wrapper_id| .{ .checked_expr = .{
                .view = view,
                .root_expr = view.entry_wrappers.get(wrapper_id).body_expr,
            } },
            .unimplemented => .unimplemented,
        };
    }

    fn callableEvalTemplateBody(
        self: *Builder,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
    ) WorkerBody {
        const template = self.callableEvalTemplate(view, template_id);
        const root = view.compile_time_roots.root(template.root);
        return switch (root.payload) {
            .fn_value => |fn_id| self.constFnValueBody(view, fn_id),
            .pending => boxyPlanInvariant("pending callable eval root reached runtime boxy body type planning before compile-time finalization"),
            .const_node,
            .discarded,
            .expect,
            .runtime,
            => boxyPlanInvariant("callable eval binding root did not output a callable value"),
        };
    }

    fn constFnValueBody(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
    ) WorkerBody {
        const store = store_view.const_store orelse
            boxyPlanInvariant("callable eval function value had no checked ConstStore");
        const raw = @intFromEnum(fn_id);
        if (raw >= store.fns.items.len) {
            boxyPlanInvariant("callable eval function value referenced a missing ConstStore function");
        }
        const fn_value = store.getFn(fn_id);
        var body = switch (fn_value.fn_def) {
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| self.rootProcedureTemplateBody(template),
            .nested => |nested| self.nestedConstFnBody(nested),
            .local_hosted,
            .imported_hosted,
            => boxyPlanInvariant("hosted stored function reached runtime boxy body type planning before hosted wrapper planning"),
            .parser_runtime,
            .encoder_for_runtime,
            => boxyPlanInvariant("generated parser/encoder stored function reached runtime boxy body type planning before generated runtime support"),
        };
        if (fn_value.captures.len != 0) {
            switch (body) {
                .checked_expr => |*checked_body| checked_body.stored_fn = .{
                    .module = store_view.key,
                    .fn_id = fn_id,
                },
                .intrinsic_wrapper,
                .hosted_proc,
                .unimplemented,
                => boxyPlanInvariant("capturing stored function did not resolve to a checked function body"),
            }
        }
        return body;
    }

    fn analyzeStoredFnCaptureTypes(self: *Builder, stored_fn: StoredFnSource) Allocator.Error!void {
        const store_view = self.moduleForId(stored_fn.module);
        const store = store_view.const_store orelse
            boxyPlanInvariant("stored function capture plan had no checked ConstStore");
        const fn_value = store.getFn(stored_fn.fn_id);
        const fn_view = switch (fn_value.fn_def) {
            .nested => |nested| self.moduleForStoredNestedFn(nested),
            .local_template,
            .imported_template,
            .local_hosted,
            .imported_hosted,
            .checked_generated,
            .parser_runtime,
            .encoder_for_runtime,
            => boxyPlanInvariant("capturing stored function did not reference a checked nested function"),
        };
        for (fn_value.captures) |capture| {
            if (!capture.id.isCanonical()) continue;
            _ = try self.analyzeType(fn_view, self.checkedBinderType(fn_view, capture.id.binder()));
        }
    }

    fn nestedConstFnBody(self: *Builder, nested: anytype) WorkerBody {
        const view = self.moduleForStoredNestedFn(nested);
        const expr_id = self.checkedLambdaExprForNestedFn(view, nested);
        return .{ .checked_expr = .{
            .view = view,
            .root_expr = expr_id,
        } };
    }

    fn generatedTagPayloadForRep(
        self: *Builder,
        rep_id: TypeRepId,
        tag_text: []const u8,
    ) Allocator.Error!RepChild {
        var current = try self.tagIdentityRep(rep_id);
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        while (true) {
            const entry = try seen.getOrPut(current);
            if (entry.found_existing) boxyPlanInvariant("generated tag payload lookup encountered a cyclic extension");
            const rep = self.plan.representations.items[@intFromEnum(current)];
            if (rep.kind != .tag_union and rep.kind != .dynamic) {
                boxyPlanInvariant("generated tag payload lookup reached a non-tag representation");
            }
            for (self.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                const module = self.moduleForId(variant.name_module);
                const names = module.canonical_names orelse
                    boxyPlanInvariant("generated tag payload lookup had no checked name store");
                if (!std.mem.eql(u8, names.tagLabelText(variant.name), tag_text)) continue;
                const payloads = self.plan.childSlice(variant.payloads);
                if (payloads.len != 1) boxyPlanInvariant("generated tag did not have one payload");
                return payloads[0];
            }
            var extension: ?TypeRepId = null;
            for (self.plan.childSlice(rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                if (extension != null) boxyPlanInvariant("generated tag payload lookup found duplicate row extensions");
                extension = try self.tagIdentityRep(child.rep);
            }
            current = extension orelse
                boxyPlanInvariant("generated tag union was missing a required tag");
        }
    }

    fn tagIdentityRep(self: *Builder, rep_id: TypeRepId) Allocator.Error!TypeRepId {
        var current = rep_id;
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        while (true) {
            const entry = try seen.getOrPut(current);
            if (entry.found_existing) boxyPlanInvariant("tag representation wrapper chain was cyclic");
            const rep = self.plan.representations.items[@intFromEnum(current)];
            if (rep.kind == .alias) {
                current = requiredSingleChildOf(&self.plan, current, .alias_backing).rep;
            } else if (rep.kind == .nominal) {
                switch (rep.kind.nominal) {
                    .transparent, .builtin_other => current = requiredSingleChildOf(&self.plan, current, .nominal_backing).rep,
                    .opaque_nominal => return current,
                }
            } else {
                return current;
            }
        }
    }

    fn generatedRecordFieldForRep(
        self: *Builder,
        rep_id: TypeRepId,
        field_text: []const u8,
    ) Allocator.Error!RepChild {
        var current = try self.recordIdentityRep(rep_id);
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();

        while (true) {
            const entry = try seen.getOrPut(current);
            if (entry.found_existing) boxyPlanInvariant("generated record field lookup encountered a cyclic extension");
            const rep = self.plan.representations.items[@intFromEnum(current)];
            if (rep.kind != .record) boxyPlanInvariant("generated record field lookup reached a non-record");
            const view = self.moduleForId(rep.source_type.module);
            var extension: ?TypeRepId = null;
            for (self.plan.childSlice(rep.children)) |child| {
                switch (child.role) {
                    .record_field => |name| {
                        const names = view.canonical_names orelse
                            boxyPlanInvariant("generated record field lookup had no checked name store");
                        if (std.mem.eql(u8, names.recordFieldLabelText(name), field_text)) return child;
                    },
                    .record_ext => extension = try self.recordIdentityRep(child.rep),
                    .alias_backing,
                    .alias_arg,
                    .nominal_backing,
                    .nominal_arg,
                    .nominal_padding_field,
                    .tuple_elem,
                    .function_arg,
                    .function_ret,
                    .tag_payload,
                    .tag_ext,
                    .list_elem,
                    .box_payload,
                    => boxyPlanInvariant("generated record field lookup found a non-record child"),
                }
            }
            current = extension orelse
                boxyPlanInvariant("generated record type was missing a required field");
        }
    }

    fn recordIdentityRep(self: *Builder, rep_id: TypeRepId) Allocator.Error!TypeRepId {
        var current = rep_id;
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        while (true) {
            const entry = try seen.getOrPut(current);
            if (entry.found_existing) boxyPlanInvariant("record representation wrapper chain was cyclic");
            const rep = self.plan.representations.items[@intFromEnum(current)];
            if (rep.kind == .alias) {
                current = requiredSingleChildOf(&self.plan, current, .alias_backing).rep;
            } else if (rep.kind == .nominal) {
                switch (rep.kind.nominal) {
                    .transparent, .builtin_other => current = requiredSingleChildOf(&self.plan, current, .nominal_backing).rep,
                    .opaque_nominal => return current,
                }
            } else {
                return current;
            }
        }
    }

    fn analyzeHostedProcTypes(
        self: *Builder,
        view: ModuleView,
        hosted: checked.HostedProc,
    ) Allocator.Error!void {
        const template = view.checked_procedure_templates.get(hosted.template.template);
        const worker_function = checkedFunctionPayload(view, template.checked_fn_root);
        for (worker_function.args) |arg| {
            _ = try self.analyzeType(view, arg);
        }
        _ = try self.analyzeType(view, worker_function.ret);

        const host_capability = hostedRepresentationForTemplate(view, hosted.template);
        const host_function = checkedFunctionPayload(view, host_capability.host_checked_fn_root);
        if (host_function.args.len != worker_function.args.len) {
            boxyPlanInvariant("hosted host signature arity disagreed with worker signature");
        }
        const worker = self.active_worker orelse boxyPlanInvariant("hosted procedure types were analyzed outside a worker");
        try self.hosted_host_requests.append(self.allocator, .{
            .worker = worker,
            .declared = typeRef(view, host_capability.host_checked_fn_root),
            .declared_rep = try self.analyzeType(view, host_capability.host_checked_fn_root),
        });
        for (host_function.args) |arg| {
            _ = try self.analyzeType(view, arg);
        }
        _ = try self.analyzeType(view, host_function.ret);
    }

    fn checkedLambdaExprForNestedFn(
        _: *Builder,
        view: ModuleView,
        nested: anytype,
    ) checked.CheckedExprId {
        for (view.nested_proc_sites.sites) |site| {
            if (site.site != nested.site) continue;
            switch (site.owner) {
                .template => |site_owner| {
                    if (nested.default_root != null) continue;
                    if (!checked_names.procedureTemplateRefEql(site_owner, nested.owner)) continue;
                },
                // A default-root-qualified stored function matches the
                // declaring module's default-root site (design.md
                // "Defaulted Fields").
                .default_root => if (nested.default_root == null) continue,
            }
            const expr_id = site.checked_expr orelse
                boxyPlanInvariant("stored nested function had no checked expression site");
            const expr = view.checked_bodies.expr(expr_id);
            if (expr.data == .lambda) return expr_id;
            if (expr.data == .closure) return expr.data.closure.lambda;
            boxyPlanInvariant("stored nested function site did not point at a lambda or closure");
        }
        boxyPlanInvariant("stored nested function referenced a missing checked nested site");
    }

    fn checkedBinderType(_: *Builder, view: ModuleView, binder: checked.PatternBinderId) checked.CheckedTypeId {
        const raw = @intFromEnum(binder);
        if (raw >= view.checked_bodies.patternBinderCount()) {
            boxyPlanInvariant("stored function capture binder was outside the checked body store");
        }
        const pattern = view.checked_bodies.patternBinder(@enumFromInt(raw)).pattern;
        if (@intFromEnum(pattern) >= view.checked_bodies.patternCount()) {
            boxyPlanInvariant("stored function capture pattern was outside the checked body store");
        }
        return view.checked_bodies.pattern(pattern).ty;
    }

    fn callableEvalTemplate(
        _: *Builder,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
    ) checked.CallableEvalTemplate {
        const raw = @intFromEnum(template_id);
        if (raw >= view.callable_eval_templates.templates.len) {
            boxyPlanInvariant("callable eval binding referenced a missing checked template");
        }
        return view.callable_eval_templates.templates[raw];
    }

    fn recordLiteralSite(
        self: *Builder,
        view: ModuleView,
        expr: checked.CheckedExprId,
        dispatch: static_dispatch.StaticDispatchPlanId,
    ) Allocator.Error!void {
        const worker = self.active_worker orelse
            boxyPlanInvariant("literal conversion was planned outside a worker");
        try self.plan.literal_sites.append(self.allocator, .{
            .source = .{ .module = view.key, .expr = expr },
            .worker = worker,
            .dispatch = dispatch,
        });
    }

    fn workerSourceForStoredFnAtType(
        self: *Builder,
        stored_fn: StoredFnSource,
        requested_type: CheckedTypeIdentity,
    ) Allocator.Error!WorkerSource {
        const store_view = self.moduleForId(stored_fn.module);
        const store = store_view.const_store orelse
            boxyPlanInvariant("stored callable worker selection had no ConstStore");
        if (@intFromEnum(stored_fn.fn_id) >= store.fns.items.len) {
            boxyPlanInvariant("stored callable worker selection referenced a missing function");
        }
        const fn_value = store.getFn(stored_fn.fn_id);
        const generated: ?struct {
            owner: checked_names.ProcedureTemplateRef,
            expr: checked.CheckedExprId,
            kind: GeneratedCodecKind,
            derivation_kind: static_dispatch.GeneratedCodecDerivationKind,
        } = switch (fn_value.fn_def) {
            .parser_runtime => |runtime| .{
                .owner = runtime.owner,
                .expr = runtime.expr,
                .kind = .parser_runtime,
                .derivation_kind = .parser,
            },
            .encoder_for_runtime => |runtime| .{
                .owner = runtime.owner,
                .expr = runtime.expr,
                .kind = .encoder_runtime,
                .derivation_kind = .encoder,
            },
            .local_template,
            .imported_template,
            .nested,
            .local_hosted,
            .imported_hosted,
            .checked_generated,
            => null,
        };
        const codec = generated orelse return self.workerSourceForConstFnValue(fn_value, requested_type);
        var stored_encoding_type: ?check.ConstStore.ConstTypeId = null;
        for (fn_value.captures) |capture| {
            if (capture.id != checked.CaptureId.generatedCheck(0)) continue;
            if (stored_encoding_type != null) {
                boxyPlanInvariant("stored generated codec had duplicate encoding captures");
            }
            stored_encoding_type = capture.ty;
        }
        const view = self.moduleForId(.{ .bytes = checked_names.procTemplateModuleDigest(codec.owner).bytes });
        const source = if (stored_encoding_type) |encoding_type|
            try self.storedGeneratedCodecSourceAtEncodingType(
                store_view,
                encoding_type,
                view,
                codec.expr,
                requested_type.ty,
                codec.kind,
                codec.derivation_kind,
                fn_value,
            )
        else
            self.storedGeneratedCodecSource(
                view,
                codec.expr,
                requested_type.ty,
                codec.kind,
                codec.derivation_kind,
                fn_value,
            );
        return .{ .generated_codec = source };
    }

    fn storedGeneratedCodecSourceAtEncodingType(
        self: *Builder,
        store_view: ModuleView,
        stored_encoding_type: check.ConstStore.ConstTypeId,
        view: ModuleView,
        expr_id: checked.CheckedExprId,
        requested_runtime_type: checked.CheckedTypeId,
        kind: GeneratedCodecKind,
        derivation_kind: static_dispatch.GeneratedCodecDerivationKind,
        stored: check.ConstStore.ConstFn,
    ) Allocator.Error!GeneratedCodecSource {
        const selected = self.generatedCodecContractForRuntimeExpr(view, expr_id, derivation_kind, stored);
        const derivation = selected.derivation;
        if (selected.runtime_ty != requested_runtime_type or
            !try self.storedTypeMatchesCheckedType(store_view, stored_encoding_type, view, derivation.encoding_ty))
        {
            boxyPlanInvariant("stored generated codec encoding disagreed with its checked contract");
        }
        return .{
            .kind = kind,
            .shape = typeRef(view, derivation.shape_ty),
            .runtime_type = typeRef(view, derivation.runtime_ty),
            .capture_type = typeRef(view, derivation.encoding_ty),
            .contract_derivation = selected.id,
            .contract_expr = .{ .module = view.key, .expr = expr_id },
        };
    }

    fn constProducerCheckedType(
        _: *Builder,
        store_view: ModuleView,
        const_ref: checked.ConstRef,
    ) checked.CheckedTypeId {
        const root = switch (const_ref.owner) {
            .top_level_binding => |owner| blk: {
                const root_id = store_view.compile_time_roots.lookupIdByPattern(owner.pattern) orelse
                    boxyPlanInvariant("stored top-level constant had no compile-time root");
                const root = store_view.compile_time_roots.root(root_id);
                if (root.kind != .constant or root.module_idx != owner.module_idx or root.pattern != owner.pattern) {
                    boxyPlanInvariant("stored top-level constant owner disagreed with its compile-time root");
                }
                break :blk root;
            },
            .hoisted_expr => |owner| blk: {
                const root = store_view.compile_time_roots.lookupHoistedRootByExpr(owner.expr) orelse
                    boxyPlanInvariant("stored hoisted constant had no compile-time root");
                if (root.module_idx != owner.module_idx) {
                    boxyPlanInvariant("stored hoisted constant owner disagreed with its compile-time root");
                }
                break :blk root;
            },
        };
        return root.checked_type;
    }

    fn planNestedCallableUseDictionaries(self: *Builder) Allocator.Error!void {
        var callable_index: usize = 0;
        while (callable_index < self.plan.callable_uses.items.len) : (callable_index += 1) {
            const use = self.plan.callable_uses.items[callable_index];
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            const callable_rep = self.plan.repForSourceType(use.callable_ty) orelse
                boxyPlanInvariant("boxy callable lookup type was not analyzed");
            const fn_children = (self.repQuery().functionChildren(callable_rep)) orelse
                boxyPlanInvariant("boxy callable lookup type was not callable");

            const arg_types = try self.allocator.alloc(CheckedTypeIdentity, fn_children.arg_count);
            defer self.allocator.free(arg_types);
            const children_span = self.plan.representations.items[@intFromEnum(fn_children.rep)].children;
            var arg_index: usize = 0;
            while (arg_index < fn_children.arg_count) : (arg_index += 1) {
                const child = self.plan.children.items[children_span.start + fn_children.args_start + arg_index];
                arg_types[arg_index] = self.plan.representations.items[@intFromEnum(child.rep)].source_type;
            }
            const ret_type = self.plan.representations.items[@intFromEnum(fn_children.ret)].source_type;
            if (worker.hidden_dicts.len == 0) {
                self.plan.callable_uses.items[callable_index].hidden_dict_args = .{};
                continue;
            }
            const evidence = self.checkedEvidenceForProcedureUse(use.use);
            const outer_stored_fn = self.active_stored_fn;
            const outer_stored_substitution = self.active_stored_substitution;
            self.active_stored_fn = use.stored_fn;
            // A stored function's value was produced at one instantiation of
            // its worker, which its use's type fixes: the substitution checking
            // records at an instantiating use comes from relating the two.
            self.active_stored_substitution = if (use.stored_fn != null)
                try self.storedUseSchemeRepSubstitutions(worker.rep, callable_rep)
            else
                null;
            defer {
                self.active_stored_fn = outer_stored_fn;
                self.active_stored_substitution = outer_stored_substitution;
            }
            self.plan.callable_uses.items[callable_index].hidden_dict_args =
                try self.materializeWorkerCallHiddenDictionaryArgsWithEvidence(
                    use.worker,
                    use.caller,
                    arg_types,
                    ret_type,
                    evidence.view,
                    evidence.entries,
                    self.useSchemeSubstitution(use.worker, use.use),
                    0,
                );
        }

        // Materialize checked instantiation edges first. A local callable's
        // declaration expression itself is not an instantiation and therefore
        // has no site evidence; it is handled in the second pass below.
        var index: usize = 0;
        while (index < self.plan.nested_callable_uses.items.len) : (index += 1) {
            const use = self.plan.nested_callable_uses.items[index];
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            if (worker.hidden_dicts.len == 0) {
                self.plan.nested_callable_uses.items[index].hidden_dict_args = .{};
                continue;
            }
            const evidence = self.checkedEvidenceForProcedureUse(use.use);
            if (evidence.entries == null and typeRefEql(use.callable_ty, worker.checked_type)) continue;
            self.plan.nested_callable_uses.items[index].hidden_dict_args =
                try self.materializeNestedCallableUseDictionaries(use, evidence.view, evidence.entries);
        }

        const dictionary_use_count = self.worker_dictionary_uses.items.len;
        index = 0;
        while (index < self.plan.nested_callable_uses.items.len) : (index += 1) {
            const use = self.plan.nested_callable_uses.items[index];
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            if (worker.hidden_dicts.len == 0 or use.hidden_dict_args.len != 0) continue;

            var source: ?Span = null;
            var source_is_ambiguous = false;
            for (self.plan.nested_callable_uses.items) |candidate| {
                if (self.baseWorker(candidate.worker) != self.baseWorker(use.worker) or candidate.caller != use.caller) continue;
                if (candidate.hidden_dict_args.len != worker.hidden_dicts.len) continue;
                if (source) |existing| {
                    const existing_args = self.plan.directCallHiddenDictionaryArgSlice(existing);
                    const candidate_args = self.plan.directCallHiddenDictionaryArgSlice(candidate.hidden_dict_args);
                    if (!std.meta.eql(existing_args, candidate_args)) {
                        source = null;
                        source_is_ambiguous = true;
                        break;
                    }
                } else {
                    source = candidate.hidden_dict_args;
                }
            }
            if (!source_is_ambiguous) {
                for (self.plan.direct_calls.items) |candidate| {
                    if (self.baseWorker(candidate.worker) != self.baseWorker(use.worker) or candidate.caller != use.caller) continue;
                    if (candidate.hidden_dict_args.len != worker.hidden_dicts.len) continue;
                    if (source) |existing| {
                        const existing_args = self.plan.directCallHiddenDictionaryArgSlice(existing);
                        const candidate_args = self.plan.directCallHiddenDictionaryArgSlice(candidate.hidden_dict_args);
                        if (!std.meta.eql(existing_args, candidate_args)) {
                            source = null;
                            source_is_ambiguous = true;
                            break;
                        }
                    } else {
                        source = candidate.hidden_dict_args;
                    }
                }
            }
            if (source) |planned| {
                self.plan.nested_callable_uses.items[index].hidden_dict_args = planned;
                continue;
            }

            if (self.workerBindsAllDictionaryParams(use.caller, worker.hidden_dicts)) {
                const view = self.moduleForId(use.use.module);
                self.plan.nested_callable_uses.items[index].hidden_dict_args =
                    try self.materializeNestedCallableUseDictionaries(use, view, null);
                continue;
            }

            for (self.plan.hiddenDictionaryParamSlice(worker.hidden_dicts)) |param| {
                if (self.workerBindsDictionarySpan(use.caller, param.dictionaries)) continue;
                try self.recordWorkerDictionaryUse(use.caller, param.rep);
            }
        }
        if (self.worker_dictionary_uses.items.len != dictionary_use_count) return;

        for (self.plan.nested_callable_uses.items) |use| {
            const worker = self.plan.workers.items[@intFromEnum(use.worker)];
            if (worker.hidden_dicts.len != 0 and use.hidden_dict_args.len == 0) {
                boxyPlanInvariant("nested callable value had no checked dictionary capture source");
            }
        }

        // A callable value capturing dictionaries that carry context methods
        // is the context specialization of its worker, capturing those inputs.
        index = 0;
        while (index < self.plan.callable_uses.items.len) : (index += 1) {
            const use = self.plan.callable_uses.items[index];
            const context = try self.contextualizeCall(use.worker, use.caller, use.hidden_dict_args);
            self.plan.callable_uses.items[index].worker = context.worker;
            self.plan.callable_uses.items[index].context_args = context.args;
        }
        index = 0;
        while (index < self.plan.nested_callable_uses.items.len) : (index += 1) {
            const use = self.plan.nested_callable_uses.items[index];
            const context = try self.contextualizeCall(use.worker, use.caller, use.hidden_dict_args);
            self.plan.nested_callable_uses.items[index].worker = context.worker;
            self.plan.nested_callable_uses.items[index].context_args = context.args;
        }
    }

    fn baseWorker(self: *const Builder, worker: WorkerPlanId) WorkerPlanId {
        return self.plan.workers.items[@intFromEnum(worker)].context_base orelse worker;
    }

    fn materializeNestedCallableUseDictionaries(
        self: *Builder,
        use: NestedCallableUsePlan,
        view: ModuleView,
        evidence: ?[]const static_dispatch.CheckedEvidence,
    ) Allocator.Error!Span {
        const callable_rep = self.plan.repForSourceType(use.callable_ty) orelse
            boxyPlanInvariant("boxy nested callable use type was not analyzed");
        const function = (self.repQuery().functionChildren(callable_rep)) orelse
            boxyPlanInvariant("boxy nested callable use type was not callable");
        const arg_types = try self.allocator.alloc(CheckedTypeIdentity, function.arg_count);
        defer self.allocator.free(arg_types);
        const children_span = self.plan.representations.items[@intFromEnum(function.rep)].children;
        for (arg_types, 0..) |*arg_type, arg_index| {
            const child = self.plan.children.items[children_span.start + function.args_start + arg_index];
            arg_type.* = self.plan.representations.items[@intFromEnum(child.rep)].source_type;
        }
        const ret_type = self.plan.representations.items[@intFromEnum(function.ret)].source_type;
        return try self.materializeWorkerCallHiddenDictionaryArgsWithEvidence(
            use.worker,
            use.caller,
            arg_types,
            ret_type,
            view,
            evidence,
            self.useSchemeSubstitution(use.worker, use.use),
            0,
        );
    }

    fn workerBindsAllDictionaryParams(self: *const Builder, worker_id: WorkerPlanId, params: Span) bool {
        for (self.plan.hiddenDictionaryParamSlice(params)) |param| {
            if (!self.workerBindsDictionarySpan(worker_id, param.dictionaries)) return false;
        }
        return true;
    }

    fn appendCheckedCallOperands(
        self: *Builder,
        args: []const checked.CheckedExprId,
    ) Allocator.Error!Span {
        const start: u32 = @intCast(self.plan.call_operands.items.len);
        for (args) |arg| try self.plan.call_operands.append(self.allocator, .{ .checked_expr = arg });
        return .{ .start = start, .len = @intCast(args.len) };
    }

    fn appendDispatchCallOperands(
        self: *Builder,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        table: *const static_dispatch.StaticDispatchPlanTable,
    ) Allocator.Error!Span {
        const operands = dispatch.argsSlice(table);
        const start: u32 = @intCast(self.plan.call_operands.items.len);
        for (operands) |operand| {
            try self.plan.call_operands.append(self.allocator, switch (operand) {
                .checked_expr => |expr| .{ .checked_expr = expr },
                .generated_interpolation_iter => |expr| .{ .generated_interpolation_iter = expr },
                .generated_numeral => |literal| .{ .generated_numeral = literal },
                .generated_quote => |literal| .{ .generated_quote = literal },
            });
        }
        return .{ .start = start, .len = @intCast(operands.len) };
    }

    fn recordWorkerBodyType(self: *Builder, worker: WorkerPlanId, rep: TypeRepId) Allocator.Error!void {
        const use = WorkerDictionaryUse{ .worker = worker, .rep = rep };
        if ((try self.worker_body_types_seen.getOrPut(use)).found_existing) return;
        try self.worker_body_types.append(self.allocator, use);
    }

    fn recordActiveWorkerDictionaryUse(self: *Builder, rep: TypeRepId) Allocator.Error!void {
        const worker = self.active_worker orelse
            boxyPlanInvariant("unresolved dictionary dispatch was analyzed outside a worker body");
        return try self.recordWorkerDictionaryUse(worker, rep);
    }

    fn recordWorkerDictionaryUse(
        self: *Builder,
        worker: WorkerPlanId,
        rep: TypeRepId,
    ) Allocator.Error!void {
        for (self.worker_dictionary_uses.items) |use| {
            if (use.worker == worker and use.rep == rep) return;
        }
        try self.worker_dictionary_uses.append(self.allocator, .{ .worker = worker, .rep = rep });
    }

    const DispatchWorkerLookup = struct {
        view: ModuleView,
        source: WorkerSource,
    };

    fn dispatchMethodTargetLookup(
        self: *Builder,
        dispatch_view: ModuleView,
        target: static_dispatch.MethodTarget,
        shape: CheckedTypeIdentity,
    ) DispatchWorkerLookup {
        return switch (target.kind) {
            .procedure => |procedure| .{
                .view = self.moduleForCheckedModuleId(procedure.template.artifact),
                .source = .{ .procedure_template = procedure.template },
            },
            // A method of a type declared in a function body is registered
            // only by the module declaring it, which owns the dispatch.
            .local_proc => |local| .{
                .view = dispatch_view,
                .source = if (self.topLevelProcedureBindingForExpr(dispatch_view, local.expr)) |binding|
                    .{ .procedure_binding = binding }
                else
                    .{ .nested_expr = .{ .module = dispatch_view.key, .expr = self.nestedCallableSiteExprForExpr(dispatch_view, local.expr) orelse local.expr } },
            },
            .structural => |kind| .{
                .view = dispatch_view,
                .source = .{ .generated_codec = .{
                    .kind = switch (kind) {
                        .parser => .parser_constructor,
                        .encoder => .encoder_constructor,
                        .equality, .hash, .map, .map_effectful => boxyPlanInvariant("non-codec structural target reached dispatch worker planning"),
                    },
                    .shape = shape,
                } },
            },
        };
    }

    fn directTargetIsLocalProc(
        self: *Builder,
        view: ModuleView,
        target: checked.ResolvedValueId,
    ) bool {
        return self.resolvedValueRecord(view, target).ref == .local_proc;
    }

    fn directTargetHasNoCaptures(
        self: *Builder,
        view: ModuleView,
        target: checked.ResolvedValueId,
    ) bool {
        const source = self.workerSourceForDirectTarget(view, target);
        if (source != .nested_expr) return false;
        return self.nestedCallableHasNoCaptures(source.nested_expr);
    }

    fn nestedCallableHasNoCaptures(self: *Builder, expr_ref: CheckedExprIdentity) bool {
        const view = self.moduleForId(expr_ref.module);
        const expr = view.checked_bodies.expr(expr_ref.expr);
        if (expr.data != .lambda and expr.data != .closure) {
            boxyPlanInvariant("nested callable capture lookup did not reference a lambda or closure");
        }
        return nestedCallableRuntimeCaptures(view, expr_ref.expr).len == 0;
    }

    fn directCallInstantiationSourceFnType(
        self: *Builder,
        view: ModuleView,
        target: checked.ResolvedValueId,
        call_site_type: checked.CheckedTypeId,
    ) CheckedTypeIdentity {
        const record = self.resolvedValueRecord(view, target);
        if (record.ref == .platform_required_proc) {
            return .{
                .module = view.key,
                .ty = record.ref.platform_required_proc.procedure.source_fn_ty_payload orelse
                    boxyPlanInvariant("platform-required procedure call missing relation-owned source function type"),
            };
        }
        return typeRef(view, call_site_type);
    }

    fn workerSourceForDirectTarget(self: *Builder, view: ModuleView, target: checked.ResolvedValueId) WorkerSource {
        const record = self.resolvedValueRecord(view, target);
        return switch (record.ref) {
            .top_level_proc,
            .promoted_top_level_proc,
            => |procedure| self.workerSourceForProcedureUse(procedure),
            .platform_required_proc => |required| self.workerSourceForProcedureUse(required.procedure),
            .local_proc => |local| if (self.topLevelProcedureBindingForExpr(view, local.expr)) |binding|
                .{ .procedure_binding = binding }
            else
                .{ .nested_expr = .{ .module = view.key, .expr = self.nestedCallableSiteExprForExpr(view, local.expr) orelse local.expr } },
            .imported_proc => |procedure| self.workerSourceForProcedureUse(procedure),
            .hosted_proc => |procedure| self.workerSourceForProcedureUse(procedure),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => boxyPlanInvariant("checked direct call target did not reference a procedure"),
        };
    }

    fn workerSourceForProcedureValueRef(
        self: *Builder,
        view: ModuleView,
        ref_id: checked.ResolvedValueRefId,
    ) ?WorkerSource {
        return self.resolveWorkerSource(.{ .value_ref = .{ .view = view, .ref_id = ref_id } });
    }

    fn workerSourceForProcedureUse(self: *Builder, procedure: checked.ProcedureUseTemplate) WorkerSource {
        return self.resolveWorkerSource(.{ .procedure_use = procedure }) orelse
            boxyPlanInvariant("procedure use resolved to no worker source");
    }

    fn workerSourceForCallableEvalTemplate(
        self: *Builder,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
    ) ?WorkerSource {
        return self.resolveWorkerSource(.{ .eval_template = .{ .view = view, .template = template_id } });
    }

    /// One reference on a chain of callable references.
    const WorkerSourceQuery = union(enum) {
        value_ref: struct { view: ModuleView, ref_id: checked.ResolvedValueRefId },
        root_expr: struct { view: ModuleView, expr: checked.CheckedExprId },
        procedure_use: checked.ProcedureUseTemplate,
        eval_template: struct { view: ModuleView, template: checked.CallableEvalTemplateId },
    };

    /// Follow a chain of callable references (a lookup, the procedure it
    /// names, that procedure's evaluated callable, and so on) to the worker
    /// source it ends at. Each step names a source, names none, or forwards
    /// to the next reference. A procedure use whose evaluated callable names
    /// no source is itself the source; since that always names one, only the
    /// most recent such procedure use can apply.
    fn resolveWorkerSource(self: *Builder, first: WorkerSourceQuery) ?WorkerSource {
        var query = first;
        var fallback: ?checked.ProcedureUseTemplate = null;
        while (true) {
            query = switch (query) {
                .value_ref => |ref| next: {
                    const view = ref.view;
                    const record = view.resolved_value_refs.callableTarget(ref.ref_id);
                    break :next switch (record.ref) {
                        .local_proc => |local| return if (self.topLevelProcedureBindingForExpr(view, local.expr)) |binding|
                            .{ .procedure_binding = binding }
                        else
                            .{ .nested_expr = .{ .module = view.key, .expr = self.nestedCallableSiteExprForExpr(view, local.expr) orelse local.expr } },
                        .top_level_proc,
                        .promoted_top_level_proc,
                        => |procedure| .{ .procedure_use = procedure },
                        .platform_required_proc => |required| .{ .procedure_use = required.procedure },
                        .imported_proc => |procedure| .{ .procedure_use = procedure },
                        .hosted_proc => |procedure| .{ .procedure_use = procedure },
                        .local_param,
                        .local_value,
                        .local_mutable_version,
                        .pattern_binder,
                        .selected_hoisted_const,
                        .top_level_const,
                        .imported_const,
                        .platform_required_declaration,
                        .platform_required_checked_error,
                        .platform_required_const,
                        => return self.procedureUseFallback(fallback),
                    };
                },
                .root_expr => |root| next: {
                    const view = root.view;
                    const expr = view.checked_bodies.expr(root.expr);
                    if (expr.data == .lambda or expr.data == .closure) {
                        return .{ .nested_expr = .{ .module = view.key, .expr = root.expr } };
                    }
                    const maybe_ref: ?checked.ResolvedValueRefId = if (expr.data == .lookup_local)
                        expr.data.lookup_local.resolved
                    else if (expr.data == .lookup_external)
                        expr.data.lookup_external
                    else if (expr.data == .lookup_required)
                        expr.data.lookup_required
                    else
                        return self.procedureUseFallback(fallback);
                    const ref_id = maybe_ref orelse return self.procedureUseFallback(fallback);
                    break :next .{ .value_ref = .{ .view = view, .ref_id = ref_id } };
                },
                .procedure_use => |procedure| next: {
                    const evaluated: ?WorkerSourceQuery = switch (procedure.binding) {
                        .top_level => |top_level| blk: {
                            const view = self.moduleForId(top_level.artifact);
                            break :blk switch (view.top_level_procedure_bindings.get(top_level.binding).body) {
                                .callable_eval_template => |template| .{ .eval_template = .{ .view = view, .template = template } },
                                .checked_error, .direct_template => null,
                            };
                        },
                        .platform_required => |required| blk: {
                            const view = self.moduleForId(required.app_value.artifact);
                            break :blk switch (view.top_level_procedure_bindings.get(required.procedure_binding).body) {
                                .callable_eval_template => |template| .{ .eval_template = .{ .view = view, .template = template } },
                                .checked_error, .direct_template => null,
                            };
                        },
                        .imported => |imported| blk: {
                            const view = self.moduleForId(imported.artifact);
                            break :blk switch (self.importedProcedureBinding(view, imported).body) {
                                .callable_eval_template => |template| .{ .eval_template = .{ .view = view, .template = template } },
                                .checked_error, .direct_template => null,
                            };
                        },
                        .hosted => null,
                    };
                    fallback = procedure;
                    break :next evaluated orelse return self.procedureUseFallback(fallback);
                },
                .eval_template => |eval| next: {
                    const view = eval.view;
                    const template = self.callableEvalTemplate(view, eval.template);
                    const root = view.compile_time_roots.root(template.root);
                    break :next switch (root.payload) {
                        .fn_value => |fn_id| {
                            const store = view.const_store orelse
                                boxyPlanInvariant("finalized callable eval root had no ConstStore");
                            return self.workerSourceForConstFnValue(
                                store.getFn(fn_id),
                                typeRef(view, template.checked_fn_root),
                            );
                        },
                        .pending => .{ .root_expr = .{ .view = view, .expr = root.expr } },
                        .const_node, .discarded, .expect, .runtime => return self.procedureUseFallback(fallback),
                    };
                },
            };
        }
    }

    /// The source a procedure use names when its evaluated callable names
    /// none: the procedure itself.
    fn procedureUseFallback(self: *Builder, maybe_procedure: ?checked.ProcedureUseTemplate) ?WorkerSource {
        const procedure = maybe_procedure orelse return null;
        return switch (procedure.binding) {
            .top_level => |top_level| blk: {
                const view = self.moduleForId(top_level.artifact);
                if (!self.procedureBindingBodyIsPendingEval(view, top_level.binding)) {
                    _ = self.rootProcedureBindingBody(view, top_level.binding);
                }
                break :blk .{ .procedure_binding = top_level };
            },
            .platform_required => |required| blk: {
                const view = self.moduleForId(required.app_value.artifact);
                if (!self.procedureBindingBodyIsPendingEval(view, required.procedure_binding)) {
                    _ = self.rootProcedureBindingBody(view, required.procedure_binding);
                }
                break :blk .{ .procedure_binding = .{
                    .artifact = required.app_value.artifact,
                    .binding = required.procedure_binding,
                } };
            },
            .imported, .hosted => .{ .procedure_use = procedure },
        };
    }

    fn storedFnSourceForProcedureValueRef(
        self: *Builder,
        view: ModuleView,
        ref_id: checked.ResolvedValueRefId,
    ) ?StoredFnSource {
        const record = view.resolved_value_refs.callableTarget(ref_id);
        return switch (record.ref) {
            .top_level_proc,
            .promoted_top_level_proc,
            => |procedure| self.storedFnSourceForProcedureUse(procedure),
            .platform_required_proc => |required| self.storedFnSourceForProcedureUse(required.procedure),
            .imported_proc => |procedure| self.storedFnSourceForProcedureUse(procedure),
            .local_proc => |local| if (self.topLevelProcedureBindingForExpr(view, local.expr)) |binding|
                self.storedFnSourceForTopLevelBinding(binding)
            else
                null,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => null,
        };
    }

    fn storedFnSourceForProcedureUse(
        self: *Builder,
        procedure: checked.ProcedureUseTemplate,
    ) ?StoredFnSource {
        return switch (procedure.binding) {
            .top_level => |binding| self.storedFnSourceForTopLevelBinding(binding),
            .platform_required => |required| self.storedFnSourceForTopLevelBinding(.{
                .artifact = required.app_value.artifact,
                .binding = required.procedure_binding,
            }),
            .imported => |imported| blk: {
                const view = self.moduleForId(imported.artifact);
                const binding = self.importedProcedureBinding(view, imported);
                break :blk switch (binding.body) {
                    .checked_error => null,
                    .callable_eval_template => |template| self.storedFnSourceForCallableEvalTemplate(view, template),
                    .direct_template => null,
                };
            },
            .hosted => null,
        };
    }

    fn storedFnSourceForTopLevelBinding(
        self: *Builder,
        binding_ref: checked.ArtifactTopLevelProcedureBindingRef,
    ) ?StoredFnSource {
        const view = self.moduleForId(binding_ref.artifact);
        const binding = view.top_level_procedure_bindings.get(binding_ref.binding);
        return switch (binding.body) {
            .checked_error => null,
            .callable_eval_template => |template| self.storedFnSourceForCallableEvalTemplate(view, template),
            .direct_template => null,
        };
    }

    fn storedFnSourceForCallableEvalTemplate(
        self: *Builder,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
    ) ?StoredFnSource {
        const template = self.callableEvalTemplate(view, template_id);
        const root = view.compile_time_roots.root(template.root);
        return switch (root.payload) {
            .fn_value => |fn_id| .{ .module = view.key, .fn_id = fn_id },
            .pending, .const_node, .discarded, .expect, .runtime => null,
        };
    }

    fn nestedCallableSiteExprForExpr(
        _: *Builder,
        view: ModuleView,
        expr: checked.CheckedExprId,
    ) ?checked.CheckedExprId {
        return nestedCallableSiteExprFor(view, expr);
    }

    fn topLevelProcedureBindingForExpr(
        _: *Builder,
        view: ModuleView,
        expr: checked.CheckedExprId,
    ) ?checked.ArtifactTopLevelProcedureBindingRef {
        for (view.top_level_procedure_bindings.bindings.items, 0..) |binding, index| {
            const template_ref = switch (binding.body) {
                .direct_template => |direct| switch (direct.template) {
                    .checked => |template| template,
                    .lifted,
                    .synthetic,
                    => continue,
                },
                .checked_error, .callable_eval_template => continue,
            };
            const template = view.checked_procedure_templates.get(template_ref.template);
            const body_id = switch (template.body) {
                .checked_body => |body| body,
                .intrinsic_wrapper,
                .entry_wrapper,
                .unimplemented,
                => continue,
            };
            if (view.checked_bodies.body(body_id).root_expr == expr) {
                return .{
                    .artifact = view.key,
                    .binding = @enumFromInt(@as(u32, @intCast(index))),
                };
            }
        }
        return null;
    }

    fn workerCheckedTypeForSource(self: *Builder, source: WorkerSource, requested_type: CheckedTypeIdentity) CheckedTypeIdentity {
        return switch (source) {
            .procedure_template => |template| self.checkedTypeForTemplate(template),
            .procedure_binding => |binding| self.checkedTypeForTopLevelBinding(binding),
            .procedure_use => |use| switch (use.binding) {
                .top_level => |binding| self.checkedTypeForTopLevelBinding(binding),
                .platform_required => |required| self.checkedTypeForTopLevelBinding(.{
                    .artifact = required.app_value.artifact,
                    .binding = required.procedure_binding,
                }),
                .imported => |imported| self.checkedTypeForImportedBinding(imported),
                .hosted => requested_type,
            },
            .nested_expr => |expr_ref| self.nestedExprDefinitionType(expr_ref),
            .generated_codec => requested_type,
            .generated_field_iterator => requested_type,
            .generated_interpolation_step => requested_type,
        };
    }

    fn nestedExprDefinitionType(self: *Builder, expr_ref: CheckedExprIdentity) CheckedTypeIdentity {
        const view = self.moduleForId(expr_ref.module);
        return typeRef(view, view.checked_bodies.expr(expr_ref.expr).ty);
    }

    fn checkedTypeForTopLevelBinding(
        self: *Builder,
        binding_ref: checked.ArtifactTopLevelProcedureBindingRef,
    ) CheckedTypeIdentity {
        const view = self.moduleForId(binding_ref.artifact);
        const binding = view.top_level_procedure_bindings.get(binding_ref.binding);
        return switch (binding.body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| self.checkedTypeForTemplate(template),
                .lifted,
                .synthetic,
                => boxyPlanInvariant("non-checked procedure template reached boxy worker type planning"),
            },
            .checked_error => |expr| typeRef(view, view.checked_bodies.expr(expr).ty),
            .callable_eval_template => |template| typeRef(view, self.callableEvalTemplate(view, template).checked_fn_root),
        };
    }

    fn checkedTypeForImportedBinding(
        self: *Builder,
        binding_ref: checked.ImportedProcedureBindingRef,
    ) CheckedTypeIdentity {
        const view = self.moduleForId(binding_ref.artifact);
        const binding = self.importedProcedureBinding(view, binding_ref);
        return switch (binding.body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| self.checkedTypeForTemplate(template),
                .lifted,
                .synthetic,
                => boxyPlanInvariant("non-checked imported procedure template reached boxy worker type planning"),
            },
            .checked_error => |expr| typeRef(view, view.checked_bodies.expr(expr).ty),
            .callable_eval_template => |template| typeRef(view, self.callableEvalTemplate(view, template).checked_fn_root),
        };
    }

    fn checkedTypeForTemplate(self: *Builder, template_ref: checked_names.ProcedureTemplateRef) CheckedTypeIdentity {
        const view = self.moduleForCheckedModuleId(template_ref.artifact);
        const template = view.checked_procedure_templates.get(template_ref.template);
        return typeRef(view, template.checked_fn_root);
    }

    fn workerSourceForCallableEvalSource(self: *Builder, source: WorkerSource) WorkerSource {
        return switch (source) {
            .procedure_binding => |binding_ref| blk: {
                const view = self.moduleForId(binding_ref.artifact);
                const binding = view.top_level_procedure_bindings.get(binding_ref.binding);
                break :blk switch (binding.body) {
                    .checked_error => boxyPlanInvariant("rejected binding reached Boxy planning callable consumption"),
                    .callable_eval_template => |template| self.workerSourceForCallableEvalTemplate(view, template) orelse source,
                    .direct_template => source,
                };
            },
            .procedure_use => |procedure| self.workerSourceForProcedureUse(procedure),
            .procedure_template,
            .nested_expr,
            .generated_codec,
            .generated_field_iterator,
            .generated_interpolation_step,
            => source,
        };
    }

    fn resolvedValueRecord(_: *Builder, view: ModuleView, target: checked.ResolvedValueId) checked.ResolvedValueRefRecord {
        const raw = @intFromEnum(target);
        if (raw >= view.resolved_value_refs.records.len) {
            boxyPlanInvariant("checked direct call target referenced a missing resolved value");
        }
        return view.resolved_value_refs.records[raw];
    }
};

fn rootRequiresHostWrapper(root: checked.RootRequest) bool {
    return root.abi != .roc or root.exposure != .private;
}

fn workerSourceForRoot(root: checked.RootRequest, root_key: checked.CheckedModuleArtifactKey) ?WorkerSource {
    if (root.procedure_binding) |binding| return .{ .procedure_binding = .{ .artifact = root_key, .binding = binding } };
    if (root.procedure_use) |procedure| return .{ .procedure_use = procedure };
    if (root.procedure_template) |template| return .{ .procedure_template = template };
    return null;
}

fn workerSourceIsHosted(source: WorkerSource) bool {
    return switch (source) {
        .procedure_use => |use| switch (use.binding) {
            .hosted => true,
            .top_level,
            .platform_required,
            .imported,
            => false,
        },
        .procedure_template,
        .procedure_binding,
        .nested_expr,
        .generated_codec,
        .generated_field_iterator,
        .generated_interpolation_step,
        => false,
    };
}

fn workerSourceEql(a: WorkerSource, b: WorkerSource) bool {
    return std.meta.eql(a, b);
}

/// One module's identity plus its name store: the only module data the
/// label-comparing representation queries need. Callers build this from
/// whatever module view they already hold.
pub const ModuleNames = struct {
    key: checked.ModuleId = .{},
    canonical_names: ?*const checked_names.CanonicalNameStore = null,
};

/// The erased-callable children of a function representation.
pub const FunctionChildren = struct {
    rep: TypeRepId,
    args_start: u32,
    arg_count: u32,
    ret: TypeRepId,
};

/// Read-only queries over a finished representation plan.
///
/// This is the single source of truth for every "what does this representation
/// contain" question. Boxy planning decides an unwrap, a descriptor argument,
/// or a dictionary argument by asking these; Boxy lowering emits that decision
/// by asking the same ones. A second copy would let the two disagree about the
/// program they are both describing, so no consumer may re-derive these.
pub const RepQuery = struct {
    plan: *const ProgramPlan,
    allocator: Allocator,

    fn rep(self: RepQuery, rep_id: TypeRepId) TypeRepresentation {
        return self.plan.representations.items[@intFromEnum(rep_id)];
    }

    /// The one child of `rep_id` with `role`; an invariant failure when the
    /// representation has none or more than one.
    pub fn requiredSingleChild(self: RepQuery, rep_id: TypeRepId, role: ChildRole) RepChild {
        return requiredSingleChildOf(self.plan, rep_id, role);
    }

    /// True when `rep_id` or anything reachable below it carries a descriptor.
    pub fn repSubtreeHasDescriptor(self: RepQuery, rep_id: TypeRepId) Allocator.Error!bool {
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        return try self.repSubtreeAny(rep_id, &seen, {}, struct {
            fn found(_: void, query: RepQuery, candidate: TypeRepId) bool {
                return query.rep(candidate).descriptor != null;
            }
        }.found);
    }

    /// Whether `root` or a representation reachable below it satisfies
    /// `found`. Reachability does not depend on visiting order.
    fn repSubtreeAny(
        self: RepQuery,
        root: TypeRepId,
        seen: *collections.DenseMap(TypeRepId, void),
        context: anytype,
        comptime found: fn (@TypeOf(context), RepQuery, TypeRepId) bool,
    ) Allocator.Error!bool {
        var pending: std.ArrayList(TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |rep_id| {
            if (found(context, self, rep_id)) return true;
            if ((try seen.getOrPut(rep_id)).found_existing) continue;
            for (self.plan.childSlice(self.rep(rep_id).children)) |child| try pending.append(self.allocator, child.rep);
        }
        return false;
    }

    /// True when a child of `rep_id` other than `selected_child` carries a
    /// descriptor that the selected child's subtree does not already cover.
    pub fn repSubtreeHasDescriptorInOtherChildren(
        self: RepQuery,
        rep_id: TypeRepId,
        selected_child: RepChild,
    ) Allocator.Error!bool {
        for (self.plan.childSlice(self.rep(rep_id).children)) |child| {
            if (child.rep == selected_child.rep and std.meta.eql(child.role, selected_child.role)) continue;
            // A sibling reachable through the selected child's subtree carries the
            // same descriptor the backing already covers; it does not block the
            // unwrap because its descriptor is collected once via the backing.
            if (try self.repSubtreeContainsRep(selected_child.rep, child.rep)) continue;
            if (try self.repSubtreeHasDescriptor(child.rep)) return true;
        }
        return false;
    }

    /// True when `rep_id` or anything reachable below it carries a dictionary.
    pub fn repSubtreeHasDictionary(self: RepQuery, rep_id: TypeRepId) Allocator.Error!bool {
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        return try self.repSubtreeAny(rep_id, &seen, {}, struct {
            fn found(_: void, query: RepQuery, candidate: TypeRepId) bool {
                return query.rep(candidate).dictionaries.len != 0;
            }
        }.found);
    }

    /// True when a child of `rep_id` other than `selected_child` carries a
    /// dictionary that the selected child's subtree does not already cover.
    pub fn repSubtreeHasDictionaryInOtherChildren(
        self: RepQuery,
        rep_id: TypeRepId,
        selected_child: RepChild,
    ) Allocator.Error!bool {
        for (self.plan.childSlice(self.rep(rep_id).children)) |child| {
            if (child.rep == selected_child.rep and std.meta.eql(child.role, selected_child.role)) continue;
            // A sibling reachable through the selected child's subtree carries the
            // same dictionary the backing already covers; it does not block the
            // unwrap because its dictionary is collected once via the backing.
            if (try self.repSubtreeContainsRep(selected_child.rep, child.rep)) continue;
            if (try self.repSubtreeHasDictionary(child.rep)) return true;
        }
        return false;
    }

    /// True when `target` is `root` or is reachable below it.
    pub fn repSubtreeContainsRep(self: RepQuery, root: TypeRepId, target: TypeRepId) Allocator.Error!bool {
        var seen = collections.DenseMap(TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        return try self.repSubtreeAny(root, &seen, target, struct {
            fn found(wanted: TypeRepId, _: RepQuery, candidate: TypeRepId) bool {
                return candidate == wanted;
            }
        }.found);
    }

    /// The backing representation an alias or field-less transparent nominal
    /// wraps, or null when `rep_id` is not such a wrapper.
    pub fn structuralWrapperBackingRep(self: RepQuery, rep_id: TypeRepId) ?TypeRepId {
        const current = self.rep(rep_id);
        if (current.kind == .alias) return self.requiredSingleChild(rep_id, .alias_backing).rep;
        if (current.kind == .nominal) {
            return switch (current.kind.nominal) {
                .transparent => if (current.declared_fields.len == 0)
                    self.requiredSingleChild(rep_id, .nominal_backing).rep
                else
                    null,
                .opaque_nominal, .builtin_other => null,
            };
        }
        return null;
    }

    /// The structure a call representation stands for at a worker position
    /// of a call boundary. A structural worker position instantiated by a
    /// call-side alias or nominal was related to that wrapper's backing by
    /// checking (see `structureBackingRep`), so every such wrapper is seen
    /// through, binding each nominal use's
    /// declaration formals in `env` so the backing's children resolve to that
    /// use's actuals. A wrapper worker position aligns with the call's
    /// wrapper itself.
    ///
    /// `env` provides `resolve(rep)` and `bindScoped(allocator, formal, actual)`.
    pub fn bindCallWrappedStructure(
        self: RepQuery,
        allocator: Allocator,
        worker_rep_id: TypeRepId,
        call_rep_id: TypeRepId,
        env: anytype,
    ) Allocator.Error!TypeRepId {
        const worker_kind = self.rep(worker_rep_id).kind;
        if (worker_kind == .alias or worker_kind == .nominal) return call_rep_id;

        var current = call_rep_id;
        while (self.structureBackingRep(current)) |backing| {
            var backing_substitutions = self.plan.nominalBackingSubstitutions(self.rep(current).nominal_backing_arg_substitutions);
            while (backing_substitutions.next()) |backing_substitution| {
                const formal_rep = backing_substitution.formal_rep orelse continue;
                const actual = env.resolve(backing_substitution.actual_rep);
                if (formal_rep != actual) try env.bindScoped(allocator, formal_rep, actual);
            }
            current = env.resolve(backing);
        }
        return current;
    }

    /// The backing an alias or backed nominal stands for where checking
    /// related it to a structure. Checking unifies a nominal with its
    /// backing's structure when the declaration is transparent (`:=`), or
    /// inside its origin module when it is opaque, so a structural position
    /// of a callee's type can be instantiated at a call by such a wrapper of
    /// that structure.
    pub fn structureBackingRep(self: RepQuery, rep_id: TypeRepId) ?TypeRepId {
        const current = self.rep(rep_id);
        return switch (current.kind) {
            .alias => self.requiredSingleChild(rep_id, .alias_backing).rep,
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => self.requiredSingleChild(rep_id, .nominal_backing).rep,
                .opaque_nominal => null,
            },
            .in_progress,
            .dynamic,
            .primitive,
            .bool_tag_union,
            .erased_callable,
            .record,
            .tuple,
            .list,
            .box,
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => null,
        };
    }

    /// The representation a descriptor argument is keyed by: wrappers unwrap
    /// until an inspect method, a nominal-backing substitution, or a
    /// non-wrapper is reached.
    pub fn descriptorArgumentIdentityRep(self: RepQuery, rep_id: TypeRepId) TypeRepId {
        var current = rep_id;
        while (true) {
            if (self.plan.inspectMethodForRep(current) != null) return current;

            if (self.rep(current).nominal_backing_arg_substitutions.len != 0) return current;

            current = self.structuralWrapperBackingRep(current) orelse return current;
        }
    }

    /// The representation a dictionary argument is keyed by. Aliases are pure
    /// transparency, but a transparent nominal owns the method namespace its
    /// dictionary slots dispatch through, so only aliases are unwrapped here;
    /// the nominal identity is preserved.
    pub fn dictionaryArgumentIdentityRep(self: RepQuery, rep_id: TypeRepId) TypeRepId {
        var current = rep_id;
        while (true) {
            if (self.rep(current).kind != .alias) return current;
            current = self.requiredSingleChild(current, .alias_backing).rep;
        }
    }

    /// True when a worker child is exactly the unwrapped backing of its
    /// worker representation and no sibling descriptor blocks the unwrap.
    pub fn workerChildCanMatchUnwrappedCallRep(
        self: RepQuery,
        worker_rep_id: TypeRepId,
        worker_child: RepChild,
    ) Allocator.Error!bool {
        const worker_backing = self.structuralWrapperBackingRep(worker_rep_id) orelse return false;
        return worker_child.rep == worker_backing and
            !try self.repSubtreeHasDescriptorInOtherChildren(worker_rep_id, worker_child);
    }

    /// The dictionary counterpart of `workerChildCanMatchUnwrappedCallRep`.
    pub fn workerChildCanMatchUnwrappedCallRepForDictionaries(
        self: RepQuery,
        worker_rep_id: TypeRepId,
        worker_child: RepChild,
    ) Allocator.Error!bool {
        const worker_backing = self.structuralWrapperBackingRep(worker_rep_id) orelse return false;
        return worker_child.rep == worker_backing and
            !try self.repSubtreeHasDictionaryInOtherChildren(worker_rep_id, worker_child);
    }

    /// The representation that carries a function's identity, unwrapping alias
    /// and transparent-nominal layers.
    pub fn functionIdentityRep(self: RepQuery, rep_id: TypeRepId) TypeRepId {
        var current = rep_id;
        while (true) {
            const current_rep = self.rep(current);
            if (current_rep.kind == .alias) {
                current = self.requiredSingleChild(current, .alias_backing).rep;
            } else if (current_rep.kind == .nominal) {
                switch (current_rep.kind.nominal) {
                    .transparent => current = self.requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => return current,
                }
            } else {
                return current;
            }
        }
    }

    /// The argument and return children of a function representation, or null
    /// when `rep_id` does not resolve to an erased callable.
    pub fn functionChildren(self: RepQuery, rep_id: TypeRepId) ?FunctionChildren {
        const identity_rep = self.functionIdentityRep(rep_id);
        const identity = self.rep(identity_rep);
        if (identity.kind != .erased_callable) return null;

        var args_start: ?u32 = null;
        var arg_count: u32 = 0;
        var ret: ?TypeRepId = null;
        for (self.plan.childSlice(identity.children), 0..) |child, i| {
            if (child.role == .function_arg) {
                if (args_start == null) args_start = @intCast(i);
                arg_count += 1;
            } else if (child.role == .function_ret) {
                ret = child.rep;
            }
        }
        return .{
            .rep = identity_rep,
            .args_start = args_start orelse 0,
            .arg_count = arg_count,
            .ret = ret orelse boxyPlanInvariant("function representation had no return child"),
        };
    }
};

/// Formal bindings of the wrappers one call-boundary node was
/// seen through, for walks that keep no lexical substitution scope.
pub const CallWrapperBindings = struct {
    const Binding = struct {
        formal_rep: TypeRepId,
        actual_rep: TypeRepId,
    };

    entries: std.ArrayList(Binding) = .empty,

    pub fn deinit(self: *CallWrapperBindings, allocator: Allocator) void {
        self.entries.deinit(allocator);
    }

    /// The innermost binding of `rep`, or `rep` itself when it is unbound.
    pub fn resolve(self: *const CallWrapperBindings, rep: TypeRepId) TypeRepId {
        var index = self.entries.items.len;
        while (index > 0) {
            index -= 1;
            if (self.entries.items[index].formal_rep == rep) return self.entries.items[index].actual_rep;
        }
        return rep;
    }

    pub fn bindScoped(self: *CallWrapperBindings, allocator: Allocator, formal_rep: TypeRepId, actual_rep: TypeRepId) Allocator.Error!void {
        try self.entries.append(allocator, .{ .formal_rep = formal_rep, .actual_rep = actual_rep });
    }
};

/// A call child found in a structure seen through a wrapper can be one of
/// that wrapper's declaration formals, which names the use's actual.
pub fn structureChildCallRep(env: anytype, through_wrapper: bool, call_child_rep: TypeRepId) TypeRepId {
    return if (through_wrapper) env.resolve(call_child_rep) else call_child_rep;
}

fn repIsTagRow(rep: TypeRepresentation) bool {
    return rep.kind == .tag_union or rep.is_open_tag_row;
}

/// True when two child roles are the same payload-free role.
///
/// Every role that carries a payload (an index, a label) answers false: this
/// asks only "is this the same kind of position", not "is this the same
/// position". Callers that need the exact position compare roles directly, and
/// callers that need cross-module label equality use
/// `NamedRepQuery.childRolesMatch`.
pub fn sameChildRoleKind(a: ChildRole, b: ChildRole) bool {
    return switch (a) {
        .alias_backing => b == .alias_backing,
        .nominal_backing => b == .nominal_backing,
        .record_ext => b == .record_ext,
        .tag_ext => b == .tag_ext,
        .list_elem => b == .list_elem,
        .box_payload => b == .box_payload,
        .alias_arg,
        .nominal_arg,
        .nominal_padding_field,
        .record_field,
        .tuple_elem,
        .function_arg,
        .function_ret,
        .tag_payload,
        => false,
    };
}

/// Representation queries that compare source-level labels, and therefore need
/// to resolve a module id to its name store.
///
/// `Modules` is any type exposing `moduleNames(checked.ModuleId) ModuleNames`.
/// Boxy planning and Boxy lowering hold different module-view types; this is
/// the seam that lets both ask one implementation the same question.
pub fn NamedRepQuery(comptime Modules: type) type {
    return struct {
        const Self = @This();

        query: RepQuery,
        modules: Modules,

        /// Returns the exact call-side row that instantiates a worker child when
        /// open tag rows expose different tags on each side of a checked function
        /// boundary. Unmatched worker payloads live in the call extension; when
        /// the call has tags the worker row does not name, or no extension of its
        /// own, the worker extension denotes the complete call row rather than
        /// only its residual extension.
        pub fn rowInstantiationTarget(
            self: Self,
            worker_rep_id: TypeRepId,
            call_rep_id: TypeRepId,
            worker_child: RepChild,
        ) ?TypeRepId {
            const worker_rep = self.query.rep(worker_rep_id);
            const call_rep = self.query.rep(call_rep_id);
            if (!repIsTagRow(worker_rep) or !repIsTagRow(call_rep)) return null;

            const call_children = self.query.plan.childSlice(call_rep.children);
            switch (worker_child.role) {
                .tag_payload => {
                    if (self.findMatchingChildByRole(call_children, worker_child) != null) return null;
                    var extension: ?TypeRepId = null;
                    for (call_children) |call_child| {
                        if (call_child.role != .tag_ext) continue;
                        if (extension != null) {
                            boxyPlanInvariant("boxy tag union representation had multiple row extensions");
                        }
                        extension = call_child.rep;
                    }
                    return extension;
                },
                .tag_ext => {
                    var call_has_extension = false;
                    for (call_children) |call_child| {
                        if (call_child.role == .tag_ext) call_has_extension = true;
                    }
                    if (!call_has_extension) return call_rep_id;
                    for (self.query.plan.tagVariantSlice(call_rep.tag_variants)) |call_variant| {
                        if (!self.tagRowNamesVariant(worker_rep, call_variant)) return call_rep_id;
                    }
                    return null;
                },
                .alias_backing,
                .alias_arg,
                .nominal_backing,
                .nominal_arg,
                .nominal_padding_field,
                .record_field,
                .record_ext,
                .tuple_elem,
                .function_arg,
                .function_ret,
                .list_elem,
                .box_payload,
                => return null,
            }
        }

        fn tagRowNamesVariant(self: Self, row: TypeRepresentation, variant: TagVariant) bool {
            const variant_names = self.modules.moduleNames(variant.name_module);
            for (self.query.plan.tagVariantSlice(row.tag_variants)) |candidate| {
                if (tagLabelNameMatches(variant_names, variant.name, self.modules.moduleNames(candidate.name_module), candidate.name)) return true;
            }
            return false;
        }

        /// True when two children fill the same role, comparing record field
        /// and tag payload labels by text across modules.
        pub fn childRolesMatch(self: Self, target: RepChild, candidate: RepChild) bool {
            return switch (target.role) {
                .record_field => |target_label| switch (candidate.role) {
                    .record_field => |candidate_label| recordFieldNameMatches(
                        self.modules.moduleNames(target.source_type.module),
                        target_label,
                        self.modules.moduleNames(candidate.source_type.module),
                        candidate_label,
                    ),
                    .alias_backing,
                    .alias_arg,
                    .nominal_backing,
                    .nominal_arg,
                    .nominal_padding_field,
                    .record_ext,
                    .tuple_elem,
                    .function_arg,
                    .function_ret,
                    .tag_payload,
                    .tag_ext,
                    .list_elem,
                    .box_payload,
                    => false,
                },
                .tag_payload => |target_payload| switch (candidate.role) {
                    .tag_payload => |candidate_payload| target_payload.index == candidate_payload.index and
                        tagLabelNameMatches(
                            self.modules.moduleNames(target.source_type.module),
                            target_payload.tag,
                            self.modules.moduleNames(candidate.source_type.module),
                            candidate_payload.tag,
                        ),
                    .alias_backing,
                    .alias_arg,
                    .nominal_backing,
                    .nominal_arg,
                    .nominal_padding_field,
                    .record_field,
                    .record_ext,
                    .tuple_elem,
                    .function_arg,
                    .function_ret,
                    .tag_ext,
                    .list_elem,
                    .box_payload,
                    => false,
                },
                .alias_backing,
                .alias_arg,
                .nominal_backing,
                .nominal_arg,
                .nominal_padding_field,
                .record_ext,
                .tuple_elem,
                .function_arg,
                .function_ret,
                .tag_ext,
                .list_elem,
                .box_payload,
                => std.meta.eql(target.role, candidate.role),
            };
        }

        /// The first child of `children` filling the same role as `target`.
        pub fn findMatchingChildByRole(self: Self, children: []const RepChild, target: RepChild) ?RepChild {
            for (children) |child| {
                if (self.childRolesMatch(target, child)) return child;
            }
            return null;
        }
    };
}

/// The label-comparison view of a module view.
pub fn moduleNamesOf(view: ModuleView) ModuleNames {
    return .{ .key = view.key, .canonical_names = view.canonical_names };
}

/// True when two record field labels name the same field, comparing by text
/// when the labels come from different modules.
pub fn recordFieldNameMatches(
    source: ModuleNames,
    source_name: RecordFieldLabelId,
    target: ModuleNames,
    target_name: RecordFieldLabelId,
) bool {
    if (moduleKeyEqual(source.key, target.key)) return source_name == target_name;
    const source_names = source.canonical_names orelse return source_name == target_name;
    const target_names = target.canonical_names orelse return source_name == target_name;
    return std.mem.eql(
        u8,
        source_names.recordFieldLabelText(source_name),
        target_names.recordFieldLabelText(target_name),
    );
}

/// True when two tag labels name the same tag, comparing by text when the
/// labels come from different modules.
pub fn tagLabelNameMatches(
    source: ModuleNames,
    source_name: TagLabelId,
    target: ModuleNames,
    target_name: TagLabelId,
) bool {
    if (moduleKeyEqual(source.key, target.key)) return source_name == target_name;
    const source_names = source.canonical_names orelse return source_name == target_name;
    const target_names = target.canonical_names orelse return source_name == target_name;
    return checked.tagLabelsMatch(source_names, source_name, target_names, target_name);
}

/// The one child of `rep_id` with `role`, resolved directly from a plan.
fn requiredSingleChildOf(plan: *const ProgramPlan, rep_id: TypeRepId, role: ChildRole) RepChild {
    var found: ?RepChild = null;
    const rep = plan.representations.items[@intFromEnum(rep_id)];
    for (plan.childSlice(rep.children)) |child| {
        if (std.meta.eql(child.role, role)) {
            if (found != null) boxyPlanInvariant("boxy representation had duplicate child role");
            found = child;
        }
    }
    return found orelse boxyPlanInvariant("boxy representation was missing required child role");
}

fn checkedFunctionPayload(view: ModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedFunctionType {
    var current = checked_ty;
    while (true) {
        switch (view.checked_types.payload(current)) {
            .pending => boxyPlanInvariant("pending checked function type reached boxy planning"),
            .alias => |alias| {
                current = alias.backing;
                continue;
            },
            .function => |function| return function,
            .err,
            .flex,
            .rigid,
            .record,
            .tuple,
            .nominal,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => boxyPlanInvariant("checked intrinsic wrapper did not have a function type"),
        }
    }
}

